// Consolidated TerminalNotes source. Each region preserves an original compilation unit.
// TN_SOURCE_* symbols let focused tests compile their original dependency set.

#if TN_WPF || TN_SOURCE_SERVICES_AUTOINSTALL_CS
#region Services/AutoInstall.cs
namespace TerminalNotes
{
using global::TerminalNotes.Services;
using global::System.ComponentModel;
using global::System.Diagnostics;
using global::System.IO;
using global::System.Text;

public enum AutoInstallStatus
{
    NotConnected,
    Completed,
    Failed
}

public sealed record AutoInstallResult(AutoInstallStatus Status, string Message);

public sealed record AutoInstallDetectionResult(
    bool IsInstalled,
    string Message,
    string? Path = null,
    string? Version = null);

public static class AutoInstall
{
    private static readonly OpenCodeInstallationService InstallationService = new();
    private static readonly OpenCodeInstallCommand Installer = new();

    /// <summary>Checks the native Windows OpenCode command used by the current backend. A command without the native
    /// opencode.exe behind it (an npm shim whose install did not finish, another wrapper) counts as not installed: the app
    /// offers to install OpenCode or shows why, and never runs it through PowerShell or cmd.exe instead (사용자 지시).</summary>
    public static Task<AutoInstallDetectionResult> CheckAsync(CancellationToken cancellationToken = default) =>
        CheckAsync(async token => RequireNative(await InstallationService.CheckAsync(token).ConfigureAwait(false)), cancellationToken);

    /// <summary>The found command as its native opencode.exe, or not installed when there is none.</summary>
    internal static AutoInstallDetectionResult RequireNative(AutoInstallDetectionResult found) =>
        !found.IsInstalled || string.IsNullOrWhiteSpace(found.Path) ? found
        : OpenCodeInstallationService.NativeExecutable(found.Path) is { } native ? found with { Path = native }
        : new AutoInstallDetectionResult(false, NativeMissing(found.Path));

    internal static string NativeMissing(string? command) =>
        "OpenCode 실행 파일(opencode.exe)을 찾지 못했습니다" + (string.IsNullOrWhiteSpace(command) ? "" : $" ({command})") +
        ". 설치가 끝나지 않았을 수 있습니다. 작업 설정의 'OpenCode 설치'로 다시 설치하세요.";

    internal static async Task<AutoInstallDetectionResult> CheckAsync(
        Func<CancellationToken, Task<AutoInstallDetectionResult>> checkOpenCode,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        return await checkOpenCode(cancellationToken);
    }

    /// <summary>Runs OPENCODE_INSTALL_COMMAND from .env. Call CheckAsync afterwards to verify readiness.</summary>
    public static Task<AutoInstallResult> RunAsync(CancellationToken cancellationToken = default) =>
        Installer.RunAsync(cancellationToken);
}

/// <summary>
/// Runs the OpenCode install command written in .env (OPENCODE_INSTALL_COMMAND, compiled into the app) in its own
/// visible Windows PowerShell window, so npm/winget progress and errors stay readable. Concurrent callers share one run.
/// </summary>
internal sealed class OpenCodeInstallCommand(string? installCommand = null, string? powershellHost = null)
{
    /// <summary>Hands the command to the PowerShell window (no quoting of the command line).</summary>
    internal const string InstallCommandVariable = "TERMINALNOTES_OPENCODE_INSTALL_COMMAND";
    // Only the default, entirely unconfigured Windows policy gets a process-local RemoteSigned (npm.ps1 needs it);
    // explicit user, machine and group policies apply unchanged. On failure the window waits for Enter.
    private const string Script = """
        $Host.UI.RawUI.WindowTitle = 'OpenCode 설치'
        $ErrorActionPreference = 'Stop'
        $configured = @(Get-ExecutionPolicy -List | Where-Object { $_.ExecutionPolicy -ne 'Undefined' })
        if ($configured.Count -eq 0) { Set-ExecutionPolicy -Scope Process -ExecutionPolicy RemoteSigned -Force }
        Write-Host ('> ' + $env:TERMINALNOTES_OPENCODE_INSTALL_COMMAND)
        $global:LASTEXITCODE = 0
        try {
            Invoke-Expression $env:TERMINALNOTES_OPENCODE_INSTALL_COMMAND
            if ($LASTEXITCODE) { throw ('종료 코드 ' + $LASTEXITCODE) }
            exit 0
        }
        catch {
            Write-Host $_
            $code = if ($LASTEXITCODE) { $LASTEXITCODE } else { 1 }
            if (-not $env:TERMINALNOTES_INSTALL_NO_PAUSE) { [void](Read-Host '설치하지 못했습니다. Enter를 누르면 닫힙니다') }
            exit $code
        }
        """;
    internal static readonly string? ConfiguredCommand = typeof(OpenCodeInstallCommand).Assembly
        .GetCustomAttributes(typeof(global::System.Reflection.AssemblyMetadataAttribute), false)
        .OfType<global::System.Reflection.AssemblyMetadataAttribute>()
        .FirstOrDefault(attribute => attribute.Key == "TerminalNotes.OpenCodeInstallCommand")?.Value?.Trim() is { Length: > 0 } command ? command : null;
    private readonly string? _command = string.IsNullOrWhiteSpace(installCommand) ? ConfiguredCommand : installCommand.Trim();
    /// <summary>Tests run the command hidden and without the failure pause.</summary>
    internal bool ShowWindow { get; init; } = true;
    private readonly object _gate = new();
    private Task<AutoInstallResult>? _activeTask;
    private CancellationTokenSource? _activeCancellation;
    private readonly List<CancellationTokenRegistration> _registrations = [];

    internal Task<AutoInstallResult> RunAsync(CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            if (_activeTask is null || _activeTask.IsCompleted)
            {
                _activeCancellation = new CancellationTokenSource();
                _activeTask = RunSharedAsync(_activeCancellation);
            }
            CancellationTokenSource active = _activeCancellation!;
            Task<AutoInstallResult> task = _activeTask;
            // Keep cancellation callbacks off the caller/UI thread and avoid inline completion under this lock.
            _registrations.Add(cancellationToken.Register(() => { _ = active.CancelAsync(); }));
            return task;
        }
    }

    private async Task<AutoInstallResult> RunSharedAsync(CancellationTokenSource cancellation)
    {
        // Leave the lock before starting any processes and before completing synchronously.
        await Task.Yield();
        try { return await RunCoreAsync(cancellation.Token).ConfigureAwait(false); }
        finally
        {
            lock (_gate)
            {
                foreach (CancellationTokenRegistration registration in _registrations) registration.Dispose();
                _registrations.Clear();
                _activeCancellation = null;
                // Clearing inside the same lock prevents callers from registering on a disposed source.
                _activeTask = null;
                cancellation.Dispose();
            }
        }
    }

    internal ProcessStartInfo? CreateStartInfo()
    {
        if (_command is null) return null;
        var info = new ProcessStartInfo
        {
            FileName = powershellHost ?? Path.Combine(Environment.SystemDirectory, "WindowsPowerShell", "v1.0", "powershell.exe"),
            WorkingDirectory = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
            UseShellExecute = false,
            CreateNoWindow = !ShowWindow,
            WindowStyle = ShowWindow ? ProcessWindowStyle.Normal : ProcessWindowStyle.Hidden
        };
        info.Environment[InstallCommandVariable] = _command;
        if (ShowWindow) info.Environment.Remove("TERMINALNOTES_INSTALL_NO_PAUSE");
        else info.Environment["TERMINALNOTES_INSTALL_NO_PAUSE"] = "1";
        foreach (string argument in new[] { "-NoProfile", "-EncodedCommand", Convert.ToBase64String(Encoding.Unicode.GetBytes(Script)) })
            info.ArgumentList.Add(argument);
        return info;
    }

    private async Task<AutoInstallResult> RunCoreAsync(CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (CreateStartInfo() is not { } info)
            return new(AutoInstallStatus.NotConnected, "OpenCode 설치 명령이 없습니다. .env의 OPENCODE_INSTALL_COMMAND에 적고 다시 빌드하세요.");
        try
        {
            using var process = new Process { StartInfo = info };
            if (!process.Start()) throw new IOException("설치 실행 프로세스를 시작하지 못했습니다.");
            using CancellationTokenRegistration registration = cancellationToken.Register(() => KillOwnedProcess(process));
            try { await process.WaitForExitAsync(cancellationToken).ConfigureAwait(false); }
            finally { KillOwnedProcess(process); }
            return process.ExitCode == 0
                ? new(AutoInstallStatus.Completed, "OpenCode 설치 명령 실행이 끝났습니다. 설치 상태를 다시 확인합니다.")
                : new(AutoInstallStatus.Failed, $"OpenCode 설치 명령이 실패했습니다 (종료 코드 {process.ExitCode}). 설치 창에 표시된 오류를 확인하세요.\n{_command}");
        }
        catch (Exception exception) when (exception is Win32Exception or IOException or UnauthorizedAccessException or ArgumentException)
        {
            return new(AutoInstallStatus.Failed, $"OpenCode 설치 명령을 실행할 수 없습니다. Windows PowerShell과 실행 정책을 확인하세요.\n{exception.Message}");
        }
    }

    private static void KillOwnedProcess(Process process)
    {
        try { if (!process.HasExited) process.Kill(entireProcessTree: true); }
        catch (Exception exception) when (exception is InvalidOperationException or Win32Exception) { }
    }
}

}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_APPINSTANCECOORDINATOR_CS
#region Services/AppInstanceCoordinator.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.IO.Pipes;
using global::System.Security.Cryptography;
using global::System.Text;
using global::System.Text.Json;


/// <summary>One dashboard per settings file. The OS releases ownership on exit/crash.</summary>
public sealed class AppInstanceCoordinator : IDisposable
{
    private const int MaximumRequestBytes = 32 * 1024;
    private readonly FileStream _ownership;
    private readonly CancellationTokenSource _shutdown = new();
    private Task? _listener;
    public string PipeName { get; }

    private AppInstanceCoordinator(string settingsPath, FileStream ownership)
    {
        _ownership = ownership;
        PipeName = GetPipeName(settingsPath);
    }

    public static string GetPipeName(string settingsPath) => "TerminalNotes-" + Convert.ToHexString(
        SHA256.HashData(Encoding.UTF8.GetBytes(Path.GetFullPath(settingsPath).ToUpperInvariant())))[..32];

    public static bool IsSharingViolation(IOException exception) => (exception.HResult & 0xffff) is 32 or 33;

    public static AppInstanceCoordinator? TryAcquire(string settingsPath)
    {
        settingsPath = Path.GetFullPath(settingsPath);
        Directory.CreateDirectory(Path.GetDirectoryName(settingsPath)!);
        FileStream ownership;
        try { ownership = new(settingsPath + ".instance.lock", FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.Read); }
        catch (IOException exception) when (IsSharingViolation(exception)) { return null; }
        try
        {
            ownership.SetLength(0);
            JsonSerializer.Serialize(ownership, new { processId = Environment.ProcessId });
            ownership.Flush();
            return new(settingsPath, ownership);
        }
        catch { ownership.Dispose(); throw; }
    }

    public static int? ReadOwnerProcessId(string settingsPath)
    {
        try
        {
            using var file = new FileStream(settingsPath + ".instance.lock", FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
            using var document = JsonDocument.Parse(file);
            return document.RootElement.GetProperty("processId").GetInt32();
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or KeyNotFoundException) { return null; }
    }

    public void StartListening(Func<string?, Task<bool>> activate)
    {
        if (_listener is not null) throw new InvalidOperationException("Activation listener already started.");
        _listener = ListenAsync(activate);
    }

    private async Task ListenAsync(Func<string?, Task<bool>> activate)
    {
        while (!_shutdown.IsCancellationRequested)
        {
            try
            {
                using var pipe = new NamedPipeServerStream(PipeName, PipeDirection.InOut, 1, PipeTransmissionMode.Byte,
                    PipeOptions.Asynchronous | PipeOptions.CurrentUserOnly);
                await pipe.WaitForConnectionAsync(_shutdown.Token).ConfigureAwait(false);
                using var requestTimeout = CancellationTokenSource.CreateLinkedTokenSource(_shutdown.Token);
                requestTimeout.CancelAfter(TimeSpan.FromSeconds(3));
                byte[] header = new byte[4];
                await pipe.ReadExactlyAsync(header, requestTimeout.Token).ConfigureAwait(false);
                int length = System.Buffers.Binary.BinaryPrimitives.ReadInt32LittleEndian(header);
                if (length is < 1 or > MaximumRequestBytes) continue;
                byte[] payload = new byte[length];
                await pipe.ReadExactlyAsync(payload, requestTimeout.Token).ConfigureAwait(false);
                string? workspace = JsonSerializer.Deserialize<string>(payload);
                if (workspace is not null && !Path.IsPathFullyQualified(workspace)) continue;
                bool accepted = await activate(workspace).ConfigureAwait(false);
                await pipe.WriteAsync(new byte[] { accepted ? (byte)1 : (byte)0 }, requestTimeout.Token).ConfigureAwait(false);
            }
            catch (OperationCanceledException) when (_shutdown.IsCancellationRequested) { break; }
            catch (Exception exception)
            {
                // Partial/failed launch messages must not disable later activation.
                System.Diagnostics.Trace.WriteLine(exception);
                if (!_shutdown.IsCancellationRequested) await Task.Delay(100).ConfigureAwait(false);
            }
        }
    }

    public static async Task<bool> TryActivateAsync(string settingsPath, string? workspace, CancellationToken cancellationToken)
    {
        try
        {
            using var pipe = new NamedPipeClientStream(".", GetPipeName(settingsPath), PipeDirection.InOut,
                PipeOptions.Asynchronous, System.Security.Principal.TokenImpersonationLevel.Identification);
            await pipe.ConnectAsync(cancellationToken).ConfigureAwait(false);
            byte[] payload = JsonSerializer.SerializeToUtf8Bytes(workspace);
            if (payload.Length > MaximumRequestBytes) return false;
            byte[] header = new byte[4];
            System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(header, payload.Length);
            await pipe.WriteAsync(header, cancellationToken).ConfigureAwait(false);
            await pipe.WriteAsync(payload, cancellationToken).ConfigureAwait(false);
            byte[] acknowledgement = new byte[1];
            await pipe.ReadExactlyAsync(acknowledgement, cancellationToken).ConfigureAwait(false);
            return acknowledgement[0] == 1;
        }
        catch (Exception exception) when (exception is IOException or OperationCanceledException or UnauthorizedAccessException) { return false; }
    }

    public void Dispose()
    {
        _shutdown.Cancel();
        _ownership.Dispose();
        // Never delete a lock path: deletion can split ownership between processes.
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_AUTOMATIONCOMMANDBUILDER_CS
#region Services/AutomationCommandBuilder.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Text;
using global::System.Text.Json;


public sealed record AutomationCommand(string Directory, string Command, string ResultPath, string CompletionPath, string EventsPath, AutomationRole Role)
{
    // Additive metadata lets completion parsing enforce the Planning contract while
    // preserving the existing positional constructor used by older callers.
    public AutomationWorkflowPhase WorkflowPhase { get; init; }
}
public sealed record AutomationStageOutput(bool Success, string Summary, string Instruction, bool Complete, long Tokens)
{
    // Set only by the native supervisor after it confirms that work stopped.
    public bool Interrupted { get; init; }
    public bool PlanApproved { get; init; }
    public string? DeliveryEvidence { get; init; }
    public AutomationPlanningOutput? PlanningPlan { get; init; }
}

/// <summary>Transfers prompts through files, never through shell interpolation. Each dispatch has its own completion marker.</summary>
public static class AutomationCommandBuilder
{
    private static readonly JsonSerializerOptions WireJsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };
    private const int MaxCliFailureDetailLength = 900;
    private const int MaxCliFailureLineLength = 320;

    public static string QuotePowerShell(string value) => "'" + value.Replace("'", "''") + "'";

    public static Task<AutomationCommand> PrepareAsync(string project, AutomationStepClaim claim, string previousResult) =>
        PrepareCoreAsync(project, claim, previousResult, nativeSession: false);

    public static Task<AutomationCommand> PrepareNativeAsync(string project, AutomationStepClaim claim, string previousResult) =>
        PrepareCoreAsync(project, claim, previousResult, nativeSession: true);

    private static async Task<AutomationCommand> PrepareCoreAsync(string project, AutomationStepClaim claim, string previousResult, bool nativeSession)
    {
        string directory = Path.Combine(project, "terminal-notes", "runs", claim.RunId.ToString("N"), claim.DispatchToken.ToString("N"));
        Directory.CreateDirectory(directory);
        string promptPath = Path.Combine(directory, "prompt.md"), schemaPath = Path.Combine(directory, "schema.json");
        string resultPath = Path.Combine(directory, "result.json"), completionPath = Path.Combine(directory, "completion.json"), eventsPath = Path.Combine(directory, "events.jsonl");
        string scriptPath = Path.Combine(directory, "run.ps1");
        string? model = claim.Options.ModelFor(claim.Role);
        if (!string.IsNullOrWhiteSpace(model) && (model.IndexOf('/') <= 0 || model.EndsWith('/')))
            throw new InvalidOperationException("이 실행의 모델 설정은 OpenCode 형식이 아닙니다. 새 플랜에서 모델을 비워 OpenCode 기본값을 사용하거나 provider/model로 지정한 뒤 다시 승인하세요.");
        string role = RoleInstructions(claim);
        const string resultContract = """{"summary":"작업 요약과 검증 결과","instruction":"다음 역할에 줄 지시","complete":false,"planApproved":false,"deliveryEvidence":null,"planning":null}""";
        string prompt = $"""
            Terminal Notes 자동화 · {claim.Role} · 회차 {claim.Iteration}
            Workflow phase: {claim.WorkflowPhase}

            {ContinuousImprovementInstructions(claim)}

            당신은 {role}
            별도의 에이전트를 만들지 마세요. Terminal Notes가 3개 역할을 순서대로 실행합니다.
            프로젝트 조사에서 terminal-notes의 실행 로그·과거 프롬프트·내부 관리 파일은 제외하고 지정된 plan.md와 terminal-notes/terminal-inputs.md(있을 때)만 읽으세요. 추가 입력의 최신 요청과 정정 내용을 반영하고 과거 요청을 순서대로 다시 실행하지 마세요. 자동화 맥락은 아래에 제공됩니다. 구현 파일이 없는 새 프로젝트라면 같은 폴더를 반복 조사하지 말고 구체적인 초기 계획을 작성하세요.
            plan.md는 사용자가 작성한 원문이며 모든 역할이 보존해야 합니다. 상세 지휘 계획은 프로그램이 별도로 저장하고 아래 '구조화된 지휘 계획'으로 전달합니다. 계획이 원본 plan.md에 없다는 이유로 반려하거나 그 파일에 상세 계획을 쓰라고 지시하지 마세요. 이전 지시가 이를 요구했다면 이 저장 계약으로 바로잡고 전달된 구조화된 계획 자체를 검토하세요.
            사용자의 판단이나 권한이 반드시 필요하면 OpenCode의 실제 질문·승인 기능으로 기다리고, 진행할 수 없는 이유를 명시하세요. 승인된 범위를 임의로 넓히지 마세요.
            지휘자가 계획 검토, 구현·빌드, 결과 검증, 수정, 서비스 실행을 끝까지 통제합니다. 검토 결과는 반드시 지휘자에게 돌아갑니다. 동일한 지적이 반복되면 원인과 접근 방법을 다시 검토하고 구체적인 수정 지시를 개선하세요. 사용자의 중단이나 실제 권한·정보 부족이 없으면 프로젝트가 완성될 때까지 진행합니다.
            재개 시 처음부터 다시 시작하지 마세요. 현재 코드·변경분·native todo·전달된 실행 결과를 먼저 대조해 완료·부분 구현·미완료를 구분하세요. 이미 구현되어 정상 동작하는 기능은 보존하고 다시 구현하지 마세요. 중간에 끊긴 변경은 현재 파일을 확인해 필요한 보완과 검증만 하세요. 완료 여부가 불명확하면 검토로 확인하고, 기존 구현의 구체적인 결함이나 변경 요청 없이 재구현하지 마세요.
            아래 지휘 계획·검토 결과와 승인된 플랜을 workflow 기준으로 사용하세요. 자동화의 상태 파일, 실행 스크립트, 완료 마커는 수정하지 마세요.
            OpenCode의 실제 native todo 기능을 사용해 역할 작업을 시작할 때 해야 할 일과 검증 항목을 만들거나 갱신하세요. 끝나지 않은 항목을 완료로 표시하지 마세요. 실제로 마친 항목만 완료로 바꾸고, 남은 문제와 막힌 이유를 최종 JSON에 정직하게 보고하세요.
            서비스처럼 계속 실행될 프로세스는 도구 호출과 분리해 시작하고 즉시 PID를 반환한 뒤 별도 요청으로 상태·HTTP 응답을 확인하세요. 서버를 포그라운드로 실행하거나 종료까지 기다리지 마세요. Windows에서 보조 프로세스는 숨기세요. OpenCode 도구 안의 PowerShell Start-Process에 -RedirectStandardOutput/-RedirectStandardError를 직접 연결하면 서버가 살아 있는 동안 도구 반환이 묶일 수 있으므로 피하세요. Node가 있다면 별도 실행 스크립트에서 child_process.spawn에 detached:true, stdio:'ignore', windowsHide:true를 지정하고 child.unref()를 호출하는 식으로 stdin/stdout/stderr를 분리하세요. 로그가 필요하면 파이프 대신 전용 파일 핸들을 사용하세요. 실행 중인 다른 프로젝트의 서버를 중단하거나 같은 서비스를 중복 실행하지 마세요.
            웹의 핵심 입력은 계산 엔진 단위 테스트나 HTML 소스 확인만으로 통과 처리하지 마세요. 실제 브라우저의 키보드·클릭 이벤트로 사용자 입력, 화면 갱신, 오류·복구를 확인하고 관찰한 결과를 보고하세요. 독립적인 브라우저 검증을 수행할 수 없다면 그 사실을 남기고 확인한 척하지 마세요.
            승인된 플랜에 Persisted plan Markdown 경로가 있으면 각 역할을 시작할 때 그 파일을 직접 다시 읽고 최신 저장 내용을 따르세요. 파일이 없거나 삭제·비어 있음·읽기 실패이면 이전 스냅샷으로 진행하지 말고 중단 사유를 보고하세요. 승인된 플랜 스냅샷은 실행 시작 시점의 기록입니다.
            최종 응답은 설명이나 코드 블록 없이 다음 JSON 객체 하나만 출력하세요. 값은 한국어로 작성하세요.
            {resultContract}
            complete는 검토자만 true로 설정할 수 있습니다. PlanReview에서는 complete=false로 두고 계획 승인 여부만 planApproved로 반환하세요. Verification의 complete=true는 구현 검증 통과이며 아직 프로젝트 완료가 아닙니다. 실제 서비스 실행과 사용자에게 표시한 결과를 FinalVerification에서 다시 검증해야 전체 완료됩니다.
            Planning 단계의 Coordinator는 반드시 planning 객체를 채워 반환하세요. planning에는 goalsAndScope(목표와 범위 문자열), ideasAndChoices(구체적인 아이디어·개선안·선택지 배열), designFilesTasks(설계·변경 파일·작업 배열), orderedImplementation(순서가 있는 구현 단계 배열), risksAndEdgeCases(위험·경계 사례 배열), acceptanceTests(실행할 인수 테스트 배열), serviceDemo(실제로 실행해 사용자에게 보여줄 명령·주소·창·정상 동작 확인 방법 문자열)를 모두 포함해야 합니다. 각 문자열과 배열 항목은 비어 있으면 안 됩니다. 이 구조는 내용의 충분함을 검사하기 위한 것이며 항목 수나 글자 수를 임의로 제한하지 않습니다. 다른 단계에서는 planning을 null로 둘 수 있습니다.
            deliveryEvidence는 실제 실행 명령·작업 폴더·프로세스/PID·접속 주소 또는 앱 창·관찰한 정상 응답과 사용자에게 표시한 결과를 담은 문자열입니다. 실행하지 않았거나 확인하지 못했다면 null로 두세요. 임의 주소, 예정된 명령, 빌드 성공만으로 실행 근거를 대신하지 마세요.

            ## 승인된 플랜 스냅샷 (실행 시작 시점 기록)
            {claim.ApprovedPlanSnapshot}

            ## 지휘 계획 및 인수 기준
            {claim.CoordinatorPlan ?? "아직 작성되지 않았습니다."}

            ## 구조화된 지휘 계획
            {(claim.CoordinatorPlanningPlan is null ? "아직 구조화된 계획이 작성되지 않았습니다." : JsonSerializer.Serialize(claim.CoordinatorPlanningPlan, WireJsonOptions))}

            ## 최근 검토 결과
            {claim.LastReviewSummary ?? "아직 검토되지 않았습니다."}

            ## 실제 서비스 실행 근거
            {claim.DeliveryEvidence ?? "아직 실행을 확인하지 않았습니다."}

            ## 이전 단계 결과
            {previousResult}
            """;
        const string schema = """
            {"type":"object","properties":{"summary":{"type":"string"},"instruction":{"type":"string"},"complete":{"type":"boolean"},"planApproved":{"type":"boolean"},"deliveryEvidence":{"type":["string","null"]},"planning":{"type":["object","null"],"properties":{"goalsAndScope":{"type":"string"},"ideasAndChoices":{"type":"array","items":{"type":"string"}},"designFilesTasks":{"type":"array","items":{"type":"string"}},"orderedImplementation":{"type":"array","items":{"type":"string"}},"risksAndEdgeCases":{"type":"array","items":{"type":"string"}},"acceptanceTests":{"type":"array","items":{"type":"string"}},"serviceDemo":{"type":"string"}},"required":["goalsAndScope","ideasAndChoices","designFilesTasks","orderedImplementation","risksAndEdgeCases","acceptanceTests","serviceDemo"],"additionalProperties":false}},"required":["summary","instruction","complete","planApproved","deliveryEvidence","planning"],"additionalProperties":false}
            """;
        if (nativeSession)
        {
            await File.WriteAllTextAsync(promptPath, prompt, new UTF8Encoding(false));
            await File.WriteAllTextAsync(schemaPath, schema, new UTF8Encoding(false));
            return new(directory, prompt, resultPath, completionPath, eventsPath, claim.Role)
            {
                WorkflowPhase = claim.WorkflowPhase
            };
        }
        string qProject = QuotePowerShell(project), qPrompt = QuotePowerShell(promptPath);
        string script = $$"""
            $ErrorActionPreference = 'Stop'
            $OutputEncoding = [Text.UTF8Encoding]::new($false)
            [Console]::OutputEncoding = [Text.UTF8Encoding]::new($false)
            $stageExit = -1
            $stageError = ''
            try {
                Set-Location -LiteralPath {{qProject}}
                $agentCommand = Get-Command opencode -CommandType Application,ExternalScript -ErrorAction Stop | Select-Object -First 1
                $stagePrompt = [IO.File]::ReadAllText({{qPrompt}}, [Text.Encoding]::UTF8)
                $agentArguments = @('run', '--format', 'json', '--auto')
                {{(string.IsNullOrWhiteSpace(model) ? "" : "$agentArguments += @('--model', " + QuotePowerShell(model) + ")")}}
                $ErrorActionPreference = 'Continue'
                $stagePrompt | & $agentCommand.Source @agentArguments 2>&1 | ForEach-Object {
                    $stageLine = $_.ToString()
                    [IO.File]::AppendAllText({{QuotePowerShell(eventsPath)}}, $stageLine + [Environment]::NewLine, [Text.UTF8Encoding]::new($false))
                    Write-Output $stageLine
                }
                $stageExit = $LASTEXITCODE
                if ($null -eq $stageExit) { $stageExit = -1 }
            }
            catch { $stageError = $_.Exception.Message; Write-Output $stageError }
            finally {
                $stageCompletion = @{ exitCode = $stageExit; error = $stageError } | ConvertTo-Json -Compress
                [IO.File]::WriteAllText({{QuotePowerShell(completionPath + ".tmp")}}, $stageCompletion, [Text.UTF8Encoding]::new($false))
                [IO.File]::Move({{QuotePowerShell(completionPath + ".tmp")}}, {{QuotePowerShell(completionPath)}})
            }
            """;
        await File.WriteAllTextAsync(promptPath, prompt, new UTF8Encoding(false));
        await File.WriteAllTextAsync(schemaPath, schema, new UTF8Encoding(false));
        await File.WriteAllTextAsync(scriptPath, script, new UTF8Encoding(true)); // Windows PowerShell 5.1 needs BOM for Korean paths.
        return new(directory, "powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File " + QuotePowerShell(scriptPath), resultPath, completionPath, eventsPath, claim.Role)
        {
            WorkflowPhase = claim.WorkflowPhase
        };
    }

    private static string ContinuousImprovementInstructions(AutomationStepClaim claim)
    {
        if (!claim.Options.ContinuousImprovement) return "";
        string history = string.Join("\n", claim.ImprovementHistory.TakeLast(12).Select(item =>
            $"주기 {item.Cycle}: {item.Goal}\n검증 결과: {item.Summary}\n실행 근거: {item.Evidence}"));
        return $"""
            지속 개선 모드 · 개선 주기 {claim.ImprovementCycle}
            사용자가 중단할 때까지 프로젝트를 발전시키는 작업입니다. '계속할까요'를 묻거나 '계속' 입력을 기다리지 마세요.
            첫 주기는 사용자의 MD 목표를 달성하세요. 이후에는 최신 MD의 목적과 제약을 지키면서 현재 코드·실제 오류·이전 검토를 근거로 다음 개선을 선정하세요.
            지휘자는 매 주기 버그 수정, 안정성·성능·사용성 개선, 관련 기능 추가 후보를 비교하고 실제 가치와 새 검증 기준이 있는 작은 목표 하나를 정하세요.
            단순 재검토 반복, 이름만 바꾼 동일 작업, 검증된 코드의 불필요한 재작성은 진행으로 인정하지 마세요. 조사에서 새 문제가 없으면 경계 사례와 회귀 테스트의 실제 공백을 찾아 보완하세요.
            검토자는 이전 완료 목표와 비교해 새 계획의 가치·중복·범위를 먼저 확인하고, 해당 주기의 목표와 기존 기능 회귀를 독립 검증하세요.
            이전 주기가 완료된 뒤의 구현·검증·최종 판정은 이번 지휘 계획의 인수 기준 및 원래 MD의 유지 조건을 함께 적용하세요.
            complete=true는 현재 주기의 검증 완료입니다. 다음 주기 여부는 프로그램이 최신 설정·종료 시간을 확인해 결정합니다. 종료 시간이 지나거나 사용자가 지속 개선을 해제해도 이번 주기는 최종 검토까지 마무리하세요.
            설정된 종료 시간: {claim.Options.ImprovementUntil?.ToString("yyyy-MM-dd HH:mm zzz") ?? "제한 없음"}. 관련 없는 기능이나 외부 배포·결제·파괴적 변경으로 범위를 넓히지 마세요.
            최근 검증을 통과한 개선 기록:
            {history}
            """;
    }

    private static string RoleInstructions(AutomationStepClaim claim) => (claim.Role, claim.WorkflowPhase) switch
    {
        (AutomationRole.Coordinator, AutomationWorkflowPhase.Planning) =>
            "지휘자입니다. 사용자의 원본 plan.md를 읽기 전용으로만 읽고 절대 수정·덮어쓰기하지 마세요. 프로젝트 소스와 설정도 조사해 원본 요구사항을 목표와 범위로 분해하고, 빠진 요구사항·구체적인 아이디어·개선안·대안과 선택 이유를 확장하세요. planning 객체의 goalsAndScope에는 달성 목표·범위·비범위를, ideasAndChoices에는 구체적인 개선·추가·수정안과 선택지를, designFilesTasks에는 설계·변경할 파일/모듈·작업을, orderedImplementation에는 의존성을 반영한 순서를, risksAndEdgeCases에는 실패·경계 사례와 완화책을, acceptanceTests에는 실제 실행할 인수 테스트와 관찰 결과를, serviceDemo에는 실제 서비스를 실행해 사용자에게 보여줄 명령·작업 폴더·주소/창·핵심 동작 확인 방법을 기록하세요. 각 항목은 프로젝트에 근거한 구체적인 내용이어야 하며 빈 배열이나 요약 한 줄로 대체하지 마세요. summary에도 계획의 핵심과 인수 기준을 남기되 영어 표제 형식에 의존하지 마세요. 이전 계획 검토의 지적을 반영하세요. instruction은 `Reviewer verification:`으로 시작해 계획을 충분히 검토하도록 지시하세요. 계획이 승인되기 전에는 파일 수정·구현·빌드·테스트·서비스 실행을 하지 마세요. enriched planning 결과는 이 단계의 구조화된 결과로만 반환하며 원본 plan.md에는 쓰지 마세요. terminal-notes 자동화 이력은 열지 말고 아래에 전달된 맥락을 사용하세요.",
        (AutomationRole.Reviewer, AutomationWorkflowPhase.PlanReview) =>
            "계획 검토자입니다. 파일을 수정하거나 구현·빌드·테스트·서비스 실행을 하지 마세요. 최신 MD와 지휘 계획을 대조해 요구사항 누락, 설계의 타당성, 구현 가능성, 예외 처리, 인수 기준과 검증 방법, 실제 실행·표시 방법을 충분히 검토하세요. 계획이 원본 MD의 반복, 일반론, 빈 선택지, 실행 근거 없는 약속, 검증할 수 없는 인수 기준처럼 구체적이지 않으면 planApproved=false로 하고 어떤 결정을 어떻게 보완할지 근거와 함께 지휘자에게 돌려보내세요. 계획을 충분히 검토해 구현 가능한 상태일 때만 planApproved=true로 하고 검토 근거를 summary에 남기세요. complete는 항상 false입니다.",
        (AutomationRole.Coordinator, AutomationWorkflowPhase.Delivery) =>
            "지휘자입니다. 구현 검증 결과와 인수 기준을 확인하고 완성된 서비스를 실제 실행해 사용자에게 보여주도록 구체적으로 지시하세요. instruction은 `Implementer action:`으로 시작하세요. 해당 프로젝트의 실제 실행 방법, 정상 동작 확인, 브라우저 또는 앱 창 표시와 유지 방법을 지시하세요. 직접 파일 수정이나 실행은 하지 마세요. 실행 근거가 확보되기 전에는 완료라고 보고하지 마세요.",
        (AutomationRole.Coordinator, _) =>
            "지휘자입니다. 프로젝트가 완성될 때까지 최근 구현·검토 결과와 최신 MD를 비교하고 다음 작업을 통제하세요. 직접 파일 수정·빌드·테스트는 하지 마세요. 한 번에 하나의 검증 가능한 작은 변경 단위를 지시하고 변경 파일, 중단점, 즉시 검토할 기준을 구체적으로 정하세요. 큰 구현을 한 번에 맡기지 말고 작은 구현과 독립 검토 사이에서 계속 다음 지시를 내리세요. 통과한 기준을 보존하고 누락·오류의 원인과 개선안을 검토해 구체적인 수정 범위 및 성공 조건을 `Implementer action:`으로 지시하세요. 현재 구현의 독립적인 확인만 필요하면 `Reviewer verification:`으로 지시하세요. 같은 검토 지적이 반복되면 이전 접근의 실패 이유와 바꿀 방법을 명확히 하세요. 승인받은 계획을 보존하고 아직 확인하지 않은 결과를 성공이라고 표현하지 마세요.",
        (AutomationRole.Implementer, AutomationWorkflowPhase.Delivery) =>
            "서비스 실행 담당 구현자입니다. 검증된 프로젝트를 실제 실행하세요. 이미 실행 중이면 해당 프로젝트의 프로세스·경로·응답을 확인해 재사용하고 중복 서버를 만들지 마세요. 웹 서비스는 로컬 정상 응답과 핵심 화면을 확인하고 실제 주소를 브라우저로 여세요. 데스크톱 앱은 실행해 실제 창을 표시하세요. CLI라면 사용자가 볼 수 있는 터미널에서 실제 동작을 시연하세요. 사용자에게 보여줄 창만 표시하고 보조 프로세스는 숨기세요. 실행한 서비스를 사용자가 확인할 수 있도록 유지하세요. 실행 명령, 작업 폴더, PID, 실제 주소/창, 정상 응답과 표시 근거를 deliveryEvidence와 summary에 남기세요. 실행 실패·필수 설정 누락은 사실대로 보고하고 근거를 만들지 마세요. 외부 배포·유료 서비스 가입은 이 단계에 포함되지 않습니다. instruction은 `Reviewer verification:`으로 시작해 실제 서비스 재확인을 요청하세요.",
        (AutomationRole.Implementer, _) =>
            "구현자입니다. 검토를 통과한 지휘 계획과 최신 MD, 지휘자의 구체적인 작업 범위 안에서 구현·수정하세요. 현재 파일과 작업 결과를 먼저 확인하고 이미 끝난 일을 반복하지 마세요. 이번에 지휘자가 정한 작은 변경 단위까지만 수행하고 검증한 뒤 즉시 검토자에게 넘기세요. 남은 큰 작업을 스스로 계속 확장하지 마세요. 지휘자의 중간 개입으로 멈췄다면 새 지시와 현재 변경분을 다시 대조하세요. 변경했다면 해당 프로젝트의 빌드와 필요한 테스트를 실제로 실행하세요. 관련 변경이 없고 검증 결과가 여전히 유효하면 불필요한 재실행 대신 근거를 적으세요. 빌드 방법이 없거나 실행할 수 없으면 사유를 보고하고 성공했다고 표현하지 마세요. summary에는 변경 파일, 실행한 명령과 실제 결과, 남은 문제를 적으세요. instruction은 `Reviewer verification:`으로 시작하고 검토자가 확인할 기준을 적으세요.",
        (AutomationRole.Reviewer, AutomationWorkflowPhase.FinalVerification) =>
            "최종 검토자입니다. 파일을 수정하지 마세요. 최신 MD의 모든 인수 기준, 실제 빌드·테스트 결과와 서비스 실행 근거를 대조하세요. 보고된 서비스가 지금도 정상 실행되는지 실제 주소 응답/프로세스/앱 창과 핵심 동작을 독립적으로 확인하고 사용자에게 실제 서비스가 표시되었는지 검증하세요. 직접 확인한 실행·표시 근거를 deliveryEvidence에 남기세요. 전부 통과했을 때만 complete=true로 하고 summary에 `Verified criteria:`와 `Verification evidence:` 및 실행 주소/창과 확인 결과를 적으세요. 실패·누락은 complete=false로 구체적인 실패 근거와 수정안을 지휘자에게 돌려보내세요. 빌드 성공이나 구현자의 주장만으로 완료하지 마세요.",
        _ =>
            "검토자입니다. 파일을 수정하지 말고 최신 MD와 지휘 계획의 각 인수 기준을 구현 결과와 실제 빌드·테스트 근거에 대조하세요. 필요한 독립 검증과 핵심 동작 확인을 실제 수행하세요. 모든 기준과 검증이 통과하면 complete=true로 하고 summary에 `Verified criteria:`와 `Verification evidence:`를 적으세요. 이 판정은 서비스 실행 전 검증 통과일 뿐 전체 완료는 아닙니다. 미충족 기준은 complete=false로 하고 `Unmet criterion:`과 `Failing evidence:`에 구체적인 근거를 남기고 지휘자가 수정 작업을 지시할 수 있게 조치를 instruction에 적으세요. 권한·정보 부족도 정확히 보고하세요."
    };

    public static async Task<AutomationStageOutput?> ReadCompletionAsync(AutomationCommand command)
    {
        if (!File.Exists(command.CompletionPath)) return null;
        long tokens = 0;
        try
        {
            using var marker = JsonDocument.Parse(await File.ReadAllTextAsync(command.CompletionPath));
            int exit = marker.RootElement.GetProperty("exitCode").GetInt32();
            string? finalResponse = null;
            string? agentError = null;
            var tokenParts = new HashSet<string>(StringComparer.Ordinal);
            if (File.Exists(command.EventsPath))
            {
                using var stream = new StreamReader(command.EventsPath);
                while (await stream.ReadLineAsync() is { } line)
                {
                    try
                    {
                        using var json = JsonDocument.Parse(line);
                        var evt = json.RootElement;
                        if (evt.ValueKind != JsonValueKind.Object || !evt.TryGetProperty("type", out var type) || type.ValueKind != JsonValueKind.String) continue;
                        string? eventType = type.GetString();
                        if (eventType == "error") agentError = evt.TryGetProperty("error", out var error) ? error.ToString() : "OpenCode 실행 오류";
                        if (evt.TryGetProperty("part", out var part) && part.ValueKind == JsonValueKind.Object)
                        {
                            if (eventType == "text" && part.TryGetProperty("text", out var response) && response.ValueKind == JsonValueKind.String) finalResponse = response.GetString();
                            if (eventType == "step_finish" && part.TryGetProperty("tokens", out var usage) && usage.ValueKind == JsonValueKind.Object)
                            {
                                string fingerprint = part.TryGetProperty("id", out var partId) ? partId.ToString() : line;
                                if (tokenParts.Add(fingerprint))
                                {
                                    long? total = Number(usage, "total");
                                    if (total is not null) tokens += total.Value;
                                    else
                                    {
                                        tokens += (Number(usage, "input") ?? 0) + (Number(usage, "output") ?? 0) + (Number(usage, "reasoning") ?? 0);
                                        if (usage.TryGetProperty("cache", out var cache) && cache.ValueKind == JsonValueKind.Object) tokens += (Number(cache, "read") ?? 0) + (Number(cache, "write") ?? 0);
                                    }
                                }
                            }
                        }
                        // Historical results remain readable after changing the default runner to OpenCode.
                        if (eventType == "turn.completed" && evt.TryGetProperty("usage", out var legacyUsage) && legacyUsage.ValueKind == JsonValueKind.Object)
                        {
                            tokens += (Number(legacyUsage, "input_tokens") ?? 0) + (Number(legacyUsage, "output_tokens") ?? 0);
                        }
                    }
                    catch (JsonException) { }
                }
            }
            if (exit != 0)
            {
                string scriptError = marker.RootElement.TryGetProperty("error", out var markerError) &&
                    markerError.ValueKind == JsonValueKind.String
                    ? markerError.GetString() ?? ""
                    : "";
                string cliOutput = ReadPlainCliFailureOutput(command.EventsPath);
                string detail = BoundFailureText(string.Join(" · ", new[] { scriptError, agentError, cliOutput }
                    .Where(value => !string.IsNullOrWhiteSpace(value))));
                string summary = $"CLI 종료 코드 {exit}" + (detail.Length == 0 ? "" : " · " + detail);
                return new(false, summary, "", false, tokens);
            }
            if (agentError is not null) return new(false, "OpenCode 오류 · " + agentError, "", false, tokens);
            if (!string.IsNullOrWhiteSpace(finalResponse))
            {
                if (!AutomationStageOutputContract.TryParse(
                    finalResponse,
                    command.Role,
                    command.WorkflowPhase,
                    out AutomationStageOutput? parsedOutput,
                    out string? selectedJson,
                    out string? parseError))
                {
                    return new(false, parseError ?? "OpenCode returned an invalid stage result.", "", false, tokens);
                }

                // Output text is never executed as a shell command. Persist only the selected result object.
                await File.WriteAllTextAsync(command.ResultPath, selectedJson!, new UTF8Encoding(false));
                return parsedOutput! with { Tokens = tokens };
            }
            if (!File.Exists(command.ResultPath)) return new(false, "결과 파일이 없어 다음 단계를 실행하지 않았습니다.", "", false, tokens);
            if (!AutomationStageOutputContract.TryParse(
                await File.ReadAllTextAsync(command.ResultPath),
                command.Role,
                command.WorkflowPhase,
                out AutomationStageOutput? resultOutput,
                out _,
                out string? resultError))
            {
                return new(false, resultError ?? "The saved stage result is invalid.", "", false, tokens);
            }

            return resultOutput! with { Tokens = tokens };
        }
        catch (Exception ex) when (ex is JsonException or InvalidOperationException or KeyNotFoundException or IOException or UnauthorizedAccessException)
        {
            return new(false, "단계 결과를 확인하지 못해 다음 작업을 멈췄습니다 · " + ex.Message, "", false, tokens);
        }
    }

    private static long? Number(JsonElement element, string property) =>
        element.TryGetProperty(property, out var value) && value.ValueKind == JsonValueKind.Number && value.TryGetInt64(out var number) && number >= 0 ? number : null;

    private static string ReadPlainCliFailureOutput(string eventsPath)
    {
        if (!File.Exists(eventsPath)) return "";
        try
        {
            using var stream = new FileStream(eventsPath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
            const int tailLength = 16 * 1024;
            long start = Math.Max(0, stream.Length - tailLength);
            stream.Seek(start, SeekOrigin.Begin);
            using var reader = new StreamReader(stream, Encoding.UTF8, detectEncodingFromByteOrderMarks: true, bufferSize: 1024, leaveOpen: false);
            if (start > 0) _ = reader.ReadLine(); // Discard a possibly partial line at the tail boundary.

            var lines = new Queue<string>();
            while (reader.ReadLine() is { } line)
            {
                if (string.IsNullOrWhiteSpace(line) || IsJsonOutputLine(line)) continue;
                string cleaned = BoundFailureText(line, MaxCliFailureLineLength);
                if (cleaned.Length == 0) continue;
                if (lines.Count == 5) lines.Dequeue();
                lines.Enqueue(cleaned);
            }
            return BoundFailureText(string.Join(" · ", lines));
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return "";
        }
    }

    private static bool IsJsonOutputLine(string line)
    {
        try
        {
            using var json = JsonDocument.Parse(line);
            return true;
        }
        catch (JsonException)
        {
            return false;
        }
    }

    private static string BoundFailureText(string value, int maxLength = MaxCliFailureDetailLength)
    {
        var cleaned = new StringBuilder(Math.Min(value.Length, maxLength));
        foreach (char character in value)
        {
            if (char.IsControl(character))
            {
                if (character is '\r' or '\n' or '\t')
                    cleaned.Append(' ');
                continue;
            }
            cleaned.Append(character);
            if (cleaned.Length >= maxLength) break;
        }
        return cleaned.ToString().Trim();
    }
}

/// <summary>Shared validation for native and CLI role output, including plan approval and delivery evidence.</summary>
public static class AutomationStageOutputContract
{
    private const int MaximumJsonDepth = 24;
    private static readonly JsonSerializerOptions WireJsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    public static bool TryParse(
        string text,
        AutomationRole? role,
        out AutomationStageOutput? output,
        out string? selectedJson,
        out string? error)
        => TryParse(text, role, null, out output, out selectedJson, out error);

    /// <summary>
    /// Parses a stage result and, when the phase is Planning, requires the
    /// structured Coordinator planning object. The phase-less overload remains
    /// compatible with historical callers and non-planning output fixtures.
    /// </summary>
    public static bool TryParse(
        string text,
        AutomationRole? role,
        AutomationWorkflowPhase? phase,
        out AutomationStageOutput? output,
        out string? selectedJson,
        out string? error)
    {
        output = null;
        selectedJson = null;
        error = null;
        string? lastValidJson = null;
        AutomationStageOutput? lastValidOutput = null;

        foreach (string candidate in FindObjectCandidates(text))
        {
            try
            {
                using JsonDocument document = JsonDocument.Parse(candidate, new JsonDocumentOptions { MaxDepth = MaximumJsonDepth });
                JsonElement root = document.RootElement;
                if (root.ValueKind != JsonValueKind.Object ||
                    !TryGetSingleProperty(root, "summary", out JsonElement summary) || summary.ValueKind != JsonValueKind.String ||
                    !TryGetSingleProperty(root, "instruction", out JsonElement instruction) || instruction.ValueKind != JsonValueKind.String ||
                    !TryGetSingleProperty(root, "complete", out JsonElement complete) || complete.ValueKind is not (JsonValueKind.True or JsonValueKind.False))
                {
                    continue;
                }

                bool planApproved = false;
                string? deliveryEvidence = null;
                AutomationPlanningOutput? planningPlan = null;
                if (root.TryGetProperty("planApproved", out _))
                {
                    if (!TryGetSingleProperty(root, "planApproved", out JsonElement approval) ||
                        approval.ValueKind is not (JsonValueKind.True or JsonValueKind.False)) continue;
                    planApproved = approval.GetBoolean();
                }
                if (root.TryGetProperty("deliveryEvidence", out _))
                {
                    if (!TryGetSingleProperty(root, "deliveryEvidence", out JsonElement evidence) ||
                        evidence.ValueKind is not (JsonValueKind.String or JsonValueKind.Null)) continue;
                    deliveryEvidence = evidence.ValueKind == JsonValueKind.String ? evidence.GetString()?.Trim() : null;
                }
                if (root.TryGetProperty("planning", out _))
                {
                    if (!TryGetSingleProperty(root, "planning", out JsonElement planning) ||
                        (planning.ValueKind != JsonValueKind.Object && planning.ValueKind != JsonValueKind.Null)) continue;
                    if (planning.ValueKind == JsonValueKind.Object &&
                        !TryParsePlanningOutput(planning, out planningPlan)) continue;
                }
                lastValidJson = candidate;
                lastValidOutput = new AutomationStageOutput(
                    true,
                    summary.GetString() ?? "",
                    instruction.GetString() ?? "",
                    complete.GetBoolean(),
                    0)
                {
                    PlanApproved = role == AutomationRole.Reviewer && planApproved,
                    DeliveryEvidence = string.IsNullOrWhiteSpace(deliveryEvidence) ? null : deliveryEvidence,
                    PlanningPlan = planningPlan
                };
            }
            catch (JsonException)
            {
                // Prose may contain braces or examples; only parseable JSON objects are candidates.
            }
        }

        if (lastValidOutput is null || lastValidJson is null)
        {
            error = "The response does not contain valid standalone JSON with string summary, string instruction, and boolean complete fields.";
            return false;
        }

        if (string.IsNullOrWhiteSpace(lastValidOutput.Summary))
        {
            error = "The stage summary must contain meaningful text.";
            return false;
        }

        if (phase == AutomationWorkflowPhase.Planning && role == AutomationRole.Coordinator)
        {
            if (lastValidOutput.PlanningPlan is null)
            {
                error = "Planning Coordinator output must contain a structured planning object.";
                return false;
            }

            if (!lastValidOutput.PlanningPlan.TryValidate(out string? planningError))
            {
                error = planningError;
                return false;
            }
        }

        // Keep the wire contract strict, but do not fail useful model work because a
        // human-readable label was translated, omitted, or formatted differently.
        // Normalize routing locally so the persisted workflow still has one explicit
        // next role. Only Reviewer may complete a run.
        AutomationStageOutput normalized = NormalizeRoleOutput(lastValidOutput, role);
        output = normalized;
        selectedJson = JsonSerializer.Serialize(new
        {
            summary = normalized.Summary,
            instruction = normalized.Instruction,
            complete = normalized.Complete,
            planApproved = normalized.PlanApproved,
            deliveryEvidence = normalized.DeliveryEvidence,
            planning = normalized.PlanningPlan
        }, WireJsonOptions);
        return true;
    }

    private static bool TryParsePlanningOutput(JsonElement value, out AutomationPlanningOutput? planning)
    {
        planning = null;
        if (!TryGetString(value, "goalsAndScope", out string? goalsAndScope) ||
            !TryGetStringArray(value, "ideasAndChoices", out IReadOnlyList<string>? ideasAndChoices) ||
            !TryGetStringArray(value, "designFilesTasks", out IReadOnlyList<string>? designFilesTasks) ||
            !TryGetStringArray(value, "orderedImplementation", out IReadOnlyList<string>? orderedImplementation) ||
            !TryGetStringArray(value, "risksAndEdgeCases", out IReadOnlyList<string>? risksAndEdgeCases) ||
            !TryGetStringArray(value, "acceptanceTests", out IReadOnlyList<string>? acceptanceTests) ||
            !TryGetString(value, "serviceDemo", out string? serviceDemo))
        {
            return false;
        }

        var candidate = new AutomationPlanningOutput(
            goalsAndScope!,
            ideasAndChoices!,
            designFilesTasks!,
            orderedImplementation!,
            risksAndEdgeCases!,
            acceptanceTests!,
            serviceDemo!);
        if (!candidate.TryValidate(out _)) return false;
        planning = candidate;
        return true;
    }

    private static bool TryGetString(JsonElement root, string name, out string? value)
    {
        value = null;
        return TryGetSingleProperty(root, name, out JsonElement element) &&
            element.ValueKind == JsonValueKind.String &&
            !string.IsNullOrWhiteSpace(value = element.GetString());
    }

    private static bool TryGetStringArray(JsonElement root, string name, out IReadOnlyList<string>? values)
    {
        values = null;
        if (!TryGetSingleProperty(root, name, out JsonElement element) || element.ValueKind != JsonValueKind.Array)
            return false;

        var parsed = new List<string>();
        foreach (JsonElement item in element.EnumerateArray())
        {
            if (item.ValueKind != JsonValueKind.String || string.IsNullOrWhiteSpace(item.GetString()))
                return false;
            parsed.Add(item.GetString()!);
        }

        values = parsed;
        return true;
    }

    private static AutomationStageOutput NormalizeRoleOutput(
        AutomationStageOutput output,
        AutomationRole? role)
    {
        string instruction = output.Instruction.Trim();
        return role switch
        {
            AutomationRole.Coordinator => output with
            {
                Instruction = NormalizeCoordinatorInstruction(instruction),
                Complete = false
            },
            AutomationRole.Implementer => output with
            {
                Instruction = NormalizeInstruction(
                    instruction,
                    "Reviewer verification",
                    "승인된 플랜의 각 기준을 현재 구현과 실제 검증 결과에 대조하세요."),
                Complete = false
            },
            AutomationRole.Reviewer when !output.Complete => output with
            {
                Instruction = NormalizeInstruction(
                    instruction,
                    "Implementer action",
                    "검토 요약의 미충족 사항을 수정하고 필요한 검증을 다시 실행하세요.")
            },
            _ => output
        };
    }

    private static string NormalizeCoordinatorInstruction(string instruction)
    {
        if (StartsWithLabeledValue(instruction, "Implementer action") ||
            StartsWithLabeledValue(instruction, "Reviewer verification"))
            return instruction;

        string lowered = instruction.ToLowerInvariant();
        bool implementation = lowered.Contains("implement", StringComparison.Ordinal) ||
            instruction.Contains("구현", StringComparison.Ordinal) ||
            instruction.Contains("수정", StringComparison.Ordinal) ||
            instruction.Contains("개선", StringComparison.Ordinal);
        bool review = lowered.Contains("review", StringComparison.Ordinal) ||
            lowered.Contains("verify", StringComparison.Ordinal) ||
            instruction.Contains("검토", StringComparison.Ordinal) ||
            instruction.Contains("검증", StringComparison.Ordinal) ||
            instruction.Contains("확인", StringComparison.Ordinal);

        if (!implementation && review)
            return NormalizeInstruction(instruction, "Reviewer verification",
                "승인된 플랜의 각 기준을 현재 구현과 실제 검증 결과에 대조하세요.");
        return NormalizeInstruction(instruction, "Implementer action",
            "승인된 플랜의 요구사항을 구현하고 필요한 검증을 실행하세요.");
    }

    private static string NormalizeInstruction(string instruction, string label, string fallback) =>
        StartsWithLabeledValue(instruction, label)
            ? instruction
            : label + ": " + (string.IsNullOrWhiteSpace(instruction) ? fallback : instruction);

    public static AutomationRole? RoleFromPrompt(string prompt)
    {
        const string headingPrefix = "Terminal Notes 자동화 · ";
        string firstLine = prompt.Split('\n', 2)[0].TrimEnd('\r');
        if (!firstLine.StartsWith(headingPrefix, StringComparison.Ordinal)) return null;

        int roleStart = headingPrefix.Length;
        int roleEnd = firstLine.IndexOf(" · ", roleStart, StringComparison.Ordinal);
        return roleEnd > roleStart && Enum.TryParse(firstLine[roleStart..roleEnd], ignoreCase: false, out AutomationRole role)
            ? role
            : null;
    }

    /// <summary>
    /// Reads the explicit workflow phase embedded in a generated prompt. This is
    /// only a compatibility fallback for callers that do not retain dispatch
    /// metadata; it is not used as semantic evidence of stage completion.
    /// </summary>
    public static AutomationWorkflowPhase? PhaseFromPrompt(string prompt)
    {
        foreach (string rawLine in prompt.Split('\n'))
        {
            string line = rawLine.TrimEnd('\r').Trim();
            const string prefix = "Workflow phase:";
            if (!line.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) continue;
            string value = line[prefix.Length..].Trim();
            return Enum.TryParse(value, ignoreCase: true, out AutomationWorkflowPhase phase)
                ? phase
                : null;
        }

        return null;
    }

    private static IEnumerable<string> FindObjectCandidates(string text)
    {
        for (int start = 0; start < text.Length; start++)
        {
            if (text[start] != '{') continue;
            int depth = 0;
            bool inString = false;
            bool escaped = false;
            for (int end = start; end < text.Length; end++)
            {
                char character = text[end];
                if (inString)
                {
                    if (escaped) escaped = false;
                    else if (character == '\\') escaped = true;
                    else if (character == '"') inString = false;
                    continue;
                }

                if (character == '"') inString = true;
                else if (character == '{') depth++;
                else if (character == '}' && --depth == 0)
                {
                    yield return text[start..(end + 1)];
                    start = end;
                    break;
                }
            }
        }
    }

    private static bool TryGetSingleProperty(JsonElement root, string name, out JsonElement value)
    {
        value = default;
        int count = 0;
        foreach (JsonProperty property in root.EnumerateObject())
        {
            if (!string.Equals(property.Name, name, StringComparison.Ordinal)) continue;
            value = property.Value;
            count++;
        }
        return count == 1;
    }

    private static bool HasLabeledValue(string text, string label)
    {
        string prefix = label + ":";
        foreach (string line in text.Split('\n'))
        {
            string candidate = line.Trim().TrimEnd('\r');
            if (!candidate.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) continue;
            string value = candidate[prefix.Length..].Trim();
            if (value.Length == 0 || value.StartsWith('<') || value.EndsWith('>')) return false;
            return !value.Equals("none", StringComparison.OrdinalIgnoreCase) &&
                !value.Equals("n/a", StringComparison.OrdinalIgnoreCase) &&
                !value.Equals("unknown", StringComparison.OrdinalIgnoreCase) &&
                !value.Equals("tbd", StringComparison.OrdinalIgnoreCase);
        }
        return false;
    }

    private static bool StartsWithLabeledValue(string text, string label)
    {
        string prefix = label + ":";
        if (!text.TrimStart().StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) return false;
        string value = text.TrimStart()[prefix.Length..].Trim();
        return value.Length > 0 && !value.StartsWith('<') && !value.EndsWith('>') &&
            !value.Equals("none", StringComparison.OrdinalIgnoreCase) &&
            !value.Equals("n/a", StringComparison.OrdinalIgnoreCase) &&
            !value.Equals("unknown", StringComparison.OrdinalIgnoreCase) &&
            !value.Equals("tbd", StringComparison.OrdinalIgnoreCase);
    }

    private static bool HasNumberedAcceptanceChecks(string summary)
    {
        string[] lines = summary.Split('\n');
        int section = Array.FindIndex(lines, line =>
            string.Equals(line.Trim().TrimEnd('\r'), "Acceptance checks:", StringComparison.OrdinalIgnoreCase));
        if (section < 0) return false;

        for (int index = section + 1; index < lines.Length; index++)
        {
            string line = lines[index].Trim().TrimEnd('\r');
            if (line.Length == 0) continue;
            int cursor = 0;
            while (cursor < line.Length && char.IsDigit(line[cursor])) cursor++;
            if (cursor == 0 || cursor + 1 >= line.Length || line[cursor] != '.' || !char.IsWhiteSpace(line[cursor + 1]))
                return false;
            return !string.IsNullOrWhiteSpace(line[(cursor + 1)..]);
        }
        return false;
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_AUTOMATIONDIAGNOSTICS_CS
#region Services/AutomationDiagnostics.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Text;
using global::System.Text.Json;
using global::System.Text.RegularExpressions;


/// <summary>Operational metadata only: never terminal input, prompts, credentials or HTTP bodies.</summary>
public sealed record AutomationDiagnosticEvent(
    DateTimeOffset Timestamp, string EventName, string Severity, string Detail,
    string? Role = null, string? Phase = null, Guid? RunId = null, Guid? DispatchToken = null)
{
    public int SchemaVersion { get; init; } = 1;
    public long Sequence { get; init; }
    public int ProcessId { get; init; } = Environment.ProcessId;
    public string BuildId { get; init; } = typeof(AutomationDiagnostics).Module.ModuleVersionId.ToString("N");
    public long? Revision { get; init; }
    public int? Iteration { get; init; }
    public string? SessionId { get; init; }
    public string? MessageId { get; init; }
    public string? ExceptionType { get; init; }
    public string? ErrorCode { get; init; }
    public string? ProjectDirectory { get; init; }
    public DateTimeOffset? LastSubstantiveProgressAt { get; init; }
    public bool? RequiresUserAction { get; init; }
    public AutomationPaneDiagnostic? Pane { get; init; }
}

public sealed record AutomationPaneDiagnostic(
    string NativeStatus, bool IsReady, bool IsRunning, bool CanStart,
    bool AutomationActive, bool HasEndpoint, bool HasPendingInput,
    bool InputBlocked, bool ManualOverride, bool Failed, bool Disposed, bool Cancelled)
{
    public string? ConnectionFailure { get; init; }
}

public static class AutomationDiagnostics
{
    private static readonly SemaphoreSlim WriteGate = new(1, 1);
    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase };
    private static readonly Regex Credentials = new(
        "(?i)([\\\"']?(?:authorization|api[_-]?key|access[_-]?token|refresh[_-]?token|password|secret)[\\\"']?\\s*[:=]\\s*)(?:[\\\"'][^\\\"']*[\\\"']|[^\\s,;]+)",
        RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));
    private static readonly Regex Bearer = new("(?i)\\b(Bearer|Basic)\\s+[A-Za-z0-9+/=_\\-.]+", RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));
    private static readonly Regex UrlCredentials = new("(?i)(https?://)[^\\s/@]+:[^\\s/@]+@", RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));
    private static readonly Regex UrlQuery = new("(?i)(https?://[^\\s?#]+)[?#][^\\s]+", RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));

    public static string LogPath(string project, Guid runId) =>
        Path.Combine(Path.GetFullPath(project), "terminal-notes", "runs", runId.ToString("N"), "diagnostics.jsonl");

    public static string Sanitize(string? value)
    {
        if (string.IsNullOrEmpty(value)) return "";
        string text = value.Length > 4096 ? value[..4096] + "…" : value;
        try
        {
            text = Bearer.Replace(text, "$1 [redacted]");
            text = Credentials.Replace(text, "$1[redacted]");
            text = UrlCredentials.Replace(text, "$1[redacted]@");
            return UrlQuery.Replace(text, "$1?[redacted]");
        }
        catch (RegexMatchTimeoutException) { return "[diagnostic detail omitted: redaction timeout]"; }
    }

    public static async Task AppendAsync(string path, AutomationDiagnosticEvent entry)
    {
#if TN_WPF
        // Only the operational event identifier crosses into always-on support logs.
        // Detail, project paths, request IDs and terminal content stay in the existing diagnostic stream.
        if (entry.Severity is "error" or "fatal" or "warning")
            ApplicationDiagnostics.RecordOperational("automation." + entry.Severity, entry.Severity, "automation", entry.EventName);
#endif
        // Serialize writes and flush every line; a failed diagnostic must be surfaced
        // by its host, but must never cause a native prompt to be submitted again.
        await WriteGate.WaitAsync().ConfigureAwait(false);
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
            string line = JsonSerializer.Serialize(entry with
            {
                Detail = Sanitize(entry.Detail),
                Pane = entry.Pane is { } pane ? pane with { ConnectionFailure = Sanitize(pane.ConnectionFailure) } : null
            }, JsonOptions) + "\n";
            await using var stream = new FileStream(path, FileMode.Append, FileAccess.Write, FileShare.Read,
                4096, FileOptions.Asynchronous);
            await stream.WriteAsync(Encoding.UTF8.GetBytes(line)).ConfigureAwait(false);
            await stream.FlushAsync().ConfigureAwait(false);
        }
        finally { WriteGate.Release(); }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_AUTOMATIONRUN_CS
#region Services/AutomationRun.cs
namespace TerminalNotes.Services
{

public enum AutomationState
{
    Draft,
    Scheduled,
    Running,
    Paused,
    Stopped,
    Completed,
    Failed
}

public enum AutomationRole
{
    Coordinator,
    Implementer,
    Reviewer
}

/// <summary>
/// Persistent workflow stage. Planning is zero so older JSON ledgers without a phase
/// default safely into the new plan review workflow.
/// </summary>
public enum AutomationWorkflowPhase
{
    Planning,
    PlanReview,
    Implementation,
    Verification,
    Delivery,
    FinalVerification
}

public sealed record AutomationExecutionOptions(
    string? CoordinatorModel = null,
    string? ImplementerModel = null,
    string? ReviewerModel = null,
    int? TokenBudget = null,
    int? MaxStageMinutes = null)
{
    public bool ContinuousImprovement { get; init; }
    public bool RecommendPlan { get; init; }
    public DateTimeOffset? ImprovementUntil { get; init; }
    public bool CanStartImprovementCycle(DateTimeOffset now) =>
        ContinuousImprovement && (ImprovementUntil is null || now < ImprovementUntil);
    public string? ModelFor(AutomationRole role) => role switch
    {
        AutomationRole.Coordinator => CoordinatorModel,
        AutomationRole.Implementer => ImplementerModel,
        AutomationRole.Reviewer => ReviewerModel,
        _ => throw new ArgumentOutOfRangeException(nameof(role))
    };
}

/// <summary>
/// Persisted workflow state. The approved plan is fixed; improvement preferences can change while running.
/// Revision and ActiveDispatchToken protect state from stale process completions.
/// </summary>
public sealed record AutomationRun(
    Guid Id,
    string ProjectDirectory,
    string ApprovedPlanSnapshot,
    AutomationExecutionOptions Options,
    // Nullable so new runs can have no iteration cap. A numeric value from an older
    // ledger remains available as historical metadata only.
    int? MaxIterations,
    int Iteration,
    AutomationState State,
    AutomationRole NextRole,
    DateTimeOffset CreatedAt,
    DateTimeOffset UpdatedAt,
    DateTimeOffset? ScheduledFor,
    Guid? ActiveDispatchToken,
    long Revision,
    bool PauseAfterCurrentStage,
    long TotalTokenUsage,
    string? LastSummary,
    string? NextInstruction,
    string? StatusDetail)
{
    // Additive persisted fields keep prior version-1 ledgers readable while retaining
    // review feedback across the Implementer stage for repeat detection.
    public string? LastReviewerFeedbackFingerprint { get; init; }
    public string? LastReviewerFeedbackInstruction { get; init; }

    // Consecutive failures for NextRole. This is persisted so retries survive an app
    // restart and so a role can never be skipped merely because OpenCode returned an
    // invalid response or its process ended. It resets only after a valid stage result.
    public int CurrentRoleRetryCount { get; init; }

    // Missing phase in an older version-1 ledger defaults to Planning. The store
    // migrates incompatible old roles back through Commander planning before resume.
    public AutomationWorkflowPhase WorkflowPhase { get; init; }
    public bool PlanApproved { get; init; }
    public string? CoordinatorPlan { get; init; }
    /// <summary>
    /// Structured plan produced by the Coordinator during Planning. This is kept
    /// separately from the user's original plan.md snapshot; the Coordinator is
    /// instructed to read that file and never modify it.
    /// </summary>
    public AutomationPlanningOutput? CoordinatorPlanningPlan { get; init; }
    public string? LastReviewSummary { get; init; }
    public string? LastReviewInstruction { get; init; }
    public string? DeliveryEvidence { get; init; }
    public string? FinalVerificationEvidence { get; init; }
    public int ImprovementCycle { get; init; } = 1;
    public IReadOnlyList<AutomationImprovementOutcome> ImprovementHistory { get; init; } = [];
}

public sealed record AutomationImprovementOutcome(int Cycle, string Goal, string PlanFingerprint,
    string Summary, string Evidence, DateTimeOffset VerifiedAt);

public sealed record AutomationStepClaim(
    Guid RunId,
    Guid DispatchToken,
    long Revision,
    AutomationRole Role,
    int Iteration,
    string ProjectDirectory,
    string ApprovedPlanSnapshot,
    AutomationExecutionOptions Options,
    long TotalTokenUsage,
    string? PreviousSummary,
    string? Instruction,
    DateTimeOffset ClaimedAt)
{
    public AutomationWorkflowPhase WorkflowPhase { get; init; }
    public bool PlanApproved { get; init; }
    public string? CoordinatorPlan { get; init; }
    public AutomationPlanningOutput? CoordinatorPlanningPlan { get; init; }
    public string? LastReviewSummary { get; init; }
    public string? LastReviewInstruction { get; init; }
    public string? DeliveryEvidence { get; init; }
    public int ImprovementCycle { get; init; } = 1;
    public IReadOnlyList<AutomationImprovementOutcome> ImprovementHistory { get; init; } = [];
}

/// <summary>
/// Structured result from one CLI process. Phase-gated completion additionally requires
/// successful plan approval, launch evidence, and final reviewer verification.
/// TokenUsage is the non-negative usage attributable to this stage.
/// </summary>
public sealed record AutomationStepResult(
    Guid RunId,
    Guid DispatchToken,
    long ExpectedRevision,
    bool Succeeded,
    string Summary,
    string Instruction,
    bool Complete,
    long TokenUsage,
    DateTimeOffset CompletedAt)
{
    public bool Interrupted { get; init; }
    public bool PlanApproved { get; init; }
    public string? DeliveryEvidence { get; init; }
    public AutomationPlanningOutput? PlanningPlan { get; init; }
}

/// <summary>
/// The structured output required from the first Coordinator Planning stage.
/// Each section is intentionally unbounded: validation checks presence and
/// meaningful content, not arbitrary word or item counts.
/// </summary>
public sealed record AutomationPlanningOutput(
    string GoalsAndScope,
    IReadOnlyList<string> IdeasAndChoices,
    IReadOnlyList<string> DesignFilesTasks,
    IReadOnlyList<string> OrderedImplementation,
    IReadOnlyList<string> RisksAndEdgeCases,
    IReadOnlyList<string> AcceptanceTests,
    string ServiceDemo)
{
    /// <summary>Human-readable rendering for the automation detail view and persisted diagnostics.</summary>
    public string ToMarkdown()
    {
        static string Items(IEnumerable<string>? values) => string.Join(Environment.NewLine, (values ?? Array.Empty<string>()).Select(value => $"- {value}"));
        return $"""
            ## 목표와 범위
            {GoalsAndScope}

            ## 아이디어·개선안·선택지
            {Items(IdeasAndChoices)}

            ## 설계·파일·작업
            {Items(DesignFilesTasks)}

            ## 구현 순서
            {Items(OrderedImplementation)}

            ## 위험과 경계 사례
            {Items(RisksAndEdgeCases)}

            ## 인수 테스트
            {Items(AcceptanceTests)}

            ## 실제 서비스 시연
            {ServiceDemo}
            """.Trim();
    }

    public bool TryValidate(out string? error)
    {
        if (string.IsNullOrWhiteSpace(GoalsAndScope))
            return Fail("planning.goalsAndScope must contain meaningful text.", out error);
        if (!ValidateItems(IdeasAndChoices, "planning.ideasAndChoices", out error)) return false;
        if (!ValidateItems(DesignFilesTasks, "planning.designFilesTasks", out error)) return false;
        if (!ValidateItems(OrderedImplementation, "planning.orderedImplementation", out error)) return false;
        if (!ValidateItems(RisksAndEdgeCases, "planning.risksAndEdgeCases", out error)) return false;
        if (!ValidateItems(AcceptanceTests, "planning.acceptanceTests", out error)) return false;
        if (string.IsNullOrWhiteSpace(ServiceDemo))
            return Fail("planning.serviceDemo must describe an actual service demonstration.", out error);

        error = null;
        return true;
    }

    private static bool ValidateItems(IReadOnlyList<string>? values, string path, out string? error)
    {
        if (values is null || values.Count == 0)
            return Fail($"{path} must contain at least one meaningful item.", out error);

        foreach (string? value in values)
        {
            if (string.IsNullOrWhiteSpace(value))
                return Fail($"{path} contains an empty item.", out error);
        }

        error = null;
        return true;
    }

    private static bool Fail(string message, out string? error)
    {
        error = message;
        return false;
    }
}

public sealed record AutomationCompletionResult(
    bool Accepted,
    AutomationRun Run,
    AutomationStepClaim? NextClaim,
    string? RejectionReason);
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_AUTOMATIONSTORE_CS
#region Services/AutomationStore.cs
namespace TerminalNotes.Services
{
using global::System.Collections.Concurrent;
using global::System.IO;
using global::System.Security.Cryptography;
using global::System.Text;
using global::System.Text.Json;
using global::System.Text.Json.Serialization;


/// <summary>
/// Atomic project-local persistence and transition logic for scheduled automation runs.
/// The host must remain open (or in its tray lifetime) to poll and dispatch scheduled work.
/// </summary>
public sealed class AutomationStore
{
    private const int StoreVersion = 1;
    private const string LegacyIterationLimitDetail = "Maximum iteration count reached.";
    private const string InterruptedStageDetail = "앱 종료로 결과 미확인; 기록 확인 후 재개";
    private const string OrphanedStageDetail = "스케줄러 소유권 종료 후 복구됨. 재개 전에 기록을 확인하세요.";
    private static readonly TimeSpan MaximumRetryDelay = TimeSpan.FromSeconds(30);

    private static readonly ConcurrentDictionary<string, SemaphoreSlim> ProcessGates =
        new(OperatingSystem.IsWindows() ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal);
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        WriteIndented = true,
        Converters = { new JsonStringEnumConverter() }
    };

    private readonly string _projectDirectory;
    private readonly string _storeDirectory;
    private readonly string _storePath;
    private readonly string _lockPath;
    private readonly SemaphoreSlim _processGate;

    public AutomationStore(string projectDirectory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(projectDirectory);
        _projectDirectory = Path.GetFullPath(projectDirectory);
        _storeDirectory = Path.Combine(_projectDirectory, "terminal-notes");
        _storePath = Path.Combine(_storeDirectory, "automation-runs.json");
        _lockPath = Path.Combine(_storeDirectory, ".automation-runs.lock");
        _processGate = ProcessGates.GetOrAdd(_storePath, static _ => new SemaphoreSlim(1, 1));
    }

    public string ProjectDirectory => _projectDirectory;
    public string StorePath => _storePath;

    public async Task<AutomationRun> CreateDraftAsync(
        string approvedPlanSnapshot,
        int? maxIterations = null,
        AutomationExecutionOptions? options = null,
        DateTimeOffset? createdAt = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(approvedPlanSnapshot);
        options ??= new AutomationExecutionOptions();
        ValidateOptions(options);
        DateTimeOffset now = createdAt ?? DateTimeOffset.UtcNow;

        return await MutateAsync((ledger, _) =>
        {
            var run = new AutomationRun(
                Guid.NewGuid(),
                _projectDirectory,
                approvedPlanSnapshot,
                options,
                maxIterations,
                Iteration: 1,
                AutomationState.Draft,
                AutomationRole.Coordinator,
                now,
                now,
                ScheduledFor: null,
                ActiveDispatchToken: null,
                Revision: 0,
                PauseAfterCurrentStage: false,
                TotalTokenUsage: 0,
                LastSummary: null,
                NextInstruction: null,
                StatusDetail: null)
            {
                WorkflowPhase = AutomationWorkflowPhase.Planning
            };
            ledger.Runs.Add(run);
            return (run, true);
        }, cancellationToken);
    }

    public async Task<IReadOnlyList<AutomationRun>> LoadAsync(
        CancellationToken cancellationToken = default) =>
        await ReadAsync(ledger => (IReadOnlyList<AutomationRun>)ledger.Runs.ToArray(), cancellationToken);

    public async Task<AutomationRun?> GetAsync(
        Guid runId,
        CancellationToken cancellationToken = default) =>
        await ReadAsync(ledger => ledger.Runs.FirstOrDefault(run => run.Id == runId), cancellationToken);

    public async Task<AutomationRun> ScheduleAsync(
        Guid runId,
        DateTimeOffset scheduledFor,
        long? expectedRevision = null,
        CancellationToken cancellationToken = default) =>
        await MutateAsync((ledger, now) =>
        {
            int index = FindRun(ledger, runId);
            AutomationRun run = ledger.Runs[index];
            CheckRevision(run, expectedRevision);
            if (run.State != AutomationState.Draft)
            {
                throw new InvalidOperationException("Only a draft automation run can be scheduled.");
            }

            AutomationRun updated = run with
            {
                State = AutomationState.Scheduled,
                ScheduledFor = scheduledFor,
                UpdatedAt = now,
                Revision = run.Revision + 1,
                StatusDetail = null
            };
            ledger.Runs[index] = updated;
            return (updated, true);
        }, cancellationToken);

    /// <summary>
    /// Starts a newly approved plan in one ledger transaction. Existing active runs
    /// block the request; paused runs are retired but remain in history.
    /// </summary>
    public async Task<AutomationRun> StartApprovedPlanAsync(
        string approvedPlanSnapshot,
        int? maxIterations = null,
        AutomationExecutionOptions? options = null,
        DateTimeOffset? scheduledFor = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(approvedPlanSnapshot);
        options ??= new AutomationExecutionOptions();
        ValidateOptions(options);

        return await MutateAsync((ledger, now) =>
        {
            if (ledger.Runs.Any(run => run.State is AutomationState.Running or AutomationState.Scheduled))
                throw new InvalidOperationException("An active automation run must finish or stop before starting a new approved plan.");

            for (int index = 0; index < ledger.Runs.Count; index++)
            {
                AutomationRun run = ledger.Runs[index];
                if (run.State != AutomationState.Paused) continue;

                ledger.Runs[index] = run with
                {
                    State = AutomationState.Stopped,
                    ActiveDispatchToken = null,
                    ScheduledFor = null,
                    PauseAfterCurrentStage = false,
                    UpdatedAt = now,
                    Revision = run.Revision + 1
                };
            }

            var started = new AutomationRun(
                Guid.NewGuid(),
                _projectDirectory,
                approvedPlanSnapshot,
                options,
                maxIterations,
                Iteration: 1,
                AutomationState.Scheduled,
                AutomationRole.Coordinator,
                now,
                now,
                ScheduledFor: scheduledFor ?? now,
                ActiveDispatchToken: null,
                Revision: 0,
                PauseAfterCurrentStage: false,
                TotalTokenUsage: 0,
                LastSummary: null,
                NextInstruction: null,
                StatusDetail: null)
            {
                WorkflowPhase = AutomationWorkflowPhase.Planning
            };
            ledger.Runs.Add(started);
            return (started, true);
        }, cancellationToken);
    }

    /// <summary>
    /// Claims every due scheduled run in one persisted transaction. A claimed run remains Running
    /// across restarts and is never returned by this method again.
    /// </summary>
    public Task<IReadOnlyList<AutomationStepClaim>> ClaimDueAsync(
        DateTimeOffset now,
        CancellationToken cancellationToken = default) =>
        ClaimDueAsync(now, int.MaxValue, cancellationToken);

    public async Task<IReadOnlyList<AutomationStepClaim>> ClaimDueAsync(
        DateTimeOffset now,
        int maxClaims,
        CancellationToken cancellationToken = default)
    {
        if (maxClaims < 1)
        {
            throw new ArgumentOutOfRangeException(nameof(maxClaims));
        }

        return await MutateAsync((ledger, _) =>
        {
            var claims = new List<AutomationStepClaim>();
            bool changed = false;
            int[] dueIndexes = ledger.Runs
                .Select((run, index) => (Run: run, Index: index))
                .Where(item => item.Run.State == AutomationState.Scheduled &&
                    item.Run.ScheduledFor is not null &&
                    item.Run.ScheduledFor <= now)
                .OrderBy(item => item.Run.ScheduledFor)
                .ThenBy(item => item.Run.CreatedAt)
                .Take(maxClaims)
                .Select(item => item.Index)
                .ToArray();
            foreach (int index in dueIndexes)
            {
                AutomationRun run = ledger.Runs[index];
                if (FinishWaitingImprovement(run, now) is { } finished)
                {
                    ledger.Runs[index] = finished;
                    changed = true;
                    continue;
                }
                run = NormalizePhaseRole(run);
                Guid token = Guid.NewGuid();
                AutomationRun claimed = run with
                {
                    State = AutomationState.Running,
                    ActiveDispatchToken = token,
                    ScheduledFor = null,
                    UpdatedAt = now,
                    Revision = run.Revision + 1,
                    StatusDetail = null
                };
                ledger.Runs[index] = claimed;
                claims.Add(ToClaim(claimed, token, now));
            }

            return ((IReadOnlyList<AutomationStepClaim>)claims, changed || claims.Count > 0);
        }, cancellationToken);
    }

    /// <summary>
    /// Recovers work from a prior app lifetime, optionally scheduling authorized unfinished work.
    /// Queued user pauses remain paused. The host must hold its single-scheduler lock before calling.
    /// </summary>
    public async Task<IReadOnlyList<AutomationRun>> RecoverInterruptedAsync(
        DateTimeOffset? recoveredAt = null,
        CancellationToken cancellationToken = default,
        bool includeScheduled = false,
        bool resumeAutomatically = false) =>
        await MutateAsync((ledger, now) =>
        {
            DateTimeOffset timestamp = recoveredAt ?? now;
            var recovered = new List<AutomationRun>();
            for (int index = 0; index < ledger.Runs.Count; index++)
            {
                AutomationRun run = ledger.Runs[index];
                bool interrupted = run.State == AutomationState.Running;
                bool abandonedSchedule = includeScheduled && run.State == AutomationState.Scheduled;
                if (!interrupted && !abandonedSchedule)
                {
                    continue;
                }

                AutomationRun updated = run with
                {
                    State = AutomationState.Paused,
                    ActiveDispatchToken = null,
                    ScheduledFor = null,
                    PauseAfterCurrentStage = false,
                    UpdatedAt = timestamp,
                    Revision = run.Revision + 1,
                    StatusDetail = interrupted
                        ? InterruptedStageDetail
                        : "앱 시작 시 예약 작업 복구; 기록 확인 후 재개"
                };
                // Only previously authorized work is restored. A user-requested
                // pause survives a crash, including a pause queued during a stage.
                if (resumeAutomatically && !run.PauseAfterCurrentStage)
                {
                    updated = NormalizePhaseRole(updated);
                    if (interrupted) updated = RouteInterruptedImplementerToReviewer(updated);
                    updated = updated with
                    {
                        State = AutomationState.Scheduled,
                        ScheduledFor = abandonedSchedule && run.ScheduledFor > timestamp ? run.ScheduledFor : timestamp,
                        StatusDetail = "중단된 연결 복구 · 기존 작업 자동 재개"
                    };
                }
                ledger.Runs[index] = updated;
                recovered.Add(updated);
            }

            return ((IReadOnlyList<AutomationRun>)recovered, recovered.Count > 0);
        }, cancellationToken);

    /// <summary>
    /// Pauses one Running claim after its scheduler owner has independently established that no
    /// live scheduler still owns it. The expected dispatch token and revision prevent recovery
    /// from invalidating a claim that has since advanced or changed.
    /// </summary>
    public async Task<AutomationRun?> TryRecoverOrphanedRunningAsync(
        Guid runId,
        Guid expectedDispatchToken,
        long expectedRevision,
        DateTimeOffset? recoveredAt = null,
        CancellationToken cancellationToken = default,
        bool resumeAutomatically = false)
    {
        if (runId == Guid.Empty)
        {
            throw new ArgumentException("A run ID is required.", nameof(runId));
        }

        if (expectedDispatchToken == Guid.Empty)
        {
            throw new ArgumentException("A dispatch token is required.", nameof(expectedDispatchToken));
        }

        if (expectedRevision < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(expectedRevision));
        }

        return await MutateAsync((ledger, now) =>
        {
            int index = FindRun(ledger, runId);
            AutomationRun run = ledger.Runs[index];
            if (run.State != AutomationState.Running ||
                run.ActiveDispatchToken != expectedDispatchToken ||
                run.Revision != expectedRevision)
            {
                return (null, false);
            }

            AutomationRun updated = run with
            {
                State = AutomationState.Paused,
                ActiveDispatchToken = null,
                ScheduledFor = null,
                PauseAfterCurrentStage = false,
                UpdatedAt = recoveredAt ?? now,
                Revision = run.Revision + 1,
                StatusDetail = OrphanedStageDetail
            };
            if (resumeAutomatically && !run.PauseAfterCurrentStage)
            {
                updated = RouteInterruptedImplementerToReviewer(NormalizePhaseRole(updated)) with
                {
                    State = AutomationState.Scheduled,
                    ScheduledFor = recoveredAt ?? now,
                    StatusDetail = "실행 연결 복구 · 기존 작업 자동 재개"
                };
            }
            ledger.Runs[index] = updated;
            return ((AutomationRun?)updated, true);
        }, cancellationToken);
    }

    public async Task<AutomationCompletionResult> CompleteStepAsync(
        AutomationStepResult result,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(result);
        if (result.TokenUsage < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(result), "Token usage cannot be negative.");
        }

        return await MutateAsync((ledger, _) =>
        {
            int index = FindRun(ledger, result.RunId);
            AutomationRun run = ledger.Runs[index];
            if (run.State != AutomationState.Running ||
                run.ActiveDispatchToken != result.DispatchToken ||
                run.Revision != result.ExpectedRevision)
            {
                return (new AutomationCompletionResult(
                    Accepted: false,
                    run,
                    NextClaim: null,
                    RejectionReason: "The stage completion is stale or the run is no longer running."), false);
            }

            long totalTokens;
            try
            {
                totalTokens = checked(run.TotalTokenUsage + result.TokenUsage);
            }
            catch (OverflowException exception)
            {
                throw new InvalidDataException("The accumulated token usage is too large.", exception);
            }

            long nextRevision = run.Revision + 1;
            AutomationRun updated = run with
            {
                ActiveDispatchToken = null,
                UpdatedAt = result.CompletedAt,
                Revision = nextRevision,
                TotalTokenUsage = totalTokens,
                LastSummary = result.Summary,
                NextInstruction = result.Instruction,
                StatusDetail = null
            };

            AutomationStepClaim? nextClaim = null;
            if (!result.Succeeded)
            {
                updated = ScheduleSameRoleRetry(
                    updated,
                    run,
                    result.CompletedAt,
                    string.IsNullOrWhiteSpace(result.Summary)
                        ? "The automation stage failed."
                        : result.Summary);
                if (result.Interrupted)
                {
                    // The native supervisor has confirmed quiescence. A partially
                    // applied implementation must be inspected before more writes.
                    updated = RouteInterruptedImplementerToReviewer(updated);
                    updated = updated with
                    {
                        DeliveryEvidence = run.NextRole == AutomationRole.Implementer ? null : run.DeliveryEvidence,
                        FinalVerificationEvidence = run.NextRole == AutomationRole.Implementer ? null : run.FinalVerificationEvidence,
                        NextInstruction = run.NextRole == AutomationRole.Implementer
                            ? $"중단 복구: {result.Summary}\n현재 파일·변경분·실행 상태를 독립적으로 검토하고 완료된 부분과 남은 작업을 지휘자에게 보고하세요. 구현을 그대로 반복하지 마세요.\n" + run.NextInstruction
                            : run.NextInstruction,
                        StatusDetail = $"{result.Summary} 다음: {updated.NextRole} · {updated.State}"
                    };
                }
            }
            else if (GetInvalidWorkflowOutputDetail(run, result) is string invalidWorkflowOutputDetail)
            {
                updated = ScheduleSameRoleRetry(updated, run, result.CompletedAt, invalidWorkflowOutputDetail);
            }
            else if (run.Options.ContinuousImprovement && run.WorkflowPhase == AutomationWorkflowPhase.Planning &&
                     result.PlanningPlan is { } proposal && run.ImprovementHistory.Any(prior =>
                         prior.PlanFingerprint == ImprovementPlanFingerprint(proposal)))
            {
                updated = ScheduleSameRoleRetry(updated, run, result.CompletedAt,
                    "이미 검증을 마친 개선 계획입니다. 현재 코드와 남은 문제를 조사해 다른 개선 목표와 인수 테스트를 정하세요.");
            }
            else if (run.WorkflowPhase == AutomationWorkflowPhase.FinalVerification &&
                result.Complete &&
                run.PlanApproved &&
                !string.IsNullOrWhiteSpace(run.DeliveryEvidence))
            {
                updated = updated with
                {
                    State = AutomationState.Completed,
                    FinalVerificationEvidence = result.DeliveryEvidence,
                    LastReviewSummary = result.Summary,
                    LastReviewInstruction = result.Instruction,
                    LastReviewerFeedbackFingerprint = string.IsNullOrWhiteSpace(result.Instruction)
                        ? run.LastReviewerFeedbackFingerprint
                        : FingerprintReviewerFeedback(result.Instruction),
                    LastReviewerFeedbackInstruction = string.IsNullOrWhiteSpace(result.Instruction)
                        ? run.LastReviewerFeedbackInstruction
                        : result.Instruction,
                    PauseAfterCurrentStage = false,
                    CurrentRoleRetryCount = 0,
                    StatusDetail = string.IsNullOrWhiteSpace(result.Summary)
                        ? "The reviewer verified the delivered service."
                        : result.Summary
                };
                if (run.Options.CanStartImprovementCycle(result.CompletedAt))
                {
                    // Persist completion and the next cycle in one transaction.
                    // A crash cannot lose the result or start duplicate cycles.
                    var outcome = new AutomationImprovementOutcome(run.ImprovementCycle,
                        run.CoordinatorPlanningPlan?.GoalsAndScope ?? run.CoordinatorPlan ?? "",
                        ImprovementPlanFingerprint(run.CoordinatorPlanningPlan), result.Summary,
                        result.DeliveryEvidence!, result.CompletedAt);
                    updated = updated with
                    {
                        State = run.PauseAfterCurrentStage ? AutomationState.Paused : AutomationState.Scheduled,
                        ScheduledFor = run.PauseAfterCurrentStage ? null : result.CompletedAt.AddSeconds(30),
                        NextRole = AutomationRole.Coordinator,
                        WorkflowPhase = AutomationWorkflowPhase.Planning,
                        ImprovementCycle = checked(run.ImprovementCycle + 1),
                        ImprovementHistory = [.. run.ImprovementHistory, outcome],
                        PlanApproved = false,
                        CoordinatorPlan = null,
                        CoordinatorPlanningPlan = null,
                        DeliveryEvidence = null,
                        FinalVerificationEvidence = null,
                        NextInstruction = "직전 개선은 독립 검증을 통과했습니다. 최신 MD와 현재 코드를 조사하고 버그 수정·품질 개선·관련 기능 추가 중 다음으로 가치 있는 작은 목표를 선정하세요. 완료한 작업을 반복하지 말고 근거, 변경 범위, 새 인수 테스트를 포함한 계획을 검토자에게 제출하세요.",
                        StatusDetail = run.PauseAfterCurrentStage ? "개선 주기 검증 완료 · 일시정지" : "개선 주기 검증 완료 · 다음 개선 준비"
                    };
                }
            }
            else
            {
                updated = AdvanceWorkflowStage(updated, run, result);

                if (run.PauseAfterCurrentStage)
                {
                    updated = updated with
                    {
                        State = AutomationState.Paused,
                        ActiveDispatchToken = null,
                        ScheduledFor = null,
                        PauseAfterCurrentStage = false,
                        StatusDetail = "Paused after the current stage."
                    };
                }
                else
                {
                    Guid nextToken = Guid.NewGuid();
                    updated = updated with
                    {
                        State = AutomationState.Running,
                        ActiveDispatchToken = nextToken,
                        PauseAfterCurrentStage = false
                    };
                    nextClaim = ToClaim(updated, nextToken, result.CompletedAt);
                }
            }

            ledger.Runs[index] = updated;
            return (new AutomationCompletionResult(true, updated, nextClaim, null), true);
        }, cancellationToken);
    }

    // This preference does not revoke a dispatch. Keep its revision/token valid so
    // the current result can commit and final verification reads the latest option.
    public async Task<AutomationRun> SetContinuousImprovementAsync(Guid runId, bool enabled,
        DateTimeOffset? until, CancellationToken cancellationToken = default, bool recommendPlan = false) =>
        await MutateAsync((ledger, now) =>
        {
            int index = FindRun(ledger, runId);
            AutomationRun run = ledger.Runs[index];
            if (run.State is AutomationState.Completed or AutomationState.Stopped or AutomationState.Failed)
                return (run, false);
            if (run.Options.ContinuousImprovement == enabled && run.Options.ImprovementUntil == until && run.Options.RecommendPlan == recommendPlan)
                return (run, false);
            var updated = run with
            {
                Options = run.Options with { ContinuousImprovement = enabled, ImprovementUntil = until, RecommendPlan = recommendPlan },
                UpdatedAt = now
            };
            updated = FinishWaitingImprovement(updated, now) ?? updated;
            ledger.Runs[index] = updated;
            return (updated, true);
        }, cancellationToken);

    private static AutomationRun? FinishWaitingImprovement(AutomationRun run, DateTimeOffset now)
    {
        // Between verified cycles there is no unfinished work to launch. Expiry
        // and manual disable must also win the race with the next scheduler poll.
        if (run.State is not (AutomationState.Scheduled or AutomationState.Paused) ||
            run.WorkflowPhase != AutomationWorkflowPhase.Planning || run.CoordinatorPlan is not null ||
            run.ImprovementHistory.LastOrDefault() is not { } previous ||
            run.Options.CanStartImprovementCycle(now)) return null;
        return run with
        {
            State = AutomationState.Completed, ScheduledFor = null, ActiveDispatchToken = null,
            PauseAfterCurrentStage = false, Revision = run.Revision + 1, UpdatedAt = now,
            WorkflowPhase = AutomationWorkflowPhase.FinalVerification, NextRole = AutomationRole.Reviewer,
            ImprovementCycle = previous.Cycle, LastSummary = previous.Summary,
            FinalVerificationEvidence = previous.Evidence,
            StatusDetail = "Loop 종료 · 마지막 개선 검증 완료"
        };
    }

    /// <summary>
    /// Pauses immediately when idle/scheduled. During an active stage, records a pause request and
    /// accepts that stage's result before entering Paused without issuing another claim.
    /// </summary>
    public async Task<AutomationRun> PauseAsync(
        Guid runId,
        CancellationToken cancellationToken = default) =>
        await MutateAsync((ledger, now) =>
        {
            int index = FindRun(ledger, runId);
            AutomationRun run = ledger.Runs[index];
            if (run.State == AutomationState.Paused)
            {
                return (run, false);
            }

            if (run.State is AutomationState.Completed or AutomationState.Failed or AutomationState.Stopped)
            {
                throw new InvalidOperationException($"A {run.State} automation run cannot be paused.");
            }

            AutomationRun updated;
            if (run.State == AutomationState.Running && run.ActiveDispatchToken is not null)
            {
                // Keep Revision unchanged so the in-flight result remains valid.
                updated = run with
                {
                    PauseAfterCurrentStage = true,
                    UpdatedAt = now,
                    StatusDetail = "Pause requested; waiting for the current stage."
                };
            }
            else
            {
                updated = run with
                {
                    State = AutomationState.Paused,
                    ActiveDispatchToken = null,
                    ScheduledFor = null,
                    PauseAfterCurrentStage = false,
                    UpdatedAt = now,
                    Revision = run.Revision + 1,
                    StatusDetail = "Paused."
                };
            }

            ledger.Runs[index] = updated;
            return (updated, true);
        }, cancellationToken);

    public async Task<AutomationRun> ResumeAsync(
        Guid runId,
        DateTimeOffset scheduledFor,
        long? expectedRevision = null,
        CancellationToken cancellationToken = default,
        bool allowStopped = false) =>
        await MutateAsync((ledger, now) =>
        {
            int index = FindRun(ledger, runId);
            AutomationRun run = ledger.Runs[index];
            CheckRevision(run, expectedRevision);
            if (run.State != AutomationState.Paused &&
                !(allowStopped && run.State is AutomationState.Stopped or AutomationState.Failed))
            {
                throw new InvalidOperationException("Only a paused automation run can be resumed.");
            }

            if (ledger.Runs.Any(candidate => candidate.Id != runId &&
                candidate.State is AutomationState.Running or AutomationState.Scheduled))
            {
                throw new InvalidOperationException(
                    "An active automation run must finish or stop before resuming this run.");
            }

            // Old ledgers lack WorkflowPhase. Their old implementer/reviewer position
            // cannot safely bypass the plan review gate, so resume them at Planning.
            AutomationRun normalized = NormalizePhaseRole(run);
            bool positionChanged = normalized.WorkflowPhase != run.WorkflowPhase ||
                normalized.NextRole != run.NextRole;

            // Old iteration-cap pauses also re-enter through the current plan gate.
            if (string.Equals(run.StatusDetail, LegacyIterationLimitDetail, StringComparison.Ordinal))
            {
                normalized = normalized with
                {
                    WorkflowPhase = AutomationWorkflowPhase.Planning,
                    NextRole = AutomationRole.Coordinator,
                    PlanApproved = false,
                    DeliveryEvidence = null,
                    FinalVerificationEvidence = null
                };
                positionChanged = true;
            }

            bool interruptedStage = string.Equals(run.StatusDetail, InterruptedStageDetail, StringComparison.Ordinal) ||
                string.Equals(run.StatusDetail, OrphanedStageDetail, StringComparison.Ordinal) ||
                run.State is AutomationState.Stopped or AutomationState.Failed;
            if (interruptedStage && !positionChanged)
            {
                normalized = RouteInterruptedImplementerToReviewer(normalized);
            }

            AutomationRun updated = normalized with
            {
                State = AutomationState.Scheduled,
                ScheduledFor = scheduledFor,
                ActiveDispatchToken = null,
                PauseAfterCurrentStage = false,
                UpdatedAt = now,
                Revision = run.Revision + 1,
                StatusDetail = null
            };
            ledger.Runs[index] = updated;
            return (updated, true);
        }, cancellationToken);

    public async Task<AutomationRun> StopAsync(
        Guid runId,
        CancellationToken cancellationToken = default) =>
        await MutateAsync((ledger, now) =>
        {
            int index = FindRun(ledger, runId);
            AutomationRun run = ledger.Runs[index];
            if (run.State == AutomationState.Stopped)
            {
                return (run, false);
            }

            if (run.State is AutomationState.Completed or AutomationState.Failed)
            {
                throw new InvalidOperationException($"A {run.State} automation run cannot be stopped.");
            }

            AutomationRun updated = run with
            {
                State = AutomationState.Stopped,
                ScheduledFor = null,
                ActiveDispatchToken = null,
                PauseAfterCurrentStage = false,
                UpdatedAt = now,
                Revision = run.Revision + 1,
                StatusDetail = "Stopped by the user."
            };
            ledger.Runs[index] = updated;
            return (updated, true);
        }, cancellationToken);

    private static AutomationRun AdvanceWorkflowStage(
        AutomationRun updated,
        AutomationRun original,
        AutomationStepResult result)
    {
        updated = updated with { CurrentRoleRetryCount = 0 };

        return (original.WorkflowPhase, original.NextRole) switch
        {
            (AutomationWorkflowPhase.Planning, AutomationRole.Coordinator) => updated with
            {
                CoordinatorPlan = result.Summary,
                CoordinatorPlanningPlan = result.PlanningPlan,
                PlanApproved = false,
                WorkflowPhase = AutomationWorkflowPhase.PlanReview,
                NextRole = AutomationRole.Reviewer
            },
            (AutomationWorkflowPhase.PlanReview, AutomationRole.Reviewer) => updated with
            {
                PlanApproved = result.PlanApproved,
                LastReviewSummary = result.Summary,
                LastReviewInstruction = result.Instruction,
                LastReviewerFeedbackFingerprint = FingerprintReviewerFeedback(result.Instruction),
                LastReviewerFeedbackInstruction = result.Instruction,
                WorkflowPhase = result.PlanApproved
                    ? AutomationWorkflowPhase.Implementation
                    : AutomationWorkflowPhase.Planning,
                NextRole = AutomationRole.Coordinator
            },
            (AutomationWorkflowPhase.Implementation, AutomationRole.Coordinator) =>
                TryGetCoordinatorNextRole(result.Instruction, out AutomationRole requestedRole) &&
                requestedRole == AutomationRole.Reviewer
                    ? updated with
                    {
                        WorkflowPhase = AutomationWorkflowPhase.Verification,
                        NextRole = AutomationRole.Reviewer
                    }
                    : updated with { NextRole = AutomationRole.Implementer },
            (AutomationWorkflowPhase.Implementation, AutomationRole.Implementer) => updated with
            {
                WorkflowPhase = AutomationWorkflowPhase.Verification,
                NextRole = AutomationRole.Reviewer
            },
            (AutomationWorkflowPhase.Verification, AutomationRole.Reviewer) => updated with
            {
                LastReviewSummary = result.Summary,
                LastReviewInstruction = result.Instruction,
                LastReviewerFeedbackFingerprint = FingerprintReviewerFeedback(result.Instruction),
                LastReviewerFeedbackInstruction = result.Instruction,
                WorkflowPhase = result.Complete
                    ? AutomationWorkflowPhase.Delivery
                    : AutomationWorkflowPhase.Implementation,
                NextRole = AutomationRole.Coordinator,
                Iteration = result.Complete ? original.Iteration : IncrementIteration(original.Iteration)
            },
            (AutomationWorkflowPhase.Delivery, AutomationRole.Coordinator) => updated with
            {
                NextRole = AutomationRole.Implementer
            },
            (AutomationWorkflowPhase.Delivery, AutomationRole.Implementer) =>
                string.IsNullOrWhiteSpace(result.DeliveryEvidence)
                    ? updated with
                    {
                        WorkflowPhase = AutomationWorkflowPhase.Implementation,
                        NextRole = AutomationRole.Coordinator,
                        StatusDetail = "Service launch evidence was missing; Commander review is required."
                    }
                    : updated with
                    {
                        DeliveryEvidence = result.DeliveryEvidence,
                        WorkflowPhase = AutomationWorkflowPhase.FinalVerification,
                        NextRole = AutomationRole.Reviewer
                    },
            (AutomationWorkflowPhase.FinalVerification, AutomationRole.Reviewer) => updated with
            {
                LastReviewSummary = result.Summary,
                LastReviewInstruction = result.Instruction,
                LastReviewerFeedbackFingerprint = FingerprintReviewerFeedback(result.Instruction),
                LastReviewerFeedbackInstruction = result.Instruction,
                WorkflowPhase = AutomationWorkflowPhase.Implementation,
                NextRole = AutomationRole.Coordinator,
                Iteration = IncrementIteration(original.Iteration),
                DeliveryEvidence = null,
                FinalVerificationEvidence = null
            },
            _ => throw new InvalidOperationException(
                $"The workflow cannot advance from {original.WorkflowPhase}/{original.NextRole}.")
        };
    }

    private static AutomationRun NormalizePhaseRole(AutomationRun run)
    {
        if (IsRoleValidForPhase(run.WorkflowPhase, run.NextRole) &&
            (run.WorkflowPhase is AutomationWorkflowPhase.Planning or AutomationWorkflowPhase.PlanReview || run.PlanApproved))
        {
            return run;
        }

        return run with
        {
            WorkflowPhase = AutomationWorkflowPhase.Planning,
            NextRole = AutomationRole.Coordinator,
            PlanApproved = false,
            DeliveryEvidence = null,
            FinalVerificationEvidence = null
        };
    }

    private static AutomationRun RouteInterruptedImplementerToReviewer(AutomationRun run) =>
        (run.WorkflowPhase, run.NextRole) switch
        {
            (AutomationWorkflowPhase.Implementation, AutomationRole.Implementer) => run with
            {
                WorkflowPhase = AutomationWorkflowPhase.Verification,
                NextRole = AutomationRole.Reviewer
            },
            (AutomationWorkflowPhase.Delivery, AutomationRole.Implementer) => run with
            {
                WorkflowPhase = AutomationWorkflowPhase.Verification,
                NextRole = AutomationRole.Reviewer
            },
            _ => run
        };

    private static bool TryGetCoordinatorNextRole(string instruction, out AutomationRole role)
    {
        string trimmed = instruction.Trim();
        if (trimmed.StartsWith("Reviewer verification:", StringComparison.OrdinalIgnoreCase))
        {
            role = AutomationRole.Reviewer;
            return true;
        }

        if (trimmed.StartsWith("Implementer action:", StringComparison.OrdinalIgnoreCase))
        {
            role = AutomationRole.Implementer;
            return true;
        }

        role = default;
        return false;
    }

    private static bool IsRoleValidForPhase(AutomationWorkflowPhase phase, AutomationRole role) =>
        (phase, role) switch
        {
            (AutomationWorkflowPhase.Planning, AutomationRole.Coordinator) => true,
            (AutomationWorkflowPhase.PlanReview, AutomationRole.Reviewer) => true,
            (AutomationWorkflowPhase.Implementation, AutomationRole.Coordinator or AutomationRole.Implementer) => true,
            (AutomationWorkflowPhase.Verification, AutomationRole.Reviewer) => true,
            (AutomationWorkflowPhase.Delivery, AutomationRole.Coordinator or AutomationRole.Implementer) => true,
            (AutomationWorkflowPhase.FinalVerification, AutomationRole.Reviewer) => true,
            _ => false
        };

    private static AutomationRun ScheduleSameRoleRetry(
        AutomationRun updated,
        AutomationRun original,
        DateTimeOffset completedAt,
        string failureDetail)
    {
        int retryCount = original.CurrentRoleRetryCount == int.MaxValue
            ? int.MaxValue
            : original.CurrentRoleRetryCount + 1;

        if (original.PauseAfterCurrentStage)
        {
            return updated with
            {
                State = AutomationState.Paused,
                ScheduledFor = null,
                ActiveDispatchToken = null,
                PauseAfterCurrentStage = false,
                CurrentRoleRetryCount = retryCount,
                NextInstruction = original.NextInstruction,
                StatusDetail = $"{failureDetail} Paused before retrying {original.NextRole}."
            };
        }

        TimeSpan delay = RetryDelay(retryCount);
        return updated with
        {
            State = AutomationState.Scheduled,
            NextRole = original.NextRole,
            Iteration = original.Iteration,
            ScheduledFor = completedAt + delay,
            ActiveDispatchToken = null,
            PauseAfterCurrentStage = false,
            CurrentRoleRetryCount = retryCount,
            NextInstruction = original.NextInstruction,
            StatusDetail = $"{failureDetail} Retrying {original.NextRole} (attempt {retryCount + 1}) in {delay.TotalSeconds:0} seconds."
        };
    }

    private static TimeSpan RetryDelay(int retryCount)
    {
        int exponent = Math.Clamp(retryCount - 1, 0, 5);
        double seconds = Math.Min(Math.Pow(2, exponent), MaximumRetryDelay.TotalSeconds);
        return TimeSpan.FromSeconds(seconds);
    }

    private static string? GetInvalidWorkflowOutputDetail(
        AutomationRun run,
        AutomationStepResult result)
    {
        AutomationRole role = run.NextRole;
        if (!IsRoleValidForPhase(run.WorkflowPhase, role))
        {
            return $"The {role} claim does not match workflow phase {run.WorkflowPhase}.";
        }

        if (string.IsNullOrWhiteSpace(result.Summary))
        {
            return $"The {role} returned an empty summary.";
        }

        if (run.WorkflowPhase == AutomationWorkflowPhase.Planning && role == AutomationRole.Coordinator)
        {
            if (result.PlanningPlan is null)
                return "The Planning Coordinator must return a structured planning object.";
            if (!result.PlanningPlan.TryValidate(out string? planningError))
                return planningError ?? "The structured planning object is incomplete.";
        }

        bool completionCandidate = run.WorkflowPhase is AutomationWorkflowPhase.Verification or AutomationWorkflowPhase.FinalVerification &&
            role == AutomationRole.Reviewer && result.Complete;
        bool finalApproval = run.WorkflowPhase == AutomationWorkflowPhase.FinalVerification &&
            role == AutomationRole.Reviewer && result.Complete;
        bool instructionRequired = !completionCandidate;
        if (instructionRequired && string.IsNullOrWhiteSpace(result.Instruction))
        {
            return role == AutomationRole.Reviewer
                ? "The reviewer returned no instruction for the next workflow step."
                : $"The {role} returned no instruction for the next role.";
        }

        if (result.Complete && !completionCandidate)
        {
            return "Only a reviewer can submit a completion candidate.";
        }

        if (finalApproval && string.IsNullOrWhiteSpace(result.DeliveryEvidence))
        {
            return "The final reviewer did not provide independent service verification evidence.";
        }

        if (run.WorkflowPhase is not (AutomationWorkflowPhase.Planning or AutomationWorkflowPhase.PlanReview) &&
            !run.PlanApproved)
        {
            return "Implementation is blocked until the reviewer approves the plan.";
        }

        return null;
    }

    private static string FingerprintReviewerFeedback(string instruction)
    {
        string normalized = string.Join(
            ' ',
            instruction
                .Normalize(NormalizationForm.FormKC)
                .Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries))
            .ToUpperInvariant();
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(normalized)));
    }

    private static AutomationStepClaim ToClaim(
        AutomationRun run,
        Guid token,
        DateTimeOffset claimedAt) =>
        new(
            run.Id,
            token,
            run.Revision,
            run.NextRole,
            run.Iteration,
            run.ProjectDirectory,
            run.ApprovedPlanSnapshot,
            run.Options,
            run.TotalTokenUsage,
            run.LastSummary,
            run.NextInstruction,
            claimedAt)
        {
            WorkflowPhase = run.WorkflowPhase,
            PlanApproved = run.PlanApproved,
            CoordinatorPlan = run.CoordinatorPlan,
            CoordinatorPlanningPlan = run.CoordinatorPlanningPlan,
            LastReviewSummary = run.LastReviewSummary,
            LastReviewInstruction = run.LastReviewInstruction,
            DeliveryEvidence = run.DeliveryEvidence,
            ImprovementCycle = run.ImprovementCycle,
            ImprovementHistory = run.ImprovementHistory
        };

    private static string ImprovementPlanFingerprint(AutomationPlanningOutput? plan) =>
        FingerprintReviewerFeedback(plan is null ? "" : plan.GoalsAndScope + "\n" +
            string.Join("\n", plan.DesignFilesTasks) + "\n" + string.Join("\n", plan.AcceptanceTests));

    private async Task<T> ReadAsync<T>(
        Func<AutomationLedger, T> read,
        CancellationToken cancellationToken)
    {
        await _processGate.WaitAsync(cancellationToken);
        try
        {
            ProjectArchiveService.ThrowIfRelocated(_projectDirectory);
            Directory.CreateDirectory(_storeDirectory);
            await using FileStream fileLock = await AcquireFileLockAsync(cancellationToken);
            (AutomationLedger ledger, _) = await ReadLedgerAsync(cancellationToken);
            return read(ledger);
        }
        finally
        {
            _processGate.Release();
        }
    }

    private async Task<T> MutateAsync<T>(
        Func<AutomationLedger, DateTimeOffset, (T Result, bool Changed)> mutation,
        CancellationToken cancellationToken)
    {
        await _processGate.WaitAsync(cancellationToken);
        try
        {
            ProjectArchiveService.ThrowIfRelocated(_projectDirectory);
            Directory.CreateDirectory(_storeDirectory);
            await using FileStream fileLock = await AcquireFileLockAsync(cancellationToken);
            (AutomationLedger ledger, byte[]? originalBytes) = await ReadLedgerAsync(cancellationToken);
            (T result, bool changed) = mutation(ledger, DateTimeOffset.UtcNow);
            if (changed)
            {
                VerifyUnchanged(originalBytes);
                byte[] bytes = JsonSerializer.SerializeToUtf8Bytes(ledger, JsonOptions);
                await AtomicWriteAsync(_storePath, bytes, cancellationToken);
            }

            return result;
        }
        finally
        {
            _processGate.Release();
        }
    }

    private async Task<FileStream> AcquireFileLockAsync(CancellationToken cancellationToken)
    {
        for (int attempt = 0; ; attempt++)
        {
            cancellationToken.ThrowIfCancellationRequested();
            try
            {
                return new FileStream(
                    _lockPath,
                    FileMode.OpenOrCreate,
                    FileAccess.ReadWrite,
                    FileShare.None,
                    bufferSize: 1,
                    FileOptions.Asynchronous);
            }
            catch (IOException) when (attempt < 200)
            {
                await Task.Delay(25, cancellationToken);
            }
        }
    }

    private async Task<(AutomationLedger Ledger, byte[]? OriginalBytes)> ReadLedgerAsync(
        CancellationToken cancellationToken)
    {
        if (!File.Exists(_storePath))
        {
            return (new AutomationLedger(), null);
        }

        byte[] bytes = await File.ReadAllBytesAsync(_storePath, cancellationToken);
        try
        {
            AutomationLedger? ledger = JsonSerializer.Deserialize<AutomationLedger>(bytes, JsonOptions);
            if (ledger is null || ledger.Version != StoreVersion || ledger.Runs is null)
            {
                throw new InvalidDataException("The automation store has an unsupported structure.");
            }

            ProjectArchiveService.RebindRuns(_projectDirectory, ledger.Runs);
            ValidateLedger(ledger);
            return (ledger, bytes);
        }
        catch (JsonException exception)
        {
            throw new InvalidDataException(
                $"The automation store is malformed and was left unchanged: {_storePath}",
                exception);
        }
    }

    private void ValidateLedger(AutomationLedger ledger)
    {
        var ids = new HashSet<Guid>();
        foreach (AutomationRun run in ledger.Runs)
        {
            if (run.Id == Guid.Empty || !ids.Add(run.Id) ||
                string.IsNullOrWhiteSpace(run.ApprovedPlanSnapshot) ||
                !Enum.IsDefined(run.State) ||
                !Enum.IsDefined(run.NextRole) ||
                !Enum.IsDefined(run.WorkflowPhase) ||
                !PathsEqual(run.ProjectDirectory, _projectDirectory) ||
                run.Iteration < 1 ||
                run.Revision < 0 || run.TotalTokenUsage < 0)
            {
                throw new InvalidDataException("The automation store contains an invalid run.");
            }

            ValidateOptions(run.Options);

            bool mustHaveToken = run.State == AutomationState.Running;
            if (mustHaveToken != (run.ActiveDispatchToken is not null) ||
                (run.State == AutomationState.Scheduled) != (run.ScheduledFor is not null))
            {
                throw new InvalidDataException("The automation store contains inconsistent dispatch state.");
            }
        }
    }

    private void VerifyUnchanged(byte[]? originalBytes)
    {
        if (originalBytes is null)
        {
            if (File.Exists(_storePath))
            {
                throw new AutomationStoreConflictException(
                    _storePath,
                    "The automation store appeared while it was being updated.");
            }

            return;
        }

        if (!File.Exists(_storePath) ||
            !File.ReadAllBytes(_storePath).AsSpan().SequenceEqual(originalBytes))
        {
            throw new AutomationStoreConflictException(
                _storePath,
                "The automation store changed outside Terminal Notes.");
        }
    }

    private static async Task AtomicWriteAsync(
        string destination,
        byte[] bytes,
        CancellationToken cancellationToken)
    {
        string directory = Path.GetDirectoryName(destination)
            ?? throw new DirectoryNotFoundException(destination);
        string temporaryPath = Path.Combine(directory, $".terminalnotes-{Guid.NewGuid():N}.tmp");
        try
        {
            await using (var stream = new FileStream(
                temporaryPath,
                FileMode.CreateNew,
                FileAccess.Write,
                FileShare.None,
                bufferSize: 64 * 1024,
                FileOptions.Asynchronous | FileOptions.WriteThrough))
            {
                await stream.WriteAsync(bytes, cancellationToken);
                await stream.FlushAsync(cancellationToken);
                stream.Flush(flushToDisk: true);
            }

            if (File.Exists(destination))
            {
                File.Move(temporaryPath, destination, overwrite: true);
            }
            else
            {
                File.Move(temporaryPath, destination);
            }

            temporaryPath = string.Empty;
        }
        finally
        {
            if (temporaryPath.Length > 0)
            {
                try { File.Delete(temporaryPath); } catch (IOException) { }
            }
        }
    }

    private static int FindRun(AutomationLedger ledger, Guid runId)
    {
        int index = ledger.Runs.FindIndex(run => run.Id == runId);
        return index >= 0
            ? index
            : throw new KeyNotFoundException($"Automation run was not found: {runId}");
    }

    private static void CheckRevision(AutomationRun run, long? expectedRevision)
    {
        if (expectedRevision is not null && run.Revision != expectedRevision)
        {
            throw new InvalidOperationException("The automation run changed after it was displayed.");
        }
    }

    private static void ValidateOptions(AutomationExecutionOptions? options)
    {
        if (options is null)
        {
            throw new InvalidDataException("The automation ledger contains missing execution options.");
        }
    }

    private static int IncrementIteration(int iteration) =>
        iteration == int.MaxValue ? int.MaxValue : iteration + 1;

    private static bool PathsEqual(string first, string second) =>
        string.Equals(
            Path.GetFullPath(first),
            Path.GetFullPath(second),
            OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);

    private sealed class AutomationLedger
    {
        public int Version { get; set; } = StoreVersion;
        public List<AutomationRun> Runs { get; set; } = [];
    }
}

public sealed class AutomationStoreConflictException : IOException
{
    public AutomationStoreConflictException(string filePath, string message) : base(message) =>
        FilePath = filePath;

    public string FilePath { get; }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_CONPTYLIFECYCLEEVENT_CS
#region Services/ConPtyLifecycleEvent.cs
namespace TerminalNotes.Services
{

/// <summary>Sanitized state for one native lifecycle operation in a ConPTY session.</summary>
public sealed record ConPtyLifecycleEvent(
    DateTimeOffset Timestamp,
    string Operation,
    string Phase,
    string? ExceptionType);
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_CONPTYLIFECYCLEWORKER_CS
#region Services/ConPtyLifecycleWorker.cs
namespace TerminalNotes.Services
{
using global::System.Diagnostics;


/// <summary>Runs blocking native resize and close work on session-owned threads.</summary>
internal sealed class ConPtyLifecycleWorker
{
    private readonly object _gate = new();
    private Task? _worker;
    private (short Columns, short Rows)? _pendingResize;
    private Action<short, short>? _resize;
    private Action? _close;
    private TaskCompletionSource? _closed;
    private bool _closing;

    public event Action<ConPtyLifecycleEvent>? LifecycleChanged;

    public void RequestResize(short columns, short rows, Action<short, short> resize)
    {
        lock (_gate)
        {
            if (_closing) return;
            _pendingResize = (columns, rows);
            _resize = resize;
            EnsureWorkerLocked();
            Monitor.PulseAll(_gate);
        }
    }

    public Task CloseAsync(Action close)
    {
        lock (_gate)
        {
            if (_closed is not null) return _closed.Task;
            _closing = true;
            _close = close;
            _closed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
            // Native resize can block indefinitely. Closing the owned job and
            // pseudoconsole must have an independent thread so stop remains usable.
            _pendingResize = null;
            _resize = null;
            _ = Task.Factory.StartNew(
                RunClose,
                CancellationToken.None,
                TaskCreationOptions.LongRunning,
                TaskScheduler.Default);
            Monitor.PulseAll(_gate);
            return _closed.Task;
        }
    }

    private void EnsureWorkerLocked()
    {
        _worker ??= Task.Factory.StartNew(
            Run,
            CancellationToken.None,
            TaskCreationOptions.LongRunning,
            TaskScheduler.Default);
    }

    private void Run()
    {
        while (true)
        {
            (short Columns, short Rows)? resize = null;
            Action<short, short>? resizeAction = null;
            lock (_gate)
            {
                while (!_closing && _pendingResize is null) Monitor.Wait(_gate);
                if (_pendingResize is { } pending && _resize is { } pendingAction)
                {
                    resize = pending;
                    _pendingResize = null;
                    resizeAction = pendingAction;
                }
                else if (_closing) return;
            }

            if (resize is not { } requested || resizeAction is null) continue;
            RaiseLifecycle("resize", "started", null);
            try
            {
                resizeAction(requested.Columns, requested.Rows);
                RaiseLifecycle("resize", "completed", null);
            }
            catch (Exception exception)
            {
                RaiseLifecycle("resize", "faulted", exception.GetType().FullName);
            }
        }
    }

    private void RunClose()
    {
        Action? close;
        TaskCompletionSource? closed;
        lock (_gate)
        {
            close = _close;
            _close = null;
            closed = _closed;
        }

        RaiseLifecycle("close", "started", null);
        try
        {
            close?.Invoke();
            RaiseLifecycle("close", "completed", null);
            closed?.TrySetResult();
        }
        catch (Exception exception)
        {
            RaiseLifecycle("close", "faulted", exception.GetType().FullName);
            closed?.TrySetException(exception);
        }
    }

    private void RaiseLifecycle(string operation, string phase, string? exceptionType)
    {
        var diagnostic = new ConPtyLifecycleEvent(DateTimeOffset.UtcNow, operation, phase, exceptionType);
        foreach (Action<ConPtyLifecycleEvent> handler in LifecycleChanged?.GetInvocationList() ?? [])
        {
            try { handler(diagnostic); }
            catch (Exception exception) { Trace.WriteLine($"ConPTY lifecycle observer failed: {exception.GetType().FullName}"); }
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_CONPTYSESSION_CS
#region Services/ConPtySession.cs
namespace TerminalNotes.Services
{
using global::System.Collections.Concurrent;
using global::System.Collections;
using global::System.ComponentModel;
using global::System.IO;
using global::System.Runtime.InteropServices;
using global::System.Text;
using global::Microsoft.Win32.SafeHandles;


/// <summary>Lossless bounded handoff from the dedicated pipe reader to output callbacks.</summary>
internal sealed class TerminalOutputBuffer(int capacity = 1024 * 1024)
{
    private readonly object _sync = new();
    private readonly Queue<string> _items = new();
    private readonly int _capacity = capacity > 0 ? capacity : throw new ArgumentOutOfRangeException(nameof(capacity));
    private int _characters;
    private int _waitingProducers;
    private bool _completed;
    internal int BufferedCharacters { get { lock (_sync) return _characters; } }
    internal bool IsEmpty { get { lock (_sync) return _items.Count == 0; } }

    // The caller is the dedicated native reader, never the UI thread. A full queue
    // backpressures only that reader; completion wakes it so HPCON can still drain.
    internal bool Enqueue(string text, CancellationToken token = default)
    {
        if (text.Length > _capacity) throw new ArgumentException("Output chunk exceeds buffer capacity.", nameof(text));
        using var registration = token.CanBeCanceled
            ? token.Register(() => { lock (_sync) Monitor.PulseAll(_sync); }) : default;
        lock (_sync)
        {
            while (!_completed && _characters > _capacity - text.Length)
            {
                token.ThrowIfCancellationRequested();
                _waitingProducers++;
                try { Monitor.Wait(_sync); }
                finally { _waitingProducers--; }
            }
            token.ThrowIfCancellationRequested();
            if (_completed) return false;
            _items.Enqueue(text);
            _characters += text.Length;
        }
        return true;
    }
    internal bool TryDequeue([global::System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out string? text)
    {
        lock (_sync)
        {
            if (!_items.TryDequeue(out text)) return false;
            _characters -= text.Length;
            if (_waitingProducers != 0) Monitor.PulseAll(_sync);
            return true;
        }
    }
    internal void Complete()
    {
        lock (_sync)
        {
            _completed = true;
            _items.Clear();
            _characters = 0;
            Monitor.PulseAll(_sync);
        }
    }
}

/// <summary>
/// Owns one Windows pseudoconsole and its PowerShell process tree.
/// </summary>
/// <remarks>
/// Assumptions: Windows 10 1809 or newer is available; each instance is started at
/// most once; callers pass terminal keystrokes (including control sequences) to
/// <see cref="Write"/> and marshal event callbacks to the UI thread themselves.
/// Setting <c>launchCodex</c> starts a fixed encoded bootstrap in the selected
/// working directory and keeps PowerShell available after Codex exits.
/// A non-empty <c>startupCommand</c> takes precedence and is transferred as UTF-8
/// Base64 through the child-only environment, never interpolated into a script.
/// ConPTY's byte stream is UTF-8, so decoding is incremental to preserve characters
/// split across native reads (including Korean text). Output is delivered verbatim;
/// ANSI/VT sequences are intentionally retained for a terminal renderer such as xterm.js.
/// </remarks>
public sealed class ConPtySession : IDisposable
{
    // ConPTY transports UTF-8, but Windows PowerShell's .NET Console writer can
    // otherwise replace characters using the inherited OEM code page first.
    private const string Utf8BootstrapScript = """
        [Console]::InputEncoding = [Text.UTF8Encoding]::new($false)
        [Console]::OutputEncoding = [Text.UTF8Encoding]::new($false)
        $OutputEncoding = [Console]::OutputEncoding
        """;
    private const string CodexBootstrapScript = """
        $codexCommand = Get-Command codex -CommandType Application,ExternalScript -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($null -eq $codexCommand) {
            Write-Host 'Codex CLI를 찾을 수 없습니다. Codex CLI was not found on PATH.' -ForegroundColor Red
        }
        else {
            try {
                & $codexCommand.Source
            }
            catch {
                Write-Host ('Codex 실행에 실패했습니다. Failed to launch Codex: ' + $_.Exception.Message) -ForegroundColor Red
            }
        }
        """;
    private const string CustomCommandBootstrapScript = """
        $encodedCommand = [Environment]::GetEnvironmentVariable('TERMINALNOTES_STARTUP_COMMAND_B64', 'Process')
        Remove-Item Env:TERMINALNOTES_STARTUP_COMMAND_B64 -ErrorAction SilentlyContinue
        try {
            if ([string]::IsNullOrEmpty($encodedCommand)) {
                throw 'The encoded startup command is missing.'
            }
            $commandBytes = [Convert]::FromBase64String($encodedCommand)
            $commandText = [Text.Encoding]::UTF8.GetString($commandBytes)
            $commandScript = [ScriptBlock]::Create($commandText)
            $previousErrorAction = $ErrorActionPreference
            try {
                $ErrorActionPreference = 'Stop'
                & $commandScript
            }
            finally {
                $ErrorActionPreference = $previousErrorAction
            }
        }
        catch {
            Write-Host ('시작 명령 실행에 실패했습니다. Startup command failed: ' + $_.Exception.Message) -ForegroundColor Red
        }
        """;

    private const uint ExtendedStartupInfoPresent = 0x00080000;
    private const uint CreateUnicodeEnvironment = 0x00000400;
    private const uint CreateSuspended = 0x00000004;
    private const uint StartfUseStdHandles = 0x00000100;
    private const nuint ProcThreadAttributePseudoConsole = 0x00020016;
    private const uint JobObjectLimitKillOnJobClose = 0x00002000;
    private const uint Infinite = 0xFFFFFFFF;
    private const uint WaitObject0 = 0;
    private const uint InputFailureExitSettleMilliseconds = 100;

    private readonly object _gate = new();
    private readonly TerminalOutputBuffer _pendingOutput = new();
    private static readonly Encoding TerminalEncoding = new UTF8Encoding(false);
    private readonly ConPtyLifecycleWorker _lifecycleWorker = new();

    private FileStream? _input;
    private TerminalInputBuffer? _inputQueue;
    private IOException? _inputFailure;
    private FileStream? _output;
    private SafePseudoConsoleHandle? _pseudoConsole;
    private SafeKernelObjectHandle? _process;
    private readonly TaskCompletionSource _processExited = new(TaskCreationOptions.RunContinuationsAsynchronously);
    private Task? _closeTask;
    private uint? _processId;

    internal async Task StopAndWaitAsync()
    {
        await CloseAsync();
        await _processExited.Task.WaitAsync(TimeSpan.FromSeconds(15));
    }
    private SafeKernelObjectHandle? _job;
    private bool _startAttempted;
    private bool _running;
    private int _disposed;
    private int _outputDispatchScheduled;

    public event Action<string>? OutputReceived;

    public event Action<int>? Exited;

    public event Action<Exception>? InputFailed;

    public event Action<ConPtyLifecycleEvent>? LifecycleChanged
    {
        add => _lifecycleWorker.LifecycleChanged += value;
        remove => _lifecycleWorker.LifecycleChanged -= value;
    }

    /// <summary>Process ID while this session still owns its ConPTY process handle.</summary>
    public uint? ProcessId
    {
        get { lock (_gate) return _processId; }
    }

    public bool IsRunning
    {
        get
        {
            lock (_gate)
            {
                return _running && Volatile.Read(ref _disposed) == 0;
            }
        }
    }

    public void Start(
        string workingDirectory,
        short columns = 120,
        short rows = 30,
        bool launchCodex = false,
        string? startupCommand = null,
        string? openCodeConfigContent = null,
        bool exitOnStartupCommandCompletion = false,
        string? executable = null,
        IReadOnlyList<string>? arguments = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(workingDirectory);
        ValidateSize(columns, rows);
        if (executable is not null && (startupCommand is not null || launchCodex))
            throw new ArgumentException("A program started directly takes no PowerShell startup command.", nameof(executable));

        if (!OperatingSystem.IsWindowsVersionAtLeast(10, 0, 17763))
        {
            throw new PlatformNotSupportedException("ConPTY requires Windows 10 version 1809 or newer.");
        }

        string fullWorkingDirectory = Path.GetFullPath(workingDirectory);
        if (!Directory.Exists(fullWorkingDirectory))
        {
            throw new DirectoryNotFoundException($"The terminal working directory does not exist: {fullWorkingDirectory}");
        }

        lock (_gate)
        {
            ThrowIfDisposed();
            if (_startAttempted)
            {
                throw new InvalidOperationException("A ConPtySession instance can only be started once.");
            }

            _startAttempted = true;
            StartCore(fullWorkingDirectory, columns, rows, launchCodex, startupCommand, openCodeConfigContent, exitOnStartupCommandCompletion,
                executable, arguments ?? []);
        }
    }

    public void Write(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (text.Length == 0)
        {
            return;
        }

        byte[] bytes = TerminalEncoding.GetBytes(text);
        lock (_gate)
        {
            ThrowIfDisposed();
            if (!_running || _inputQueue is null)
            {
                throw new InvalidOperationException("The pseudoconsole is not running.");
            }

            if (_inputFailure is { } failure)
            {
                throw new IOException("The terminal input writer has failed.", failure);
            }

            if (!_inputQueue.TryWrite(bytes))
            {
                throw new IOException("The terminal input queue is no longer available.", _inputQueue.Failure);
            }
        }
    }

    public void Resize(short columns, short rows)
    {
        ValidateSize(columns, rows);
        SafePseudoConsoleHandle pseudoConsole;
        bool addedReference = false;
        lock (_gate)
        {
            ThrowIfDisposed();
            if (!_running || _pseudoConsole is null)
            {
                throw new InvalidOperationException("The pseudoconsole is not running.");
            }
            pseudoConsole = _pseudoConsole;
            pseudoConsole.DangerousAddRef(ref addedReference);
        }

        try { ResizePseudoConsoleCore(pseudoConsole, columns, rows); }
        finally { if (addedReference) pseudoConsole.DangerousRelease(); }
    }

    /// <summary>Queues the latest size without waiting for the native resize call.</summary>
    public void RequestResize(short columns, short rows)
    {
        ValidateSize(columns, rows);
        lock (_gate)
        {
            ThrowIfDisposed();
            if (!_running || _pseudoConsole is null)
                throw new InvalidOperationException("The pseudoconsole is not running.");
        }
        _lifecycleWorker.RequestResize(columns, rows, ResizeNativeForLifecycleWorker);
    }

    private void ResizeNativeForLifecycleWorker(short columns, short rows)
    {
        SafePseudoConsoleHandle? pseudoConsole;
        bool addedReference = false;
        lock (_gate)
        {
            if (Volatile.Read(ref _disposed) != 0 || !_running || _pseudoConsole is null) return;
            pseudoConsole = _pseudoConsole;
            pseudoConsole.DangerousAddRef(ref addedReference);
        }
        if (!addedReference || pseudoConsole is null) return;
        try { ResizePseudoConsoleCore(pseudoConsole, columns, rows); }
        finally { pseudoConsole.DangerousRelease(); }
    }

    private static void ResizePseudoConsoleCore(SafePseudoConsoleHandle pseudoConsole, short columns, short rows)
    {
        int result = pseudoConsole.Bundled
            ? ConptyResizePseudoConsole(pseudoConsole, new Coord(columns, rows))
            : ResizePseudoConsole(pseudoConsole, new Coord(columns, rows));
        if (result < 0) Marshal.ThrowExceptionForHR(result);
    }

    // Windows 10's inbox console host drops non-ASCII input (Korean) that arrives through ConPTY; Windows 11's does not
    // (사용자 확인: 한글 입력 문제는 윈도우10에서만). The app ships Microsoft's current ConPTY (conpty.dll and
    // x64\OpenConsole.exe from microsoft/terminal, MIT) and uses it when both files are present, falling back to the
    // inbox kernel32 functions when that host cannot start. TERMINALNOTES_INBOX_CONPTY=1 forces the inbox host.
    internal static bool BundledConPtyAvailable =>
        Environment.GetEnvironmentVariable("TERMINALNOTES_INBOX_CONPTY") != "1" &&
        File.Exists(Path.Combine(AppContext.BaseDirectory, "conpty.dll")) &&
        File.Exists(Path.Combine(AppContext.BaseDirectory, "x64", "OpenConsole.exe"));

    private static int CreatePseudoConsoleWithBestHost(Coord size, SafeFileHandle input, SafeFileHandle output,
        out IntPtr pseudoConsole, out bool bundled)
    {
        if (BundledConPtyAvailable)
        {
            try
            {
                int result = ConptyCreatePseudoConsole(size, input, output, 0, out pseudoConsole);
                if (result >= 0) { bundled = true; return result; }
            }
            catch (Exception exception) when (exception is DllNotFoundException or EntryPointNotFoundException or BadImageFormatException)
            {
                System.Diagnostics.Trace.WriteLine("Bundled ConPTY unavailable: " + exception.GetType().Name);
            }
        }
        bundled = false;
        return CreatePseudoConsole(size, input, output, 0, out pseudoConsole);
    }

    public Task CloseAsync()
    {
        FileStream? input;
        TerminalInputBuffer? inputQueue;
        FileStream? output;
        SafePseudoConsoleHandle? pseudoConsole;
        SafeKernelObjectHandle? process;
        SafeKernelObjectHandle? job;
        var completion = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);

        lock (_gate)
        {
            if (_closeTask is not null) return _closeTask;
            _closeTask = completion.Task;
            Interlocked.Exchange(ref _disposed, 1);

            _running = false;
            _processId = null;
            input = Take(ref _input);
            inputQueue = Take(ref _inputQueue);
            output = Take(ref _output);
            pseudoConsole = Take(ref _pseudoConsole);
            process = Take(ref _process);
            job = Take(ref _job);
            inputQueue?.Complete();
        }

        _pendingOutput.Complete();
        Task cleanup = _lifecycleWorker.CloseAsync(() => CloseHandles(job, input, pseudoConsole, output, process));
        _ = cleanup.ContinueWith(task =>
        {
            if (task.IsFaulted) completion.TrySetException(task.Exception!.InnerExceptions);
            else if (task.IsCanceled) completion.TrySetCanceled();
            else completion.TrySetResult();
        }, CancellationToken.None, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
        return completion.Task;
    }

    private void CloseHandles(
        SafeKernelObjectHandle? job,
        FileStream? input,
        SafePseudoConsoleHandle? pseudoConsole,
        FileStream? output,
        SafeKernelObjectHandle? process)
    {
        // Closing this job kills only the process tree created by this session. Keep
        // the output reader alive while closing HPCON: ClosePseudoConsole can wait for
        // pending terminal output, and the dedicated reader prevents a pipe deadlock.
        List<Exception>? failures = null;
        DisposeAndCapture(job, ref failures);
        DisposeAndCapture(input, ref failures);
        DisposeAndCapture(pseudoConsole, ref failures);
        DisposeAndCapture(output, ref failures);
        DisposeAndCapture(process, ref failures);
        if (process is null) _processExited.TrySetResult();

        GC.SuppressFinalize(this);
        if (failures is { Count: 1 }) throw failures[0];
        if (failures is { Count: > 1 }) throw new AggregateException(failures);
    }

    private static void DisposeAndCapture(IDisposable? resource, ref List<Exception>? failures)
    {
        if (resource is null) return;
        try { resource.Dispose(); }
        catch (Exception exception) { (failures ??= []).Add(exception); }
    }

    public void Dispose()
    {
        CloseAsync().GetAwaiter().GetResult();
    }

    private void StartCore(
        string workingDirectory,
        short columns,
        short rows,
        bool launchCodex,
        string? startupCommand,
        string? openCodeConfigContent,
        bool exitOnStartupCommandCompletion,
        string? executable,
        IReadOnlyList<string> arguments)
    {
        SafeFileHandle? pseudoConsoleInput = null;
        SafeFileHandle? terminalInput = null;
        SafeFileHandle? terminalOutput = null;
        SafeFileHandle? pseudoConsoleOutput = null;
        SafePseudoConsoleHandle? pseudoConsole = null;
        SafeKernelObjectHandle? process = null;
        SafeKernelObjectHandle? thread = null;
        SafeKernelObjectHandle? job = null;
        FileStream? inputStream = null;
        TerminalInputBuffer? inputQueue = null;
        FileStream? outputStream = null;
        ProcThreadAttributeList? attributeList = null;
        bool assignedToJob = false;
        bool ownershipTransferred = false;

        try
        {
            CreatePipeChecked(out pseudoConsoleInput, out terminalInput, "creating the ConPTY input pipe");
            CreatePipeChecked(out terminalOutput, out pseudoConsoleOutput, "creating the ConPTY output pipe");

            int createResult = CreatePseudoConsoleWithBestHost(
                new Coord(columns, rows),
                pseudoConsoleInput,
                pseudoConsoleOutput,
                out IntPtr pseudoConsoleValue,
                out bool bundledHost);
            if (createResult < 0)
            {
                Marshal.ThrowExceptionForHR(createResult);
            }

            pseudoConsole = new SafePseudoConsoleHandle(pseudoConsoleValue, ownsHandle: true, bundled: bundledHost);

            // HPCON owns its references to these two ends after successful creation.
            pseudoConsoleInput.Dispose();
            pseudoConsoleInput = null;
            pseudoConsoleOutput.Dispose();
            pseudoConsoleOutput = null;

            attributeList = new ProcThreadAttributeList(pseudoConsole);
            job = CreateKillOnCloseJob();

            string powerShellPath = GetPowerShellPath();
            var startupInfo = new StartupInfoEx
            {
                StartupInfo = new StartupInfo
                {
                    Cb = Marshal.SizeOf<StartupInfoEx>(),
                    // Null explicit standard handles prevent CreateProcess from
                    // duplicating redirected parent handles into the console client.
                    Flags = StartfUseStdHandles
                },
                AttributeList = attributeList.Pointer
            };

            // A program started directly (OpenCode's TUI) is the console's only client; otherwise PowerShell hosts the session.
            string? encodedStartupCommand = null;
            string program = executable is null ? powerShellPath : Path.GetFullPath(executable);
            string commandLine = executable is null
                ? BuildPowerShellCommandLine(powerShellPath, launchCodex, startupCommand, exitOnStartupCommandCompletion, out encodedStartupCommand)
                : string.Join(' ', new[] { program }.Concat(arguments).Select(QuoteArgument));
            ProcessInformation processInformation;
            IntPtr environment = CreateChildEnvironment(encodedStartupCommand, openCodeConfigContent);
            try
            {
                if (!CreateProcess(
                    program,
                    new StringBuilder(commandLine),
                    IntPtr.Zero,
                    IntPtr.Zero,
                    false,
                    ExtendedStartupInfoPresent | CreateUnicodeEnvironment | CreateSuspended | (TaskMemoryGuard.Job != IntPtr.Zero ? TaskMemoryGuard.LaunchFlags : 0),
                    environment,
                    workingDirectory,
                    ref startupInfo,
                    out processInformation))
                {
                    ThrowLastWin32Error(executable is null ? "creating PowerShell in the pseudoconsole" : "starting " + Path.GetFileName(program) + " in the pseudoconsole");
                }
            }
            finally
            {
                Marshal.FreeHGlobal(environment);
            }

            process = new SafeKernelObjectHandle(processInformation.Process, ownsHandle: true);
            thread = new SafeKernelObjectHandle(processInformation.Thread, ownsHandle: true);

            TaskMemoryGuard.Launching();
            TaskMemoryGuard.Enroll(process.DangerousGetHandle());
            if (!AssignProcessToJobObject(job, process))
            {
                ThrowLastWin32Error("assigning the terminal program to its private job object");
            }
            TaskMemoryGuard.Register(job, workingDirectory);

            assignedToJob = true;

            // Anonymous pipes are synchronous handles. A dedicated blocking reader is
            // deliberate: it continuously drains VT output without consuming a UI or
            // thread-pool thread, and it remains active during ClosePseudoConsole.
            inputStream = new FileStream(terminalInput, FileAccess.Write, 4096, isAsync: false);
            terminalInput = null;
            outputStream = new FileStream(terminalOutput, FileAccess.Read, 8192, isAsync: false);
            terminalOutput = null;
            inputQueue = new TerminalInputBuffer();
            StartInputWriter(inputStream, inputQueue);
            StartOutputReader(outputStream);

            uint resumeResult = ResumeThread(thread);
            if (resumeResult == uint.MaxValue)
            {
                ThrowLastWin32Error("resuming PowerShell");
            }

            thread.Dispose();
            thread = null;

            _input = inputStream;
            _inputQueue = inputQueue;
            _output = outputStream;
            _pseudoConsole = pseudoConsole;
            _process = process;
            _processId = processInformation.ProcessId;
            _job = job;
            _running = true;

            inputStream = null;
            inputQueue = null;
            outputStream = null;
            pseudoConsole = null;
            process = null;
            job = null;
            ownershipTransferred = true;

            StartExitWatcher(_process);
        }
        catch
        {
            _running = false;

            if (ownershipTransferred)
            {
                // StartExitWatcher is the only operation that can fail after transfer.
                Take(ref _job)?.Dispose();
                Take(ref _inputQueue)?.Complete();
                Take(ref _input)?.Dispose();
                Take(ref _pseudoConsole)?.Dispose();
                Take(ref _output)?.Dispose();
                Take(ref _process)?.Dispose();
            }
            else
            {
                if (process is not null && !assignedToJob)
                {
                    _ = TerminateProcess(process, 1);
                }

                job?.Dispose();
                inputQueue?.Complete();
                inputStream?.Dispose();
                pseudoConsole?.Dispose();
                outputStream?.Dispose();
                process?.Dispose();
            }

            throw;
        }
        finally
        {
            attributeList?.Dispose();
            thread?.Dispose();
            pseudoConsoleInput?.Dispose();
            terminalInput?.Dispose();
            terminalOutput?.Dispose();
            pseudoConsoleOutput?.Dispose();
        }
    }

    private void StartOutputReader(FileStream output)
    {
        _ = Task.Factory.StartNew(
            () => ReadOutput(output),
            CancellationToken.None,
            TaskCreationOptions.LongRunning,
            TaskScheduler.Default);
    }

    private void StartInputWriter(FileStream input, TerminalInputBuffer inputQueue)
    {
        _ = Task.Factory.StartNew(
            () => WriteInput(input, inputQueue),
            CancellationToken.None,
            TaskCreationOptions.LongRunning,
            TaskScheduler.Default);
    }

    private void WriteInput(FileStream input, TerminalInputBuffer inputQueue)
    {
        try
        {
            while (inputQueue.Reader.WaitToReadAsync().AsTask().GetAwaiter().GetResult())
            {
                while (inputQueue.Reader.TryRead(out byte[]? bytes))
                {
                    input.Write(bytes, 0, bytes.Length);
                    input.Flush();
                }
            }
        }
        catch (IOException exception)
        {
            if (!inputQueue.TryFail(exception)) return;

            if (DidOwnedProcessExitDuringInputFailureSettle(inputQueue)) return;

            bool reportFailure;
            lock (_gate)
            {
                reportFailure = Volatile.Read(ref _disposed) == 0 && _running && ReferenceEquals(_inputQueue, inputQueue);
                if (reportFailure) _inputFailure = exception;
            }

            if (reportFailure) RaiseInputFailed(exception);
        }
        catch (ObjectDisposedException) when (Volatile.Read(ref _disposed) != 0)
        {
        }
    }

    private bool DidOwnedProcessExitDuringInputFailureSettle(TerminalInputBuffer inputQueue)
    {
        SafeKernelObjectHandle? process;
        bool addedReference = false;
        lock (_gate)
        {
            if (Volatile.Read(ref _disposed) != 0 || !_running || !ReferenceEquals(_inputQueue, inputQueue))
            {
                return true;
            }

            process = _process;
            if (process is null || process.IsClosed || process.IsInvalid)
            {
                return true;
            }

            process.DangerousAddRef(ref addedReference);
        }

        if (!addedReference) return true;

        try
        {
            // This runs on the dedicated writer thread, never on the WPF caller.
            _ = WaitForSingleObject(process.DangerousGetHandle(), InputFailureExitSettleMilliseconds);

            lock (_gate)
            {
                if (Volatile.Read(ref _disposed) != 0 || !_running ||
                    !ReferenceEquals(_inputQueue, inputQueue) || !ReferenceEquals(_process, process))
                {
                    return true;
                }

                // Recheck under the lifecycle lock to close the watcher-lag race.
                return WaitForSingleObject(process.DangerousGetHandle(), 0) == WaitObject0;
            }
        }
        finally
        {
            process.DangerousRelease();
        }
    }

    private void RaiseInputFailed(Exception exception)
    {
        Delegate[] handlers = InputFailed?.GetInvocationList() ?? [];
        foreach (var handler in handlers)
        {
            try { ((Action<Exception>)handler)(exception); }
            catch { /* Input-failure observers are outside the session lifetime boundary. */ }
        }
    }

    private void ReadOutput(FileStream output)
    {
        var decoder = new UTF8Encoding(
            encoderShouldEmitUTF8Identifier: false,
            throwOnInvalidBytes: false).GetDecoder();
        byte[] bytes = new byte[8192];
        char[] characters = new char[Encoding.UTF8.GetMaxCharCount(bytes.Length)];

        try
        {
            while (true)
            {
                int count = output.Read(bytes, 0, bytes.Length);
                if (count == 0)
                {
                    break;
                }

                int byteOffset = 0;
                while (byteOffset < count)
                {
                    decoder.Convert(
                        bytes.AsSpan(byteOffset, count - byteOffset),
                        characters,
                        flush: false,
                        out int bytesUsed,
                        out int charactersUsed,
                        out _);
                    byteOffset += bytesUsed;
                    if (charactersUsed > 0)
                    {
                        QueueOutput(new string(characters, 0, charactersUsed));
                    }
                }
            }

            decoder.Convert(
                ReadOnlySpan<byte>.Empty,
                characters,
                flush: true,
                out _,
                out int finalCharacters,
                out _);
            if (finalCharacters > 0)
            {
                QueueOutput(new string(characters, 0, finalCharacters));
            }
        }
        catch (IOException) when (Volatile.Read(ref _disposed) != 0)
        {
        }
        catch (ObjectDisposedException) when (Volatile.Read(ref _disposed) != 0)
        {
        }
    }

    private void QueueOutput(string text)
    {
        if (Volatile.Read(ref _disposed) != 0)
        {
            return;
        }

        if (!_pendingOutput.Enqueue(text)) return;
        if (Interlocked.CompareExchange(ref _outputDispatchScheduled, 1, 0) == 0)
        {
            ThreadPool.UnsafeQueueUserWorkItem(
                static session => session.DispatchOutput(),
                this,
                preferLocal: false);
        }
    }

    private void DispatchOutput()
    {
        while (true)
        {
            while (_pendingOutput.TryDequeue(out string? text))
            {
                if (Volatile.Read(ref _disposed) != 0)
                {
                    continue;
                }

                try
                {
                    OutputReceived?.Invoke(text);
                }
                catch
                {
                    // A subscriber must not stop terminal drainage or other subscribers.
                }
            }

            Volatile.Write(ref _outputDispatchScheduled, 0);
            if (_pendingOutput.IsEmpty ||
                Interlocked.CompareExchange(ref _outputDispatchScheduled, 1, 0) != 0)
            {
                return;
            }
        }
    }

    private void StartExitWatcher(SafeKernelObjectHandle process)
    {
        bool addedReference = false;
        process.DangerousAddRef(ref addedReference);

        try
        {
            _ = Task.Factory.StartNew(
                () =>
                {
                    int exitCode = -1;
                    try
                    {
                        if (WaitForSingleObject(process.DangerousGetHandle(), Infinite) == WaitObject0 &&
                            GetExitCodeProcess(process.DangerousGetHandle(), out uint nativeExitCode))
                        {
                            exitCode = unchecked((int)nativeExitCode);
                        }
                    }
                    finally
                    {
                        process.DangerousRelease();
                    }

                    HandleProcessExit(exitCode);
                },
                CancellationToken.None,
                TaskCreationOptions.LongRunning,
                TaskScheduler.Default);
        }
        catch
        {
            if (addedReference)
            {
                process.DangerousRelease();
            }

            throw;
        }
    }

    private void HandleProcessExit(int exitCode)
    {
        _processExited.TrySetResult();
        lock (_gate)
        {
            _running = false;
            _inputQueue?.Complete();
            if (Volatile.Read(ref _disposed) != 0)
            {
                return;
            }
        }

        ThreadPool.UnsafeQueueUserWorkItem(
            static state =>
            {
                if (Volatile.Read(ref state.Session._disposed) != 0)
                {
                    return;
                }

                try
                {
                    state.Session.Exited?.Invoke(state.ExitCode);
                }
                catch
                {
                    // Event handlers are outside the lifetime-management boundary.
                }
            },
            (Session: this, ExitCode: exitCode),
            preferLocal: false);
    }

    private static SafeKernelObjectHandle CreateKillOnCloseJob()
    {
        SafeKernelObjectHandle job = CreateJobObject(IntPtr.Zero, null);
        if (job.IsInvalid)
        {
            ThrowLastWin32Error("creating a private job object");
        }

        var limits = new JobObjectExtendedLimitInformation
        {
            BasicLimitInformation = new JobObjectBasicLimitInformation
            {
                LimitFlags = JobObjectLimitKillOnJobClose
            }
        };

        int size = Marshal.SizeOf<JobObjectExtendedLimitInformation>();
        IntPtr buffer = Marshal.AllocHGlobal(size);
        try
        {
            Marshal.StructureToPtr(limits, buffer, fDeleteOld: false);
            if (!SetInformationJobObject(job, JobObjectInfoType.ExtendedLimitInformation, buffer, (uint)size))
            {
                ThrowLastWin32Error("configuring the private job object");
            }

            return job;
        }
        catch
        {
            job.Dispose();
            throw;
        }
        finally
        {
            Marshal.FreeHGlobal(buffer);
        }
    }

    // One command-line argument as CommandLineToArgvW reads it back.
    private static string QuoteArgument(string argument)
    {
        if (argument.Length > 0 && argument.IndexOfAny([' ', '\t', '\n', '\v', '"']) < 0) return argument;
        var quoted = new StringBuilder("\"");
        for (int index = 0; index < argument.Length; index++)
        {
            int backslashes = 0;
            while (index < argument.Length && argument[index] == '\\') { backslashes++; index++; }
            if (index == argument.Length) { quoted.Append('\\', backslashes * 2); break; }
            if (argument[index] == '"') quoted.Append('\\', backslashes * 2 + 1).Append('"');
            else quoted.Append('\\', backslashes).Append(argument[index]);
        }
        return quoted.Append('"').ToString();
    }

    private static string GetPowerShellPath()
    {
        string path = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.Windows),
            "System32",
            "WindowsPowerShell",
            "v1.0",
            "powershell.exe");
        return File.Exists(path) ? path : "powershell.exe";
    }

    private static string BuildPowerShellCommandLine(
        string powerShellPath,
        bool launchCodex,
        string? startupCommand,
        bool exitOnStartupCommandCompletion,
        out string? encodedStartupCommand)
    {
        encodedStartupCommand = null;
        if (!string.IsNullOrWhiteSpace(startupCommand))
        {
            encodedStartupCommand = Convert.ToBase64String(TerminalEncoding.GetBytes(startupCommand));
            string customEncodedBootstrap = Convert.ToBase64String(
                Encoding.Unicode.GetBytes(Utf8BootstrapScript + "\n" + CustomCommandBootstrapScript));
            // A native OpenCode pane's lifetime must follow OpenCode, not an idle
            // PowerShell prompt left behind after launch failure or process exit.
            string lifecycleOptions = exitOnStartupCommandCompletion ? "-NoProfile" : "-NoExit";
            return $"\"{powerShellPath}\" -NoLogo {lifecycleOptions} -EncodedCommand {customEncodedBootstrap}";
        }

        if (!launchCodex)
        {
            string shellBootstrap = Convert.ToBase64String(Encoding.Unicode.GetBytes(Utf8BootstrapScript));
            return $"\"{powerShellPath}\" -NoLogo -NoExit -EncodedCommand {shellBootstrap}";
        }

        // EncodedCommand keeps the bootstrap fixed and independent of the selected
        // working directory. CreateProcess supplies that directory separately.
        string encodedBootstrap = Convert.ToBase64String(
            Encoding.Unicode.GetBytes(Utf8BootstrapScript + "\n" + CodexBootstrapScript));
        return $"\"{powerShellPath}\" -NoLogo -NoExit -EncodedCommand {encodedBootstrap}";
    }

    private static IntPtr CreateChildEnvironment(string? encodedStartupCommand, string? openCodeConfigContent)
    {
        var variables = new SortedDictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (DictionaryEntry entry in Environment.GetEnvironmentVariables())
        {
            if (entry.Key is string name && entry.Value is string value)
            {
                variables[name] = value;
            }
        }

        variables["TERM"] = "xterm-256color";
        variables["COLORTERM"] = "truecolor";
        if (encodedStartupCommand is not null)
        {
            variables["TERMINALNOTES_STARTUP_COMMAND_B64"] = encodedStartupCommand;
        }
        if (openCodeConfigContent is not null)
        {
            variables["OPENCODE_CONFIG_CONTENT"] = openCodeConfigContent;
        }

        var block = new StringBuilder();
        foreach ((string name, string value) in variables)
        {
            block.Append(name).Append('=').Append(value).Append('\0');
        }

        block.Append('\0');
        return Marshal.StringToHGlobalUni(block.ToString());
    }

    private static void CreatePipeChecked(
        out SafeFileHandle readPipe,
        out SafeFileHandle writePipe,
        string operation)
    {
        if (!CreatePipe(out readPipe, out writePipe, IntPtr.Zero, 0))
        {
            ThrowLastWin32Error(operation);
        }
    }

    private static void ValidateSize(short columns, short rows)
    {
        if (columns <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(columns), "Terminal columns must be positive.");
        }

        if (rows <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(rows), "Terminal rows must be positive.");
        }
    }

    private void ThrowIfDisposed()
    {
        ObjectDisposedException.ThrowIf(Volatile.Read(ref _disposed) != 0, this);
    }

    private static T? Take<T>(ref T? value) where T : class
    {
        T? result = value;
        value = null;
        return result;
    }

    private static void ThrowLastWin32Error(string operation)
    {
        throw new Win32Exception(Marshal.GetLastWin32Error(), $"Failed while {operation}.");
    }

    private sealed class ProcThreadAttributeList : IDisposable
    {
        private IntPtr _pointer;

        public ProcThreadAttributeList(SafePseudoConsoleHandle pseudoConsole)
        {
            nuint size = 0;
            _ = InitializeProcThreadAttributeList(IntPtr.Zero, 1, 0, ref size);
            if (size == 0)
            {
                ThrowLastWin32Error("sizing the process attribute list");
            }

            _pointer = Marshal.AllocHGlobal(checked((nint)size));
            if (!InitializeProcThreadAttributeList(_pointer, 1, 0, ref size))
            {
                int error = Marshal.GetLastWin32Error();
                Marshal.FreeHGlobal(_pointer);
                _pointer = IntPtr.Zero;
                throw new Win32Exception(error, "Failed while initializing the process attribute list.");
            }

            try
            {
                if (!UpdateProcThreadAttribute(
                        _pointer,
                        0,
                        ProcThreadAttributePseudoConsole,
                        pseudoConsole.DangerousGetHandle(),
                        (nuint)IntPtr.Size,
                        IntPtr.Zero,
                        IntPtr.Zero))
                {
                    ThrowLastWin32Error("adding the pseudoconsole process attribute");
                }
            }
            catch
            {
                Dispose();
                throw;
            }
        }

        public IntPtr Pointer => _pointer;

        public void Dispose()
        {
            IntPtr pointer = Interlocked.Exchange(ref _pointer, IntPtr.Zero);
            if (pointer == IntPtr.Zero)
            {
                return;
            }

            DeleteProcThreadAttributeList(pointer);
            Marshal.FreeHGlobal(pointer);
        }
    }

    private sealed class SafeKernelObjectHandle : SafeHandleZeroOrMinusOneIsInvalid
    {
        public SafeKernelObjectHandle()
            : base(ownsHandle: true)
        {
        }

        public SafeKernelObjectHandle(IntPtr handle, bool ownsHandle)
            : base(ownsHandle)
        {
            SetHandle(handle);
        }

        protected override bool ReleaseHandle() => CloseHandle(handle);
    }

    private sealed class SafePseudoConsoleHandle : SafeHandleZeroOrMinusOneIsInvalid
    {
        public SafePseudoConsoleHandle()
            : base(ownsHandle: true)
        {
        }

        public SafePseudoConsoleHandle(IntPtr handle, bool ownsHandle, bool bundled = false)
            : base(ownsHandle)
        {
            SetHandle(handle);
            Bundled = bundled;
        }

        /// <summary>Created by the bundled conpty.dll, so it is resized and closed there too.</summary>
        public bool Bundled { get; }

        protected override bool ReleaseHandle()
        {
            if (Bundled) ConptyClosePseudoConsole(handle);
            else ClosePseudoConsole(handle);
            return true;
        }
    }

    [StructLayout(LayoutKind.Sequential)]
    private readonly struct Coord
    {
        public Coord(short x, short y)
        {
            X = x;
            Y = y;
        }

        public readonly short X;
        public readonly short Y;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    private struct StartupInfo
    {
        public int Cb;
        public IntPtr Reserved;
        public IntPtr Desktop;
        public IntPtr Title;
        public uint X;
        public uint Y;
        public uint XSize;
        public uint YSize;
        public uint XCountChars;
        public uint YCountChars;
        public uint FillAttribute;
        public uint Flags;
        public ushort ShowWindow;
        public ushort Reserved2;
        public IntPtr Reserved2Pointer;
        public IntPtr StandardInput;
        public IntPtr StandardOutput;
        public IntPtr StandardError;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct StartupInfoEx
    {
        public StartupInfo StartupInfo;
        public IntPtr AttributeList;
    }

    [StructLayout(LayoutKind.Sequential)]
    private readonly struct ProcessInformation
    {
        public readonly IntPtr Process;
        public readonly IntPtr Thread;
        public readonly uint ProcessId;
        public readonly uint ThreadId;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct JobObjectBasicLimitInformation
    {
        public long PerProcessUserTimeLimit;
        public long PerJobUserTimeLimit;
        public uint LimitFlags;
        public nuint MinimumWorkingSetSize;
        public nuint MaximumWorkingSetSize;
        public uint ActiveProcessLimit;
        public nuint Affinity;
        public uint PriorityClass;
        public uint SchedulingClass;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct IoCounters
    {
        public ulong ReadOperationCount;
        public ulong WriteOperationCount;
        public ulong OtherOperationCount;
        public ulong ReadTransferCount;
        public ulong WriteTransferCount;
        public ulong OtherTransferCount;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct JobObjectExtendedLimitInformation
    {
        public JobObjectBasicLimitInformation BasicLimitInformation;
        public IoCounters IoInfo;
        public nuint ProcessMemoryLimit;
        public nuint JobMemoryLimit;
        public nuint PeakProcessMemoryUsed;
        public nuint PeakJobMemoryUsed;
    }

    private enum JobObjectInfoType
    {
        ExtendedLimitInformation = 9
    }

