    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool SetInformationJobObject(
        SafeKernelObjectHandle job,
        JobObjectInfoType informationClass,
        IntPtr information,
        uint informationLength);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool AssignProcessToJobObject(
        SafeKernelObjectHandle job,
        SafeKernelObjectHandle process);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint ResumeThread(SafeKernelObjectHandle thread);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint WaitForSingleObject(IntPtr handle, uint milliseconds);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GetExitCodeProcess(IntPtr process, out uint exitCode);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool TerminateProcess(SafeKernelObjectHandle process, uint exitCode);

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool CloseHandle(IntPtr handle);
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_DIAGNOSTICLOGANALYZER_CS
#region Services/DiagnosticLogAnalyzer.cs
namespace TerminalNotes.Services
{
using global::System.Globalization;
using global::System.IO;
using global::System.Text;
using global::System.Text.Json;


public sealed record DiagnosticLogAnalysis(string Summary, bool IsPartial, int ParsedEvents, int InvalidLines);

/// <summary>Reads bounded snapshots only; no raw text, user paths or arbitrary labels enter the report.</summary>
public static class DiagnosticLogAnalyzer
{
    public const int MaximumBytesPerFile = 2 * 1024 * 1024;
    public const int MaximumLinesPerFile = 10000;
    private sealed record Entry(DateTimeOffset Time, string Name, double? Duration, string Stage);
    private sealed record MemoryProcess(long? Pid, long? ParentPid, string Name, string Description, long? PrivateBytes, long? WorkingBytes, bool IsApp);
    private sealed record MemorySample(DateTimeOffset Time, long? AppPid, DateTimeOffset? AppStart, long? Load, long? Total, long? Available,
        long? PrivateBytes, long? WorkingBytes, long? Count, long? Unreadable, bool Partial, MemoryProcess[] Processes);
    private static readonly Dictionary<string, string> Stages = new(StringComparer.Ordinal)
    {
        ["native_server_start_requested"] = "OpenCode 서버 시작 요청",
        ["native_server_started"] = "OpenCode 서버 시작됨",
        ["native_server_exited"] = "OpenCode 서버 종료됨",
        ["session_start_requested"] = "터미널 시작 요청",
        ["session_started"] = "터미널 시작됨",
        ["session_exited"] = "터미널 종료됨",
        ["resize_requested"] = "크기 변경 요청",
        ["resize_started"] = "크기 변경 시작",
        ["resize_completed"] = "크기 변경 완료",
        ["close_requested"] = "터미널 종료 요청",
        ["close_started"] = "터미널 종료 시작",
        ["close_completed"] = "터미널 종료 완료"
    };

    public static Task<DiagnosticLogAnalysis> AnalyzeAsync(IEnumerable<string> paths, CancellationToken cancellationToken = default)
    {
        string[] snapshot = paths.Take(9).ToArray();
        return Task.Run(() => Analyze(snapshot, cancellationToken), cancellationToken);
    }

    public static Task<DiagnosticLogAnalysis> AnalyzeDefaultAsync(string settingsPath, CancellationToken cancellationToken = default) => Task.Run(() =>
    {
        var paths = new List<string> { settingsPath + ".ui-diagnostics.jsonl", settingsPath + ".automation-diagnostics.jsonl", settingsPath + ".resource-diagnostics.jsonl" };
        string backup = settingsPath + ".resource-diagnostics.jsonl.1";
        if (File.Exists(backup)) paths.Add(backup);
        // Keep the existing bounded parser and reserve the remaining slots for recent daily files.
        string dailyDirectory = Path.Combine(AppContext.GetData("TerminalNotes.DataDirectory") is string directory ? directory
            : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "TerminalNotes"), "diagnostics", "daily");
        try
        {
            if (Directory.Exists(dailyDirectory))
                paths.AddRange(Directory.EnumerateFiles(dailyDirectory, "*.jsonl")
                    .Where(path => (File.GetAttributes(path) & FileAttributes.ReparsePoint) == 0)
                    .OrderByDescending(File.GetLastWriteTimeUtc).Take(9 - paths.Count));
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { }
        return Analyze(paths.ToArray(), cancellationToken);
    }, cancellationToken);

    private static DiagnosticLogAnalysis Analyze(string[] paths, CancellationToken token)
    {
        var entries = new List<Entry>();
        var notices = new List<string>();
        MemorySample? latestMemory = null, maximumLoad = null;
        int memoryCount = 0;
        bool partial = paths.Length > 8;
        int invalid = 0, unknown = 0;
        for (int file = 0; file < Math.Min(paths.Length, 8); file++)
        {
            token.ThrowIfCancellationRequested();
            try
            {
                using var stream = new FileStream(paths[file], FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete);
                long length = stream.Length, offset = Math.Max(0, length - MaximumBytesPerFile);
                partial |= offset > 0;
                stream.Seek(offset, SeekOrigin.Begin);
                byte[] bytes = new byte[(int)(length - offset)];
                int read = 0;
                while (read < bytes.Length)
                {
                    token.ThrowIfCancellationRequested();
                    int count = stream.Read(bytes, read, bytes.Length - read);
                    if (count == 0) break;
                    read += count;
                }
                partial |= read != bytes.Length;
                // Drop a potentially split UTF-8 codepoint / JSON line at the tail boundary.
                int start = offset > 0 ? Array.IndexOf(bytes, (byte)'\n', 0, read) + 1 : 0;
                if (offset > 0 && start == 0) { partial = true; continue; }
                string text = Encoding.UTF8.GetString(bytes, start, read - start).TrimStart('\uFEFF');
                string[] lines = text.Split('\n');
                int first = Math.Max(0, lines.Length - MaximumLinesPerFile);
                partial |= first > 0;
                for (int line = first; line < lines.Length; line++)
                {
                    token.ThrowIfCancellationRequested();
                    if (string.IsNullOrWhiteSpace(lines[line])) continue;
                    try
                    {
                        using var json = JsonDocument.Parse(lines[line], new JsonDocumentOptions { MaxDepth = 32 });
                        var root = json.RootElement;
                        string name = String(root, "eventName");
                        if (name.Length == 0) name = String(root, "event");
                        bool daily = Number(root, "schemaVersion", 1) == 1 && Guid.TryParseExact(String(root, "sessionId"), "N", out _)
                            && (name.StartsWith("session.", StringComparison.Ordinal) || String(root, "severity") is "warning" or "error" or "fatal");
                        if (!(name is "dispatcher_unresponsive" or "dispatcher_recovered" or "terminal_lifecycle_fault") &&
                            name != "resource_snapshot" && !name.StartsWith("auto_resume_", StringComparison.Ordinal) && !daily) { unknown++; continue; }
                        string timestamp = String(root, "timestampUtc");
                        if (timestamp.Length == 0) timestamp = String(root, "timestamp");
                        if (!DateTimeOffset.TryParse(timestamp, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out var time)) { invalid++; continue; }
                        time = time.ToUniversalTime();
                        if (name == "resource_snapshot")
                        {
                            var memory = ReadMemory(root, time);
                            memoryCount++;
                            partial |= memory.Partial;
                            if (latestMemory is null || time >= latestMemory.Time) latestMemory = memory;
                            if (memory.Load.HasValue && (maximumLoad is null || memory.Load > maximumLoad.Load || memory.Load == maximumLoad.Load && time > maximumLoad.Time)) maximumLoad = memory;
                        }
                        string stage = String(root, "terminalStage");
                        string safeStage = Stages.TryGetValue(stage, out var label) ? label : "기록된 단계 없음";
                        if (daily)
                        {
                            safeStage = DailyStage(root, name);
                            name = name switch
                            {
                                "session.start" => "daily_start",
                                "session.normal_exit" => "daily_normal_exit",
                                "session.previous_abnormal_shutdown" => "daily_abnormal",
                                "session.heartbeat" => "daily_heartbeat",
                                _ when String(root, "severity") == "warning" => "daily_warning",
                                _ => String(root, "severity") == "fatal" ? "daily_fatal" : "daily_error"
                            };
                        }
                        double? duration = root.TryGetProperty("durationSeconds", out var d) && d.ValueKind == JsonValueKind.Number && d.TryGetDouble(out double seconds) &&
                            double.IsFinite(seconds) && seconds >= 0 && seconds <= 31536000 ? seconds : null;
                        entries.Add(new(time.ToUniversalTime(), name.StartsWith("auto_resume_", StringComparison.Ordinal) ? "auto_resume" : name, duration, safeStage));
                    }
                    catch (Exception ex) when (ex is JsonException or InvalidOperationException or FormatException) { invalid++; }
                }
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException or NotSupportedException)
            {
                notices.Add($"파일 {file + 1}: 읽을 수 없습니다. 로그가 아직 없거나 접근 권한이 부족할 수 있습니다.");
                partial = true;
            }
        }
        entries.Sort((a, b) => a.Time.CompareTo(b.Time));
        var report = new StringBuilder("관측된 기록\n");
        report.AppendLine(partial ? "부분 분석 · 파일당 최근 2 MiB / 최대 10,000줄 / 최대 8개 파일을 분석합니다." : "선택한 파일의 읽기 시점 기록을 분석했습니다.");
        report.AppendLine($"유효 이벤트 {entries.Count}개 · 손상/불완전 줄 {invalid}개 · 지원하지 않는 이벤트 {unknown}개");
        if (entries.Count > 0)
        {
            report.AppendLine($"기록 범위 (UTC): {entries[0].Time:yyyy-MM-dd HH:mm:ss} ~ {entries[^1].Time:yyyy-MM-dd HH:mm:ss}");
            var stalls = entries.Where(e => e.Name == "dispatcher_unresponsive").ToArray();
            var recovered = entries.Where(e => e.Name == "dispatcher_recovered").ToArray();
            // These legacy fields describe the last active child terminal, not the
            // dispatcher. Switching panes can change them during the same stall;
            // append-only files can also contain multiple app lifetimes.
            report.AppendLine($"UI 응답 지연 기록 {stalls.Length}개 · 복구 기록 {recovered.Length}개");
            double[] durations = recovered.Where(e => e.Duration.HasValue).Select(e => e.Duration!.Value).ToArray();
            if (durations.Length > 0) report.AppendLine($"복구 기록의 최대 지연 {durations.Max():0.0}초 (유효 시간 기록 {durations.Length}개)");
            report.AppendLine($"터미널 수명주기 오류 {entries.Count(e => e.Name == "terminal_lifecycle_fault")}회 · 자동 진행 이벤트 {entries.Count(e => e.Name == "auto_resume")}개");
            if (entries.Any(e => e.Name.StartsWith("daily_", StringComparison.Ordinal)))
            {
                report.AppendLine($"앱 시작 {entries.Count(e => e.Name == "daily_start")}회 · 정상 종료 {entries.Count(e => e.Name == "daily_normal_exit")}회 · 이전 비정상 종료 관측 {entries.Count(e => e.Name == "daily_abnormal")}회 · 치명적 오류 관측 {entries.Count(e => e.Name == "daily_fatal")}회");
                report.AppendLine("강제 종료·전원 손실은 마지막 생존 관측과 다음 실행의 발견 시각만 알 수 있으며, 정확한 종료 시각과 원인은 알 수 없습니다.");
            }
            foreach (var e in entries.Where(e => e.Name is not ("auto_resume" or "resource_snapshot" or "daily_heartbeat")).TakeLast(8))
                report.AppendLine($"{e.Time:MM-dd HH:mm:ss} UTC · {EventLabel(e.Name)} · {e.Stage}" + (e.Duration.HasValue ? $" · {e.Duration:0.0}초" : ""));
        }
        else report.AppendLine("분석할 지원 이벤트가 없습니다. 다른 PC에서 복사한 JSONL 파일을 불러오거나 앱을 사용한 뒤 새로고침하세요.");
        foreach (string notice in notices) report.AppendLine(notice);
        AppendMemory(report, latestMemory, maximumLoad, memoryCount);
        report.AppendLine("\n해석과 확인 사항");
        report.AppendLine("응답 지연은 화면 응답 확인 신호가 늦어진 관측입니다. 절전·프로세스 일시 중단을 배제하지 못하며, 마지막 단계는 원인으로 확정할 수 없습니다.");
        report.AppendLine("터미널 번호·프로세스는 지연 도중 바뀔 수 있고 여러 앱 실행의 기록이 섞일 수 있어, 지연과 복구의 짝이나 현재 멈춤을 단정하지 않습니다.");
        report.AppendLine("다른 창은 정상이고 터미널만 멈춘 경우, 출력 표시·입력 대기·OpenCode 연결을 별도로 확인해야 합니다. 보안 정책이나 네트워크가 원인이라는 결론은 이 기록만으로 내릴 수 없습니다.");
        report.AppendLine(entries.Any(e => e.Name.StartsWith("daily_", StringComparison.Ordinal))
            ? "일일 로그에 기록된 앱 버전과 빌드 식별자는 실행 당시의 정보입니다. 현재 앱과 같은 빌드인지 비교하세요."
            : "이 요약은 실행 컴퓨터나 앱 버전을 확인하지 않으므로, 현재 앱과 기록을 남긴 PC의 앱이 같은 버전인지 별도로 확인하세요.");
        report.AppendLine("높은 메모리 사용률만으로 메모리 누수나 멈춤의 원인을 확정하지 않습니다. 여러 앱 실행을 이어 붙인 기록에서 사용량 증가 추세를 추정하지 않습니다.");
        report.AppendLine("요청문·플랜·인증 정보·원문 오류·파일 경로는 요약에 포함하지 않습니다.");
        return new(report.ToString(), partial, entries.Count, invalid);
    }

    private static string String(JsonElement root, string key) => root.ValueKind == JsonValueKind.Object && root.TryGetProperty(key, out var value) && value.ValueKind == JsonValueKind.String ? value.GetString() ?? "" : "";
    private static string DailyStage(JsonElement root, string name)
    {
        var parts = new List<string>();
        string version = String(root, "appVersion");
        if (version.Length <= 32 && Version.TryParse(version, out var parsedVersion)) parts.Add("v" + parsedVersion);
        if (Guid.TryParseExact(String(root, "buildId"), "N", out var build)) parts.Add("빌드 " + build.ToString("N"));
        if (name == "session.previous_abnormal_shutdown")
        {
            if (Date(root, "lastSeen") is { } lastSeen) parts.Add($"마지막 생존 관측 {lastSeen:yyyy-MM-dd HH:mm:ss} UTC");
            parts.Add("종료 시각·원인 알 수 없음");
            if (Flag(root, "fatalExceptionObserved")) parts.Add("이전 실행에서 치명적 예외 관측");
        }
        if (root.TryGetProperty("exceptions", out var exceptions) && exceptions.ValueKind == JsonValueKind.Array && exceptions.GetArrayLength() > 0)
        {
            var first = exceptions[0];
            string type = String(first, "type"), hResult = String(first, "hResult");
            if ((type.StartsWith("System.", StringComparison.Ordinal) || type.StartsWith("TerminalNotes.", StringComparison.Ordinal))
                && type.Length <= 120 && type.All(c => char.IsAsciiLetterOrDigit(c) || c is '.' or '_' or '+' or '`')) parts.Add(type);
            if (hResult.Length == 10 && hResult.StartsWith("0x", StringComparison.Ordinal) && hResult.AsSpan(2).ToString().All(Uri.IsHexDigit)) parts.Add(hResult);
        }
        if (Number(root, "priorWriteFailures") is > 0) parts.Add("이전 로그 저장 실패 관측");
        if (Number(root, "droppedEvents") is > 0) parts.Add("대기열 초과로 일부 이벤트 생략");
        return parts.Count > 0 ? string.Join(" · ", parts) : "일일 운영 기록";
    }
    private static long? Number(JsonElement root, string key, long maximum = 1L << 50) => root.ValueKind == JsonValueKind.Object && root.TryGetProperty(key, out var value) &&
        value.ValueKind == JsonValueKind.Number && value.TryGetInt64(out long number) && number >= 0 && number <= maximum ? number : null;
    private static bool Flag(JsonElement root, string key) => root.ValueKind == JsonValueKind.Object && root.TryGetProperty(key, out var value) && value.ValueKind == JsonValueKind.True;
    private static DateTimeOffset? Date(JsonElement root, string key) => DateTimeOffset.TryParse(String(root, key), CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out var date) ? date.ToUniversalTime() : null;
    private static string Label(string value, bool executable = false)
    {
        // Imported executable metadata is untrusted. Never show paths, credential
        // assignments or control characters; the remaining label stays bounded.
        if (value.Length == 0 || value.Length > 160 || value.Any(c => char.IsControl(c) || char.GetUnicodeCategory(c) == UnicodeCategory.Format || c is '/' or '\\' or ':' or '=' or '@')) return "";
        foreach (string marker in new[] { "bearer", "authorization", "password", "secret", "token", "api_key", "api-key" })
            if (value.Contains(marker, StringComparison.OrdinalIgnoreCase)) return "";
        if (executable && value.Any(c => !char.IsAsciiLetterOrDigit(c) && c is not ('.' or '_' or '-' or ' '))) return "";
        return value.Trim()[..Math.Min(value.Trim().Length, executable ? 64 : 80)];
    }
    private static MemorySample ReadMemory(JsonElement root, DateTimeOffset time)
    {
        long? appPid = Number(root, "appProcessId", int.MaxValue);
        var rows = new List<MemoryProcess>();
        bool partial = Flag(root, "isPartial");
        if (root.TryGetProperty("processes", out var processes) && processes.ValueKind == JsonValueKind.Array)
        {
            partial |= processes.GetArrayLength() > 32;
            foreach (var item in processes.EnumerateArray().Take(32))
            {
                if (item.ValueKind != JsonValueKind.Object) { partial = true; continue; }
                long? pid = Number(item, "processId", int.MaxValue);
                bool app = Flag(item, "isApp") && appPid is > 0 && pid == appPid;
                string description = Label(String(item, "description"));
                if (description.Length == 0) description = Label(String(item, "productName"));
                rows.Add(new(pid is > 0 ? pid : null, Number(item, "parentProcessId", int.MaxValue), Label(String(item, "name"), true), description,
                    Number(item, "privateBytes"), Number(item, "workingSetBytes"), app));
            }
        }
        long? total = Number(root, "totalPhysicalBytes"), available = Number(root, "availablePhysicalBytes");
        if (total.HasValue && available > total) available = null;
        return new(time, appPid is > 0 ? appPid : null, Date(root, "appStartedAtUtc"), Number(root, "systemMemoryLoadPercent", 100), total, available,
            Number(root, "treePrivateBytes"), Number(root, "treeWorkingSetBytes"), Number(root, "processCount", 1000000), Number(root, "unreadableProcessCount", 1000000), partial, rows.ToArray());
    }
    private static string Bytes(long? value) => value.HasValue ? $"{value.Value / (1024d * 1024):0.0} MiB" : "확인 불가";
    private static string Id(long? value) => value?.ToString(CultureInfo.InvariantCulture) ?? "확인 불가";
    private static void AppendMemory(StringBuilder report, MemorySample? latest, MemorySample? maximum, int count)
    {
        report.AppendLine("\n메모리 관측");
        if (latest is null) { report.AppendLine("과거 로그에 메모리 관측 기록이 없어 사용량이나 점유 프로세스를 확인할 수 없습니다."); return; }
        report.AppendLine($"메모리 기록 {count}개 · 최신 관측 {latest.Time:yyyy-MM-dd HH:mm:ss} UTC" + (latest.Partial ? " · 프로세스 일부만 측정" : ""));
        report.AppendLine($"최근 시스템 메모리 사용률: {(latest.Load.HasValue ? latest.Load + "%" : "확인 불가")} · 사용 가능 {Bytes(latest.Available)} / 전체 {Bytes(latest.Total)}");
        if (maximum is not null) report.AppendLine($"선택한 기록의 최대 사용률: {maximum.Load}% · {maximum.Time:yyyy-MM-dd HH:mm:ss} UTC (최신 앱 실행과 다를 수 있음)");
        report.AppendLine($"최신 앱 PID {Id(latest.AppPid)} · 시작 {(latest.AppStart.HasValue ? latest.AppStart.Value.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) + " UTC" : "확인 불가")}");
        AppendProcesses(report, latest, "최근 기록의 큰 메모리 점유 프로세스 (전용 메모리 순):");
        if (maximum is not null && (maximum.Time != latest.Time || maximum.AppPid != latest.AppPid || maximum.AppStart != latest.AppStart))
        {
            report.AppendLine($"\n최대 사용률 관측 당시: {maximum.Load}% · {maximum.Time:yyyy-MM-dd HH:mm:ss} UTC · 앱 PID {Id(maximum.AppPid)}" + (maximum.Partial ? " · 일부만 측정" : ""));
            AppendProcesses(report, maximum, "최대 사용률 관측 당시의 큰 메모리 점유 프로세스 (전용 메모리 순):");
            report.AppendLine("이 목록은 그 시각의 측정 근거이며, 해당 프로세스가 멈춤을 일으켰다는 판정은 아닙니다.");
        }
        report.AppendLine("프로세스 이름·설명은 해당 로그에 기록된 실행 파일 정보이며, 임의의 요청문이나 명령줄을 분석한 결과가 아닙니다.");
    }
    private static void AppendProcesses(StringBuilder report, MemorySample sample, string heading)
    {
        var app = sample.Processes.FirstOrDefault(p => p.IsApp);
        report.AppendLine($"앱 자체: 전용 메모리 {Bytes(app?.PrivateBytes)} · 작업 집합 {Bytes(app?.WorkingBytes)}");
        report.AppendLine($"측정된 앱·하위 프로세스 합계: 전용 메모리 {Bytes(sample.PrivateBytes)} · 작업 집합 {Bytes(sample.WorkingBytes)}");
        report.AppendLine($"프로세스 수 {Id(sample.Count)} · 읽지 못한 프로세스 {Id(sample.Unreadable)} · 작업 집합 합계에는 공유 페이지가 중복될 수 있습니다.");
        report.AppendLine(heading);
        foreach (var process in sample.Processes.OrderByDescending(p => p.PrivateBytes).Take(5))
            report.AppendLine($"• {(process.Name.Length > 0 ? process.Name : "이름 확인 불가")}" + (process.Description.Length > 0 ? $" ({process.Description})" : "") +
                $" · PID {Id(process.Pid)} / 부모 {Id(process.ParentPid)} · 전용 {Bytes(process.PrivateBytes)} · 작업 집합 {Bytes(process.WorkingBytes)}");
    }
    private static string EventLabel(string name) => name switch
    {
        "dispatcher_unresponsive" => "UI 응답 지연", "dispatcher_recovered" => "UI 응답 복구", "terminal_lifecycle_fault" => "터미널 수명주기 오류",
        "daily_start" => "앱 시작", "daily_normal_exit" => "정상 종료", "daily_abnormal" => "이전 비정상 종료 관측",
        "daily_fatal" => "치명적 예외 관측", "daily_error" => "앱 오류 관측", "daily_warning" => "앱 경고 관측", _ => "자동 진행"
    };
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_EXTERNALTERMINALLAUNCHER_CS
#region Services/ExternalTerminalLauncher.cs
namespace TerminalNotes.Services
{
using global::System.Diagnostics;
using global::System.IO;
using global::System.Net;
using global::System.Net.Http;
using global::System.Net.Http.Headers;
using global::System.Net.Sockets;
using global::System.Security.Cryptography;
using global::System.Text;
using global::System.Text.Json;
using global::System.Text.Json.Nodes;
using global::System.Text.RegularExpressions;


public sealed record ExternalTerminalLaunch(string Directory, string SessionId, ProcessStartInfo StartInfo)
{
    public string Project { get; init; } = string.Empty;
    public Uri? Endpoint { get; init; }
    public int Port { get; init; }
}

/// <summary>Starts a standalone CMD/OpenCode process. No ConPTY job or app lifetime owns it.</summary>
public static class ExternalTerminalLauncher
{
    private static readonly TimeSpan DefaultStartupTimeout = TimeSpan.FromSeconds(60);
    private static readonly TimeSpan PollInterval = TimeSpan.FromMilliseconds(150);
    private static readonly TimeSpan CleanupTimeout = TimeSpan.FromSeconds(10);
    private const int MaximumSessionResponseBytes = 256 * 1024;
    private static string Root => Path.Combine(OpenCodeProjectContext.DataDirectory, "CmdSessions");
    private static string Key(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
    private static string ProjectFolder(string project) => Path.Combine(Root, Key(Path.TrimEndingDirectorySeparator(Path.GetFullPath(project)).ToUpperInvariant()));
    private static string LeasePath(string project, string session) => Path.Combine(ProjectFolder(project), Key(session) + ".lock");

    public static bool IsProjectActive(string project) => System.IO.Directory.Exists(ProjectFolder(project)) &&
        System.IO.Directory.EnumerateFiles(ProjectFolder(project), "*.lock").Any(IsLocked);
    // Admission is global: a detached CMD stays active even after its pane or app closes.
    public static int ActiveSessionCount
    {
        get
        {
            try
            {
                return System.IO.Directory.Exists(Root)
                    ? System.IO.Directory.EnumerateDirectories(Root).Sum(folder => System.IO.Directory.EnumerateFiles(folder, "*.lock").Count(IsLocked))
                    : 0;
            }
            catch (IOException) { return int.MaxValue; }
            catch (UnauthorizedAccessException) { return int.MaxValue; }
        }
    }

    public static bool IsSessionActive(string project, string session) => IsLocked(LeasePath(project, session));

    /// <summary>
    /// Closes the standalone CMD windows the app opened for this project so their conversations can return to an
    /// app terminal. A running answer is aborted first, then only the recorded cmd.exe tree is ended (its lease must
    /// still be held, so a reused process ID is never touched). Returns the session IDs that were released.
    /// </summary>
    public static async Task<IReadOnlyList<string>> StopProjectAsync(string project, CancellationToken cancellationToken = default)
    {
        project = Path.GetFullPath(project);
        string folder = ProjectFolder(project);
        var released = new List<string>();
        if (!System.IO.Directory.Exists(folder)) return released;
        foreach (string launchFolder in System.IO.Directory.EnumerateDirectories(folder))
        {
            cancellationToken.ThrowIfCancellationRequested();
            string session, lease;
            int port;
            try
            {
                using var json = JsonDocument.Parse(File.ReadAllText(Path.Combine(launchFolder, "launch.json")));
                JsonElement root = json.RootElement;
                if (root.GetProperty("Project").GetString() is not { } launchProject || !DirectoriesEqual(launchProject, project)) continue;
                session = root.GetProperty("Session").GetString() ?? "";
                lease = root.GetProperty("Lease").GetString() ?? "";
                port = root.GetProperty("Port").GetInt32();
                ValidateSession(session);
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or
                InvalidDataException or KeyNotFoundException or InvalidOperationException or FormatException)
            { continue; }
            // Only this project's own lease for that session counts; launch.json cannot point elsewhere.
            if (!string.Equals(Path.GetFullPath(lease), LeasePath(project, session), StringComparison.OrdinalIgnoreCase) || !IsLocked(lease)) continue;
            if (port is >= 1 and <= 65535) await TryAbortSessionAsync(port, project, session, cancellationToken);
            if (OwnedCmdProcess(launchFolder) is { } process)
            {
                using (process)
                {
                    try { if (!process.HasExited) process.Kill(entireProcessTree: true); }
                    catch (Exception exception) when (exception is InvalidOperationException or System.ComponentModel.Win32Exception) { }
                    try { await process.WaitForExitAsync(cancellationToken).WaitAsync(CleanupTimeout, cancellationToken); }
                    catch (TimeoutException) { }
                }
            }
            DateTime deadline = DateTime.UtcNow + CleanupTimeout;
            while (IsLocked(lease))
            {
                if (DateTime.UtcNow >= deadline)
                    throw new IOException("CMD 창을 닫지 못했습니다. 해당 CMD 창을 직접 닫은 뒤 다시 시도하세요.");
                await Task.Delay(PollInterval, cancellationToken);
            }
            released.Add(session);
        }
        return released;
    }

    // The cmd.exe recorded at launch, only while it is still that process: named cmd and started after its launch folder.
    private static Process? OwnedCmdProcess(string launchFolder)
    {
        try
        {
            string pidPath = Path.Combine(launchFolder, "cmd.pid");
            if (!File.Exists(pidPath) || !int.TryParse(File.ReadAllText(pidPath).Trim(), System.Globalization.NumberStyles.None,
                    System.Globalization.CultureInfo.InvariantCulture, out int pid) || pid <= 0) return null;
            var process = Process.GetProcessById(pid);
            if (!string.Equals(process.ProcessName, "cmd", StringComparison.OrdinalIgnoreCase) ||
                process.StartTime.ToUniversalTime() < System.IO.Directory.GetCreationTimeUtc(launchFolder).AddSeconds(-5))
            {
                process.Dispose();
                return null;
            }
            return process;
        }
        catch (Exception exception) when (exception is ArgumentException or InvalidOperationException or IOException or
            UnauthorizedAccessException or System.ComponentModel.Win32Exception or NotSupportedException)
        { return null; }
    }

    // Lets OpenCode record a running answer as stopped before its window closes. Failure only means it was idle or gone.
    private static async Task TryAbortSessionAsync(int port, string project, string session, CancellationToken cancellationToken)
    {
        try
        {
            using var client = CreateHttpClient(TimeSpan.FromSeconds(3));
            var uri = new Uri($"http://127.0.0.1:{port}/session/{Uri.EscapeDataString(session)}/abort?directory={Uri.EscapeDataString(project)}");
            using var response = await client.PostAsync(uri, new StringContent("{}", Encoding.UTF8, "application/json"), cancellationToken);
        }
        catch (Exception exception) when (exception is HttpRequestException or TaskCanceledException or IOException && !cancellationToken.IsCancellationRequested)
        { }
    }

    private static bool IsLocked(string path)
    {
        if (!File.Exists(path)) return false;
        try { using var probe = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, FileShare.None); return false; }
        catch (FileNotFoundException) { return false; }
        catch (IOException) { return true; }
        catch (UnauthorizedAccessException) { return true; }
    }

    public static async Task<string> ResolveRootSessionAsync(Uri endpoint, string project, string candidate, CancellationToken token = default)
    {
        if (!endpoint.IsAbsoluteUri || !endpoint.IsLoopback || endpoint.Scheme != "http" || !string.IsNullOrEmpty(endpoint.UserInfo))
            throw new InvalidOperationException("로컬 OpenCode 세션만 이어 열 수 있습니다.");
        using var client = CreateHttpClient(TimeSpan.FromSeconds(8));
        var seen = new HashSet<string>(StringComparer.Ordinal);
        for (int depth = 0; depth < 16 && seen.Add(candidate); depth++)
        {
            ValidateSession(candidate);
            var uri = new Uri(endpoint, "/session/" + Uri.EscapeDataString(candidate) + "?directory=" + Uri.EscapeDataString(project));
            using var response = await client.GetAsync(uri, token);
            response.EnsureSuccessStatusCode();
            using var json = JsonDocument.Parse(await response.Content.ReadAsStringAsync(token));
            var root = json.RootElement;
            if (root.GetProperty("id").GetString() != candidate || root.GetProperty("directory").GetString() is not { } directory ||
                !DirectoriesEqual(directory, project))
                throw new InvalidOperationException("현재 프로젝트와 세션의 연결을 확인하지 못했습니다.");
            if (!root.TryGetProperty("parentID", out var parent) || parent.ValueKind == JsonValueKind.Null) return candidate;
            candidate = parent.GetString() ?? throw new InvalidDataException("세션 정보가 올바르지 않습니다.");
        }
        throw new InvalidDataException("이어 열 원본 세션을 확인하지 못했습니다.");
    }

    public static ExternalTerminalLaunch Prepare(string command, string project, string session, string? plan, string title, bool autoMode)
    {
        ValidateSession(session);
        project = Path.GetFullPath(project);
        if (!System.IO.Directory.Exists(project) || !File.Exists(command)) throw new FileNotFoundException("프로젝트 또는 OpenCode 실행 파일을 찾지 못했습니다.");
        if (IsSessionActive(project, session)) throw new InvalidOperationException("이 세션은 이미 CMD에서 열려 있습니다.");
        int port = ReserveLoopbackPort();
        var endpoint = new Uri($"http://127.0.0.1:{port}/");
        string folder = Path.Combine(ProjectFolder(project), Guid.NewGuid().ToString("N"));
        System.IO.Directory.CreateDirectory(folder);
        string contextPath = Path.Combine(folder, "instructions.md");
        using var context = new OpenCodeProjectContext(project, plan, title);
        File.Copy(context.InstructionFilePath, contextPath);
        var config = JsonNode.Parse(context.CreateProcessConfigContent(Environment.GetEnvironmentVariable("OPENCODE_CONFIG_CONTENT")))!.AsObject();
        var instructions = config["instructions"]!.AsArray();
        for (int i = 0; i < instructions.Count; i++)
            if (instructions[i]?.GetValue<string>() == context.InstructionFilePath) instructions[i] = contextPath;
        File.WriteAllText(Path.Combine(folder, "launch.json"), JsonSerializer.Serialize(new
        {
            Command = Path.GetFullPath(command), Project = project, Session = session, Title = title,
            Config = config.ToJsonString(), AutoMode = autoMode, Lease = LeasePath(project, session), Port = port
        }), new UTF8Encoding(false));
        File.WriteAllText(Path.Combine(folder, "launch.ps1"), Script, new UTF8Encoding(true));
        string invocation = "& '" + Path.Combine(folder, "launch.ps1").Replace("'", "''") + "'";
        var start = new ProcessStartInfo(Path.Combine(Environment.SystemDirectory, "cmd.exe"))
        {
            UseShellExecute = true, WorkingDirectory = project, WindowStyle = ProcessWindowStyle.Normal,
            // Only fixed tokens and Base64 enter cmd.exe's parser. Paths/titles/config never become shell code.
            Arguments = "/d /v:off /k powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -EncodedCommand " + Convert.ToBase64String(Encoding.Unicode.GetBytes(invocation))
        };
        return new(folder, session, start) { Project = project, Endpoint = endpoint, Port = port };
    }

    public static async Task LaunchAsync(ExternalTerminalLaunch launch, CancellationToken cancellationToken = default, TimeSpan? timeout = null)
    {
        ArgumentNullException.ThrowIfNull(launch);
        launch = RestoreMetadata(launch);
        if (string.IsNullOrWhiteSpace(launch.Project) || launch.Endpoint is not { IsLoopback: true, Scheme: "http" } endpoint ||
            launch.Port is < 1 or > 65535 || endpoint.Port != launch.Port)
            throw new InvalidOperationException("CMD launch에는 프로젝트와 loopback 시작 확인 주소가 필요합니다.");
        TimeSpan startupTimeout = timeout ?? DefaultStartupTimeout;
        if (startupTimeout <= TimeSpan.Zero) throw new ArgumentOutOfRangeException(nameof(timeout));
        using var timeoutSource = new CancellationTokenSource(startupTimeout);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, timeoutSource.Token);
        Process? process = null;
        try
        {
            linked.Token.ThrowIfCancellationRequested();
            process = Process.Start(launch.StartInfo) ?? throw new IOException("CMD 창을 열지 못했습니다.");
            await File.WriteAllTextAsync(Path.Combine(launch.Directory, "cmd.pid"), process.Id.ToString(System.Globalization.CultureInfo.InvariantCulture), cancellationToken);
            using var client = CreateHttpClient();
            Uri sessionUri = new(endpoint, "/session/" + Uri.EscapeDataString(launch.SessionId) +
                "?directory=" + Uri.EscapeDataString(launch.Project));
            while (true)
            {
                linked.Token.ThrowIfCancellationRequested();
                ThrowIfLaunchEnded(launch, process);
                bool started = File.Exists(Path.Combine(launch.Directory, "started"));
                if (started && IsSessionActive(launch.Project, launch.SessionId))
                {
                    bool verified = await VerifyExactSessionAsync(client, sessionUri, launch.SessionId, launch.Project, linked.Token);
                    ThrowIfLaunchEnded(launch, process);
                    if (verified && IsSessionActive(launch.Project, launch.SessionId)) return;
                }
                await Task.Delay(PollInterval, linked.Token);
            }
        }
        catch (OperationCanceledException ex) when (timeoutSource.IsCancellationRequested && !cancellationToken.IsCancellationRequested)
        {
            try { await StopOwnedProcessTreeAsync(process); }
            catch (Exception cleanup) { throw new IOException("CMD 시작 시간이 초과됐고 자체 프로세스 종료도 확인하지 못했습니다.", new AggregateException(ex, cleanup)); }
            throw new TimeoutException("CMD에서 OpenCode 세션 시작 확인이 시간 초과되어 자체 실행 트리를 종료했습니다.", ex);
        }
        catch (Exception startupError)
        {
            try { await StopOwnedProcessTreeAsync(process); }
            catch (Exception cleanup) { throw new IOException("CMD 시작에 실패했고 자체 프로세스 종료도 확인하지 못했습니다.", new AggregateException(startupError, cleanup)); }
            throw;
        }
        finally { process?.Dispose(); }
    }

    private static ExternalTerminalLaunch RestoreMetadata(ExternalTerminalLaunch launch)
    {
        if (!string.IsNullOrWhiteSpace(launch.Project) && launch.Endpoint is not null && launch.Port > 0)
            return launch;
        string jsonPath = Path.Combine(launch.Directory, "launch.json");
        using var json = JsonDocument.Parse(File.ReadAllText(jsonPath));
        JsonElement root = json.RootElement;
        string project = root.GetProperty("Project").GetString() ?? throw new InvalidDataException("CMD launch project is missing.");
        string session = root.GetProperty("Session").GetString() ?? throw new InvalidDataException("CMD launch session is missing.");
        int port = root.GetProperty("Port").GetInt32();
        if (!string.Equals(session, launch.SessionId, StringComparison.Ordinal) || port is < 1 or > 65535)
            throw new InvalidDataException("CMD launch metadata does not match the requested session.");
        return launch with { Project = Path.GetFullPath(project), Port = port, Endpoint = new Uri($"http://127.0.0.1:{port}/") };
    }
    private static void ThrowIfLaunchEnded(ExternalTerminalLaunch launch, Process process)
    {
        string failurePath = Path.Combine(launch.Directory, "failed.txt");
        if (File.Exists(failurePath))
        {
            string detail;
            try { detail = File.ReadAllText(failurePath); }
            catch (IOException) { detail = "실패 정보를 읽을 수 없습니다."; }
            throw new IOException("CMD 이어가기 실패 · " + detail);
        }
        if (File.Exists(Path.Combine(launch.Directory, "completed")))
            throw new IOException("OpenCode 세션이 시작 확인 전에 종료되었습니다.");
        if (process.HasExited)
            throw new IOException("CMD가 OpenCode 세션 시작을 확인하기 전에 종료되었습니다.");
    }

    private static async Task<bool> VerifyExactSessionAsync(HttpClient client, Uri uri, string session, string project, CancellationToken token)
    {
        using var requestTimeout = new CancellationTokenSource(TimeSpan.FromSeconds(2));
        using var requestCancellation = CancellationTokenSource.CreateLinkedTokenSource(token, requestTimeout.Token);
        try
        {
            using var response = await client.GetAsync(uri, HttpCompletionOption.ResponseHeadersRead, requestCancellation.Token);
            if (response.StatusCode is HttpStatusCode.NotFound or HttpStatusCode.ServiceUnavailable || (int)response.StatusCode >= 500)
                return false;
            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException("OpenCode 시작 확인 API가 HTTP " + (int)response.StatusCode + "을 반환했습니다.", null, response.StatusCode);
            await using var stream = await response.Content.ReadAsStreamAsync(requestCancellation.Token);
            using var limited = new MemoryStream();
            byte[] buffer = new byte[8192];
            while (true)
            {
                int read = await stream.ReadAsync(buffer, requestCancellation.Token);
                if (read == 0) break;
                if (limited.Length + read > MaximumSessionResponseBytes)
                    throw new InvalidDataException("OpenCode 세션 시작 응답이 너무 큽니다.");
                limited.Write(buffer, 0, read);
            }
            using var json = JsonDocument.Parse(limited.ToArray());
            JsonElement root = json.RootElement;
            if (!root.TryGetProperty("id", out var id) || id.GetString() != session ||
                !root.TryGetProperty("directory", out var directory) || directory.GetString() is not { } value || !DirectoriesEqual(value, project))
                throw new InvalidDataException("OpenCode 시작 응답이 요청한 세션 또는 프로젝트와 일치하지 않습니다.");
            return true;
        }
        catch (OperationCanceledException) when (!token.IsCancellationRequested && requestTimeout.IsCancellationRequested)
        {
            return false;
        }
        catch (HttpRequestException ex) when (ex.StatusCode is null or >= HttpStatusCode.InternalServerError)
        {
            return false;
        }
    }
    private static async Task StopOwnedProcessTreeAsync(Process? process)
    {
        if (process is null) return;
        try
        {
            if (!process.HasExited) process.Kill(entireProcessTree: true);
        }
        catch (InvalidOperationException) when (process.HasExited) { }
        catch (System.ComponentModel.Win32Exception) when (process.HasExited) { }

        try { await process.WaitForExitAsync().WaitAsync(CleanupTimeout); }
        catch (TimeoutException ex)
        {
            throw new IOException("시작에 사용한 CMD 프로세스 트리 종료를 확인하지 못했습니다.", ex);
        }
        catch (System.ComponentModel.Win32Exception ex)
        {
            throw new IOException("시작에 사용한 CMD 프로세스 트리 종료 상태를 확인하지 못했습니다.", ex);
        }
        if (!process.HasExited)
            throw new IOException("시작에 사용한 CMD 프로세스가 여전히 실행 중입니다.");
    }
    private static HttpClient CreateHttpClient(TimeSpan? timeout = null)
    {
        var client = new HttpClient(new HttpClientHandler { UseProxy = false, AllowAutoRedirect = false })
        { Timeout = timeout ?? Timeout.InfiniteTimeSpan, MaxResponseContentBufferSize = MaximumSessionResponseBytes };
        if (Environment.GetEnvironmentVariable("OPENCODE_SERVER_PASSWORD") is { Length: > 0 } password)
            client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Basic", Convert.ToBase64String(Encoding.UTF8.GetBytes(
                (Environment.GetEnvironmentVariable("OPENCODE_SERVER_USERNAME") ?? "opencode") + ":" + password)));
        return client;
    }

    private static int ReserveLoopbackPort()
    {
        using var listener = new TcpListener(IPAddress.Loopback, 0);
        listener.Start();
        return ((IPEndPoint)listener.LocalEndpoint).Port;
    }

    private static bool DirectoriesEqual(string first, string second) =>
        string.Equals(Path.TrimEndingDirectorySeparator(Path.GetFullPath(first)),
            Path.TrimEndingDirectorySeparator(Path.GetFullPath(second)), StringComparison.OrdinalIgnoreCase);

    private static void ValidateSession(string session)
    {
        if (!Regex.IsMatch(session, "\\Ases_[A-Za-z0-9_]{1,200}\\z", RegexOptions.CultureInvariant))
            throw new InvalidDataException("이어 열 세션 ID가 올바르지 않습니다.");
    }

    private const string Script = """
        $ErrorActionPreference = 'Stop'
        $cmdSessionLease = $null
        try {
            $cmdSession = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'launch.json') -Raw -Encoding UTF8 | ConvertFrom-Json
            $cmdSessionLease = [System.IO.File]::Open($cmdSession.Lease, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
            Set-Location -LiteralPath $cmdSession.Project
            $Host.UI.RawUI.WindowTitle = $cmdSession.Title + ' - OpenCode CMD'
            $env:OPENCODE_CONFIG_CONTENT = $cmdSession.Config
            $cmdSessionArgs = @('--hostname', '127.0.0.1', '--port', [string]$cmdSession.Port, '--session', $cmdSession.Session)
            if ($cmdSession.AutoMode) { $cmdSessionArgs += '--auto' }
            Write-Host 'CMD에서 기존 대화를 이어갑니다. TerminalNotes를 종료해도 이 창은 유지됩니다.'
            Write-Host '다음 요청은 이 창에 입력하세요. 지휘/검토/구현 자동 순환은 앱에서 중단되었습니다.'
            [System.IO.File]::WriteAllText((Join-Path $PSScriptRoot 'started'), 'started')
            & $cmdSession.Command @cmdSessionArgs
            if ($LASTEXITCODE -ne 0) { throw ('OpenCode exit code: ' + $LASTEXITCODE) }
        } catch {
            [System.IO.File]::WriteAllText((Join-Path $PSScriptRoot 'failed.txt'), $_.Exception.Message)
            Write-Host ('CMD 이어가기 실패: ' + $_.Exception.Message) -ForegroundColor Red
        } finally {
            if ($null -ne $cmdSessionLease) { $cmdSessionLease.Dispose() }
            [System.IO.File]::WriteAllText((Join-Path $PSScriptRoot 'completed'), 'completed')
        }
        """;
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_EXTERNALTERMINALSTATUSCACHE_CS
#region Services/ExternalTerminalStatusCache.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Collections.Immutable;


internal enum ExternalTerminalStatus { Unknown, Inactive, Active }
internal enum ExternalTerminalCheck { Authoritative, Preview }

/// <summary>Display-only lease observations. Actions must still check the actual lease.</summary>
internal sealed class ExternalTerminalStatusCache : IDisposable
{
    private sealed record Observation(ExternalTerminalStatus Status, DateTimeOffset CheckedAt);
    private readonly Func<string, bool> _probe;
    private readonly Func<DateTimeOffset> _utcNow;
    private readonly TimeSpan _refreshInterval;
    private readonly TimeSpan _maximumAge;
    private ImmutableDictionary<string, Observation> _snapshot =
        ImmutableDictionary.Create<string, Observation>(StringComparer.OrdinalIgnoreCase);
    private int _refreshing;
    private int _disposed;

    internal ExternalTerminalStatusCache(Func<string, bool> probe,
        Func<DateTimeOffset>? utcNow = null, TimeSpan? refreshInterval = null, TimeSpan? maximumAge = null)
    {
        _probe = probe;
        _utcNow = utcNow ?? (() => DateTimeOffset.UtcNow);
        _refreshInterval = refreshInterval ?? TimeSpan.FromSeconds(2);
        _maximumAge = maximumAge ?? TimeSpan.FromSeconds(5);
    }

    internal bool IsRefreshing => Volatile.Read(ref _refreshing) != 0;

    internal ExternalTerminalStatus Read(string project)
    {
        if (Volatile.Read(ref _disposed) != 0) return ExternalTerminalStatus.Unknown;
        var snapshot = Volatile.Read(ref _snapshot);
        return snapshot.TryGetValue(project, out var observation) && _utcNow() - observation.CheckedAt <= _maximumAge
            ? observation.Status : ExternalTerminalStatus.Unknown;
    }

    internal void RequestRefresh(IEnumerable<string> projects)
    {
        if (Volatile.Read(ref _disposed) != 0 || Interlocked.CompareExchange(ref _refreshing, 1, 0) != 0) return;
        string[] requested = projects.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
        _ = Task.Run(() =>
        {
            try
            {
                var snapshot = Volatile.Read(ref _snapshot);
                // Share unchanged entries across publications; each probe updates only its tree path.
                var targets = requested.ToHashSet(StringComparer.OrdinalIgnoreCase);
                var next = snapshot.RemoveRange(snapshot.Keys.Where(project => !targets.Contains(project)));
                foreach (string project in requested)
                {
                    if (Volatile.Read(ref _disposed) != 0) return;
                    if (next.TryGetValue(project, out var observation) && _utcNow() - observation.CheckedAt < _refreshInterval) continue;
                    ExternalTerminalStatus status;
                    try { status = _probe(project) ? ExternalTerminalStatus.Active : ExternalTerminalStatus.Inactive; }
                    catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
                    { status = ExternalTerminalStatus.Unknown; }
                    if (Volatile.Read(ref _disposed) != 0) return;
                    next = next.SetItem(project, new(status, _utcNow()));
                    Volatile.Write(ref _snapshot, next);
                }
                if (Volatile.Read(ref _disposed) == 0) Volatile.Write(ref _snapshot, next);
            }
            finally { Volatile.Write(ref _refreshing, 0); }
        });
    }

    // A blocked OS filesystem call cannot be cancelled. At most one probe remains, with no UI callbacks.
    public void Dispose() => Interlocked.Exchange(ref _disposed, 1);
}
}
#endregion
#endif

