    public static string FilePath => Path.Combine(DirectoryPath, "global-agent-instructions.md");

    /// <summary>Raised with the backup path when an account other than the master accounts had its own edits replaced by the
    /// default (the edited text is kept in that backup). May be raised on a background thread.</summary>
    public static event Action<string>? EditsReverted;

    /// <summary>Creates the default file and upgrades only the user-approved previous contents. For accounts other than the
    /// master accounts (InstructionEditors) any other contents also go back to the default, so a file edited outside the app
    /// is not used either (2026-11-10 사용자: 설정 화면만이 아니라 파일을 직접 고치는 것도 막기).</summary>
    public static string EnsureFile()
    {
        Directory.CreateDirectory(DirectoryPath);
        try
        {
            using var stream = new FileStream(FilePath, FileMode.CreateNew, FileAccess.Write, FileShare.Read);
            using var writer = new StreamWriter(stream, Utf8);
            writer.Write(DefaultContents);
        }
        catch (IOException) when (File.Exists(FilePath))
        {
            // Another process created it, or the user already has customized instructions.
        }
        ReplaceWithDefault(IsApprovedPreviousInstructions, "before-approved-upgrade");
        if (!InstructionEditors.Allowed) RestoreDefaultForThisAccount();
        return FilePath;
    }

    private enum Replacement { Unchanged, Replaced, Busy }

    private static Replacement RestoreDefaultForThisAccount()
    {
        byte[] defaults = Utf8.GetBytes(DefaultContents);
        var outcome = ReplaceWithDefault(bytes => !bytes.AsSpan().SequenceEqual(defaults), "before-default-restore", out string? backup);
        if (outcome == Replacement.Replaced && backup is not null) EditsReverted?.Invoke(backup);
        return outcome;
    }

    /// <summary>For accounts other than the master accounts, while the app runs: an edit, replacement or deletion of the file goes
    /// back to the default within a second, so OpenCode (which reads the file on every request) does not use it. Null for the
    /// master accounts.</summary>
    public static IDisposable? GuardDefault()
    {
        if (InstructionEditors.Allowed) return null;
        Directory.CreateDirectory(DirectoryPath);
        var watcher = new FileSystemWatcher(DirectoryPath, Path.GetFileName(FilePath))
        {
            NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite | NotifyFilters.Size,
            IncludeSubdirectories = false
        };
        global::System.Threading.Timer? pending = null;
        void Retry()
        {
            try { pending?.Change(1000, global::System.Threading.Timeout.Infinite); }
            catch (ObjectDisposedException) { }
        }
        pending = new global::System.Threading.Timer(_ =>
        {
            try
            {
                if (!File.Exists(FilePath)) EnsureFile();
                else if (RestoreDefaultForThisAccount() == Replacement.Busy) Retry();
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException) { Retry(); }
        }, null, global::System.Threading.Timeout.Infinite, global::System.Threading.Timeout.Infinite);
        global::System.Threading.Timer timer = pending;
        void Schedule()
        {
            try { timer.Change(400, global::System.Threading.Timeout.Infinite); }
            catch (ObjectDisposedException) { }
        }
        watcher.Changed += (_, _) => Schedule();
        watcher.Created += (_, _) => Schedule();
        watcher.Deleted += (_, _) => Schedule();
        watcher.Renamed += (_, _) => Schedule();
        watcher.EnableRaisingEvents = true;
        return new Guard(watcher, timer);
    }

    private sealed class Guard(FileSystemWatcher watcher, global::System.Threading.Timer timer) : IDisposable
    {
        public void Dispose()
        {
            watcher.EnableRaisingEvents = false;
            watcher.Dispose();
            timer.Dispose();
        }
    }

    private static Replacement ReplaceWithDefault(Func<byte[], bool> shouldReplace, string backupKind) =>
        ReplaceWithDefault(shouldReplace, backupKind, out _);

    private static Replacement ReplaceWithDefault(Func<byte[], bool> shouldReplace, string backupKind, out string? backupPath)
    {
        backupPath = null;
        try
        {
            using var lockStream = new FileStream(LockPath, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None);
            using var instructions = new FileStream(FilePath, FileMode.Open, FileAccess.ReadWrite, FileShare.None);
            byte[] originalBytes = ReadAllBytes(instructions);
            if (!shouldReplace(originalBytes)) return Replacement.Unchanged;

            string backup = FilePath + "." + backupKind + "." + Guid.NewGuid().ToString("N") + ".md";
            bool backupComplete = false;
            bool backupCreated = false;
            bool mutationStarted = false;
            try
            {
                using (var backupStream = new FileStream(backup, FileMode.CreateNew, FileAccess.Write, FileShare.None))
                {
                    backupCreated = true;
                    backupStream.Write(originalBytes);
                    backupStream.Flush(flushToDisk: true);
                }
                backupComplete = true;

                // Keep the target exclusively open from the check
                // through the durable backup and replacement write.
                if (!shouldReplace(ReadAllBytes(instructions)))
                {
                    TryDelete(backup);
                    return Replacement.Unchanged;
                }
                byte[] replacement = Utf8.GetBytes(DefaultContents);
                instructions.Position = 0;
                mutationStarted = true;
                instructions.SetLength(0);
                instructions.Write(replacement);
                instructions.Flush(flushToDisk: true);
                if (!ReadAllBytes(instructions).AsSpan().SequenceEqual(replacement))
                    throw new IOException("The global instruction replacement could not be verified.");
                backupPath = backup;
                return Replacement.Replaced;
            }
            catch (IOException)
            {
                if (mutationStarted) RestoreOriginalInstructions(instructions, originalBytes);
                if (backupCreated && !backupComplete) TryDelete(backup);
                return Replacement.Busy;
            }
            catch (UnauthorizedAccessException)
            {
                if (mutationStarted) RestoreOriginalInstructions(instructions, originalBytes);
                if (backupCreated && !backupComplete) TryDelete(backup);
                return Replacement.Busy;
            }
        }
        catch (IOException)
        {
            // A busy or unavailable instruction file must not prevent startup.
            return Replacement.Busy;
        }
        catch (UnauthorizedAccessException)
        {
            // A read-only or externally locked instruction file is left untouched.
            return Replacement.Busy;
        }
    }

    private static bool IsApprovedPreviousInstructions(byte[] bytes) =>
        ApprovedPreviousInstructionsHashes.Contains(Convert.ToHexString(SHA256.HashData(bytes)), StringComparer.Ordinal);

    private static byte[] ReadAllBytes(FileStream stream)
    {
        stream.Position = 0;
        using var buffer = new MemoryStream();
        stream.CopyTo(buffer);
        return buffer.ToArray();
    }

    private static void RestoreOriginalInstructions(FileStream stream, byte[] originalBytes)
    {
        try
        {
            stream.Position = 0;
            stream.SetLength(0);
            stream.Write(originalBytes);
            stream.Flush(flushToDisk: true);
        }
        catch (IOException) { }
        catch (UnauthorizedAccessException) { }
    }

    private static void TryDelete(string path)
    {
        try { if (File.Exists(path)) File.Delete(path); }
        catch (IOException) { }
        catch (UnauthorizedAccessException) { }
    }

    public static string ReadCurrent() => File.ReadAllText(EnsureFile(), Encoding.UTF8);

    /// <summary>
    /// Saves only if the file still matches the text the editor originally loaded.
    /// A persistent exclusive lock coordinates multiple TerminalNotes processes.
    /// </summary>
    public static SaveResult TrySave(string expectedContents, string newContents)
    {
        ArgumentNullException.ThrowIfNull(expectedContents);
        ArgumentNullException.ThrowIfNull(newContents);
        EnsureFile();

        FileStream lockStream;
        try
        {
            lockStream = new FileStream(LockPath, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None);
        }
        catch (IOException)
        {
            return SaveResult.Busy;
        }

        using (lockStream)
        {
            try
            {
                // Keep the current file open without sharing write access until the
                // replacement is committed. This also detects edits made by an
                // external Markdown editor between the UI read and save.
                using var currentFile = new FileStream(FilePath, FileMode.Open, FileAccess.Read, FileShare.Read | FileShare.Delete);
                string current;
                using (var reader = new StreamReader(currentFile, Encoding.UTF8, detectEncodingFromByteOrderMarks: true, leaveOpen: true))
                    current = reader.ReadToEnd();
                if (!string.Equals(current, expectedContents, StringComparison.Ordinal))
                    return SaveResult.Conflict;

                string temporaryPath = FilePath + "." + Guid.NewGuid().ToString("N") + ".tmp";
                try
                {
                    File.WriteAllText(temporaryPath, newContents, Utf8);
                    File.Replace(temporaryPath, FilePath, destinationBackupFileName: null);
                    return SaveResult.Saved;
                }
                finally
                {
                    if (File.Exists(temporaryPath)) File.Delete(temporaryPath);
                }
            }
            catch (IOException)
            {
                return SaveResult.Busy;
            }
            catch (UnauthorizedAccessException) { return SaveResult.Busy; }
        }
    }

    public enum SaveResult { Saved, Conflict, Busy }

    private const string DefaultContents = """
        # 프로젝트 터미널 작업 지침

        ## 핵심 원칙

        1. 목적은 사용자가 원하는 것을 실제로 동작하는 수준까지 만드는 것이다. 토큰 사용량이나 변경 규모 때문에 작업을 줄이거나 멈추지 않는다. 필요하면 여러 파일 수정, 구조 변경, 기존 로직 교체도 하고, 큰 작업은 쪼개서 끝까지 한다.
        2. 우선순위: 사용자의 가장 최근 명시적 지시가 플랜, 불러온 스킬, 이 지침보다 우선한다. 스킬의 구체적인 절차는 이 지침의 일반 원칙보다 우선한다. 데이터 보호와 되돌리기 어려운 작업에 관한 규칙은 항상 지킨다.
        3. 요청은 문자 그대로의 최소 범위가 아니라 목적(무엇을, 누가 쓰려고, 어느 완성도로)에 맞게 해석한다. 해석이 갈리면 사용자 의도에 가장 가까운 쪽을 택하고 이유를 보고에 남긴다. 의도와 무관한 기능이나 변경은 더하지 않는다.
        4. 추측하지 않는다. 코드·설정·문서·실행 결과로 확인한 사실과 확인하지 못한 것을 구분해 말한다.
        5. 직접 실행해 확인하기 전에는 완료라고 하지 않는다.
        6. 사용자에게 하는 설명·질문·보고는 한국어로 짧고 구체적으로 쓴다. 코드, 명령, 경로, 식별자, 오류 원문은 번역하지 않고 그대로 둔다.

        ## 요청과 플랜

        - 가장 최근 요청을 기준으로 일한다. 최초 목표와 수락된 제약은 유지하고, 최신 메시지는 현재 작업의 추가 지시·수정·질문으로 반영한다.
        - 과거 터미널 입력 기록, 보관된 프롬프트, 화면 출력, 승인 응답은 새 요청으로 보지 않는다.
        - 프로젝트 `plan.md`가 있으면 요청과 함께 읽고 현재 코드·이미 적용된 변경·유효한 검증 결과와 대조한다. 플랜은 작업의 지도다: 우선순위·순서·완료 기준은 따르되, 완료 표시가 없거나 TODO가 남았다는 이유만으로 이미 구현된 기능을 다시 만들지 않는다.
        - `plan.md`를 고칠 때는 바뀐 요구사항만 반영한다. 날짜·시간, 완료·진행 표시, 작업 기록, 검증 결과, 변경 이력은 쓰지 않는다. 완료 여부와 진행 상황은 보고로만 알린다.
        - 질문에는 답하고, 구현이나 파일 수정을 요청받지 않았으면 파일을 바꾸지 않는다.
        - 되돌릴 수 있는 결정은 사용자 목표에 가장 맞는 쪽으로 정해 진행하고 그 가정을 보고에 남긴다. 사용자만 아는 사실(계정, 비밀정보, 업무 규칙, 실제 데이터)이나 되돌리기 어려운 선택만 구체적인 선택지와 추천을 붙여 묻는다.

        ## 품질 기준

        - 실제 사용자가 그대로 쓸 수 있게 만든다. 빈 값, 잘못된 입력, 파일·네트워크 오류, 권한 부족을 처리하고, 사용자에게 보이는 메시지는 무엇이 문제이고 어떻게 하면 되는지 알 수 있게 쓴다.
        - 임시 코드, 가짜 데이터, 하드코딩된 예시 값, `TODO`, 주석 처리된 미완성 코드, 동작하지 않는 단추를 남기지 않는다. 사용자가 시제품이나 예시를 원한 경우만 예외이고 그 사실을 보고에 밝힌다.
        - 기존 코드의 구조, 이름 규칙, 스타일, 사용 중인 라이브러리를 따른다. 같은 일을 하는 코드가 있으면 새로 만들지 않고 재사용하거나 고친다.
        - 외부 라이브러리·API·명령은 프로젝트에 설치된 버전과 문서·코드를 확인하고 쓴다. 존재를 확인하지 않은 함수나 옵션을 쓰지 않는다.
        - 비밀번호·토큰·API 키는 코드나 저장소에 넣지 않고 환경 변수나 저장소에서 제외된 설정 파일로 다룬다.

        ## 디자인

        - 항상 심플하고 미니멀하게, 단순하고 간단하게 만든다. 화면에는 꼭 필요한 요소만 두고 장식, 쓰지 않는 단추, 과한 색과 효과를 넣지 않는다. 코드도 같은 결과를 내는 더 단순한 구조를 택한다. 사용자가 원한 기능을 빼라는 뜻은 아니다.
        - 화면 글자와 메시지는 꼭 필요한 말만 짧게 쓴다. 설명 문단, 같은 안내의 반복, 긴 결과 메시지를 넣지 않는다. 꼭 필요한 안내는 입력칸 안내문이나 툴팁으로 둔다.
        - 화면이 있으면 첫 화면에서 할 일이 보이고 진행 중·완료·오류 상태가 드러나게 한다.
        - 모든 요소(제목, 본문, 보조 설명, 단추, 입력칸, 목록·표, 툴팁, 제목 표시줄)의 글자가 배경과 충분히 대비되게 한다. 마우스 오버·선택·비활성 상태에서도 글자가 배경에 묻히지 않는지 실제 화면으로 확인한다. 어두운 테마는 창 전체에 적용해 기본 글자색(검정)이 남지 않게 한다.
        - C# WPF 앱은 기본 Windows 제목 표시줄 대신 앱 테마에 맞는 모던하고 깔끔한 제목 표시줄을 직접 만들고 최소화·최대화(이전 크기로)·닫기 단추를 넣는다. 끌어서 옮기기, 두 번 눌러 최대화, 가장자리 크기 조절이 되고 최대화했을 때 작업 표시줄을 가리지 않는지 확인한다.

        ## 진행 방법

        - 시작 전에 관련 지침과 요청에 필요한 코드·설정·문서를 조사한다. `rg`로 파일명과 심볼을 찾고 정의·호출자·상태 전이와 저장·읽기·재열기·실행 경로를 따라간다.
        - 증상은 재현할 수 있으면 먼저 재현하고, 호출 흐름을 따라 원인을 확인한 뒤 고친다.
        - 여러 단계가 필요하면 시작할 때 목표, 완료 기준, 단계 목록(todo)을 정하고 실제 결과에 맞게 갱신한다. 각 단계가 실제로 동작하는지 확인한 뒤 다음으로 넘어간다. 막히면 같은 시도를 고집하지 말고 원인을 다시 보고 다른 접근을 쓴다.
        - 필요한 부분만 읽고 쓴다. 큰 파일은 바꿀 부분만 고치고, 긴 로그와 출력은 필요한 줄만 걸러 보며, 긴 작업은 한 응답에 몰아 쓰지 않고 단계별로 나눈다.
        - 정상 완료, 실패, 차단을 구분할 수 있는 실제 신호를 관찰한다. 출력이 없거나 오래 걸린다는 이유만으로 완료·실패·정체를 단정하지 않는다. 느린 시작, 대기, 장시간 실행은 현재 단계와 관찰 가능한 근거로 판단하고, 진행을 지어내거나 성급히 중단하지 않는다.
        - 같은 검색이나 검증에서 새 증거가 두 번 연속 나오지 않으면 반복하지 말고 다른 관련 경로를 확인한다. 그래도 진전이 없으면 확인한 사실, 막힌 이유, 필요한 입력을 정리해 보고한다.

        ## 실행 환경

        - Windows에서 실행된다. 명령을 실행하기 전에 현재 셸(PowerShell, cmd, bash)을 확인하고 그 셸의 문법을 쓴다. 공백이나 한글이 든 경로는 따옴표로 감싼다.
        - 한글이 든 파일은 UTF-8로 읽고 쓴다. Windows PowerShell 5.1의 `Get-Content`·`Set-Content`는 기본 인코딩이 UTF-8이 아니므로 인코딩을 명시한다.
        - 개발 서버나 감시(watch) 모드처럼 스스로 끝나지 않는 명령으로 작업을 멈추게 하지 않는다. 실행 확인은 1~2분 안에서만 하고, 직접 시작한 프로세스만 정확히 종료한 뒤 종료됐는지 확인한다. 프로세스 이름으로 일괄 종료하지 않는다.
        - Python·Excel처럼 메모리를 많이 쓰는 프로그램은 같은 작업에 하나만 띄우고, 다시 실행하기 전에 이전 실행이 끝났는지 확인한다. 같은 처리를 매번 처음부터 다시 돌리지 말고 중간 결과를 파일로 저장해 다시 쓰며, 큰 데이터는 필요한 열·행만 읽는다. 조회·외부 연결에는 시간 제한을 두고, 끝나면 연결과 xlwings로 연 Excel 앱(`app.quit()`)을 닫는다.
        - 이 앱은 태스크에서 실행한 프로그램의 메모리를 제한한다(PC 여유 메모리에 맞춰 바뀌고, 프로그램 하나는 RAM의 절반까지). MemoryError·out of memory·heap out of memory·메모리 할당 실패가 나면 같은 방식으로 다시 실행하지 않는다. 데이터를 나눠(청크·스트리밍) 처리하고, 필요한 열·행만 읽고, 중간 결과를 파일로 넘겨 메모리를 줄인 뒤 다시 실행한다. 동시에 띄운 다른 무거운 프로그램은 먼저 끝낸다.
        - 새 패키지는 꼭 필요할 때만 추가하고 이미 설치된 도구와 표준 기능을 먼저 쓴다. 네트워크·프록시·권한 문제로 설치가 실패하면 같은 설치를 반복하지 말고 대안을 찾거나 필요한 조치를 보고한다.
        - PC에 NPU가 있으면(작업 관리자 성능 탭, `Get-PnpDevice -Class ComputeAccelerator`) 모델 추론·임베딩·음성·이미지 처리 같은 AI 연산은 NPU를 먼저 쓴다. NPU를 쓰는 실행 방식(Windows ML, ONNX Runtime의 QNN·OpenVINO·DirectML 실행 공급자 등)을 프로젝트에 맞게 고르고 실제로 NPU에서 실행되는지 확인한다. NPU가 없거나 그 연산을 지원하지 않으면 GPU, 그다음 CPU를 쓰고 이유를 보고에 남긴다.

        ## DRM이 걸린 문서

        - DRM으로 보호된 Office 파일은 openpyxl·pandas·python-pptx 같은 라이브러리로 열 수 없다. `File is not a zip file`이나 암호화·형식 오류가 나면 DRM을 의심한다.
        - DRM이 걸린 Excel 파일은 xlwings로만 연다. 다른 방법을 시도하지 말고 처음부터 `xw.App(visible=False)` → `app.books.open(경로)`로 열고, 값과 서식도 xlwings로 읽고 쓴다. 결과는 새 파일로 저장하고 원본은 사용자가 요청한 경우에만 덮어쓴다.
        - xlwings는 Excel 전용이다. PowerPoint·Word 파일은 pywin32의 `win32com.client.Dispatch("PowerPoint.Application")`·`Dispatch("Word.Application")`로 연다.
        - 직접 연 문서와 앱만 닫는다. 사용자가 이미 열어 둔 Office 창은 닫지 않는다.

        ## 데이터레이크

        - 데이터레이크(datalake) 데이터는 Impala로만 조회·처리한다. Hive·Spark 같은 다른 엔진이나 원본 파일 직접 읽기로 우회하지 않는다.
        - 접속 주소·포트·인증 정보는 사용자가 알려 준 값만 쓰고 지어내지 않는다. 비밀번호를 코드나 파일에 남기지 않는다.

        ## 자동 진행(Loop)

        - 앱이 자동 진행으로 작업을 이어 갈 때는 사용자가 바로 답할 수 없다. 되돌릴 수 있는 결정은 묻지 말고 사용자 목표에 맞게 정해 진행하며 가정을 보고에 남긴다.
        - 매 회차에는 플랜에서 아직 동작하지 않는 항목과 실제 결함 중 사용자에게 영향이 가장 큰 것부터 처리한다. 회차 결과는 보고에만 남긴다.
        - 같은 부분을 근거 없이 계속 고치거나 이미 잘 동작하는 부분을 갈아엎지 않는다. 바꾼 뒤에는 기존 기능이 깨지지 않았는지 확인한다.
        - 되돌리기 어렵거나 비밀정보·결제·외부 계정·사용자 승인이 꼭 필요한 결정만 이유와 함께 멈추고 묻는다.

        ## 변경과 데이터 보호

        - 필요하면 기존 로직을 크게 고치거나 교체해도 된다. 변경 이유는 확인할 수 있게 남기고, 요청과 무관한 기존 동작은 제거하지 않는다.
        - 저장 파일·설정·세션·초안·기록을 정리한다는 명목으로 삭제하지 않는다.
        - 파일·폴더 대량 삭제, git 강제 푸시·기록 재작성, 배포·외부 게시는 사용자가 명시적으로 요청한 경우에만 한다.
        - git 저장소면 시작할 때 `git status`로 커밋되지 않은 사용자 변경을 확인하고 덮어쓰지 않는다. 사용자 파일을 덮어쓰기 전에 기존 데이터와 충돌하지 않는지 확인한다.
        - 비밀정보와 터미널 원문 입력을 불필요하게 출력·저장·복사하지 않는다. 요청받지 않으면 원문 입력, 메시지 내용, 세션 식별자, 시간 측정 기록을 새로 만들지 않는다.

        ## 검증

        - 변경의 위험과 영향 범위에 맞게 검증한다. 빌드와 관련 테스트를 실행하고, 바꾼 동작에 맞는 테스트를 추가하거나 갱신한다.
        - 앱·서비스는 실제 실행 경로에서 사용자처럼 써 본다: 주요 흐름을 처음부터 끝까지, 빈 상태와 오류 상태, 다시 실행한 뒤 데이터가 유지되는지까지 확인한다.
        - 목(mock)이나 시뮬레이션 결과를 실제 외부 서비스·모델·사용자 세션의 검증으로 표현하지 않는다.
        - 빌드 성공은 런타임 검증이 아니다. 오래된 실행 파일이나 이전 게시 폴더의 결과를 현재 소스의 결과라고 하지 않는다.
        - 검증이 실패하면 원인을 확인해 고치고 다시 검증한다. 검증하지 못했으면 이유와 미확인 범위를 보고한다.

        ## 단일 세션과 도구

        - 이 앱의 OpenCode는 프로젝트별 단일 에이전트 세션으로 작업한다. 역할을 나눈 에이전트 팀, 하위 에이전트, 자동 순환 스케줄러를 만들지 않는다.
        - OpenCode에 설정된 기본 모델과 이 프로세스에 주입된 도구·권한·승인 설정을 그대로 따르고 모델을 바꾸지 않는다. 사용자가 금지한 외부 통신이나 도구를 우회하지 않는다.

        ## 스킬과 플러그인

        - 작업을 시작할 때 `skill` 도구의 스킬 목록을 확인한다. 요청과 맞는 스킬이 있으면 먼저 불러와 그 절차대로 하고, 스킬에 든 정해진 규칙이나 작업 방식을 추측으로 대신하지 않는다. 맞는 스킬이 없으면 묻거나 기다리지 말고 진행한다.
        - 사용한 스킬 이름은 마무리 보고에 적는다.
        - 플러그인은 OpenCode 시작 때 자동으로 실행되므로 따로 불러오지 않는다. 플러그인이 더한 도구가 작업에 맞으면 같은 기능을 새로 만들지 말고 그 도구를 쓴다.
        - 요청받지 않으면 `~/.config/opencode/skills`·`~/.config/opencode/plugins`의 파일을 고치거나 지우지 않는다.

        ## 마무리

        - 끝내기 전에 이번 변경 전체를 다시 읽고 요구사항과 완료 기준을 하나씩 대조한다. 빠진 항목, 버그, 경계 상황 누락, 디버그 출력, 불필요한 변경, 남은 임시 코드를 찾으면 고치고 다시 검증한다.
        - 완료 조건:
          - 최초 목표, 최신 수정, 수락된 제약, 플랜을 모두 반영했고 실제로 동작한다.
          - 관련 호출자와 저장·읽기·재열기·실행 경로에서 바뀐 동작을 검증했다.
          - 영향받는 기존 동작과 데이터를 보존했다.
          - 빌드와 의미 있는 테스트를 실행했거나, 못 한 이유와 미확인 범위를 밝혔다.
          - 테스트 더블·시뮬레이션 결과와 실제 실행 결과를 구분했고, 하지 않은 검증을 했다고 하지 않는다.
        - 보고는 바뀐 점(경로와 이유) → 확인 결과(실행한 검증과 실제 결과) → 남은 문제(미확인 사항과 제한) 순서로 사실만 짧게 쓴다. 변경이 없으면 기존 구현과 그 근거를 설명한다. 완료라고 하려면 코드 변경이나 유효한 검증 같은 확인 가능한 근거가 있어야 한다.
        - 다음 작업으로 넘길 때는 현재 요청, 완료한 범위, 남은 구체 항목, 관련 경로, 마지막 검증과 결과를 보고에 남긴다. `plan.md`에는 쓰지 않는다. 완료한 일을 다시 하라고 지시하거나, 없는 증거를 만들거나, 사용자의 원문 프롬프트를 불필요하게 복제하지 않는다.
        """;
}

/// <summary>OpenCode's own global settings file, edited from 설정 like the global instructions (사용자: "설정에서 전역지침 편집하듯이
/// 플러그인이 저장되는 컨피그 파일도 편집가능하게", "플러그인은 하나만 편집하게"): models, permissions and plugins, the file
/// `opencode plugin -g` writes to. Only this one: tui.json (the terminal screen's plugins) and a task's .opencode\ stay OpenCode's.</summary>
internal static class OpenCodeConfigFile
{
    internal const string Title = "OpenCode 설정";
    private const string Purpose = "모델·권한·플러그인(plugin)을 정합니다.";
    private const string Starting = "{\n  \"$schema\": \"https://opencode.ai/config.json\"\n}\n";
    // OpenCode reads all of these, later over earlier, and writes to the first that exists.
    private static readonly string[] Names = ["opencode.jsonc", "opencode.json", "config.json"];
    private static readonly UTF8Encoding Utf8 = new(encoderShouldEmitUTF8Identifier: false);

    // OpenCode reads <XDG_CONFIG_HOME or ~/.config>/opencode when it starts; tests point this elsewhere.
    private static string FolderPath => AppContext.GetData("TerminalNotes.OpenCodeConfigDirectory") is string test
        ? Path.GetFullPath(test)
        : Path.Combine(Environment.GetEnvironmentVariable("XDG_CONFIG_HOME") is { Length: > 0 } config
            ? config : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".config"), "opencode");

    /// <summary>The file OpenCode writes to: the first name that exists, or a new opencode.jsonc.</summary>
    internal static string FilePath
    {
        get
        {
            string folder = FolderPath;
            return Path.Combine(folder, Array.Find(Names, name => File.Exists(Path.Combine(folder, name))) ?? Names[0]);
        }
    }

    /// <summary>What it is for, and the other files beside it: OpenCode reads those too, so a value may come from them.</summary>
    internal static string Description
    {
        get
        {
            string folder = FolderPath, chosen = Path.GetFileName(FilePath);
            string[] others = Array.FindAll(Names, name => name != chosen && File.Exists(Path.Combine(folder, name)));
            return others.Length == 0 ? Purpose : $"{Purpose} 같은 폴더에 {string.Join(", ", others)}도 있습니다.";
        }
    }

    internal static string ReadCurrent()
    {
        string path = FilePath;
        return File.Exists(path) ? File.ReadAllText(path) : Starting;
    }

    /// <summary>Saves valid JSON or JSONC only: OpenCode refuses to start on a broken file. A file changed since it was opened (by
    /// `opencode plugin`, say) is not overwritten.</summary>
    internal static GlobalAgentInstructions.SaveResult TrySave(string expectedContents, string newContents)
    {
        Validate(newContents);
        string path = FilePath, temporary = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
        try
        {
            if (!string.Equals(ReadCurrent(), expectedContents, StringComparison.Ordinal)) return GlobalAgentInstructions.SaveResult.Conflict;
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(temporary, newContents, Utf8);
            if (File.Exists(path)) File.Replace(temporary, path, destinationBackupFileName: null);
            else File.Move(temporary, path);
            return GlobalAgentInstructions.SaveResult.Saved;
        }
        catch (IOException) { return GlobalAgentInstructions.SaveResult.Busy; }
        catch (UnauthorizedAccessException) { return GlobalAgentInstructions.SaveResult.Busy; }
        finally
        {
            try { File.Delete(temporary); }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
        }
    }

    private static void Validate(string contents)
    {
        try
        {
            using var parsed = global::System.Text.Json.JsonDocument.Parse(contents, new global::System.Text.Json.JsonDocumentOptions
                { AllowTrailingCommas = true, CommentHandling = global::System.Text.Json.JsonCommentHandling.Skip });
            if (parsed.RootElement.ValueKind != global::System.Text.Json.JsonValueKind.Object)
                throw new InvalidOperationException("설정 전체를 { }로 감싸야 합니다.");
        }
        catch (global::System.Text.Json.JsonException exception)
        {
            throw new InvalidOperationException($"JSON 형식이 맞지 않습니다 · {exception.LineNumber + 1}번째 줄");
        }
    }
}

/// <summary>OpenCode's own global instructions, &lt;XDG_CONFIG_HOME or ~/.config&gt;/opencode/AGENTS.md (2026-11-10 사용자: "사용자는
/// opencode 지침만 수정하게 설정에서 기능을 하나 추가하고 마스터인 경우에만 opencode 지침, 터미널 노트 전역지침, 플랜메이커 전역지침
/// 이렇게 수정되게 해"). Every account edits this one; the app never writes it otherwise. OpenCode reads it inside and outside
/// Terminal Notes, together with the Terminal Notes instructions it is given. Without this file OpenCode falls back to
/// ~/.claude/CLAUDE.md (checked with OpenCode 1.18.34), so creating it replaces that fallback.</summary>
internal static class OpenCodeAgentInstructions
{
    internal const string Title = "OpenCode 지침";
    private static readonly UTF8Encoding Utf8 = new(encoderShouldEmitUTF8Identifier: false);

    // Same folder as OpenCodeConfigFile: OpenCode reads <XDG_CONFIG_HOME or ~/.config>/opencode; tests point this elsewhere.
    private static string FolderPath => AppContext.GetData("TerminalNotes.OpenCodeConfigDirectory") is string test
        ? Path.GetFullPath(test)
        : Path.Combine(Environment.GetEnvironmentVariable("XDG_CONFIG_HOME") is { Length: > 0 } config
            ? config : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".config"), "opencode");

    internal static string FilePath => Path.Combine(FolderPath, "AGENTS.md");

    private static string ClaudeFallbackPath => Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".claude", "CLAUDE.md");

    private static bool ClaudeFallbackDisabled =>
        new[] { "OPENCODE_DISABLE_CLAUDE_CODE", "OPENCODE_DISABLE_CLAUDE_CODE_PROMPT" }.Any(name =>
            Environment.GetEnvironmentVariable(name) is { } value && (value == "1" || value.Equals("true", StringComparison.OrdinalIgnoreCase)));

    internal static string Description
    {
        get
        {
            const string purpose = "Terminal Notes 밖에서 쓰는 OpenCode에도 적용합니다. Terminal Notes 안에서는 Terminal Notes 지침과 함께 쓰입니다.";
            return !File.Exists(FilePath) && !ClaudeFallbackDisabled && File.Exists(ClaudeFallbackPath)
                ? purpose + " 지금은 이 파일이 없어 OpenCode가 ~/.claude/CLAUDE.md를 읽습니다. 저장하면 그 대신 이 파일을 읽습니다(CLAUDE.md는 그대로)."
                : purpose;
        }
    }

    internal static string ReadCurrent()
    {
        string path = FilePath;
        return File.Exists(path) ? File.ReadAllText(path) : string.Empty;
    }

    /// <summary>A file changed since it was opened is not overwritten; saving unchanged text writes nothing (so opening and saving
    /// an empty editor does not create the file and hide the CLAUDE.md fallback).</summary>
    internal static GlobalAgentInstructions.SaveResult TrySave(string expectedContents, string newContents)
    {
        ArgumentNullException.ThrowIfNull(expectedContents);
        ArgumentNullException.ThrowIfNull(newContents);
        string path = FilePath, temporary = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
        try
        {
            string current = ReadCurrent();
            if (!string.Equals(current, expectedContents, StringComparison.Ordinal)) return GlobalAgentInstructions.SaveResult.Conflict;
            if (string.Equals(current, newContents, StringComparison.Ordinal)) return GlobalAgentInstructions.SaveResult.Saved;
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(temporary, newContents, Utf8);
            if (File.Exists(path)) File.Replace(temporary, path, destinationBackupFileName: null);
            else File.Move(temporary, path);
            return GlobalAgentInstructions.SaveResult.Saved;
        }
        catch (IOException) { return GlobalAgentInstructions.SaveResult.Busy; }
        catch (UnauthorizedAccessException) { return GlobalAgentInstructions.SaveResult.Busy; }
        finally
        {
            try { File.Delete(temporary); }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_MARKDOWNDOCUMENT_CS
#region Services/MarkdownDocument.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Security.Cryptography;
using global::System.Text;


/// <summary>
/// Represents a Markdown file while preserving its on-disk Unicode encoding.
/// </summary>
public sealed class MarkdownDocument
{
    public const int MaxFileSizeBytes = 5 * 1024 * 1024;

    private readonly DocumentEncoding _encoding;
    private string _text;
    private string _originalText;
    private FileFingerprint? _originalFingerprint;

    private MarkdownDocument(
        string? filePath,
        string text,
        DocumentEncoding encoding,
        FileFingerprint? originalFingerprint)
    {
        FilePath = filePath;
        _text = text;
        _originalText = text;
        _encoding = encoding;
        _originalFingerprint = originalFingerprint;
    }

    public string? FilePath { get; private set; }

    public string Text
    {
        get => _text;
        set => _text = value ?? throw new ArgumentNullException(nameof(value));
    }

    public bool IsDirty => !string.Equals(_text, _originalText, StringComparison.Ordinal);

    public static MarkdownDocument Create() =>
        new(filePath: null, text: string.Empty, DocumentEncoding.Utf8, originalFingerprint: null);

    public static MarkdownDocument Load(string path)
    {
        string fullPath = NormalizePath(path);
        byte[] bytes;

        using (var stream = new FileStream(
                   fullPath,
                   FileMode.Open,
                   FileAccess.Read,
                   FileShare.Read,
                   bufferSize: 64 * 1024,
                   FileOptions.SequentialScan))
        {
            if (stream.Length > MaxFileSizeBytes)
            {
                throw new IOException(
                    $"The file is larger than the {MaxFileSizeBytes / (1024 * 1024)} MB limit: {fullPath}");
            }

            bytes = new byte[checked((int)stream.Length)];
            stream.ReadExactly(bytes);
        }

        (DocumentEncoding encoding, int preambleLength) = DetectEncoding(bytes, fullPath);
        string text = Decode(bytes.AsSpan(preambleLength), encoding, fullPath);
        var fingerprint = new FileFingerprint(bytes.LongLength, Hash(bytes));

        return new MarkdownDocument(fullPath, text, encoding, fingerprint);
    }

    public void Save(string? path = null, bool overwriteExternalChanges = false)
    {
        string destination = path is null
            ? FilePath ?? throw new InvalidOperationException("A path is required when saving a new document.")
            : NormalizePath(path);

        bool isTrackedPath = FilePath is not null && PathsEqual(FilePath, destination);
        bool mustMatchOriginal = isTrackedPath && !overwriteExternalChanges;

        if (!isTrackedPath && !overwriteExternalChanges && File.Exists(destination))
        {
            throw new DocumentConflictException(
                destination,
                "The Save As destination already exists and was not overwritten.");
        }

        byte[] bytes = Encode(_text, _encoding, destination);
        string? temporaryPath = null;

        try
        {
            temporaryPath = WriteTemporaryFile(destination, bytes);

            if (mustMatchOriginal)
            {
                ReplaceTrackedFile(temporaryPath, destination);
            }
            else if (overwriteExternalChanges && File.Exists(destination))
            {
                ReplaceExistingFile(temporaryPath, destination);
            }
            else
            {
                MoveNewFile(temporaryPath, destination, overwriteExternalChanges);
            }

            temporaryPath = null;
            FilePath = destination;
            _originalText = _text;
            _originalFingerprint = new FileFingerprint(bytes.LongLength, Hash(bytes));
        }
        finally
        {
            if (temporaryPath is not null)
            {
                try
                {
                    File.Delete(temporaryPath);
                }
                catch (IOException)
                {
                    // The destination is intact; an orphaned temporary file is safer than masking the save error.
                }
                catch (UnauthorizedAccessException)
                {
                    // See above.
                }
            }
        }
    }

    private void ReplaceTrackedFile(string temporaryPath, string destination)
    {
        if (_originalFingerprint is null)
        {
            throw new InvalidOperationException("The document has no original file fingerprint.");
        }

        FileStream currentFile;
        try
        {
            // Sharing deletion lets the atomic replace happen while denying concurrent write handles.
            currentFile = new FileStream(
                destination,
                FileMode.Open,
                FileAccess.Read,
                FileShare.Read | FileShare.Delete,
                bufferSize: 64 * 1024,
                FileOptions.SequentialScan);
        }
        catch (IOException exception) when (
            exception is FileNotFoundException or DirectoryNotFoundException)
        {
            throw new DocumentConflictException(
                destination,
                "The file was deleted or moved after it was opened.",
                exception);
        }

        using (currentFile)
        {
            if (currentFile.Length > MaxFileSizeBytes)
            {
                throw new DocumentConflictException(
                    destination,
                    "The file changed after it was opened and is now larger than the supported limit.");
            }

            var currentFingerprint = new FileFingerprint(currentFile.Length, Hash(currentFile));
            if (currentFingerprint != _originalFingerprint.Value)
            {
                throw new DocumentConflictException(
                    destination,
                    "The file changed on disk after it was opened.");
            }

            try
            {
                File.Replace(temporaryPath, destination, destinationBackupFileName: null, ignoreMetadataErrors: true);
            }
            catch (IOException exception) when (!File.Exists(destination))
            {
                throw new DocumentConflictException(
                    destination,
                    "The file was deleted or moved while the save was being completed.",
                    exception);
            }
        }
    }

    private static void ReplaceExistingFile(string temporaryPath, string destination)
    {
        try
        {
            File.Replace(temporaryPath, destination, destinationBackupFileName: null, ignoreMetadataErrors: true);
        }
        catch (IOException) when (!File.Exists(destination))
        {
            // The destination disappeared between the existence check and the replace.
            File.Move(temporaryPath, destination);
        }
    }

    private static void MoveNewFile(string temporaryPath, string destination, bool overwriteExternalChanges)
    {
        try
        {
            File.Move(temporaryPath, destination);
        }
        catch (IOException exception) when (!overwriteExternalChanges && File.Exists(destination))
        {
            throw new DocumentConflictException(
                destination,
                "A file appeared at the Save As destination before the save completed.",
                exception);
        }
        catch (IOException) when (overwriteExternalChanges && File.Exists(destination))
        {
            File.Replace(temporaryPath, destination, destinationBackupFileName: null, ignoreMetadataErrors: true);
        }
    }

    private static string WriteTemporaryFile(string destination, byte[] bytes)
    {
        string? directory = Path.GetDirectoryName(destination);
        if (string.IsNullOrEmpty(directory))
        {
            throw new DirectoryNotFoundException($"The destination has no parent directory: {destination}");
        }

        for (int attempt = 0; attempt < 10; attempt++)
        {
            string temporaryPath = Path.Combine(directory, $".terminalnotes-{Guid.NewGuid():N}.tmp");
            FileStream stream;
            try
            {
                stream = new FileStream(
                    temporaryPath,
                    FileMode.CreateNew,
                    FileAccess.Write,
                    FileShare.None,
                    bufferSize: 64 * 1024,
                    FileOptions.WriteThrough);
            }
            catch (IOException) when (File.Exists(temporaryPath))
            {
                // An extremely unlikely generated-name collision; try another name.
                continue;
            }

            try
            {
                using (stream)
                {
                    stream.Write(bytes);
                    stream.Flush(flushToDisk: true);
                }

                return temporaryPath;
            }
            catch
            {
                try
                {
                    File.Delete(temporaryPath);
                }
                catch (IOException)
                {
                    // Preserve the original write error.
                }
                catch (UnauthorizedAccessException)
                {
                    // Preserve the original write error.
                }

                throw;
            }
        }

        throw new IOException($"Could not create a temporary file beside: {destination}");
    }

    private static byte[] Encode(string text, DocumentEncoding documentEncoding, string path)
    {
        Encoding encoding = GetEncoding(documentEncoding);
        byte[] payload;
        try
        {
            payload = encoding.GetBytes(text);
        }
        catch (EncoderFallbackException exception)
        {
            throw new InvalidDataException($"The document contains text that cannot be encoded: {path}", exception);
        }

        byte[] preamble = encoding.GetPreamble();
        long totalLength = (long)preamble.Length + payload.Length;
        if (totalLength > MaxFileSizeBytes)
        {
            throw new IOException(
                $"The encoded document is larger than the {MaxFileSizeBytes / (1024 * 1024)} MB limit: {path}");
        }

        byte[] result = GC.AllocateUninitializedArray<byte>(checked((int)totalLength));
        preamble.CopyTo(result, 0);
        payload.CopyTo(result, preamble.Length);
        return result;
    }

    private static (DocumentEncoding Encoding, int PreambleLength) DetectEncoding(
        ReadOnlySpan<byte> bytes,
        string path)
    {
        if (bytes.StartsWith(new byte[] { 0x00, 0x00, 0xFE, 0xFF }) ||
            bytes.StartsWith(new byte[] { 0xFF, 0xFE, 0x00, 0x00 }))
        {
            throw new InvalidDataException($"UTF-32 Markdown files are not supported: {path}");
        }

        if (bytes.StartsWith(new byte[] { 0xEF, 0xBB, 0xBF }))
        {
            return (DocumentEncoding.Utf8Bom, 3);
        }

        if (bytes.StartsWith(new byte[] { 0xFF, 0xFE }))
        {
            return (DocumentEncoding.Utf16LittleEndian, 2);
        }

        if (bytes.StartsWith(new byte[] { 0xFE, 0xFF }))
        {
            return (DocumentEncoding.Utf16BigEndian, 2);
        }

        return (DocumentEncoding.Utf8, 0);
    }

    private static string Decode(ReadOnlySpan<byte> bytes, DocumentEncoding documentEncoding, string path)
    {
        try
        {
            return GetEncoding(documentEncoding).GetString(bytes);
        }
        catch (DecoderFallbackException exception)
        {
            throw new InvalidDataException($"The file is not valid {EncodingName(documentEncoding)} text: {path}", exception);
        }
    }

    private static Encoding GetEncoding(DocumentEncoding encoding) => encoding switch
    {
        DocumentEncoding.Utf8 => new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true),
        DocumentEncoding.Utf8Bom => new UTF8Encoding(encoderShouldEmitUTF8Identifier: true, throwOnInvalidBytes: true),
        DocumentEncoding.Utf16LittleEndian => new UnicodeEncoding(
            bigEndian: false,
            byteOrderMark: true,
            throwOnInvalidBytes: true),
        DocumentEncoding.Utf16BigEndian => new UnicodeEncoding(
            bigEndian: true,
            byteOrderMark: true,
            throwOnInvalidBytes: true),
        _ => throw new ArgumentOutOfRangeException(nameof(encoding))
    };

    private static string EncodingName(DocumentEncoding encoding) => encoding switch
    {
        DocumentEncoding.Utf8 or DocumentEncoding.Utf8Bom => "UTF-8",
        DocumentEncoding.Utf16LittleEndian or DocumentEncoding.Utf16BigEndian => "UTF-16",
        _ => "Unicode"
    };

    private static string NormalizePath(string path)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);
        return Path.GetFullPath(path);
    }

    private static bool PathsEqual(string first, string second) =>
        string.Equals(
            first,
            second,
            OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);

    private static string Hash(ReadOnlySpan<byte> bytes) =>
        Convert.ToHexString(SHA256.HashData(bytes));

    private static string Hash(Stream stream) =>
        Convert.ToHexString(SHA256.HashData(stream));

    private readonly record struct FileFingerprint(long Length, string Sha256);

    private enum DocumentEncoding
    {
        Utf8,
        Utf8Bom,
        Utf16LittleEndian,
        Utf16BigEndian
    }
}

/// <summary>
/// Thrown when saving would overwrite a file that changed or an existing Save As target.
/// </summary>
public sealed class DocumentConflictException : IOException
{
    public DocumentConflictException(string filePath, string message)
        : base(message)
    {
        FilePath = filePath;
    }

    public DocumentConflictException(string filePath, string message, Exception innerException)
        : base(message, innerException)
    {
        FilePath = filePath;
    }

    public string FilePath { get; }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEAUTOMATIONCLIENT_CS
#region Services/OpenCodeAutomationClient.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Globalization;
using global::System.Net.Http;
using global::System.Net;
using global::System.Net.Http.Headers;
using global::System.Text;
using global::System.Text.Json;


public sealed record OpenCodeAutomationDispatch(
    string SessionId,
    string MessageId,
    string Prompt = "",
    DateTimeOffset? SubmittedAt = null,
    AutomationRole? Role = null)
{
    public AutomationWorkflowPhase? WorkflowPhase { get; init; }
}

/// <summary>
/// A failure reported by the native OpenCode automation API. POST requests are
/// never retried because their effects may have reached the visible session.
/// </summary>
public sealed class OpenCodeAutomationException : Exception
{
    public OpenCodeAutomationException(string code, string message, Exception? innerException = null)
        : base(message, innerException) => Code = code;

    public string Code { get; }
}

/// <summary>
/// Creates and selects one visible OpenCode root session, submits its role
/// prompt through the native API, and reads completion from native session data.
/// </summary>
public sealed partial class OpenCodeAutomationClient : IDisposable
{
    private const int MaximumResponseBytes = 2 * 1024 * 1024;
    private const int MaximumPromptCharacters = 256 * 1024;
    private const int MaximumMessageCount = 200;
    private const int MaximumSessions = 100;
    private const int MaximumDescendantDepth = 16;
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(3);
    private static readonly TimeSpan OperationTimeout = TimeSpan.FromSeconds(12);
    private static readonly TimeSpan SubmissionAcknowledgementGrace = TimeSpan.FromSeconds(15);

    private readonly Uri _serverUri;
    private readonly string _directory;
    private readonly HttpClient _httpClient;
    private readonly bool _ownsHttpClient;
    private readonly string? _authorization;
    private readonly bool _useTuiSelection;
    private bool _disposed;

    // A null completion can mean a healthy busy session OR a failed read. Expose
    // the latter without changing the safe same-session retry behavior.
    public string? LastReadWarning { get; private set; }
    public IReadOnlyCollection<string> ObservedSessionIds { get; private set; } = [];

    public OpenCodeAutomationClient(Uri serverUri, string directory, HttpClient? httpClient = null, TimeProvider? timeProvider = null, bool useTuiSelection = true)
    {
        ArgumentNullException.ThrowIfNull(serverUri);
        ArgumentException.ThrowIfNullOrWhiteSpace(directory);
        if (!serverUri.IsAbsoluteUri || (serverUri.Scheme != Uri.UriSchemeHttp && serverUri.Scheme != Uri.UriSchemeHttps))
            throw new ArgumentException("The OpenCode server URI must be an absolute HTTP URI.", nameof(serverUri));
        if (!serverUri.IsLoopback)
            throw new ArgumentException("The OpenCode automation server must use a loopback address.", nameof(serverUri));
        if (!string.IsNullOrEmpty(serverUri.UserInfo))
            throw new ArgumentException("Credentials must be supplied through OpenCode server environment settings.", nameof(serverUri));
        if (!string.IsNullOrEmpty(serverUri.Query) || !string.IsNullOrEmpty(serverUri.Fragment))
            throw new ArgumentException("The OpenCode server URI cannot include a query or fragment.", nameof(serverUri));

        _serverUri = serverUri;
        _timeProvider = timeProvider ?? TimeProvider.System;
        _useTuiSelection = useTuiSelection;
        _directory = Path.GetFullPath(directory);
        _authorization = CreateAuthorizationHeader();
        if (httpClient is null)
        {
            _httpClient = new HttpClient(new HttpClientHandler
            {
                UseProxy = false,
                AllowAutoRedirect = false
            });
            _httpClient.Timeout = Timeout.InfiniteTimeSpan;
            _ownsHttpClient = true;
        }
        else
        {
            _httpClient = httpClient;
        }
    }

    /// <summary>
    /// Creates a dedicated root session, selects it in the visible TUI, and
    /// submits one exact user message. The callback runs at the final submit
    /// boundary, after session creation and selection, so callers can recheck
    /// ownership and cancellation immediately before the non-repeatable POST.
    /// </summary>
    public async Task<OpenCodeAutomationDispatch> StartAsync(
        string title,
        string prompt,
        string? model,
        CancellationToken cancellationToken = default,
        Action? beforeSubmit = null,
        Action<string>? sessionCreated = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(title);
        ArgumentException.ThrowIfNullOrWhiteSpace(prompt);
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (title.Length > 512)
            throw new ArgumentException("The automation session title exceeds the bounded title size.", nameof(title));
        if (prompt.Length > MaximumPromptCharacters)
            throw new ArgumentException("The role prompt exceeds the bounded prompt size.", nameof(prompt));
        ModelReference? modelReference = ParseModel(model);

        using var operationTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        operationTimeout.CancelAfter(OperationTimeout);
        CancellationToken token = operationTimeout.Token;
        try
        {
            // A successful, well-formed status read proves the loopback endpoint
            // is ready before the first state-changing request is attempted.
            using (JsonDocument status = await GetJsonAsync(BuildEndpoint("/session/status"), token).ConfigureAwait(false))
                _ = RequireObject(status.RootElement, "session status map");

            using JsonDocument created = await PostJsonAsync(
                BuildEndpoint("/session"),
                new { title },
                token,
                "session_create").ConfigureAwait(false);
            JsonElement createdSession = RequireObject(created.RootElement, "created session");
            string sessionId = GetString(createdSession, "id") ?? "";
            ValidateSessionId(sessionId);
            VerifySessionIdentity(createdSession, sessionId, title, requireTitle: true);
            if (GetString(createdSession, "parentID") is not null)
                throw Failure("not_root_session", "OpenCode created a child session where a dedicated root session was required.");

            using (JsonDocument detail = await GetJsonAsync(BuildSessionEndpoint(sessionId), token).ConfigureAwait(false))
            {
                JsonElement session = RequireObject(detail.RootElement, "session detail");
                VerifySessionIdentity(session, sessionId, title, requireTitle: true);
                if (GetString(session, "parentID") is not null)
                    throw Failure("not_root_session", "OpenCode returned a child session where a dedicated root session was required.");
            }

            if (_useTuiSelection)
            using (JsonDocument selected = await PostJsonAsync(
                       BuildEndpoint("/tui/select-session"),
                       new { sessionID = sessionId },
                       token,
                       "tui_select").ConfigureAwait(false))
            {
                if (selected.RootElement.ValueKind != JsonValueKind.True)
                    throw Failure("tui_select_not_confirmed", "OpenCode did not acknowledge the exact session selection broadcast.");
            }

            string messageId = OpenCodeRecoveryClient.CreateMessageId();
            sessionCreated?.Invoke(sessionId);
            object promptRequest = modelReference is null
                ? new
                {
                    messageID = messageId,
                    parts = new[] { new { type = "text", text = prompt, metadata = new { terminalnotes = new { requestID = messageId } } } }
                }
                : new
                {
                    messageID = messageId,
                    parts = new[] { new { type = "text", text = prompt, metadata = new { terminalnotes = new { requestID = messageId } } } },
                    model = new { providerID = modelReference.ProviderID, modelID = modelReference.ModelID }
                };
            byte[] promptPayload = JsonSerializer.SerializeToUtf8Bytes(promptRequest);
            if (promptPayload.Length > MaximumResponseBytes)
                throw Failure("payload_too_large", "The role prompt request exceeds the bounded JSON payload size.");

            token.ThrowIfCancellationRequested();
            beforeSubmit?.Invoke();
            token.ThrowIfCancellationRequested();
            var dispatch = new OpenCodeAutomationDispatch(
                sessionId,
                messageId,
                prompt,
                _timeProvider.GetUtcNow(),
                AutomationStageOutputContract.RoleFromPrompt(prompt))
            {
                WorkflowPhase = AutomationStageOutputContract.PhaseFromPrompt(prompt)
            };
            try
            {
                await PostPromptAsync(sessionId, promptPayload, token).ConfigureAwait(false);
            }
            catch (OpenCodeAutomationException exception) when (exception.Code == "prompt_response_ambiguous")
            {
                // The POST may already have reached OpenCode. Preserve its exact
                // session/message identity and let ReadCompletionAsync reconcile it;
                // resubmitting here could execute a mutating role twice.
            }
            return dispatch;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (OperationCanceledException exception)
        {
            throw Failure("request_timeout", "OpenCode did not finish the bounded session setup and prompt submission.", exception);
        }
        catch (OpenCodeAutomationException)
        {
            throw;
        }
        catch (HttpRequestException exception)
        {
            throw Failure("disconnected", "The OpenCode loopback server could not complete session setup or prompt submission.", exception);
        }
        catch (IOException exception)
        {
            throw Failure("invalid_response", "OpenCode returned a response that could not be read safely.", exception);
        }
        catch (JsonException exception)
        {
            throw Failure("invalid_response", "OpenCode returned malformed JSON during session setup or prompt submission.", exception);
        }
    }

    /// <summary>
    /// Reads one bounded native snapshot. Pending work, blocked input, uncertain
    /// reads, and recovery awaiting confirmed quiescence all retain this dispatch.
    /// </summary>
    public async Task<AutomationStageOutput?> ReadCompletionAsync(
        OpenCodeAutomationDispatch dispatch,
        CancellationToken cancellationToken = default)
    {
        LastReadWarning = null;
        ArgumentNullException.ThrowIfNull(dispatch);
        ValidateSessionId(dispatch.SessionId);
        ValidateMessageId(dispatch.MessageId);
        ObjectDisposedException.ThrowIf(_disposed, this);

        using var operationTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        operationTimeout.CancelAfter(OperationTimeout);
        CancellationToken token = operationTimeout.Token;
        try
        {
            AutomationSnapshot snapshot = await ReadSnapshotAsync(dispatch, token).ConfigureAwait(false);
            ObserveProgress(dispatch, snapshot);
            if (_recoveryReason is not null)
                return RecoveredOutputIfIdle(snapshot);
            // A tool error can be followed by corrective work in the same turn.
            // Never release ownership while that turn or a descendant is active.
            if (snapshot.Status is NativeRunStatus.Busy or NativeRunStatus.Retry ||
                snapshot.HasBusyDescendants || snapshot.HasPendingInput || snapshot.HasRunningTools)
                return null;
            foreach (AssistantMessage assistant in snapshot.AssistantMessages)
            {
                if (assistant.Error is not null)
                    return FailureOutput("OpenCode reported an assistant error: " + BoundText(assistant.Error), snapshot.Tokens);
                if (assistant.HasToolError)
                    return FailureOutput("OpenCode reported a tool error in the exact role response.", snapshot.Tokens);
            }
            if (!snapshot.HasTargetUserMessage)
            {
                if (IsWithinAcknowledgementGrace(dispatch)) return null;
                return FailureOutput("The exact role user message is missing from its native OpenCode session.");
            }
            if (!snapshot.LatestUserMessageIsTarget)
                return FailureOutput("A later user message replaced this role dispatch in its dedicated session.");
            if (!snapshot.TargetUserTextMatches)
                return FailureOutput("The exact role user message does not contain the submitted prompt.");

            if (snapshot.AssistantMessages.Count == 0)
            {
                if (IsWithinAcknowledgementGrace(dispatch)) return null;
                return FailureOutput("OpenCode became idle without creating an assistant response for the exact role message.");
            }

            foreach (AssistantMessage assistant in snapshot.AssistantMessages)
            {
                if (assistant.HasRunningTool)
                    return null;
                if (assistant.Finish is null || assistant.CompletedAt is null)
                {
                    if (IsWithinAcknowledgementGrace(dispatch)) return null;
                    return FailureOutput("OpenCode became idle before the exact role assistant message had a terminal finish and completion time.");
                }
            }

            AssistantMessage finalAssistant = snapshot.AssistantMessages
                .OrderByDescending(item => item.CreatedAt)
                .ThenByDescending(item => item.Id, StringComparer.Ordinal)
                .First();
            if (!string.Equals(finalAssistant.Finish, "stop", StringComparison.Ordinal))
                return FailureOutput("The exact role turn ended without a successful terminal assistant finish.");
            if (finalAssistant.CompletedAt < finalAssistant.CreatedAt)
                return FailureOutput("OpenCode returned an invalid completion time for the exact role response.");

            string responseText = string.Concat(finalAssistant.TextParts);
            if (!AutomationStageOutputContract.TryParse(
                responseText,
                dispatch.Role ?? AutomationStageOutputContract.RoleFromPrompt(dispatch.Prompt),
                dispatch.WorkflowPhase ?? AutomationStageOutputContract.PhaseFromPrompt(dispatch.Prompt),
                out AutomationStageOutput? output,
                out _,
                out string? error))
                return FailureOutput(error ?? "OpenCode's final assistant response did not match the required JSON contract.", snapshot.Tokens);

            return output! with { Tokens = snapshot.Tokens };
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (OperationCanceledException)
        {
            ObserveTransportFailure();
            LastReadWarning = "OpenCode 결과 조회 시간 초과 · 동일 세션 재확인";
            return null;
        }
        catch (OpenCodeAutomationException exception) when (exception.Code == "transient_http_error")
        {
            ObserveTransportFailure();
            LastReadWarning = exception.Message;
            return null;
        }
        catch (OpenCodeAutomationException exception)
        {
            ResetTransportFailures();
            // An invalid snapshot does not prove that a mutating session stopped.
            LastReadWarning = exception.Message;
            return null;
        }
        catch (HttpRequestException)
        {
            ObserveTransportFailure();
            LastReadWarning = "OpenCode 결과 조회 연결 실패 · 동일 세션 재확인";
            return null;
        }
        catch (IOException)
        {
            ObserveTransportFailure();
            LastReadWarning = "OpenCode 결과 응답 읽기 실패 · 동일 세션 재확인";
            return null;
        }
        catch (JsonException exception)
        {
            ResetTransportFailures();
            LastReadWarning = "OpenCode returned malformed JSON in the native completion read. " + exception.GetType().Name + ".";
            return null;
        }
        finally
        {
            if (LastReadWarning is not null) ResetProgressObservation();
        }
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        if (_ownsHttpClient) _httpClient.Dispose();
    }

    private async Task<AutomationSnapshot> ReadSnapshotAsync(OpenCodeAutomationDispatch dispatch, CancellationToken cancellationToken)
    {
        using JsonDocument detailDocument = await GetJsonAsync(BuildSessionEndpoint(dispatch.SessionId), cancellationToken).ConfigureAwait(false);
        JsonElement detail = RequireObject(detailDocument.RootElement, "session detail");
        VerifySessionIdentity(detail, dispatch.SessionId, expectedTitle: null, requireTitle: false);
        if (GetString(detail, "parentID") is not null)
            throw Failure("not_root_session", "The target automation session is no longer a root session.");

        Task<JsonDocument> statusTask = GetJsonAsync(BuildEndpoint("/session/status"), cancellationToken);
        Task<JsonDocument> childTask = GetJsonAsync(BuildSessionEndpoint(dispatch.SessionId, "/children"), cancellationToken);
        Task<JsonDocument> permissionTask = GetJsonAsync(BuildEndpoint("/permission"), cancellationToken);
        Task<JsonDocument> questionTask = GetJsonAsync(BuildEndpoint("/question"), cancellationToken);
        Task<JsonDocument> messagesTask = GetJsonAsync(
            BuildSessionEndpoint(dispatch.SessionId, "/message", "limit=" + MaximumMessageCount.ToString(CultureInfo.InvariantCulture)),
            cancellationToken);
        try { await Task.WhenAll(statusTask, childTask, permissionTask, questionTask, messagesTask).ConfigureAwait(false); }
        catch
        {
            foreach (var task in new[] { statusTask, childTask, permissionTask, questionTask, messagesTask })
                if (task.IsCompletedSuccessfully) task.Result.Dispose();
            throw;
        }

        using JsonDocument statusDocument = await statusTask.ConfigureAwait(false);
        using JsonDocument childDocument = await childTask.ConfigureAwait(false);
        using JsonDocument permissionDocument = await permissionTask.ConfigureAwait(false);
        using JsonDocument questionDocument = await questionTask.ConfigureAwait(false);
        using JsonDocument messagesDocument = await messagesTask.ConfigureAwait(false);

        JsonElement statuses = RequireObject(statusDocument.RootElement, "session status map");
        NativeRunStatus rootStatus = ReadStatus(statuses, dispatch.SessionId);
        List<SessionIdentity> descendants = await ReadDescendantsAsync(
            dispatch.SessionId,
            RequireArray(childDocument.RootElement, "session children"),
            cancellationToken).ConfigureAwait(false);
        HashSet<string> sessionIds = new(StringComparer.Ordinal) { dispatch.SessionId };
        foreach (SessionIdentity descendant in descendants)
            sessionIds.Add(descendant.Id);

        bool busyDescendants = false;
        bool retrying = rootStatus == NativeRunStatus.Retry;
        bool descendantTools = false;
        var progress = new StringBuilder();
        var activeSessionIds = new List<string>();
        if (rootStatus != NativeRunStatus.Idle) activeSessionIds.Add(dispatch.SessionId);
        foreach (SessionIdentity descendant in descendants.OrderBy(item => item.Id, StringComparer.Ordinal))
        {
            NativeRunStatus status = ReadStatus(statuses, descendant.Id);
            if (status is NativeRunStatus.Busy or NativeRunStatus.Retry)
            {
                busyDescendants = true;
                activeSessionIds.Add(descendant.Id);
            }
            retrying |= status == NativeRunStatus.Retry;
            using JsonDocument childMessages = await GetJsonAsync(
                BuildSessionEndpoint(descendant.Id, "/message", "limit=" + MaximumMessageCount), cancellationToken).ConfigureAwait(false);
            bool childTools = AppendMessageProgress(progress, childMessages.RootElement, descendant.Id);
            descendantTools |= childTools;
            if (childTools && !activeSessionIds.Contains(descendant.Id)) activeSessionIds.Add(descendant.Id);
        }

        bool hasPendingPermission = HasPendingInput(permissionDocument.RootElement, "permissions", sessionIds);
        bool hasPendingQuestion = HasPendingInput(questionDocument.RootElement, "questions", sessionIds);
        bool pendingInput = hasPendingPermission || hasPendingQuestion;
        MessageEvidence messages = ParseMessages(
            RequireArray(messagesDocument.RootElement, "session messages"),
            dispatch.SessionId,
            dispatch.MessageId,
            dispatch.Prompt);
        bool runningTools = AppendMessageProgress(progress, messagesDocument.RootElement, dispatch.SessionId, dispatch.MessageId);
        if (runningTools && !activeSessionIds.Contains(dispatch.SessionId)) activeSessionIds.Add(dispatch.SessionId);
        ObservedSessionIds = sessionIds.ToArray();
        return new AutomationSnapshot(
            rootStatus,
            busyDescendants,
            pendingInput,
            messages.HasTargetUserMessage,
            messages.LatestUserMessageIsTarget,
            messages.TargetUserTextMatches,
            messages.AssistantMessages,
            messages.Tokens,
            Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(progress.ToString()))),
            progress.Length > 0,
            progress.ToString(Math.Max(0, progress.Length - 10000), Math.Min(progress.Length, 10000)),
            runningTools || descendantTools,
            retrying,
            activeSessionIds,
            messagesDocument.RootElement.EnumerateArray().Any(row =>
                GetString(GetProperty(row, "info"), "role") == "user" &&
                GetString(GetProperty(row, "info"), "id") != dispatch.MessageId));
    }

    private async Task<List<SessionIdentity>> ReadDescendantsAsync(
        string rootSessionId,
        JsonElement initialChildren,
        CancellationToken cancellationToken)
    {
        var result = new List<SessionIdentity>();
        var pending = new Queue<(string ParentId, JsonElement Children, int Depth)>();
        pending.Enqueue((rootSessionId, initialChildren, 1));
        var seen = new HashSet<string>(StringComparer.Ordinal) { rootSessionId };
        while (pending.Count > 0)
        {
            (string parentId, JsonElement children, int depth) = pending.Dequeue();
            if (depth > MaximumDescendantDepth)
                throw Failure("descendant_depth_exceeded", "The automation session descendant tree exceeded the supported depth.");
            foreach (JsonElement childElement in children.EnumerateArray())
            {
                JsonElement child = RequireObject(childElement, "child session");
                string id = GetString(child, "id") ?? "";
                ValidateSessionId(id);
                if (!seen.Add(id))
                    throw Failure("ambiguous_descendant", "OpenCode returned a duplicate session in the automation descendant tree.");
                if (seen.Count - 1 > MaximumSessions)
                    throw Failure("too_many_descendants", "The automation session exceeded the supported descendant count.");
                string? actualParentId = GetString(child, "parentID");
                if (!string.Equals(actualParentId, parentId, StringComparison.Ordinal))
                    throw Failure("descendant_identity_mismatch", "OpenCode returned a child session with an unexpected parent ID.");
                string childDirectory = GetString(child, "directory") ?? "";
                if (!DirectoriesEqual(childDirectory, _directory))
                    throw Failure("descendant_directory_mismatch", "OpenCode returned a descendant session from a different directory.");

                var identity = new SessionIdentity(id, parentId, childDirectory);
                result.Add(identity);
                using JsonDocument nested = await GetJsonAsync(
                    BuildSessionEndpoint(id, "/children"),
                    cancellationToken).ConfigureAwait(false);
                pending.Enqueue((id, RequireArray(nested.RootElement, "descendant children").Clone(), depth + 1));
            }
        }
        return result;
    }

    private async Task<JsonDocument> GetJsonAsync(Uri endpoint, CancellationToken cancellationToken)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, endpoint);
        return await SendJsonAsync(request, cancellationToken).ConfigureAwait(false);
    }

    private async Task<JsonDocument> PostJsonAsync(Uri endpoint, object payload, CancellationToken cancellationToken, string operation)
    {
        using var request = CreateJsonRequest(HttpMethod.Post, endpoint, JsonSerializer.SerializeToUtf8Bytes(payload));
        try
        {
            return await SendJsonAsync(request, cancellationToken).ConfigureAwait(false);
        }
        catch (OpenCodeAutomationException exception) when (exception.Code is "request_timeout" or "disconnected" or "invalid_response")
        {
            throw Failure(operation + "_ambiguous", "The " + operation + " response was lost or invalid; OpenCode was not sent a retry.", exception);
        }
    }

    private async Task<JsonDocument> SendJsonAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        using var requestTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        requestTimeout.CancelAfter(RequestTimeout);
        using HttpResponseMessage response = await SendCoreAsync(request, requestTimeout.Token).ConfigureAwait(false);
        EnsureSuccess(response);
        byte[] bytes = await ReadBoundedAsync(
            await response.Content.ReadAsStreamAsync(requestTimeout.Token).ConfigureAwait(false),
            MaximumResponseBytes,
            requestTimeout.Token).ConfigureAwait(false);
        return JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 48 });
    }

    private async Task PostPromptAsync(string sessionId, byte[] payload, CancellationToken cancellationToken)
    {
        using var request = CreateJsonRequest(HttpMethod.Post, BuildSessionEndpoint(sessionId, "/prompt_async"), payload);
        using var requestTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        requestTimeout.CancelAfter(RequestTimeout);
        try
        {
            using HttpResponseMessage response = await SendCoreAsync(request, requestTimeout.Token).ConfigureAwait(false);
            if (response.StatusCode != HttpStatusCode.NoContent)
            {
                if ((int)response.StatusCode is >= 400 and < 500)
                    throw Failure("prompt_rejected", $"OpenCode rejected the exact role prompt with HTTP {(int)response.StatusCode}.");
                throw Failure("prompt_response_ambiguous", $"OpenCode returned HTTP {(int)response.StatusCode} for the role prompt; it was not retried.");
            }
        }
        catch (OperationCanceledException exception)
        {
            throw Failure("prompt_response_ambiguous", "The role prompt response timed out after dispatch may have begun; it was not retried.", exception);
        }
        catch (HttpRequestException exception)
        {
            throw Failure("prompt_response_ambiguous", "The role prompt response was lost after dispatch may have begun; it was not retried.", exception);
        }
    }

    private async Task<HttpResponseMessage> SendCoreAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        if (_authorization is not null)
            request.Headers.Authorization = AuthenticationHeaderValue.Parse(_authorization);
        HttpResponseMessage response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
        Uri requested = request.RequestUri ?? throw Failure("invalid_request", "The OpenCode request did not have an endpoint URI.");
        Uri? finalUri = response.RequestMessage?.RequestUri;
        if (finalUri is null || !IsAllowedFinalUri(finalUri) || !UriEquals(requested, finalUri))
        {
            response.Dispose();
            throw Failure("redirect_rejected", "OpenCode redirected a loopback request to a different endpoint.");
        }
        return response;
    }

    private void EnsureSuccess(HttpResponseMessage response)
    {
        if (response.IsSuccessStatusCode) return;
        bool transient = response.StatusCode is HttpStatusCode.RequestTimeout or HttpStatusCode.TooManyRequests ||
                         (int)response.StatusCode >= 500;
        throw Failure(transient ? "transient_http_error" : "http_error",
            $"OpenCode returned HTTP {(int)response.StatusCode} for {response.RequestMessage?.RequestUri?.AbsolutePath ?? "a native API request"}.");
    }

    private HttpRequestMessage CreateJsonRequest(HttpMethod method, Uri endpoint, byte[] payload)
    {
        var request = new HttpRequestMessage(method, endpoint)
        {
            Content = new ByteArrayContent(payload)
        };
        request.Content.Headers.ContentType = new MediaTypeHeaderValue("application/json");
        return request;
    }

    private Uri BuildEndpoint(string path, string? query = null)
    {
        string root = _serverUri.GetLeftPart(UriPartial.Authority) + _serverUri.AbsolutePath.TrimEnd('/');
        string endpoint = root + path;
        var queryParts = new List<string>();
        if (query is not null) queryParts.Add(query);
        queryParts.Add("directory=" + Uri.EscapeDataString(_directory));
        return new Uri(endpoint + "?" + string.Join("&", queryParts), UriKind.Absolute);
    }

    private Uri BuildSessionEndpoint(string sessionId, string suffix = "", string? query = null) =>
        BuildEndpoint("/session/" + Uri.EscapeDataString(sessionId) + suffix, query);

    private static NativeRunStatus ReadStatus(JsonElement statuses, string sessionId)
    {
        if (!statuses.TryGetProperty(sessionId, out JsonElement status))
            return NativeRunStatus.Idle; // OpenCode omits idle sessions from its status map.
        if (status.ValueKind != JsonValueKind.Object)
            throw Failure("invalid_status", "OpenCode returned a malformed session status entry.");
        return GetString(status, "type") switch
        {
            "idle" => NativeRunStatus.Idle,
            "busy" => NativeRunStatus.Busy,
            "retry" => NativeRunStatus.Retry,
            string value => throw Failure("invalid_status", "OpenCode returned an unknown session status: " + BoundText(value) + "."),
            null => throw Failure("invalid_status", "OpenCode returned a session status without its native type.")
        };
    }

    private static bool HasPendingInput(JsonElement entries, string resource, HashSet<string> targetSessionIds)
    {
        JsonElement array = RequireArray(entries, resource);
        bool found = false;
        foreach (JsonElement entryElement in array.EnumerateArray())
        {
            JsonElement entry = RequireObject(entryElement, resource + " entry");
            string? sessionId = GetString(entry, "sessionID");
            if (string.IsNullOrWhiteSpace(sessionId))
                throw Failure("invalid_pending_input", "OpenCode returned a " + resource + " entry without a session ID.");
            if (targetSessionIds.Contains(sessionId)) found = true;
        }
        return found;
    }

    private static MessageEvidence ParseMessages(JsonElement messages, string sessionId, string targetMessageId, string expectedPrompt)
    {
        JsonElement[] rows = messages.EnumerateArray().ToArray();
        if (rows.Length > MaximumMessageCount)
            throw Failure("too_many_messages", "OpenCode returned more messages than the bounded role session read permits.");

        var parsed = new List<ParsedMessage>(rows.Length);
        foreach (JsonElement rowElement in rows)
        {
            JsonElement row = RequireObject(rowElement, "message row");
            JsonElement info = RequireObject(GetProperty(row, "info"), "message info");
            string id = GetString(info, "id") ?? "";
            string? role = GetString(info, "role");
            string? actualSessionId = GetString(info, "sessionID");
            if (string.IsNullOrWhiteSpace(id) || role is not ("user" or "assistant"))
                throw Failure("invalid_message", "OpenCode returned a message without a recognized ID or role.");
            if (!string.Equals(actualSessionId, sessionId, StringComparison.Ordinal))
                throw Failure("message_session_mismatch", "OpenCode returned a message from a different session.");
            JsonElement parts = RequireArray(GetProperty(row, "parts"), "message parts");
            long created = ReadRequiredTime(GetProperty(GetProperty(info, "time"), "created"), "message creation");
            long? completed = ReadOptionalTime(GetProperty(GetProperty(info, "time"), "completed"), "message completion");
            string? parentId = GetString(info, "parentID");
            string? finish = GetString(info, "finish");
            string? messageError = ParseError(GetProperty(info, "error"));
            var textParts = new List<string>();
            bool hasToolError = false;
            bool hasRunningTool = false;
            foreach (JsonElement partElement in parts.EnumerateArray())
            {
                JsonElement part = RequireObject(partElement, "message part");
                string? type = GetString(part, "type");
                if (type == "text")
                {
                    string? text = GetString(part, "text");
                    if (text is null) throw Failure("invalid_message", "OpenCode returned a text part without text.");
                    textParts.Add(text);
                }
                else if (type == "tool")
                {
                    JsonElement state = GetProperty(part, "state");
                    if (state.ValueKind != JsonValueKind.Object)
                        throw Failure("invalid_message", "OpenCode returned a tool part without a state object.");
                    string? toolStatus = GetString(state, "status");
                    if (toolStatus is "pending" or "running") hasRunningTool = true;
                    if (toolStatus == "error") hasToolError = true;
                    if (toolStatus is not ("pending" or "running" or "completed" or "error"))
                        throw Failure("invalid_message", "OpenCode returned a tool part with an unknown state.");
                }
            }

            long messageTokens = ReadTokenCount(GetProperty(info, "tokens"));
            parsed.Add(new ParsedMessage(id, role, parentId, created, completed, finish, messageError, textParts, hasToolError, hasRunningTool, messageTokens));
        }

        ParsedMessage? targetUser = parsed.FirstOrDefault(message =>
            message.Role == "user" && string.Equals(message.Id, targetMessageId, StringComparison.Ordinal));
        if (parsed.Count(message => message.Role == "user" && string.Equals(message.Id, targetMessageId, StringComparison.Ordinal)) > 1)
            throw Failure("duplicate_message_id", "OpenCode returned the target user message more than once.");
        ParsedMessage? latestUser = parsed.Where(message => message.Role == "user")
            .OrderByDescending(message => message.CreatedAt)
            .ThenByDescending(message => message.Id, StringComparer.Ordinal)
            .FirstOrDefault();

        if (targetUser is null)
            return new MessageEvidence(false, false, false, new List<AssistantMessage>(), 0);

        List<ParsedMessage> assistantsAfterTarget = parsed
            .Where(message => message.Role == "assistant" && IsAfter(message, targetUser))
            .ToList();
        foreach (ParsedMessage assistant in assistantsAfterTarget)
        {
            if (!string.Equals(assistant.ParentId, targetMessageId, StringComparison.Ordinal))
                throw Failure("assistant_parent_mismatch", "A later assistant message in the dedicated session is not parented to the exact role message.");
        }
        var assistantMessages = assistantsAfterTarget
            .Select(message => new AssistantMessage(
                message.Id,
                message.CreatedAt,
                message.CompletedAt,
                message.Finish,
                message.Error,
                message.TextParts,
                message.HasToolError,
                message.HasRunningTool))
            .ToList();

        string targetText = string.Concat(targetUser.TextParts);
        long tokenTotal = assistantsAfterTarget
            .Where(message => string.Equals(message.ParentId, targetMessageId, StringComparison.Ordinal))
            .Aggregate(0L, (total, message) => SaturatingAdd(total, message.Tokens));
        return new MessageEvidence(
            true,
            latestUser is not null && string.Equals(latestUser.Id, targetMessageId, StringComparison.Ordinal),
            string.Equals(targetText, expectedPrompt, StringComparison.Ordinal),
            assistantMessages,
            tokenTotal);
    }

    private void VerifySessionIdentity(JsonElement session, string expectedSessionId, string? expectedTitle, bool requireTitle)
    {
        string? actualId = GetString(session, "id");
        string? actualDirectory = GetString(session, "directory");
        if (!string.Equals(actualId, expectedSessionId, StringComparison.Ordinal))
            throw Failure("session_identity_mismatch", "OpenCode returned a different session ID than the one created for this role.");
        if (string.IsNullOrWhiteSpace(actualDirectory) || !DirectoriesEqual(actualDirectory, _directory))
            throw Failure("session_directory_mismatch", "OpenCode returned a role session from a different directory.");
        if (requireTitle && !string.Equals(GetString(session, "title"), expectedTitle, StringComparison.Ordinal))
            throw Failure("session_title_mismatch", "OpenCode returned a role session with a different title.");
    }

    private static void ValidateSessionId(string sessionId)
    {
        if (sessionId.Length is < 4 or > 128 || !sessionId.StartsWith("ses", StringComparison.Ordinal) ||
            sessionId.Any(character => !(char.IsAsciiLetterOrDigit(character) || character is '_' or '-')))
            throw Failure("invalid_session_id", "OpenCode returned an invalid session ID.");
    }

    private static void ValidateMessageId(string messageId)
    {
        if (messageId.Length is < 5 or > 128 || !messageId.StartsWith("msg_", StringComparison.Ordinal) ||
            messageId.Any(character => !(char.IsAsciiLetterOrDigit(character) || character is '_' or '-')))
            throw Failure("invalid_message_id", "The automation dispatch contains an invalid message ID.");
    }

    private static ModelReference? ParseModel(string? model)
    {
        if (string.IsNullOrWhiteSpace(model)) return null;
        int slash = model.IndexOf('/');
        if (slash <= 0 || slash == model.Length - 1 || model.AsSpan(slash + 1).Contains('/'))
            throw new ArgumentException("The OpenCode model must use provider/model format.", nameof(model));
        string providerId = model[..slash].Trim();
        string modelId = model[(slash + 1)..].Trim();
        if (providerId.Length == 0 || modelId.Length == 0 || providerId.Length > 128 || modelId.Length > 256)
            throw new ArgumentException("The OpenCode model must use bounded provider/model identifiers.", nameof(model));
        return new ModelReference(providerId, modelId);
    }

    private bool IsAllowedFinalUri(Uri uri) =>
        uri.IsAbsoluteUri && uri.IsLoopback &&
        string.Equals(uri.Scheme, _serverUri.Scheme, StringComparison.OrdinalIgnoreCase) &&
        string.Equals(uri.Host, _serverUri.Host, StringComparison.OrdinalIgnoreCase) &&
        uri.Port == _serverUri.Port;

    private static bool UriEquals(Uri left, Uri right) =>
        string.Equals(left.AbsoluteUri, right.AbsoluteUri, StringComparison.OrdinalIgnoreCase);

    private static bool DirectoriesEqual(string left, string right)
    {
        try
        {
            string leftFull = Path.TrimEndingDirectorySeparator(Path.GetFullPath(left));
            string rightFull = Path.TrimEndingDirectorySeparator(Path.GetFullPath(right));
            return string.Equals(leftFull, rightFull, OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
        }
        catch (ArgumentException) { return false; }
        catch (IOException) { return false; }
    }

    private static string? CreateAuthorizationHeader()
    {
        string? password = Environment.GetEnvironmentVariable("OPENCODE_SERVER_PASSWORD");
        if (string.IsNullOrEmpty(password)) return null;
        string username = Environment.GetEnvironmentVariable("OPENCODE_SERVER_USERNAME") ?? "opencode";
        return "Basic " + Convert.ToBase64String(Encoding.UTF8.GetBytes(username + ":" + password));
    }

    private static async Task<byte[]> ReadBoundedAsync(Stream stream, int maximumBytes, CancellationToken cancellationToken)
    {
        using var output = new MemoryStream();
        byte[] buffer = new byte[16 * 1024];
        while (true)
        {
            int read = await stream.ReadAsync(buffer.AsMemory(), cancellationToken).ConfigureAwait(false);
            if (read == 0) break;
            if (output.Length + read > maximumBytes)
                throw Failure("response_too_large", "OpenCode returned a response larger than the native API safety limit.");
            output.Write(buffer, 0, read);
        }
        return output.ToArray();
    }

    private static JsonElement RequireObject(JsonElement element, string resource) =>
        element.ValueKind == JsonValueKind.Object
            ? element
            : throw Failure("invalid_response", "OpenCode returned an invalid " + resource + " response.");

    private static JsonElement RequireArray(JsonElement element, string resource) =>
        element.ValueKind == JsonValueKind.Array
            ? element
            : throw Failure("invalid_response", "OpenCode returned an invalid " + resource + " response.");

    private static JsonElement GetProperty(JsonElement element, string propertyName) =>
        element.ValueKind == JsonValueKind.Object && element.TryGetProperty(propertyName, out JsonElement value) ? value : default;

    private static string? GetString(JsonElement element, string propertyName)
    {
        JsonElement value = GetProperty(element, propertyName);
        return value.ValueKind == JsonValueKind.String ? value.GetString() : null;
    }

    private static long ReadRequiredTime(JsonElement element, string description) =>
        ReadOptionalTime(element, description) ?? throw Failure("invalid_message_time", "OpenCode returned a message without a valid " + description + " time.");

    private static long? ReadOptionalTime(JsonElement element, string description)
    {
        if (element.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null) return null;
        if (element.ValueKind == JsonValueKind.Number && element.TryGetInt64(out long number) && number >= 0) return number;
        if (element.ValueKind == JsonValueKind.String && DateTimeOffset.TryParse(element.GetString(), CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out DateTimeOffset parsed))
            return parsed.ToUnixTimeMilliseconds();
        throw Failure("invalid_message_time", "OpenCode returned an invalid " + description + " time.");
    }

    private static string? ParseError(JsonElement error)
    {
        if (error.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null) return null;
        if (error.ValueKind != JsonValueKind.Object)
            return "OpenCode returned a malformed assistant error marker.";
        string? name = GetString(error, "name") ?? GetString(error, "type");
        JsonElement data = GetProperty(error, "data");
        string? message = GetString(data, "message");
        return string.IsNullOrWhiteSpace(name) ? message ?? "OpenCode reported an assistant error." :
            string.IsNullOrWhiteSpace(message) ? name : name + ": " + message;
    }

    private static long ReadTokenCount(JsonElement tokens)
    {
        if (tokens.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null) return 0;
        if (tokens.ValueKind != JsonValueKind.Object)
            throw Failure("invalid_tokens", "OpenCode returned malformed assistant token usage.");
        JsonElement total = GetProperty(tokens, "total");
        if (total.ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null))
        {
            if (total.ValueKind != JsonValueKind.Number || !total.TryGetInt64(out long totalTokens) || totalTokens < 0)
                throw Failure("invalid_tokens", "OpenCode returned invalid total token usage.");
            return totalTokens;
        }
        long result = 0;
        foreach (string field in new[] { "input", "output", "reasoning" })
            result = SaturatingAdd(result, ReadNonNegativeInt64(tokens, field));
        JsonElement cache = GetProperty(tokens, "cache");
        if (cache.ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null))
        {
            if (cache.ValueKind != JsonValueKind.Object)
                throw Failure("invalid_tokens", "OpenCode returned malformed cache token usage.");
            result = SaturatingAdd(result, ReadNonNegativeInt64(cache, "read"));
            result = SaturatingAdd(result, ReadNonNegativeInt64(cache, "write"));
        }
        return result;
    }

    private static long ReadNonNegativeInt64(JsonElement element, string propertyName)
    {
        JsonElement value = GetProperty(element, propertyName);
        if (value.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null) return 0;
        if (value.ValueKind != JsonValueKind.Number || !value.TryGetInt64(out long number) || number < 0)
            throw Failure("invalid_tokens", "OpenCode returned invalid token usage for " + propertyName + ".");
        return number;
    }

    private static long SaturatingAdd(long left, long right) => left > long.MaxValue - right ? long.MaxValue : left + right;

    private static bool IsAfter(ParsedMessage message, ParsedMessage other) =>
        message.CreatedAt > other.CreatedAt ||
        (message.CreatedAt == other.CreatedAt && string.CompareOrdinal(message.Id, other.Id) > 0);

    private static string BoundText(string value)
    {
        var builder = new StringBuilder(Math.Min(value.Length, 300));
        foreach (char character in value)
        {
            if (char.IsControl(character))
            {
                if (character is '\r' or '\n' or '\t') builder.Append(' ');
                continue;
            }
            builder.Append(character);
            if (builder.Length >= 300) break;
        }
        return builder.ToString().Trim();
    }

    private static AutomationStageOutput FailureOutput(string summary, long tokens = 0) => new(false, summary, "", false, tokens);

    private bool IsWithinAcknowledgementGrace(OpenCodeAutomationDispatch dispatch) =>
        dispatch.SubmittedAt is not null && _timeProvider.GetUtcNow() - dispatch.SubmittedAt.Value < SubmissionAcknowledgementGrace;

    private static OpenCodeAutomationException Failure(string code, string message, Exception? innerException = null) =>
        new(code, message, innerException);

    private enum NativeRunStatus { Idle, Busy, Retry }
    private sealed record ModelReference(string ProviderID, string ModelID);
    private sealed record SessionIdentity(string Id, string ParentId, string Directory);
    private sealed record ParsedMessage(
        string Id,
        string Role,
        string? ParentId,
        long CreatedAt,
        long? CompletedAt,
        string? Finish,
        string? Error,
        List<string> TextParts,
        bool HasToolError,
        bool HasRunningTool,
        long Tokens);
    private sealed record AssistantMessage(
        string Id,
        long CreatedAt,
        long? CompletedAt,
        string? Finish,
        string? Error,
        List<string> TextParts,
        bool HasToolError,
        bool HasRunningTool);
    private sealed record MessageEvidence(
        bool HasTargetUserMessage,
        bool LatestUserMessageIsTarget,
        bool TargetUserTextMatches,
        List<AssistantMessage> AssistantMessages,
        long Tokens);
    private sealed record AutomationSnapshot(
        NativeRunStatus Status,
        bool HasBusyDescendants,
        bool HasPendingInput,
        bool HasTargetUserMessage,
        bool LatestUserMessageIsTarget,
        bool TargetUserTextMatches,
        List<AssistantMessage> AssistantMessages,
        long Tokens,
        string ProgressFingerprint,
        bool HasProgressEvidence,
        string ProgressExcerpt,
        bool HasRunningTools,
        bool IsRetrying,
        List<string> ActiveSessionIds,
        bool HasUnexpectedUserMessage);
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEAUTOMATIONCLIENT_STARTUP_CS
#region Services/OpenCodeAutomationClient.Startup.cs
namespace TerminalNotes.Services
{
using global::System.Net;
using global::System.Net.Http;
using global::System.IO;
using global::System.Text.Json;


public sealed partial class OpenCodeAutomationClient
{
    private static readonly TimeSpan StartupRequestTimeout = TimeSpan.FromSeconds(30);

    public async Task<string> CreateStartupSessionAsync(string title, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(title);
        if (title.Length > 256) throw new ArgumentOutOfRangeException(nameof(title));
        ObjectDisposedException.ThrowIf(_disposed, this);

        using (JsonDocument status = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildEndpoint("/session/status"), payload: null, operation: "startup_status", cancellationToken)
               .ConfigureAwait(false))!)
            _ = RequireObject(status.RootElement, "session status map");

        JsonDocument created;
        try
        {
            created = (await SendStartupJsonAsync(
                HttpMethod.Post, BuildEndpoint("/session"), new { title }, "startup_session_create", cancellationToken)
                .ConfigureAwait(false))!;
        }
        catch (OpenCodeAutomationException exception) when (exception.Code is "request_timeout" or "disconnected" or "invalid_response" or "transient_http_error" or "response_too_large")
        {
            throw Failure("session_create_ambiguous", "The startup session creation response was uncertain; no prompt was submitted.", exception);
        }

        string sessionId;
        using (created)
        {
            JsonElement session = RequireObject(created.RootElement, "created startup session");
            sessionId = GetString(session, "id") ?? "";
            ValidateSessionId(sessionId);
            VerifySessionIdentity(session, sessionId, title, requireTitle: true);
            EnsureStartupRootSession(session);
        }

        using JsonDocument detail = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildSessionEndpoint(sessionId), payload: null, operation: "startup_session_detail", cancellationToken)
               .ConfigureAwait(false))!;
        VerifySessionIdentity(RequireObject(detail.RootElement, "startup session detail"), sessionId, title, requireTitle: true);
        EnsureStartupRootSession(detail.RootElement);
        return sessionId;
    }

    public async Task SelectStartupSessionAsync(string sessionId, CancellationToken cancellationToken = default)
    {
        ValidateSessionId(sessionId);
        ObjectDisposedException.ThrowIf(_disposed, this);
        using JsonDocument detail = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildSessionEndpoint(sessionId), payload: null, operation: "startup_session_detail", cancellationToken)
               .ConfigureAwait(false))!;
        JsonElement session = RequireObject(detail.RootElement, "startup session detail");
        VerifySessionIdentity(session, sessionId, expectedTitle: null, requireTitle: false);
        EnsureStartupRootSession(session);

        if (!_useTuiSelection) return;

        using JsonDocument selected = (await SendStartupJsonAsync(
                   HttpMethod.Post, BuildEndpoint("/tui/select-session"), new { sessionID = sessionId }, "startup_tui_select", cancellationToken)
               .ConfigureAwait(false))!;
        if (selected.RootElement.ValueKind != JsonValueKind.True)
            throw Failure("tui_select_not_confirmed", "OpenCode did not acknowledge the exact startup session selection.");
    }

    public async Task SubmitStartupPromptAsync(
        OpenCodeAutomationDispatch dispatch,
        Action beforeSubmit,
        CancellationToken cancellationToken = default,
        Action? submissionNotSent = null,
        bool allowBusy = false)
    {
        ArgumentNullException.ThrowIfNull(dispatch);
        ArgumentNullException.ThrowIfNull(beforeSubmit);
        ValidateSessionId(dispatch.SessionId);
        ValidateMessageId(dispatch.MessageId);
        if (string.IsNullOrWhiteSpace(dispatch.Prompt) || dispatch.Prompt.Length > MaximumPromptCharacters)
            throw Failure("invalid_prompt", "The startup prompt is empty or exceeds the native request limit.");
        ObjectDisposedException.ThrowIf(_disposed, this);

        using JsonDocument detail = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildSessionEndpoint(dispatch.SessionId), payload: null, operation: "startup_session_detail", cancellationToken)
               .ConfigureAwait(false))!;
        JsonElement session = RequireObject(detail.RootElement, "startup session detail");
        VerifySessionIdentity(session, dispatch.SessionId, expectedTitle: null, requireTitle: false);
        EnsureStartupRootSession(session);

        using JsonDocument status = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildEndpoint("/session/status"), payload: null, operation: "startup_status", cancellationToken)
               .ConfigureAwait(false))!;
        JsonElement statuses = RequireObject(status.RootElement, "session status map");
        NativeRunStatus runStatus = ReadStatus(statuses, dispatch.SessionId);
        if (runStatus != NativeRunStatus.Idle && !(allowBusy && runStatus == NativeRunStatus.Busy))
            throw Failure("session_not_idle", "OpenCode has not confirmed the startup session is idle.");

        using JsonDocument permissions = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildEndpoint("/permission"), payload: null, operation: "startup_permissions", cancellationToken)
               .ConfigureAwait(false))!;
        using JsonDocument questions = (await SendStartupJsonAsync(
                   HttpMethod.Get, BuildEndpoint("/question"), payload: null, operation: "startup_questions", cancellationToken)
               .ConfigureAwait(false))!;
        var targetSession = new HashSet<string>(StringComparer.Ordinal) { dispatch.SessionId };
        if (HasPendingInput(permissions.RootElement, "permissions", targetSession) ||
            HasPendingInput(questions.RootElement, "questions", targetSession))
            throw Failure("session_input_pending", "The startup session has an unanswered permission or question request.");

        byte[] payload = JsonSerializer.SerializeToUtf8Bytes(new
        {
            messageID = dispatch.MessageId,
            parts = new[] { new { type = "text", text = dispatch.Prompt } }
        });
        if (payload.Length > MaximumResponseBytes)
            throw Failure("payload_too_large", "The startup prompt request exceeds the bounded JSON payload size.");

        cancellationToken.ThrowIfCancellationRequested();
        beforeSubmit();
        if (cancellationToken.IsCancellationRequested)
        {
            submissionNotSent?.Invoke();
            cancellationToken.ThrowIfCancellationRequested();
        }
        await PostPromptAsync(dispatch.SessionId, payload, cancellationToken).ConfigureAwait(false);
    }

    public async Task<bool> HasStartupMessageAsync(OpenCodeAutomationDispatch dispatch, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(dispatch);
        ValidateSessionId(dispatch.SessionId);
        ValidateMessageId(dispatch.MessageId);
        ObjectDisposedException.ThrowIf(_disposed, this);

        Uri endpoint = BuildSessionEndpoint(
            dispatch.SessionId, "/message/" + Uri.EscapeDataString(dispatch.MessageId));
        using JsonDocument? document = await SendStartupJsonAsync(
            HttpMethod.Get, endpoint, payload: null, operation: "startup_message_read", cancellationToken, missingIsFalse: true)
            .ConfigureAwait(false);
        if (document is null) return false;

        JsonElement message = RequireObject(document.RootElement, "startup message");
        JsonElement info = RequireObject(GetProperty(message, "info"), "startup message info");
        if (!string.Equals(GetString(info, "id"), dispatch.MessageId, StringComparison.Ordinal) ||
            !string.Equals(GetString(info, "sessionID"), dispatch.SessionId, StringComparison.Ordinal) ||
            !string.Equals(GetString(info, "role"), "user", StringComparison.Ordinal))
            throw Failure("startup_message_identity_mismatch", "OpenCode returned a different native message identity for the startup request.");

        var text = new System.Text.StringBuilder();
        foreach (JsonElement partElement in RequireArray(GetProperty(message, "parts"), "startup message parts").EnumerateArray())
        {
            JsonElement part = RequireObject(partElement, "startup message part");
            if (!string.Equals(GetString(part, "type"), "text", StringComparison.Ordinal))
                throw Failure("startup_message_mismatch", "OpenCode returned non-text content for the startup prompt.");
            text.Append(GetString(part, "text") ?? throw Failure("invalid_message", "OpenCode returned a text part without text."));
        }
        if (!string.Equals(text.ToString(), dispatch.Prompt, StringComparison.Ordinal))
            throw Failure("startup_message_mismatch", "OpenCode returned different text for the startup prompt message.");
        return true;
    }

    private async Task<JsonDocument?> SendStartupJsonAsync(
        HttpMethod method,
        Uri endpoint,
        object? payload,
        string operation,
        CancellationToken cancellationToken,
        bool missingIsFalse = false)
    {
        using var requestTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        requestTimeout.CancelAfter(StartupRequestTimeout);
        byte[]? body = payload is null ? null : JsonSerializer.SerializeToUtf8Bytes(payload);
        // Only reads and selection of the already verified exact session may be
        // repeated. Session creation and prompt submission must remain single-shot.
        bool retrySafe = method == HttpMethod.Get ||
            (method == HttpMethod.Post && operation == "startup_tui_select");
        try
        {
            for (int attempt = 0; ; attempt++)
            {
                requestTimeout.Token.ThrowIfCancellationRequested();
                bool canRetry = retrySafe && attempt < 2;
                using (var request = body is null
                    ? new HttpRequestMessage(method, endpoint)
                    : CreateJsonRequest(method, endpoint, body))
                {
                    try
                    {
                        using HttpResponseMessage response = await SendCoreAsync(request, requestTimeout.Token).ConfigureAwait(false);
                        if (missingIsFalse && response.StatusCode == HttpStatusCode.NotFound) return null;
                        bool transient = response.StatusCode is HttpStatusCode.RequestTimeout or HttpStatusCode.TooManyRequests ||
                            (int)response.StatusCode is >= 500 and <= 599;
                        if (!canRetry || !transient)
                        {
                            EnsureSuccess(response);
                            byte[] bytes = await ReadBoundedAsync(
                                await response.Content.ReadAsStreamAsync(requestTimeout.Token).ConfigureAwait(false),
                                MaximumResponseBytes,
                                requestTimeout.Token).ConfigureAwait(false);
                            return JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 48 });
                        }
                    }
                    catch (HttpRequestException) when (canRetry && !requestTimeout.IsCancellationRequested) { }
                    catch (OperationCanceledException) when (canRetry && !requestTimeout.IsCancellationRequested) { }
                }
                // All attempts and delays share the original bounded deadline.
                await Task.Delay(TimeSpan.FromMilliseconds(attempt == 0 ? 250 : 750), requestTimeout.Token).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException exception) when (!cancellationToken.IsCancellationRequested)
        {
            throw Failure("request_timeout", "OpenCode did not finish the bounded " + operation + " request.", exception);
        }
        catch (HttpRequestException exception)
        {
            throw Failure("disconnected", "The OpenCode loopback server could not complete the " + operation + " request.", exception);
        }
        catch (IOException exception)
        {
            throw Failure("invalid_response", "OpenCode returned a response that could not be read safely for " + operation + ".", exception);
        }
        catch (JsonException exception)
        {
            throw Failure("invalid_response", "OpenCode returned malformed JSON for " + operation + ".", exception);
        }
    }

    private static void EnsureStartupRootSession(JsonElement session)
    {
        if (GetString(session, "parentID") is not null)
            throw Failure("not_root_session", "OpenCode returned a child session where a dedicated startup root session was required.");
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEAUTOMATIONCLIENT_SUPERVISION_CS
#region Services/OpenCodeAutomationClient.Supervision.cs
namespace TerminalNotes.Services
{
using global::System.Net.Http;
using global::System.Text;
using global::System.Text.Json;


public sealed partial class OpenCodeAutomationClient
{
    // These are inactivity windows, not limits on stage duration or retry count.
    // Tool/child work gets a longer window because a build may produce no output.
    private static readonly TimeSpan ResponseInactivity = TimeSpan.FromMinutes(3);
    private static readonly TimeSpan ToolInactivity = TimeSpan.FromMinutes(10);
    private readonly TimeProvider _timeProvider;
    private string? _observedDispatch;
    private string? _progressFingerprint;
    private DateTimeOffset _lastObservation;
    private AutomationSnapshot? _lastSnapshot;
    private string? _recoveryReason;
    private readonly HashSet<string> _abortSent = new(StringComparer.Ordinal);
    private DateTimeOffset? _idleSince;
    private DateTimeOffset? _firstAbortAt;
    private string? _requestedIntervention;
    private DateTimeOffset? _retryObservedAt;
    private DateTimeOffset? _transportFailureSince;
    private DateTimeOffset _lastTransportFailure;
    private int _transportFailures;
    private AutomationSnapshot? _lastVerifiedSnapshot;
    private DateTimeOffset _lastTuiSelection;
    private string? _selectedDispatch;
    public string? TuiConnectionWarning { get; private set; }

    public DateTimeOffset? LastProgressAt { get; private set; }
    // UI activity only advances on assistant/tool evidence. Watchdog grace
    // resets, repeated busy polls and approval waits must not animate progress.
    public DateTimeOffset? LastActivityAt { get; private set; }
    public string ProgressExcerpt => _lastSnapshot?.ProgressExcerpt ?? "아직 확인된 응답이 없습니다.";
    public long ObservedTokens { get; private set; }
    public bool IsRecovering => _recoveryReason is not null;
    public bool IsCoordinatorIntervention => IsRecovering && _requestedIntervention is not null;
    public bool IsProviderRetrying => _lastSnapshot?.IsRetrying == true;
    public bool HasPendingNativeInput => _lastSnapshot?.HasPendingInput == true;
    public bool HasNativeSnapshot => _lastSnapshot is not null && LastReadWarning is null;
    public bool IsNativeIdle => _lastSnapshot is { Status: NativeRunStatus.Idle, HasBusyDescendants: false, HasRunningTools: false };
    public bool HasRecentActivity => LastActivityAt is { } at && _timeProvider.GetUtcNow() - at <= TimeSpan.FromSeconds(8);
    public string? SupervisionNotice => IsRecovering ? "정체 작업 중단 확인 중" :
        LastReadWarning is not null ? "연결 복구 대기" : TuiConnectionWarning is not null ? "터미널 화면 연결 재시도" : IsProviderRetrying ? "서비스 재시도 대기" :
        IsStalled ? "진행 정체 확인 중" : !HasRecentActivity ? "응답 변화 대기" : null;
    // Only repeated transport failures authorize replacing the already owned
    // local process. Malformed data/identity conflicts never grant this right.
    // The caller must still verify pane ownership, manual input and cancellation,
    // and confirm process exit before handing partial work to another role.
    public bool CanRestartUnresponsiveProcess => _transportFailureSince is { } since &&
        _transportFailures >= 3 && _timeProvider.GetUtcNow() - since >= ResponseInactivity &&
        _timeProvider.GetUtcNow() - _lastTransportFailure < TimeSpan.FromSeconds(30) &&
        (_lastVerifiedSnapshot is null ||
         (!_lastVerifiedSnapshot.HasPendingInput && !_lastVerifiedSnapshot.HasUnexpectedUserMessage &&
          (!_lastVerifiedSnapshot.HasTargetUserMessage ||
           (_lastVerifiedSnapshot.LatestUserMessageIsTarget && _lastVerifiedSnapshot.TargetUserTextMatches))));
    private bool RetryGraceElapsed => _retryObservedAt is { } at &&
        _timeProvider.GetUtcNow() - at >= TimeSpan.FromSeconds(45);

    private void ObserveTransportFailure()
    {
        DateTimeOffset now = _timeProvider.GetUtcNow();
        _transportFailureSince ??= now;
        _lastTransportFailure = now;
        _transportFailures++;
    }

    private void ResetTransportFailures()
    {
        _transportFailureSince = null;
        _transportFailures = 0;
    }

    public async Task RefreshTuiSessionAsync(OpenCodeAutomationDispatch dispatch, Func<bool> stillOwned,
        CancellationToken cancellationToken = default)
    {
        if (!_useTuiSelection) return;
        DateTimeOffset now = _timeProvider.GetUtcNow();
        string identity = dispatch.SessionId + "/" + dispatch.MessageId;
        if (!stillOwned() || LastReadWarning is not null || _lastSnapshot is not { } snapshot ||
            snapshot.HasPendingInput || snapshot.HasUnexpectedUserMessage ||
            !snapshot.HasTargetUserMessage || !snapshot.LatestUserMessageIsTarget || !snapshot.TargetUserTextMatches ||
            (_selectedDispatch == identity && now - _lastTuiSelection < TimeSpan.FromSeconds(15))) return;
        _selectedDispatch = identity;
        _lastTuiSelection = now;
        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(TimeSpan.FromSeconds(3));
        try
        {
            // select-session acknowledges a broadcast, not a rendered view. The
            // initial event can precede the TUI subscriber. Rebind the exact owned
            // session after native acknowledgement and periodically while owned.
            // Never submit a prompt or type "continue" to repair only the display.
            using JsonDocument detail = await GetJsonAsync(BuildSessionEndpoint(dispatch.SessionId), timeout.Token).ConfigureAwait(false);
            VerifySessionIdentity(detail.RootElement, dispatch.SessionId, null, false);
            if (!stillOwned()) return;
            timeout.Token.ThrowIfCancellationRequested();
            using JsonDocument response = await PostJsonAsync(BuildEndpoint("/tui/select-session"),
                new { sessionID = dispatch.SessionId }, timeout.Token, "tui_select").ConfigureAwait(false);
            TuiConnectionWarning = response.RootElement.ValueKind == JsonValueKind.True ? null : "화면 연결 응답 미확인";
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested) { throw; }
        catch (Exception ex) when (ex is OpenCodeAutomationException or HttpRequestException or System.IO.IOException or JsonException or OperationCanceledException)
        {
            TuiConnectionWarning = "터미널 화면 연결 재시도";
        }
    }
    // Escalation is allowed only with fresh, exact native evidence. An unreadable
    // endpoint or approval/question can never authorize killing its process tree.
    public bool CanRestartStalledProcess => IsRecovering && LastReadWarning is null &&
        _lastSnapshot is { HasPendingInput: false, HasUnexpectedUserMessage: false } &&
        (!_lastSnapshot.IsRetrying || RetryGraceElapsed) &&
        (_lastSnapshot.ActiveSessionIds.Count > 0 || _lastSnapshot.HasRunningTools || _lastSnapshot.HasBusyDescendants) &&
        (!_lastSnapshot.HasTargetUserMessage || (_lastSnapshot.LatestUserMessageIsTarget && _lastSnapshot.TargetUserTextMatches)) &&
        _firstAbortAt is { } abortAt && LastProgressAt is { } progressAt &&
        _timeProvider.GetUtcNow() - _lastObservation < TimeSpan.FromSeconds(5) &&
        _timeProvider.GetUtcNow() - abortAt >= TimeSpan.FromMinutes(1) &&
        _timeProvider.GetUtcNow() - progressAt >= TimeSpan.FromMinutes(1);
    public bool IsStalled => _lastSnapshot is { } snapshot && LastReadWarning is null &&
        !snapshot.HasPendingInput && (!snapshot.IsRetrying || RetryGraceElapsed) &&
        LastProgressAt is { } progressAt &&
        _timeProvider.GetUtcNow() - _lastObservation < TimeSpan.FromSeconds(30) &&
        _timeProvider.GetUtcNow() - progressAt >=
            (snapshot.HasRunningTools || snapshot.HasBusyDescendants ? ToolInactivity : ResponseInactivity);

    private void ResetProgressObservation()
    {
        _lastSnapshot = null;
        LastProgressAt = null;
        LastActivityAt = null;
        _idleSince = null;
        _retryObservedAt = null;
    }

    private void ObserveProgress(OpenCodeAutomationDispatch dispatch, AutomationSnapshot snapshot)
    {
        string identity = dispatch.SessionId + "/" + dispatch.MessageId;
        if (_observedDispatch != identity)
        {
            _observedDispatch = identity;
            _progressFingerprint = null;
            _recoveryReason = null;
            _abortSent.Clear();
            _firstAbortAt = null;
            _requestedIntervention = null;
            ObservedTokens = 0;
            ResetProgressObservation();
        }
        DateTimeOffset now = _timeProvider.GetUtcNow();
        bool changed = snapshot.ProgressFingerprint != _progressFingerprint;
        if (changed || snapshot.HasPendingInput) _retryObservedAt = null;
        if (snapshot.IsRetrying) _retryObservedAt ??= now;
        if (snapshot.HasProgressEvidence && snapshot.ProgressFingerprint != _progressFingerprint)
            LastActivityAt = now;
        if (LastProgressAt is null || snapshot.ProgressFingerprint != _progressFingerprint ||
            now - _lastObservation >= TimeSpan.FromSeconds(30) || snapshot.HasPendingInput)
            LastProgressAt = now;
        _progressFingerprint = snapshot.ProgressFingerprint;
        _lastObservation = now;
        _lastSnapshot = snapshot;
        _lastVerifiedSnapshot = snapshot;
        ResetTransportFailures();
        ObservedTokens = Math.Max(ObservedTokens, snapshot.Tokens);
    }

    /// <summary>
    /// Rechecks native progress and ownership before aborting only this dispatch's
    /// root/descendants. A new prompt is never sent here. Uncertain abort responses
    /// keep their ownership until subsequent reads prove the whole tree idle.
    /// </summary>
    public async Task<AutomationStageOutput?> RecoverStalledAsync(
        OpenCodeAutomationDispatch dispatch, Func<bool> stillOwned,
        CancellationToken cancellationToken = default)
    {
        if ((!IsRecovering && !IsStalled && _requestedIntervention is null) || !stillOwned()) return null;
        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(OperationTimeout);
        CancellationToken token = timeout.Token;
        try
        {
            // One side effect per pass: descendants first, then the root. Each
            // subsequent abort gets another complete identity/input/progress read.
            AutomationSnapshot snapshot = await ReadSnapshotAsync(dispatch, token).ConfigureAwait(false);
            ObserveProgress(dispatch, snapshot);
            if (snapshot.HasPendingInput || (snapshot.IsRetrying && !RetryGraceElapsed) || !stillOwned()) return null;
            if (snapshot.HasUnexpectedUserMessage) return null;
            if (snapshot.HasTargetUserMessage &&
                (!snapshot.LatestUserMessageIsTarget || !snapshot.TargetUserTextMatches)) return null;
            if (!IsRecovering && !IsStalled && _requestedIntervention is null) return null;
            if (_requestedIntervention is not null && !snapshot.HasTargetUserMessage) return null;
            _recoveryReason ??= _requestedIntervention ?? "실제 응답·도구 진행이 정체되어 해당 역할 작업을 중단했습니다. 현재 변경 상태를 확인하고 남은 목표를 계속 진행하세요.";
            AutomationStageOutput? recovered = RecoveredOutputIfIdle(snapshot);
            if (recovered is not null) return recovered;
            string? target = snapshot.ActiveSessionIds
                .OrderBy(id => id == dispatch.SessionId ? 1 : 0)
                .FirstOrDefault(id => !_abortSent.Contains(id))
                // OpenCode may report idle while an owned tool is still running.
                // Try its exact root once, then require the normal exit/grace checks.
                ?? (snapshot.HasRunningTools && !_abortSent.Contains(dispatch.SessionId) ? dispatch.SessionId : null);
            if (target is null) return null;
            token.ThrowIfCancellationRequested();
            if (!stillOwned()) return null;
            _abortSent.Add(target); // A lost response must not cause a blind POST replay.
            _firstAbortAt ??= _timeProvider.GetUtcNow();
            using JsonDocument response = await PostJsonAsync(BuildSessionEndpoint(target, "/abort"),
                new { }, token, "session_abort").ConfigureAwait(false);
            if (response.RootElement.ValueKind != JsonValueKind.True)
                LastReadWarning = "정체 작업 중단 응답 미확인 · 동일 세션 종료 확인 중";
            return null;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested) { throw; }
        catch (Exception exception) when (exception is OpenCodeAutomationException or HttpRequestException or
                                          System.IO.IOException or JsonException or OperationCanceledException)
        {
            LastReadWarning = "정체 작업 중단 확인 재시도 · " + exception.Message;
            _idleSince = null;
            return null;
        }
    }

    public Task<AutomationStageOutput?> RequestCoordinatorInterventionAsync(
        OpenCodeAutomationDispatch dispatch, string instruction, Func<bool> stillOwned,
        CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(instruction) || !stillOwned()) return Task.FromResult<AutomationStageOutput?>(null);
        _requestedIntervention = "지휘자의 중간 개입 · " + instruction;
        return RecoverStalledAsync(dispatch, stillOwned, cancellationToken);
    }

    private AutomationStageOutput? RecoveredOutputIfIdle(AutomationSnapshot snapshot)
    {
        if (snapshot.Status != NativeRunStatus.Idle || snapshot.HasBusyDescendants ||
            snapshot.HasRunningTools || snapshot.HasPendingInput || snapshot.HasUnexpectedUserMessage ||
            (snapshot.HasTargetUserMessage && (!snapshot.LatestUserMessageIsTarget || !snapshot.TargetUserTextMatches)))
        {
            _idleSince = null;
            return null;
        }
        DateTimeOffset now = _timeProvider.GetUtcNow();
        _idleSince ??= now;
        // A second stable observation avoids handing off on a transient idle edge.
        if (now - _idleSince < TimeSpan.FromSeconds(1)) return null;
        return FailureOutput(_recoveryReason!, snapshot.Tokens) with { Interrupted = true };
    }

    private static bool AppendMessageProgress(StringBuilder progress, JsonElement messages,
        string sessionId, string? targetMessageId = null)
    {
        JsonElement rows = RequireArray(messages, "progress messages");
        if (rows.GetArrayLength() > MaximumMessageCount)
            throw Failure("too_many_messages", "OpenCode progress exceeded the bounded message count.");
        bool runningTool = false;
        foreach (JsonElement row in rows.EnumerateArray().OrderBy(row => GetString(GetProperty(row, "info"), "id"), StringComparer.Ordinal))
        {
            JsonElement info = RequireObject(GetProperty(row, "info"), "progress message info");
            if (GetString(info, "sessionID") != sessionId)
                throw Failure("message_session_mismatch", "Progress messages came from a different session.");
            if (GetString(info, "role") != "assistant" ||
                (targetMessageId is not null && GetString(info, "parentID") != targetMessageId)) continue;
            JsonElement parts = RequireArray(GetProperty(row, "parts"), "progress parts");
            // Allocating an empty assistant/message ID is not model activity.
            if (!parts.EnumerateArray().Any(part => GetString(part, "type") == "tool" ||
                (GetString(part, "type") is "text" or "reasoning" && !string.IsNullOrWhiteSpace(GetString(part, "text"))))) continue;
            Append(sessionId);
            Append(GetString(info, "id"));
            Append(GetString(info, "finish"));
            Append(ReadTokenCount(GetProperty(info, "tokens")).ToString(System.Globalization.CultureInfo.InvariantCulture));
            foreach (JsonElement part in parts.EnumerateArray())
            {
                string? type = GetString(part, "type");
                if (type is "text" or "reasoning") { Append(type); Append(GetString(part, "text")); }
                else if (type == "tool")
                {
                    JsonElement state = RequireObject(GetProperty(part, "state"), "tool state");
                    string? status = GetString(state, "status");
                    if (status is not ("pending" or "running" or "completed" or "error"))
                        throw Failure("invalid_tool_status", "OpenCode returned an unknown progress tool state.");
                    runningTool |= status is "pending" or "running";
                    Append(GetString(part, "callID")); Append(GetString(part, "tool")); Append(status);
                    foreach (string property in new[] { "title", "input", "output", "error" })
                    {
                        JsonElement value = GetProperty(state, property);
                        Append(value.ValueKind == JsonValueKind.Undefined ? null : value.GetRawText());
                    }
                    // Streamed shell output may be exposed here while still running.
                    Append(GetString(GetProperty(state, "metadata"), "output"));
                }
            }
        }
        return runningTool;

        // Length framing prevents different sequences of text from colliding.
        void Append(string? value) => progress.Append(value?.Length ?? 0).Append(':').Append(value).Append(';');
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEAUTORESUMECONTROLLER_CS
#region Services/OpenCodeAutoResumeController.cs
namespace TerminalNotes.Services
{
