public sealed record OpenCodeRecommendedPlanRequest(string ProjectDirectory, string SessionId, string MessageId,
    string PlanPath, string PlanHash, DateTimeOffset? Until, Func<bool> StillOwned,
    Func<CancellationToken, Task<bool>> VerifyAsync);

public sealed record OpenCodeRecommendedPlanResult(string PlanHash, bool Changed);

/// <summary>
/// Pins recovery to native evidence for a local user submission. Never reads terminal
/// output, types into a shell, resurrects historical work, or repeats an uncertain POST.
/// </summary>
public sealed class OpenCodeAutoResumeController : IDisposable
{
    private static readonly Dictionary<string, OpenCodeAutoResumeController> Owners = new(StringComparer.OrdinalIgnoreCase);
    private static readonly object OwnersGate = new();
    private readonly object _gate = new();
    private readonly SemaphoreSlim _tickGate = new(1, 1);
    private readonly CancellationTokenSource _lifetime = new();
    private CancellationTokenSource _work = new();
    private readonly OpenCodeRecoveryClient _client;
    private readonly string _project;
    private readonly Func<bool> _canAct;
    private readonly TimeProvider _time;
    private readonly Func<Action<string>, CancellationToken, Task<IDisposable>>? _acquireContinuationAdmission;
    private OpenCodeRecoveryPolicy _policy = new();
    private readonly TerminalInputCapture _localInput = new();
    private string? _planPath, _planHash, _sessionId, _requestId, _expectedUserMessageId, _pendingMessageId;
    private string? _previousUserMessageId;
    private ContextRecovery? _contextRecovery;
    private RecoveryModelSelection? _contextWorkModel;
    private string? _contextWorkAgent, _contextWorkVariant;
    private bool _contextContinuation;
    private string? _unverifiedNativeUserMessageId;

    private sealed class ContextRecovery(RecoveryNativeMessage source)
    {
