    }

    private DateTimeOffset? _awaitingMessageUntil;
    private DateTimeOffset? _continuousImprovementUntil;
    private bool _recommendPlan, _recommendedPlanFallback;
    private int _recommendedPlanFailures;
    private DateTimeOffset? _recommendedPlanRetryAt;
    private string? _recommendedPlanMessageId;
    private OpenCodeRecommendedPlanResult? _recommendedPlanResult;
    private string? _reviewCompletionMessage, _reviewTodoFingerprint, _reviewProgressFingerprint;
    private DateTimeOffset? _nextCompletedReviewAt;
    private int _unchangedReviewCycles;
    private bool _abortAccepted;
    private string? _abortedLaunchToolFingerprint;
    private DateTimeOffset? _stalledAbortAttemptedAt;
    private string? _stalledAbortActivity, _stalledAbortProgress, _stalledAbortRequest;
    private string _lastUserInstruction = "";
    private bool _isStalled, _restartRequested, _abortActionInFlight;
    private bool _hasVerifiedNotificationStall;
    private string? _notificationStallSession, _notificationStallRequest, _notificationStallProgress, _notificationStallActivity;
    private bool _notificationStallHasTools;
    private long _notificationStallWork, _notificationStallBinding;
    private DateTimeOffset? _notificationStallSince, _notificationStallLastVerifiedAt;
    public bool IsStalled { get { lock (_gate) return _isStalled; } }
    public bool HasVerifiedNotificationStall
    {
        get
        {
            lock (_gate)
            {
                DateTimeOffset now = _time.GetUtcNow();
                return _hasVerifiedNotificationStall && _notificationStallLastVerifiedAt is { } verifiedAt &&
                    now >= verifiedAt && now - verifiedAt <= TimeSpan.FromSeconds(30);
            }
        }
    }
    public Func<OpenCodeStalledRestart, Task<bool>>? RestartStalledProcessAsync { get; set; }
    public Func<OpenCodeStalledRestart, Task<OpenCodeRestartOutcome>>? RestartStalledProcessWithOutcomeAsync { get; set; }
    public Func<OpenCodeRecommendedPlanRequest, CancellationToken, Task<OpenCodeRecommendedPlanResult?>>? RecommendPlanAsync { get; set; }
    private DateTimeOffset? _stalledRestartRetryAt;
    private int _stalledRestartRetryAttempts;
    private OpenCodeRecoverySignal? _candidate;
    private readonly Dictionary<string, long> _todoSignals = new(StringComparer.Ordinal);
    private DateTimeOffset? _localSubmissionAt;
    private string? _apiSubmissionSession, _apiSubmissionMessage;
    private long _apiSubmissionTodoVersion;
    private long _epoch, _userWork, _binding, _statusVersion;
    private long? _lastPollTimestamp;
    private bool _enabled, _continuousImprovementEnabled, _disposed, _workConfirmed, _started, _observeCompletion;
    private bool _continuousTaskInProgress, _isRecoveryPaused;
    private string _status = "";
    private readonly Dictionary<string, DateTimeOffset> _diagnosticLastEmitted = new(StringComparer.Ordinal);
    private DateTimeOffset? _lastSubstantiveProgressAt, _lastHealthDiagnosticAt;
    public DateTimeOffset? LastSubstantiveProgressAt { get { lock (_gate) return _lastSubstantiveProgressAt; } }
    private string? _lastProgressFingerprint;
    private DateTimeOffset? _nextReadRetryAt;
    private int _readFailureCount;
    private RecoverySessionEvidence? _lastVerifiedEvidence;
    private DateTimeOffset? _errorRetryAt;
    private DateTimeOffset? _providerRetryAt;
    private string? _errorRetryMessageId;
    private int _errorRetryAttempts;
    private long _snapshotVersion, _acceptedErrorRetries;
    private bool _manualErrorRetryRequested;
    private bool _confirmedApiReceipt;
    private Task<(bool Valid, string? Hash)>? _submittedPlanRead;
    private string? _restartSubmittedPrompt, _restartOriginalInstruction;
    private bool _confirmedPendingReceipt;

    public bool CanRetryError { get { lock (_gate) return CanRetryErrorLocked(); } }
    public DateTimeOffset? ErrorRetryAt { get { lock (_gate) return _errorRetryAt; } }

    private bool CanRetryErrorLocked() => !_disposed && _canAct() && _pendingMessageId is null &&
        !_restartRequested && !_abortActionInFlight && _lastVerifiedEvidence is { } evidence &&
        evidence.SessionId == _sessionId && evidence.LatestUserMessageId == _expectedUserMessageId &&
        evidence.Status == OpenCodeRecoveryStatus.Idle && !evidence.HasRunningTools && !evidence.HasBusyDescendants &&
        !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
        !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants &&
        OpenCodeFailureClassifier.CanRetryManually(evidence);

    public async Task<bool> RetryErrorAsync()
    {
        long accepted;
        lock (_gate)
        {
            if (!CanRetryErrorLocked() || _manualErrorRetryRequested) return false;
            accepted = _acceptedErrorRetries;
            _manualErrorRetryRequested = true;
            _policy = new();
        }
        try
        {
            await TickSafelyAsync().ConfigureAwait(false);
            lock (_gate) return _acceptedErrorRetries > accepted;
        }
        catch (OperationCanceledException) { return false; }
        finally { lock (_gate) _manualErrorRetryRequested = false; }
    }

    /// <summary>Restores an exact compaction reservation after reconnecting the same persisted native session; sends nothing.</summary>
    public bool RestoreContextRecovery(OpenCodeErrorRestart request, bool previousOwnedHostStopped = false)
    {
        if (!request.ReconcileOnly || request.ContextRecovery is not { } saved || saved.Source.Model is null || !request.CanRestart()) return false;
        lock (_gate)
        {
            if (_disposed || !RecoveryActiveLocked || !_canAct() || _sessionId is not null ||
                !string.Equals(_planPath, request.PlanPath, StringComparison.OrdinalIgnoreCase)) return false;
            try
            {
                var file = new FileInfo(request.PlanPath);
                if (!file.Exists || file.Length > 2 * 1024 * 1024 ||
                    Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(File.ReadAllText(request.PlanPath)))) != request.PlanHash) return false;
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or ArgumentException) { return false; }
            lock (OwnersGate)
            {
                if (Owners.TryGetValue(OwnerKey(request.SessionId), out var owner) && !ReferenceEquals(owner, this) && !owner._disposed) return false;
                Owners[OwnerKey(request.SessionId)] = this;
            }
            _sessionId = _continuationSessionId = request.SessionId;
            _requestId = saved.RequestId;
            _expectedUserMessageId = saved.ExpectedUserMessageId;
            _lastUserInstruction = request.OriginalInstruction;
            _planHash = request.PlanHash;
            _workConfirmed = saved.WorkConfirmed;
            _continuousTaskInProgress = request.RequiresContinuousImprovement;
            _contextRecovery = new(saved.Source)
            {
                SummaryModel = saved.SummaryModel, MarkerId = saved.MarkerId, NativeAuto = saved.NativeAuto,
                Dispatched = saved.Dispatched, SummaryCompleted = saved.SummaryCompleted, AmbiguousReplay = saved.AmbiguousReplay,
                ErrorEvidence = saved.ErrorEvidence, RetryAt = saved.RetryAt, ProviderRetryAt = saved.ProviderRetryAt,
                Attempts = saved.Attempts, InterruptedHost = previousOwnedHostStopped
            };
            _contextWorkModel = saved.Source.Model;
            _contextWorkAgent = saved.Source.Agent;
            _contextWorkVariant = saved.Source.Variant;
            _providerRetryAt = saved.ProviderRetryAt;
            SetContextWaitLocked("대화 정리 복구 · 기존 세션 확인 중", "The exact compaction reservation was restored without submitting a prompt.");
            return true;
        }
    }

    public OpenCodeErrorRestart? GetConfirmedRecoverySnapshot()
    {
        lock (_gate)
        {
            if (_unverifiedNativeUserMessageId is not null) return null;
            // Startup's exact-ID receipt can precede the first monitor poll. Its
            // bounded plan read was armed before POST; never substitute an uncertain send.
            if (!_disposed && _lastVerifiedEvidence is null && _confirmedApiReceipt &&
                _apiSubmissionSession is { } submittedSession && _apiSubmissionMessage is { } submittedMessage &&
                _planPath is { } submittedPath && _submittedPlanRead is { IsCompletedSuccessfully: true } planRead &&
                planRead.Result is { Valid: true, Hash: { } submittedHash } && !string.IsNullOrWhiteSpace(_lastUserInstruction))
            {
                long receiptVersion = _snapshotVersion;
                return new(submittedSession, submittedMessage, submittedPath, submittedHash,
                    BuildErrorRecoveryPrompt(submittedPath), _lastUserInstruction,
                    () => { lock (_gate) return receiptVersion == _snapshotVersion; })
                { AutomaticRetryEnabled = RecoveryActiveLocked, RetryAttempt = _errorRetryAttempts };
            }
            if (!_disposed && _contextRecovery is { } context && _sessionId is { } contextSession &&
                _requestId is { } contextRequest && _expectedUserMessageId is { } contextExpected &&
                _planPath is { } contextPath && _planHash is { } contextHash && _pendingMessageId is null &&
                !_abortActionInFlight && !string.IsNullOrWhiteSpace(_lastUserInstruction) &&
                (_lastVerifiedEvidence is not { } native || !ContextBlocked(native)))
            {
                long contextVersion = _snapshotVersion;
                return new(contextSession, contextExpected, contextPath, contextHash, BuildErrorRecoveryPrompt(contextPath),
                    _lastUserInstruction, () => { lock (_gate) return contextVersion == _snapshotVersion; })
                {
                    ReconcileOnly = true, AutomaticRetryEnabled = RecoveryActiveLocked,
                    RetryAttempt = context.Attempts, NotBeforeUtc = context.ProviderRetryAt,
                    RequiresContinuousImprovement = _continuousTaskInProgress,
                    ContextRecovery = new(contextRequest, contextExpected, context.Source, context.SummaryModel,
                        context.MarkerId, context.NativeAuto, context.Dispatched, context.SummaryCompleted,
                        context.AmbiguousReplay, context.ErrorEvidence, context.RetryAt, context.ProviderRetryAt,
                        context.Attempts, _workConfirmed)
                };
            }
            if (_disposed || _restartRequested || _pendingMessageId is not null || _abortActionInFlight ||
                _lastVerifiedEvidence is not { } evidence || evidence.SessionId != _sessionId ||
                evidence.LatestUserMessageId != _expectedUserMessageId || evidence.Status == OpenCodeRecoveryStatus.Unknown ||
                evidence.HasSuccessfulFinalResponse && !(ContinuousOptionEnabledLocked && HasSafeCompletedResponseLocked(evidence)) || evidence.HasBusyDescendants ||
                evidence.HasPendingPermission || evidence.HasPendingQuestion ||
                evidence.HasPendingPermissionInDescendants || evidence.HasPendingQuestionInDescendants ||
                evidence.HasErrorMarker && !OpenCodeFailureClassifier.CanRetryManually(evidence) ||
                _planPath is not { } path || _planHash is not { } hash || string.IsNullOrWhiteSpace(_lastUserInstruction)) return null;
            long version = _snapshotVersion;
            return new(evidence.SessionId, _expectedUserMessageId!, path, hash,
                BuildErrorRecoveryPrompt(path), _lastUserInstruction,
                () => { lock (_gate) return version == _snapshotVersion; })
            {
                AutomaticRetryEnabled = RecoveryActiveLocked && (!evidence.HasErrorMarker || CanAutoRetryLocked(evidence) || OpenCodeFailureClassifier.CanCompact(evidence)),
                RetryAttempt = _errorRetryAttempts,
                NotBeforeUtc = EffectiveRetryAtLocked(evidence),
                RequiresContinuousImprovement = evidence.HasSuccessfulFinalResponse
            };
        }
    }

    public OpenCodeAutoResumeController(string project, string? planPath, OpenCodeRecoveryClient client,
        Func<bool> canAct, TimeProvider? timeProvider = null,
        Func<Action<string>, CancellationToken, Task<IDisposable>>? acquireContinuationAdmission = null)
    {
        _project = Path.TrimEndingDirectorySeparator(Path.GetFullPath(project));
        _planPath = planPath;
        _client = client;
        _canAct = canAct;
        _time = timeProvider ?? TimeProvider.System;
        _acquireContinuationAdmission = acquireContinuationAdmission;
        _localInput.Submitted += text =>
        {
            if (text.TrimStart().StartsWith('/')) return;
            lock (_gate)
            {
                _lastUserInstruction = text;
                _localSubmissionAt = _time.GetUtcNow();
                _continuousTaskInProgress = ContinuousOptionEnabledLocked;
            }
        };
    }

    public event Action<string>? StatusChanged;
    public event Action<OpenCodeAutoResumeDiagnostic>? DiagnosticEmitted;
    public string Status { get { lock (_gate) return _status; } }
    private bool _hasUnfinishedWork, _hasVerifiedCompletion;
    public bool HasUnfinishedWork { get { lock (_gate) return RecoveryActiveLocked && _hasUnfinishedWork; } }
    public bool IsContinuousImprovementEnabled
    {
        get
        {
            lock (_gate)
                return _continuousImprovementEnabled &&
                    (_continuousImprovementUntil is not { } until || until > _time.GetUtcNow());
        }
    }
    public bool HasContinuousImprovementWork { get { lock (_gate) return IsContinuousImprovementEnabled && _hasUnfinishedWork; } }
    public bool IsContinuousImprovementActive { get { lock (_gate) return ContinuousOptionEnabledLocked && _sessionId is not null && !_isRecoveryPaused && !_work.IsCancellationRequested; } }
    public bool IsRecoveryPaused { get { lock (_gate) return _isRecoveryPaused; } }
    public bool HasVerifiedCompletion { get { lock (_gate) return _hasVerifiedCompletion; } }
    private string? _continuationSessionId;
    public string? ContinuationSessionId { get { lock (_gate) return _sessionId ?? _candidate?.SessionId ?? _continuationSessionId; } }
    public string? VerifiedContinuationSessionId { get { lock (_gate) return _continuationSessionId; } }
    public void EnableTaskCompletionMonitoring() { lock (_gate) _observeCompletion = true; }

    public void Start()
    {
        lock (_gate)
        {
            if (_started || _disposed) return;
            _started = true;
            _ = Task.Run(RunAsync);
        }
    }

    public void SetEnabled(bool enabled)
    {
        lock (_gate)
        {
            if (_disposed || _enabled == enabled) return;
            _enabled = enabled;
            if (!RecoveryActiveLocked && !_observeCompletion) InvalidateLocked();
            SetStatusLocked(enabled ? "" : "자동 진행 꺼짐");
        }
    }

    public void SetContinuousImprovement(bool enabled, DateTimeOffset? until, bool recommendPlan = false)
    {
        lock (_gate)
        {
            if (_disposed) return;
            if (enabled && until is { } end && end <= _time.GetUtcNow()) enabled = false;
            if (_continuousImprovementEnabled == enabled && _continuousImprovementUntil == until && _recommendPlan == recommendPlan) return;
            _continuousImprovementEnabled = enabled;
            _continuousImprovementUntil = until;
            _recommendPlan = recommendPlan;
            _recommendedPlanMessageId = null;
            _recommendedPlanResult = null;
            _recommendedPlanFallback = false;
            _recommendedPlanFailures = 0;
            _recommendedPlanRetryAt = null;
            if (enabled && (_sessionId is not null || _candidate is not null || _localSubmissionAt is not null))
                _continuousTaskInProgress = true;
            _epoch++;
            _work.Cancel();
            _work.Dispose();
            _work = new CancellationTokenSource();
            _policy = new();
            SetStatusLocked(enabled ? "Loop · 근거 확인 대기" : "");
        }
    }

    public void Suspend(string reason)
    {
        lock (_gate)
        {
            if (_disposed) return;
            InvalidateLocked();
            SetStatusLocked(_enabled ? reason : "자동 진행 꺼짐");
        }
    }

    public void UpdatePlan(string? path)
    {
        lock (_gate)
        {
            if (_disposed || string.Equals(_planPath, path, StringComparison.OrdinalIgnoreCase)) return;
            _planPath = path;
            _binding++;
            InvalidateLocked();
            SetStatusLocked(_enabled ? "MD 변경 · 새 요청 대기" : "자동 진행 꺼짐");
        }
    }

    public void ObserveLocalInput(string input)
    {
        if (input.Length == 0) return;
        lock (_gate)
        {
            if ((!RecoveryActiveLocked && !_observeCompletion) || _disposed) return;
            if (TerminalInputCapture.IsTerminalResponse(input))
            {
                return;
            }
            InvalidateLocked(preserveInput: true); // Cancel queued work before forwarding a user's key to the TUI.
            _localInput.Observe(input);
            if (input.Contains('\x03') || input == "\x1b")
            {
                _localInput.Clear();
                _localSubmissionAt = null;
                EmitDiagnosticLocked("manual_stop", "user", "Automatic recovery stopped by user input.");
                SetStatusLocked("사용자 중단 · 자동 진행 멈춤");
                return;
            }
            SetStatusLocked("");
        }
    }

    public void ObserveSubmittedPrompt(string prompt, string? sessionId = null, string? messageId = null)
    {
        lock (_gate)
        {
            if ((!RecoveryActiveLocked && !_observeCompletion) || _disposed) return;
            InvalidateLocked();
            if (!string.IsNullOrWhiteSpace(prompt) && !prompt.TrimStart().StartsWith('/'))
            {
                _lastUserInstruction = prompt == _restartSubmittedPrompt && _restartOriginalInstruction is { } original ? original : prompt;
                _localSubmissionAt = _time.GetUtcNow();
                _continuousTaskInProgress = ContinuousOptionEnabledLocked;
                _apiSubmissionSession = sessionId;
                _apiSubmissionMessage = messageId;
                _apiSubmissionTodoVersion = sessionId is null ? 0 : _todoSignals.GetValueOrDefault(sessionId);
                if (sessionId is not null && messageId is not null && _planPath is { } path)
                    _submittedPlanRead = ReadPlanAsync(path, _work.Token);
            }
            SetStatusLocked("");
        }
    }

    // An exact native message read can restore correlation after a missed SSE event.
    // A user's intervening input invalidates these IDs before this method can act.
    public void ConfirmApiSubmission(string sessionId, string messageId)
    {
        lock (_gate)
        {
            if (_disposed || _apiSubmissionSession != sessionId || _apiSubmissionMessage != messageId ||
                _sessionId is not null) return;
            _localSubmissionAt = _time.GetUtcNow();
            _confirmedApiReceipt = true;
            _candidate = new("message.updated", sessionId, messageId, _localSubmissionAt, _apiSubmissionTodoVersion);
        }
        _ = TickSafelyAsync();
    }

    public void PreserveRestartInstruction(string submittedPrompt, string? originalInstruction)
    {
        lock (_gate)
        {
            if (!_disposed && originalInstruction is not null)
            {
                _restartSubmittedPrompt = submittedPrompt;
                _restartOriginalInstruction = originalInstruction;
                if (_lastUserInstruction == submittedPrompt) _lastUserInstruction = originalInstruction;
            }
        }
    }
    public void ObserveNativeSignal(OpenCodeRecoverySignal signal)
    {
        bool poll = false;
        lock (_gate)
        {
            if ((!RecoveryActiveLocked && !_observeCompletion) || _disposed) return;
            if (signal.Type == "todo.updated")
            {
                if (_todoSignals.Count > 64) _todoSignals.Clear();
                _todoSignals[signal.SessionId] = signal.Version;
                if (signal.SessionId == _sessionId) _workConfirmed = true;
                return;
            }
            if (signal.Type == "session.error" && signal.SessionId == _sessionId)
            {
                // The fresh HTTP evidence distinguishes our abort acknowledgement from other errors.
                poll = true;
            }
            else if (signal.Type == "message.updated" && signal.MessageId is { } messageId)
            {
                if (_apiSubmissionMessage is not null && _sessionId is null &&
                    (signal.SessionId != _apiSubmissionSession || messageId != _apiSubmissionMessage)) return;
                if (signal.SessionId == _sessionId && (messageId == _pendingMessageId || messageId == _expectedUserMessageId))
                    return;
                if (_localSubmissionAt is not { } submitted)
                {
                    if (signal.SessionId == _sessionId)
                    {
                        _unverifiedNativeUserMessageId = messageId;
                        _snapshotVersion++;
                        // Native compaction/replay also creates user messages. Only a
                        // fresh structured chain may distinguish it from a new input.
                        poll = true;
                    }
                    if (!poll) return; // Other sessions can be child-agent work; never retarget from their events.
                    _ = TickSafelyAsync();
                    return;
                }
                var now = _time.GetUtcNow();
                if (now - submitted > TimeSpan.FromMinutes(2) || signal.MessageCreatedAt is not { } created ||
                    created < submitted.AddSeconds(-2) || created > now.AddSeconds(5)) return;
                if (_candidate is { } candidate && (candidate.SessionId != signal.SessionId || candidate.MessageId != messageId))
                {
                    if (_confirmedApiReceipt && signal.SessionId == _apiSubmissionSession)
                    {
                        _unverifiedNativeUserMessageId = messageId;
                        _snapshotVersion++;
                        _ = TickSafelyAsync();
                        return;
                    }
                    InvalidateLocked();
                    SetStatusLocked("세션 확인 필요 · 자동 진행 멈춤");
                    return;
                }
                _candidate ??= signal; // Repeated metadata updates must not move the causal todo baseline.
                poll = true;
            }
        }
        if (poll) _ = TickSafelyAsync();
    }

    private async Task RunAsync()
    {
        try
        {
            while (!_lifetime.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), _time, _lifetime.Token).ConfigureAwait(false);
                await TickSafelyAsync().ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task TickSafelyAsync()
    {
        try { await TickAsync().ConfigureAwait(false); }
        catch (OperationCanceledException) { }
        catch (Exception exception)
        {
            lock (_gate)
            {
                if (_disposed || (!RecoveryActiveLocked && !_observeCompletion)) return;
                // Keep the exact owner, request pin, policy reservation and epoch. The next
                // periodic tick retries safe reads; it cannot retarget or repeat a POST.
                bool actionUncertain = _pendingMessageId is not null || _restartRequested || _abortActionInFlight;
                if (_restartRequested) _isRecoveryPaused = true;
                if (!actionUncertain) RecordReadFailureLocked();
                EmitDiagnosticLocked(actionUncertain ? "action_ambiguous" : "tick_fault",
                    actionUncertain ? "action" : "read",
                    actionUncertain
                        ? "An action may have started; native evidence or user review is required before further action."
                        : "Recovery check failed; the exact request remains pinned for a safe retry.",
                    errorCode: "unexpected_exception", exceptionType: exception.GetType().Name, requiresUserAction: actionUncertain);
            }
        }
    }

    public async Task TickAsync()
    {
        if (!await _tickGate.WaitAsync(0).ConfigureAwait(false)) return;
        try
        {
            long epoch;
            string? session, path;
            CancellationToken cancellation;
            OpenCodeRecoverySignal? candidate;
            lock (_gate)
            {
                if (_continuousImprovementEnabled && _continuousImprovementUntil is { } end && end <= _time.GetUtcNow())
                {
                    _continuousImprovementEnabled = false;
                    _continuousImprovementUntil = null;
                    SetStatusLocked("Loop 종료 시간 도달");
                }
                if (_disposed || _restartRequested && _isRecoveryPaused || (!RecoveryActiveLocked && !_observeCompletion) || (_sessionId is null && _candidate is null)) return;
                if (_nextReadRetryAt is { } retryAt && _time.GetUtcNow() < retryAt) return;
                long timestamp = _time.GetTimestamp();
                if (_lastPollTimestamp is long previous && _time.GetElapsedTime(previous, timestamp) > TimeSpan.FromMinutes(2))
                {
                    // A polling gap makes the old activity interval stale, not the
                    // confirmed request. Preserve ownership, provider deadlines and
                    // uncertain delivery; fresh native checks below reconcile them.
                    _lastVerifiedEvidence = null;
                    _hasVerifiedCompletion = false;
                    _stalledAbortAttemptedAt = null;
                    _stalledAbortActivity = _stalledAbortProgress = _stalledAbortRequest = null;
                    ResetNotificationStallLocked();
                    if (_sessionId is { } pinned)
                        _policy.ObservePollingGap(UnavailableObservation(pinned) with { RecoveryEnabled = RecoveryActiveLocked }, _time.GetUtcNow());
                    SetStatusLocked("장시간 대기 복귀 · 현재 요청 상태 확인 중");
                }
                _lastPollTimestamp = timestamp;
                if (!_canAct())
                {
                    _hasVerifiedCompletion = false;
                    ResetNotificationStallLocked();
                    if (_sessionId is { } pinned) _policy.Evaluate(UnavailableObservation(pinned), _time.GetUtcNow());
                    SetStatusLocked("상태 연결 대기");
                    EmitDiagnosticLocked("native_unavailable", "read", "OpenCode native state is temporarily unavailable.", errorCode: "unavailable");
                    return;
                }
                epoch = _epoch;
                candidate = _candidate;
                session = _sessionId ?? candidate?.SessionId;
                path = _planPath;
                cancellation = _work.Token;
            }
            if (session is null || path is null) return;
            var plan = await ReadPlanAsync(path, cancellation).ConfigureAwait(false);
            var read = await _client.ReadAsync(session, cancellation).ConfigureAwait(false);
            if (await HandleContextRecoveryAsync(epoch, session, path, plan, read, cancellation).ConfigureAwait(false)) return;
            RecoveryDecision decision;
            bool restart = false;
            lock (_gate)
            {
                if (!IsCurrentLocked(epoch)) return;
                if (!read.IsAvailable || read.Evidence is not { } evidence)
                {
                    RecordReadFailureLocked();
                    _hasVerifiedCompletion = false;
                    ResetNotificationStallLocked();
                    SetStatusLocked("상태 연결 대기");
                    EmitDiagnosticLocked("native_unavailable", "read", "OpenCode native state is temporarily unavailable.",
                        read.ErrorCode ?? "unavailable");
                    if (_sessionId is not null)
                        _policy.Evaluate(UnavailableObservation(session), _time.GetUtcNow());
                    return;
                }
                _readFailureCount = 0;
                _nextReadRetryAt = null;
                if (candidate is not null && _sessionId is null)
                {
                    bool confirmedCandidate = _confirmedApiReceipt && _apiSubmissionSession == session &&
                        _apiSubmissionMessage == candidate.MessageId;
                    if (_localSubmissionAt is not { } submitted ||
                        !confirmedCandidate && _time.GetUtcNow() - submitted > TimeSpan.FromMinutes(2))
                    {
                        InvalidateLocked();
                        SetStatusLocked("요청 확인 시간 초과 · 새 요청 대기");
                        return;
                    }
                    if (confirmedCandidate)
                    {
                        // Slow native reads cannot expire an exact accepted receipt.
                        // Its submission-time plan and input generation still fence it.
                        if (_submittedPlanRead is { IsCompleted: false })
                        {
                            SetStatusLocked("저장된 MD 확인 대기");
                            return;
                        }
                        if (_submittedPlanRead is not { IsCompletedSuccessfully: true } capturedPlan ||
                            !capturedPlan.Result.Valid || capturedPlan.Result.Hash != plan.Hash)
                        {
                            InvalidateLocked();
                            SetStatusLocked("MD 내용 변경 · 새 요청 대기");
                            return;
                        }
                    }
                    if (!string.IsNullOrEmpty(evidence.ParentSessionId) || evidence.LatestUserMessageId != candidate.MessageId)
                    {
                        InvalidateLocked();
                        SetStatusLocked("세션 확인 필요 · 자동 진행 멈춤");
                        return;
                    }
                    _sessionId = session;
                    _continuationSessionId = session;
                    _requestId = _expectedUserMessageId = candidate.MessageId;
                    _localSubmissionAt = null;
                    _candidate = null;
                    _userWork++;
                    _workConfirmed = _todoSignals.GetValueOrDefault(session) > candidate.Version;
                    _planHash = plan.Hash;
                    lock (OwnersGate) Owners[OwnerKey(session)] = this;
                }
                if (!OwnsSessionLocked(session)) { InvalidateLocked(); SetStatusLocked("다른 터미널에서 관리 중"); return; }
                if (!AdoptRecommendedPlanLocked(evidence, plan.Hash, plan.Valid) ||
                    !ValidateEvidenceLocked(evidence, plan.Hash, plan.Valid)) { ResetNotificationStallLocked(); return; }
                if (_pendingMessageId is { } observedPending && evidence.LatestUserMessageId == observedPending)
                {
                    _previousUserMessageId = _expectedUserMessageId;
                    _expectedUserMessageId = observedPending;
                    _pendingMessageId = null;
                    _awaitingMessageUntil = null;
                    _confirmedPendingReceipt = true;
                    if (_contextContinuation)
                    {
                        _contextRecovery = null;
                        _contextContinuation = false;
                    }
                }
                _lastVerifiedEvidence = evidence;
                if (_stalledAbortAttemptedAt is not null &&
                    (evidence.ActivityFingerprint != _stalledAbortActivity || evidence.ProgressFingerprint != _stalledAbortProgress ||
                     evidence.Status == OpenCodeRecoveryStatus.Retry && EffectiveRetryAtLocked(evidence) is { } retryDeadline && _time.GetUtcNow() < retryDeadline))
                {
                    _stalledAbortAttemptedAt = null;
                    _stalledRestartRetryAt = null;
                    _stalledRestartRetryAttempts = 0;
                }
                if (_lastProgressFingerprint != evidence.ProgressFingerprint)
                {
                    if (_lastProgressFingerprint is not null)
                    {
                        _lastSubstantiveProgressAt = _time.GetUtcNow();
                        _errorRetryAttempts = 0;
                        _errorRetryAt = null;
                    }
                    _lastProgressFingerprint = evidence.ProgressFingerprint;
                }
                _hasUnfinishedWork = HasConfirmedTodoWorkLocked(evidence) && evidence.IncompleteTodoCount > 0 || HasUntrackedRequestLocked(evidence);
                if (evidence.HasErrorMarker && CanAutoRetryLocked(evidence))
                {
                    string retryEvidence = string.Join("|", evidence.CurrentErrors.Select(error => error.RetryEvidenceId));
                    if (_errorRetryMessageId != retryEvidence)
                        _providerRetryAt = OpenCodeFailureClassifier.ProviderRetryAt(evidence, _time.GetUtcNow());
                    if (_errorRetryAt is null || _errorRetryMessageId != retryEvidence)
                    {
                        DateTimeOffset nextRetry = _time.GetUtcNow() + OpenCodeFailureClassifier.RetryDelay(_errorRetryAttempts + 1);
                        if (_providerRetryAt is { } providerDeadline && providerDeadline > nextRetry) nextRetry = providerDeadline;
                        if (_errorRetryAt is null || nextRetry > _errorRetryAt) _errorRetryAt = nextRetry;
                        _errorRetryMessageId = retryEvidence;
                    }
                }
                else if (evidence.HasErrorMarker && !CanAutoRetryLocked(evidence)) _errorRetryAt = null;
                restart = CanRestartStalledLocked(evidence);
                _hasVerifiedCompletion = _workConfirmed && evidence.LatestUserMessageId == _expectedUserMessageId && evidence.AllTodosCompleted && evidence.HasSuccessfulFinalResponse &&
                    evidence.Status == OpenCodeRecoveryStatus.Idle && !evidence.HasRunningTools && !evidence.HasBusyDescendants &&
                    !evidence.HasErrorMarker && !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
                    !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants;
                if (_hasVerifiedCompletion) { _errorRetryAttempts = 0; _errorRetryAt = null; }
                if (_hasVerifiedCompletion && !ContinuousOptionEnabledLocked) _continuousTaskInProgress = false;
                if (HasSafeCompletedResponseLocked(evidence) && ContinuousOptionEnabledLocked && _reviewCompletionMessage != _expectedUserMessageId)
                {
                    bool changed = _reviewTodoFingerprint != evidence.TodoFingerprint || _reviewProgressFingerprint != evidence.ProgressFingerprint;
                    TimeSpan delay = _reviewCompletionMessage is null || changed
                        ? OpenCodeRecoveryPolicy.IdleSettlePeriod
                        : TimeSpan.FromMinutes(_unchangedReviewCycles switch { 0 => 1, 1 => 3, _ => 10 });
                    _unchangedReviewCycles = changed ? 0 : Math.Min(3, _unchangedReviewCycles + 1);
                    _reviewCompletionMessage = _expectedUserMessageId;
                    _reviewTodoFingerprint = evidence.TodoFingerprint;
                    _reviewProgressFingerprint = evidence.ProgressFingerprint;
                    // Rounds that changed nothing come further apart (1, 3, then 10 minutes) but never end the Loop
                    // (사용자: 중간에 멈추면 Loop가 무슨 의미가 있어): it runs until its end time or the user stops it.
                    _nextCompletedReviewAt = _time.GetUtcNow() + delay;
                }
                decision = _policy.Evaluate(ToObservation(evidence, plan.Valid), _time.GetUtcNow());
                if (_pendingMessageId is { } pendingId && decision.Phase != RecoveryPhase.AwaitingNativeResponse && evidence.LatestUserMessageId == pendingId)
                {
                    if (evidence.LatestUserMessageId == pendingId)
                    {
                        _previousUserMessageId = _expectedUserMessageId;
                        _expectedUserMessageId = pendingId;
                    }
                    _pendingMessageId = null;
                    _awaitingMessageUntil = null;
                }
                UpdateVerifiedNotificationStallLocked(evidence, _time.GetUtcNow());
                _isRecoveryPaused = decision.Action == RecoveryAction.Pause;
                if (_isRecoveryPaused) _hasUnfinishedWork = false;
                ShowDecisionLocked(decision);
                if (evidence.HasErrorMarker && _errorRetryAt is { } failureRetry && !_manualErrorRetryRequested &&
                    RecoveryActiveLocked && evidence.Status == OpenCodeRecoveryStatus.Idle && CanAutoRetryLocked(evidence))
                {
                    int seconds = Math.Max(0, (int)Math.Ceiling((failureRetry - _time.GetUtcNow()).TotalSeconds));
                    string reason = OpenCodeFailureClassifier.DisplayReason(evidence);
                    SetStatusLocked(seconds > 0 ? $"{reason} · {seconds}초 후 자동 재시도" : "오류 자동 재시도 확인 중");
                }
                else if (evidence.HasErrorMarker && CanRetryErrorLocked())
                    SetStatusLocked(OpenCodeFailureClassifier.DisplayReason(evidence) + (RecoveryActiveLocked ? "" : " · 자동 진행 꺼짐"));
                if (_lastHealthDiagnosticAt is not { } lastHealth || _time.GetUtcNow() - lastHealth >= TimeSpan.FromMinutes(5))
                {
                    _lastHealthDiagnosticAt = _time.GetUtcNow();
                    EmitDiagnosticLocked("health_snapshot", decision.Phase.ToString(), "Recovery monitor is active and native state was checked.");
                }
            }
            if (restart)
            {
                await RestartStalledAsync(epoch, session, path, cancellation).ConfigureAwait(false);
                return;
            }
            if (decision.Action is not (RecoveryAction.Continue or RecoveryAction.Abort)) return;

            // Planning owns only this tick, never the controller lock or project action
            // gate. Stop, input and mode changes can therefore cancel it immediately.
            if (decision.Action == RecoveryAction.Continue &&
                !await PrepareRecommendedPlanAsync(epoch, session, path, cancellation).ConfigureAwait(false)) return;

            using var continuationAdmission = decision.Action == RecoveryAction.Continue
                ? await AcquireContinuationAdmissionAsync(epoch, session, cancellation).ConfigureAwait(false) : null;
            using (await ProjectRecoveryActionGate.AcquireAsync(_project, cancellation).ConfigureAwait(false))
            {
                // Repeat all native checks immediately before a side effect, after this project's queue.
                var freshPlan = await ReadPlanAsync(path, cancellation).ConfigureAwait(false);
                var fresh = await _client.ReadAsync(session, cancellation).ConfigureAwait(false);
                string? messageId = null;
                Task? actionTask = null;
                string? stalledLaunchToolFingerprint = null;
                lock (_gate)
                {
                    if (!IsCurrentLocked(epoch) || !OwnsSessionLocked(session) || !fresh.IsAvailable || fresh.Evidence is not { } evidence ||
                        !ValidateEvidenceLocked(evidence, freshPlan.Hash, freshPlan.Valid)) return;
                    if (_acquireContinuationAdmission is not null && decision.Action == RecoveryAction.Continue && read.Evidence is { } queuedEvidence &&
                        (evidence.LatestUserMessageId != queuedEvidence.LatestUserMessageId ||
                         evidence.ActivityFingerprint != queuedEvidence.ActivityFingerprint || evidence.ProgressFingerprint != queuedEvidence.ProgressFingerprint ||
                         evidence.TodoFingerprint != queuedEvidence.TodoFingerprint)) return;
                    var checkedDecision = _policy.Evaluate(ToObservation(evidence, freshPlan.Valid), _time.GetUtcNow());
                    if (checkedDecision.Action != decision.Action || !_policy.TryRecordActionAttempted(checkedDecision, _time.GetUtcNow())) return;
                    decision = checkedDecision;
                    if (decision.Action == RecoveryAction.Continue)
                    {
                        bool errorRecovery = evidence.HasErrorMarker && CanRecoverErrorLocked(evidence);
                        if (errorRecovery)
                        {
                            _errorRetryAttempts = Math.Min(int.MaxValue - 1, _errorRetryAttempts + 1);
                            _errorRetryAt = _time.GetUtcNow() + OpenCodeFailureClassifier.RetryDelay(_errorRetryAttempts + 1);
                        }
                        messageId = OpenCodeRecoveryClient.CreateMessageId();
                        _confirmedPendingReceipt = false;
                        _pendingMessageId = messageId;
                        bool completedReview = CanReviewCompletedLocked(evidence);
                        actionTask = _client.ContinueAsync(session, errorRecovery || _contextContinuation ? BuildErrorRecoveryPrompt(path) : completedReview && (!_recommendPlan || _recommendedPlanFallback) ? BuildImprovementReviewPrompt(path) : BuildContinuationPrompt(path), messageId, cancellation,
                            expectedUserMessageId: _expectedUserMessageId, allowAbortedTurn: _abortAccepted,
                            canSend: () => CanSend(epoch, session, path, freshPlan.Hash),
                            expectedProgressFingerprint: evidence.ProgressFingerprint,
                            expectedTodoFingerprint: evidence.TodoFingerprint,
                            allowUntrackedWork: HasUntrackedRequestLocked(evidence), expectedActivityFingerprint: evidence.ActivityFingerprint,
                            expectedStalledLaunchToolFingerprint: _abortedLaunchToolFingerprint,
                            allowCompletedReview: completedReview, allowErrorRecovery: errorRecovery,
                            manualErrorRecovery: BroadErrorRetryLocked,
                            providerRetryAt: _providerRetryAt, retryClock: _time.GetUtcNow,
                            expectedRetryEvidence: errorRecovery ? string.Join("|", evidence.CurrentErrors.Select(error => error.RetryEvidenceId)) : null,
                            model: _contextWorkModel, agent: _contextWorkAgent, variant: _contextWorkVariant,
                            requireCurrentUserTodoWrite: !_workConfirmed && HasCurrentTodoWriteLocked(evidence));
                    }
                    else
                    {
                        _abortActionInFlight = true;
                        _stalledAbortAttemptedAt = _time.GetUtcNow();
                        _stalledAbortActivity = evidence.ActivityFingerprint;
                        _stalledAbortProgress = evidence.ProgressFingerprint;
                        _stalledAbortRequest = evidence.LatestUserMessageId;
                        stalledLaunchToolFingerprint = evidence.StalledLaunchToolFingerprint;
                        actionTask = _client.AbortAsync(session, cancellation,
                        expectedUserMessageId: _expectedUserMessageId, canSend: () => CanSend(epoch, session, path, freshPlan.Hash),
                        expectedProgressFingerprint: evidence.ProgressFingerprint,
                        expectedTodoFingerprint: evidence.TodoFingerprint,
                            allowUntrackedWork: HasUntrackedRequestLocked(evidence), expectedActivityFingerprint: evidence.ActivityFingerprint,
                            expectedStalledLaunchToolFingerprint: stalledLaunchToolFingerprint, retryClock: _time.GetUtcNow,
                            expectedRetryEvidence: string.Join("|", evidence.CurrentErrors.Select(error => error.RetryEvidenceId)),
                            providerRetryAt: EffectiveRetryAtLocked(evidence));
                    }
                    SetStatusLocked(decision.Action == RecoveryAction.Continue
                        ? CanReviewCompletedLocked(evidence) ? "Loop · 결과 검토 및 다음 개선 진행" : "미완료 작업 자동 재개"
                        : "정체 복구 · 중단 확인 중");
                }
                RecoveryActionResult outcome;
                string? actionExceptionType = null;
                try
                {
                    await actionTask.ConfigureAwait(false);
                    // Transport-specific result adaptation is isolated here.
                    outcome = ReadActionOutcome(actionTask);
                }
                catch (OperationCanceledException exception) { outcome = RecoveryActionResult.Ambiguous; actionExceptionType = exception.GetType().Name; }
                catch (Exception exception) { outcome = RecoveryActionResult.Ambiguous; actionExceptionType = exception.GetType().Name; }
                lock (_gate)
                {
                    if (!IsCurrentLocked(epoch)) return;
                    _policy.RecordActionResult(decision.DecisionId, outcome, _time.GetUtcNow());
                    if (outcome == RecoveryActionResult.Accepted)
                    {
                        if (messageId is not null)
                        {
                            _recommendedPlanMessageId = null;
                            _recommendedPlanResult = null;
                            _recommendedPlanFallback = false;
                            if (_lastVerifiedEvidence?.HasErrorMarker == true) _acceptedErrorRetries++;
                            _contextContinuation = false;
                            _contextRecovery = null;
                            _previousUserMessageId = _expectedUserMessageId;
                            _expectedUserMessageId = messageId;
                            _awaitingMessageUntil = _time.GetUtcNow().AddMinutes(2);
                            _abortAccepted = false;
                            _abortedLaunchToolFingerprint = null;
                        }
                        else
                        {
                            _abortAccepted = true;
                            _abortedLaunchToolFingerprint = stalledLaunchToolFingerprint;
                        }
                    }
                    EmitDiagnosticLocked(outcome switch
                    {
                        RecoveryActionResult.Accepted => decision.Action == RecoveryAction.Abort ? "abort_accepted" : "continuation_accepted",
                        RecoveryActionResult.Ambiguous => "action_ambiguous",
                        _ => "action_rejected"
                    }, decision.Phase.ToString(), outcome switch
                    {
                        RecoveryActionResult.Accepted => "Native recovery action was accepted.",
                        RecoveryActionResult.Ambiguous => "Recovery action delivery is uncertain; native evidence is required before any further action.",
                        _ => "Native recovery action was not accepted."
                    }, messageId, errorCode: rejectionCode(actionTask), exceptionType: actionExceptionType,
                    requiresUserAction: outcome != RecoveryActionResult.Accepted);
                    string? rejection = actionTask switch
                    {
                        Task<OpenCodeRecoveryContinueResult> task when task.IsCompletedSuccessfully => task.Result.ErrorCode,
                        Task<OpenCodeRecoveryActionResult> task when task.IsCompletedSuccessfully => task.Result.ErrorCode,
                        _ => null
                    };
                    bool nativeStateAdvanced = outcome == RecoveryActionResult.Failed &&
                        rejection is "progress_changed" or "session_not_ready";
                    if (nativeStateAdvanced)
                    {
                        _stalledAbortAttemptedAt = null;
                        SetStatusLocked("진행 상태 변경 · 다시 확인 중");
                    }
                    else if (decision.Action == RecoveryAction.Abort && outcome != RecoveryActionResult.Accepted)
                        SetStatusLocked("정체 복구 · 중단 응답 확인 중");
                    else if (outcome == RecoveryActionResult.Failed &&
                        (_lastVerifiedEvidence?.HasErrorMarker == true || ContinuousOptionEnabledLocked) &&
                        rejection is "message_preflight_failed" or "identity_unavailable" or "disconnected" or "unavailable" or "timeout" or "http_error")
                    {
                        // These client results occur before POST. Keep the pinned
                        // request; the policy delays and fully revalidates the next attempt.
                        RecordReadFailureLocked();
                        SetStatusLocked(ContinuousOptionEnabledLocked ? "Loop · 연결 복구 후 개선 재시도 대기" : "오류 재시도 연결 대기");
                    }
                    else if (outcome == RecoveryActionResult.Failed)
                    {
                        InvalidateLocked();
                        SetStatusLocked("재개 결과 확인 필요 · 자동 재시도 멈춤");
                    }
                    if (outcome != RecoveryActionResult.Ambiguous) _pendingMessageId = null;
                    _abortActionInFlight = false;
                }
            }
        }
        finally { _tickGate.Release(); }
    }

    private bool OwnsRecommendedPlanLocked(long epoch, string session, string message, string path) =>
        IsCurrentLocked(epoch) && ContinuousOptionEnabledLocked && _recommendPlan &&
        _unverifiedNativeUserMessageId is null && OwnsSessionLocked(session) && _sessionId == session &&
        _expectedUserMessageId == message && _planPath == path && _pendingMessageId is null;

    private bool AdoptRecommendedPlanLocked(RecoverySessionEvidence evidence, string? hash, bool valid)
    {
        if (_recommendedPlanResult is not { Changed: true } result || _recommendedPlanMessageId != _expectedUserMessageId)
            return true;
        if (_planHash == result.PlanHash) return true;
        if (!ContinuousOptionEnabledLocked || !_recommendPlan || !HasSafeCompletedResponseLocked(evidence) || !valid || hash != result.PlanHash)
        {
            InvalidateLocked();
            SetStatusLocked("Loop 2 · 저장된 플랜 또는 완료 상태 확인 필요");
            return false;
        }
        // Only the exact callback's saved hash may replace the submission-time hash.
        // Every later native/file preflight continues to enforce this new hash.
        _planHash = result.PlanHash;
        return true;
    }

    // The planner gave this completed result no next plan: it failed, or found nothing new. Loop never stops for that
    // (사용자: 중간에 멈추면 Loop가 무슨 의미가 있어). The first failure in a row plans again after a minute; after that, and
    // whenever nothing new was found, the round asks the work session itself to review the result and improve it.
    private void RecommendedPlanFailedLocked(string message, string reason)
    {
        _recommendedPlanFailures = Math.Min(int.MaxValue - 1, _recommendedPlanFailures + 1);
        EmitDiagnosticLocked("recommended_plan_failed", "plan", reason);
        if (_recommendedPlanFailures >= 2)
        {
            ReviewInsteadOfPlanLocked(message);
            return;
        }
        _recommendedPlanMessageId = null;
        _recommendedPlanRetryAt = _time.GetUtcNow() + OpenCodeFailureClassifier.RetryDelay(_recommendedPlanFailures);
        SetStatusLocked("Loop 2 · 다음 플랜 작성 실패 · 1분 후 다시 작성합니다");
    }

    private void ReviewInsteadOfPlanLocked(string message)
    {
        _recommendedPlanMessageId = message;
        _recommendedPlanFallback = true;
        _recommendedPlanRetryAt = null;
        SetStatusLocked("Loop 2 · 이번 회차는 결과 검토와 개선으로 이어갑니다");
    }

    private async Task<bool> PrepareRecommendedPlanAsync(long epoch, string session, string path, CancellationToken cancellation)
    {
        string message, originalHash;
        DateTimeOffset? deadline;
        Func<OpenCodeRecommendedPlanRequest, CancellationToken, Task<OpenCodeRecommendedPlanResult?>> callback;
        lock (_gate)
        {
            if (!IsCurrentLocked(epoch)) return false;
            if (!_recommendPlan || _lastVerifiedEvidence is not { } evidence || !CanReviewCompletedLocked(evidence)) return true;
            if (_expectedUserMessageId is not { } id) return false;
            if (_recommendedPlanMessageId == id && (_recommendedPlanFallback || _recommendedPlanResult is { Changed: true })) return true;
            if (_recommendedPlanRetryAt is { } retryAt && _time.GetUtcNow() < retryAt)
            {
                int seconds = Math.Max(1, (int)Math.Ceiling((retryAt - _time.GetUtcNow()).TotalSeconds));
                SetStatusLocked($"Loop 2 · 다음 플랜 다시 작성 대기 · {seconds}초 후");
                return false;
            }
            if (RecommendPlanAsync is not { } handler || _planHash is not { } hash)
            {
                // No planner for this terminal, or no exact saved plan: the round reviews the result in place.
                ReviewInsteadOfPlanLocked(id);
                return true;
            }
            _recommendedPlanRetryAt = null;
            callback = handler;
            message = id;
            originalHash = hash;
            deadline = _continuousImprovementUntil;
            _recommendedPlanMessageId = message;
            SetStatusLocked("Loop 2 · 플랜메이커 Auto Recommand 진행 중");
        }

        bool StillOwned()
        {
            lock (_gate) return OwnsRecommendedPlanLocked(epoch, session, message, path) && _planHash == originalHash;
        }
        async Task<bool> VerifyAsync(CancellationToken token)
        {
            if (!StillOwned()) return false;
            var plan = await ReadPlanAsync(path, token).ConfigureAwait(false);
            var read = await _client.ReadAsync(session, token).ConfigureAwait(false);
            lock (_gate)
                return OwnsRecommendedPlanLocked(epoch, session, message, path) && _planHash == originalHash &&
                    plan.Valid && plan.Hash == originalHash && read.IsAvailable && read.Evidence is { } evidence &&
                    HasSafeCompletedResponseLocked(evidence);
        }

        using var deadlineCancellation = new CancellationTokenSource();
        TimeSpan remaining = deadline is { } end ? end - _time.GetUtcNow() : Timeout.InfiniteTimeSpan;
        using var deadlineTimer = deadline is null ? null : _time.CreateTimer(_ =>
        {
            if (_time.GetUtcNow() >= deadline) deadlineCancellation.Cancel();
        }, null, remaining <= TimeSpan.Zero ? TimeSpan.Zero : TimeSpan.FromMilliseconds(Math.Min(remaining.TotalMilliseconds, uint.MaxValue - 1d)),
            TimeSpan.FromSeconds(1));
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellation, deadlineCancellation.Token);
        try
        {
            linked.Token.ThrowIfCancellationRequested();
            var request = new OpenCodeRecommendedPlanRequest(_project, session, message, path, originalHash, deadline, StillOwned, VerifyAsync);
            OpenCodeRecommendedPlanResult? result = await callback(request, linked.Token).WaitAsync(linked.Token).ConfigureAwait(false);
            lock (_gate)
            {
                if (!OwnsRecommendedPlanLocked(epoch, session, message, path) || linked.IsCancellationRequested) return false;
                if (result is null || string.IsNullOrEmpty(result.PlanHash) || result.Changed != (result.PlanHash != originalHash))
                {
                    RecommendedPlanFailedLocked(message, "Recommended planning did not produce an owned, safely saved result.");
                    return _recommendedPlanFallback;
                }
                _recommendedPlanFailures = 0;
                if (!result.Changed)
                {
                    EmitDiagnosticLocked("recommended_plan_unchanged", "plan", "Recommended planning found nothing new; the work session reviews the result.");
                    ReviewInsteadOfPlanLocked(message);
                    return true;
                }
                // Cache before any further reads: a transient API failure cannot repeat
                // an already successful planning/save cycle for this completed message.
                _recommendedPlanResult = result;
            }
            var savedPlan = await ReadPlanAsync(path, linked.Token).ConfigureAwait(false);
            var fresh = await _client.ReadAsync(session, linked.Token).ConfigureAwait(false);
            lock (_gate)
            {
                if (!OwnsRecommendedPlanLocked(epoch, session, message, path) || linked.IsCancellationRequested) return false;
                if (!fresh.IsAvailable || fresh.Evidence is not { } evidence)
                {
                    RecordReadFailureLocked();
                    return false;
                }
                return AdoptRecommendedPlanLocked(evidence, savedPlan.Hash, savedPlan.Valid) &&
                    ValidateEvidenceLocked(evidence, savedPlan.Hash, savedPlan.Valid);
            }
        }
        catch (OperationCanceledException) when (linked.IsCancellationRequested)
        {
            lock (_gate)
                if (!_disposed && _epoch == epoch && deadline is { } until && _time.GetUtcNow() >= until)
                    SetStatusLocked("Loop 2 종료 시간 도달");
            return false;
        }
        catch (Exception exception)
        {
            lock (_gate)
            {
                if (!OwnsRecommendedPlanLocked(epoch, session, message, path)) return false;
                RecommendedPlanFailedLocked(message, "Recommended planning failed (" + exception.GetType().Name + ").");
                return _recommendedPlanFallback;
            }
        }
    }

    private async Task<IDisposable?> AcquireContinuationAdmissionAsync(long epoch, string session, CancellationToken cancellation)
    {
        if (_acquireContinuationAdmission is null) return null;
        DateTimeOffset? deadline;
        lock (_gate)
        {
            if (!IsCurrentLocked(epoch) || !RecoveryActiveLocked || !OwnsSessionLocked(session)) return null;
            deadline = !_manualErrorRetryRequested && _continuousImprovementEnabled ? _continuousImprovementUntil : null;
        }
        using var deadlineCancellation = new CancellationTokenSource();
        bool waiting = true;
        TimeSpan remaining = deadline is { } end ? end - _time.GetUtcNow() : Timeout.InfiniteTimeSpan;
        using var deadlineTimer = deadline is null ? null : _time.CreateTimer(_ =>
        {
            lock (_gate)
                if (waiting && _time.GetUtcNow() >= deadline) deadlineCancellation.Cancel();
        }, null, remaining <= TimeSpan.Zero ? TimeSpan.Zero : TimeSpan.FromMilliseconds(Math.Min(remaining.TotalMilliseconds, uint.MaxValue - 1d)),
            TimeSpan.FromSeconds(1));
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellation, deadlineCancellation.Token);
        Task<IDisposable>? acquisition = null;
        try
        {
            linked.Token.ThrowIfCancellationRequested();
            acquisition = _acquireContinuationAdmission(status =>
            {
                lock (_gate)
                {
                    if (waiting && !linked.IsCancellationRequested && IsCurrentLocked(epoch) && RecoveryActiveLocked && OwnsSessionLocked(session))
                        SetStatusLocked((ContinuousOptionEnabledLocked ? "Loop · " : "자동 진행 · ") + status);
                }
            }, linked.Token);
            return await acquisition.WaitAsync(linked.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (linked.IsCancellationRequested)
        {
            // A late lease from an injected provider must not strand the shared queue.
            if (acquisition is not null) _ = ReleaseLateAdmissionAsync(acquisition);
            lock (_gate)
                if (!_disposed && _epoch == epoch && deadline is { } until && _time.GetUtcNow() >= until)
                    SetStatusLocked("Loop 종료 시간 도달");
            throw;
        }
        finally { lock (_gate) waiting = false; }
    }

    private static async Task ReleaseLateAdmissionAsync(Task<IDisposable> acquisition)
    {
        try { (await acquisition.ConfigureAwait(false)).Dispose(); }
        catch { /* Cancellation or admission failure did not grant a lease. */ }
    }

    private void SetContextWaitLocked(string status, string reason)
    {
        SetStatusLocked(status);
        if (_lastHealthDiagnosticAt is not { } last || _time.GetUtcNow() - last >= TimeSpan.FromMinutes(1))
        {
            _lastHealthDiagnosticAt = _time.GetUtcNow();
            EmitDiagnosticLocked("context_recovery_wait", "context_recovery", reason);
        }
    }

    private static bool ContextBlocked(RecoverySessionEvidence evidence) =>
        evidence.HasPendingPermission || evidence.HasPendingQuestion || evidence.HasPendingPermissionInDescendants ||
        evidence.HasPendingQuestionInDescendants || evidence.HasRunningTools || evidence.HasBusyDescendants;

    /// <summary>Reconciles native-owned compaction before ordinary latest-user ownership checks.</summary>
    private async Task<bool> HandleContextRecoveryAsync(long epoch, string session, string path,
        (bool Valid, string? Hash) plan, OpenCodeRecoveryReadResult read, CancellationToken cancellation)
    {
        if (!read.IsAvailable || read.Evidence is not { } evidence) return false;
        ContextRecovery? context;
        lock (_gate)
        {
            if (!IsCurrentLocked(epoch)) return false;
            // A confirmed original receipt can already have a native compaction
            // chain before the first monitoring read. Bind only its saved plan and
            // exact persisted source; the chain below still proves every new user.
            if (_sessionId is null && _confirmedApiReceipt && _candidate is { } accepted &&
                accepted.SessionId == session && _submittedPlanRead is { IsCompletedSuccessfully: true } captured &&
                captured.Result.Valid && captured.Result.Hash == plan.Hash && plan.Valid &&
                evidence.NativeMessages.Any(message => message.Id == accepted.MessageId && message.Role == "user") &&
                evidence.NativeMessages.SkipWhile(message => message.Id != accepted.MessageId).Skip(1)
                    .FirstOrDefault(message => message.Role == "user") is { IsCompaction: true, CompactionAuto: true })
            {
                lock (OwnersGate)
                {
                    if (Owners.TryGetValue(OwnerKey(session), out var owner) && !ReferenceEquals(owner, this)) return false;
                    Owners[OwnerKey(session)] = this;
                }
                _sessionId = _continuationSessionId = session;
                _requestId = _expectedUserMessageId = accepted.MessageId;
                _localSubmissionAt = null;
                _candidate = null;
                _userWork++;
                _workConfirmed = _todoSignals.GetValueOrDefault(session) > accepted.Version;
                _planHash = plan.Hash;
            }
            if (!OwnsSessionLocked(session) || evidence.SessionId != _sessionId) return false;
            if (!plan.Valid || _planHash is not null && plan.Hash != _planHash) return false;
            if (_pendingMessageId is not null || _abortActionInFlight || _restartRequested) return false;
            var source = evidence.NativeMessages.FirstOrDefault(message => message.Id == _expectedUserMessageId && message.Role == "user");
            var nextUsers = evidence.NativeMessages.SkipWhile(message => message.Id != _expectedUserMessageId).Skip(1).Where(message => message.Role == "user").ToArray();
            bool compaction = source?.IsCompaction == true || nextUsers.FirstOrDefault()?.IsCompaction == true;
            if (_contextRecovery is null && !OpenCodeFailureClassifier.CanCompact(evidence) && !compaction) return false;
            if (_contextRecovery is null)
            {
                if (source?.Model is null) { SetContextWaitLocked("대화 정리 대기 · 원래 모델 확인 필요", "The exact request model is unavailable."); return true; }
                _contextRecovery = new(source);
                _contextWorkModel ??= source.Model;
                _contextWorkAgent ??= source.Agent;
                _contextWorkVariant ??= source.Variant;
                if (source.IsCompaction) { _contextRecovery.MarkerId = source.Id; _contextRecovery.NativeAuto = source.CompactionAuto; }
            }
            context = _contextRecovery;
        }

        // Pin the effective native compaction agent, including an explicitly
        // configured override. Never select a replacement provider or model.
        if (context.SummaryModel is null)
        {
            var selected = await _client.GetCompactionModelAsync(context.Source.Model!, cancellation).ConfigureAwait(false);
            lock (_gate)
            {
                if (!IsCurrentLocked(epoch) || !ReferenceEquals(context, _contextRecovery)) return true;
                if (selected is null) { SetContextWaitLocked("대화 정리 대기 · 요약 모델 연결 확인", "The effective native compaction agent selection is unavailable."); return true; }
                context.SummaryModel = selected;
            }
        }

        bool attempt = false;
        lock (_gate)
        {
            if (!IsCurrentLocked(epoch) || !ReferenceEquals(context, _contextRecovery) || !OwnsSessionLocked(session)) return true;
            var messages = evidence.NativeMessages;
            // Each new compaction user must immediately follow the currently owned
            // user in user-order. A summary is linked by its native parentID.
            var users = messages.Where(message => message.Role == "user").ToArray();
            int owned = Array.FindIndex(users, message => message.Id == _expectedUserMessageId);
            if (owned < 0) { SetContextWaitLocked("재개 확인 필요 · 정확한 요청 이력 대기", "The pinned request is outside the bounded native history."); return true; }
            if (owned + 1 < users.Length && users[owned + 1].IsCompaction)
            {
                var marker = users[owned + 1];
                if (marker.Model != _contextWorkModel) { SetContextWaitLocked("재개 확인 필요 · 요청 모델 변경", "The compaction user does not retain the pinned work model."); return true; }
                if (!marker.CompactionAuto && !context.Dispatched) return false; // A separate manual compact is not our transaction.
                context.MarkerId = marker.Id;
                context.NativeAuto = marker.CompactionAuto;
                context.RetryInterruptedSummary = false;
                context.Dispatched = true;
                _expectedUserMessageId = marker.Id;
                ClearNativeUserFenceLocked(evidence, marker.Id);
                owned++;
            }
            if (context.MarkerId is { } markerId)
            {
                var summary = messages.LastOrDefault(message => message.Role == "assistant" && message.IsSummary && message.ParentId == markerId);
                if (summary is not null && summary.Model != context.SummaryModel)
                { SetContextWaitLocked("재개 확인 필요 · 요약 모델 변경", "The summary model does not match the pinned effective compaction agent."); return true; }
                if (summary is { IsFinished: true, SuccessfulFinish: true } && summary.Errors.Count == 0)
                {
                    context.SummaryCompleted = true;
                    if (owned + 1 < users.Length)
                    {
                        var resumed = users[owned + 1];
                        bool taggedReplay = context.Source.RequestMarker is { } marker && resumed.RequestMarker == marker &&
                            resumed.TextFingerprint == context.Source.TextFingerprint;
                        bool syntheticContinue = resumed.IsCompactionContinuation;
                        if (!context.NativeAuto || resumed.Model != _contextWorkModel || (!taggedReplay && !syntheticContinue))
                        {
                            context.AmbiguousReplay = true;
                            SetContextWaitLocked("재개 확인 필요 · 새 요청 식별 불명확", "A native user after compaction lacks the pinned replay correlation or native continuation marker.");
                            return true;
                        }
                        // Do not dispatch: native auto compaction already created
                        // the continuation/replay and owns the next model turn.
                        _expectedUserMessageId = resumed.Id;
                        ClearNativeUserFenceLocked(evidence, resumed.Id);
                        _contextRecovery = null;
                        _contextContinuation = false;
                        _confirmedPendingReceipt = true;
                        _isRecoveryPaused = false;
                        return false;
                    }
                    if (context.NativeAuto && context.InterruptedHost && evidence.LatestUserMessageId == markerId &&
                        evidence.Status == OpenCodeRecoveryStatus.Idle && !ContextBlocked(evidence))
                    {
                        // Only a confirmed terminated owned host proves that the
                        // old auto handler cannot create its continuation later.
                        // The exact successful summary can now use our ordinary
                        // reserved-ID continuation and its final native checks.
                        context.NativeAuto = false;
                        context.InterruptedHost = false;
                    }
                    if (context.NativeAuto && evidence.LatestUserMessageId == _expectedUserMessageId &&
                        evidence.Status is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry)
                    {
                        _lastVerifiedEvidence = evidence;
                        return false; // Stall-only policy; never invent a native auto continuation.
                    }
                    if (context.NativeAuto)
                    { SetContextWaitLocked("원래 작업 재개 중 · native 재개 확인", "The successful native automatic summary is awaiting its own continuation receipt."); return true; }
                    if (evidence.Status == OpenCodeRecoveryStatus.Idle && !ContextBlocked(evidence))
                    {
                        _contextContinuation = true;
                        SetStatusLocked("원래 작업 재개 중 · 요약 결과 확인 완료");
                        _isRecoveryPaused = false;
                        return false; // Ordinary exact-ID Continue provides duplicate protection.
                    }
                    return false;
                }
                if ((summary is null || !summary.IsFinished) && (context.InterruptedHost || context.RetryInterruptedSummary) &&
                    evidence.Status == OpenCodeRecoveryStatus.Idle && evidence.LatestUserMessageId == markerId && !ContextBlocked(evidence))
                {
                    context.Dispatched = false;
                    context.RetryInterruptedSummary = true;
                    context.InterruptedHost = false;
                }
                else if (summary is null || !summary.IsFinished)
                {
                    _lastVerifiedEvidence = evidence;
                    if (evidence.Status is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry &&
                        evidence.LatestUserMessageId == _expectedUserMessageId) return false; // Existing stall/abort/restart guards apply.
                    SetContextWaitLocked("대화 정리 중 · native 결과 확인", "The reserved compaction has no completed correlated summary yet.");
                    return true;
                }
                if (!context.RetryInterruptedSummary && !OpenCodeFailureClassifier.CanCompact(evidence) && !OpenCodeFailureClassifier.CanRetryAutomatically(evidence))
                    return false; // Authentication/approval/other manual restrictions remain ordinary policy gates.
                // A failed summary definitively ended the prior mutation. It is
                // safe to reserve a new attempt after the same unlimited backoff.
                context.Dispatched = false;
            }
            else if (context.Dispatched && context.InterruptedHost && evidence.LatestUserMessageId == _expectedUserMessageId &&
                evidence.Status == OpenCodeRecoveryStatus.Idle && !ContextBlocked(evidence))
            {
                context.Dispatched = false;
                context.InterruptedHost = false;
            }
            else if (context.Dispatched && evidence.LatestUserMessageId == _expectedUserMessageId &&
                evidence.Status is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry)
            {
                _lastVerifiedEvidence = evidence;
                return false; // The mutation remains reserved while the stall watchdog observes it.
            }
            else if (context.Dispatched)
            {
                SetContextWaitLocked("재개 확인 필요 · 대화 정리 전송 결과 불명확", "Compaction dispatch is uncertain; another non-idempotent summarize is prohibited.");
                return true;
            }
            if (evidence.LatestUserMessageId != _expectedUserMessageId) return false;
            _lastVerifiedEvidence = evidence;
            _hasVerifiedCompletion = false;
            _hasUnfinishedWork = true;
            _isRecoveryPaused = false;
            string failure = string.Join("|", evidence.CurrentErrors.Select(error => error.RetryEvidenceId));
            if (context.ErrorEvidence != failure)
            {
                context.ErrorEvidence = failure;
                context.ProviderRetryAt = OpenCodeFailureClassifier.ProviderRetryAt(evidence, _time.GetUtcNow());
                context.RetryAt = _time.GetUtcNow() + OpenCodeFailureClassifier.RetryDelay(context.Attempts + 1);
            }
            var deadline = context.RetryAt;
            if (context.ProviderRetryAt > deadline) deadline = context.ProviderRetryAt;
            if (evidence.NativeRetryAt > deadline) deadline = evidence.NativeRetryAt;
            _providerRetryAt = context.ProviderRetryAt;
            if (evidence.Status is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry && !context.Dispatched)
                return false;
            if (!RecoveryActiveLocked || evidence.Status != OpenCodeRecoveryStatus.Idle || ContextBlocked(evidence) ||
                deadline is { } future && _time.GetUtcNow() < future)
            {
                int seconds = deadline is { } next ? Math.Max(0, (int)Math.Min(int.MaxValue, Math.Ceiling((next - _time.GetUtcNow()).TotalSeconds))) : 0;
                SetStatusLocked(seconds > 0 ? $"대화 정리 재시도 대기 · {seconds}초 후 확인" : "대화 정리 대기 · 승인·연결 상태 확인");
                return true;
            }
            attempt = true;
        }
        if (!attempt) return true;
        using var continuationAdmission = await AcquireContinuationAdmissionAsync(epoch, session, cancellation).ConfigureAwait(false);
        using (await ProjectRecoveryActionGate.AcquireAsync(_project, cancellation).ConfigureAwait(false))
        {
            RecoveryNativeMessage target;
            lock (_gate)
            {
                if (!CanSend(epoch, session, path, plan.Hash) || !ReferenceEquals(context, _contextRecovery) || context.Dispatched) return true;
                target = evidence.NativeMessages.First(message => message.Id == _expectedUserMessageId);
                // Reserve before HTTP. Any uncertain dispatched result retains
                // this reservation until an exact new marker/summary is observed.
                context.MarkerId = null;
                context.SummaryCompleted = false;
                context.Dispatched = true;
                context.Attempts = Math.Min(int.MaxValue - 1, context.Attempts + 1);
                context.RetryAt = _time.GetUtcNow() + OpenCodeFailureClassifier.RetryDelay(context.Attempts + 1);
                SetStatusLocked("대화 정리 중 · native 요청 확인");
            }
            var result = await _client.CompactAsync(session, target.Id, context.Source.Model!, context.SummaryModel!,
                evidence.ActivityFingerprint, evidence.ProgressFingerprint, evidence.TodoFingerprint,
                () => CanSend(epoch, session, path, plan.Hash), context.ProviderRetryAt, _time.GetUtcNow, cancellation, context.ErrorEvidence, context.RetryInterruptedSummary).ConfigureAwait(false);
            lock (_gate)
            {
                if (!IsCurrentLocked(epoch) || !ReferenceEquals(context, _contextRecovery)) return true;
                if (result.Outcome == OpenCodeRecoveryOutcome.Rejected)
                {
                    context.Dispatched = false; // Client rejection is guaranteed before POST.
                    if (result.ErrorCode == "compaction_model_changed") context.SummaryModel = null;
                }
                EmitDiagnosticLocked(result.Outcome == OpenCodeRecoveryOutcome.Ambiguous ? "compaction_ambiguous" : "compaction_requested",
                    "context_recovery", "Native compaction requires exact message-chain reconciliation before continuation.", errorCode: SafeCode(result.ErrorCode));
            }
        }
        return true;
    }

    private static string? rejectionCode(Task? action) => action switch
    {
        Task<OpenCodeRecoveryContinueResult> task when task.IsCompletedSuccessfully => SafeCode(task.Result.ErrorCode),
        Task<OpenCodeRecoveryActionResult> task when task.IsCompletedSuccessfully => SafeCode(task.Result.ErrorCode),
        _ => null
    };

    private static string? SafeCode(string? value) => value is not null && value.Length <= 64 &&
        value.All(character => char.IsAsciiLetterOrDigit(character) || character is '_' or '-') ? value : null;

    private void RecordReadFailureLocked()
    {
        _readFailureCount = Math.Min(_readFailureCount + 1, 6);
        int seconds = Math.Min(10 * (1 << Math.Min(_readFailureCount - 1, 3)), 60);
        _nextReadRetryAt = _time.GetUtcNow().AddSeconds(seconds);
    }

    private static RecoveryActionResult ReadActionOutcome(Task action)
    {
        OpenCodeRecoveryOutcome outcome = action switch
        {
            Task<OpenCodeRecoveryContinueResult> continuation => continuation.Result.Outcome,
            Task<OpenCodeRecoveryActionResult> abort => abort.Result.Outcome,
            _ => OpenCodeRecoveryOutcome.Ambiguous
        };
        return outcome switch
        {
            OpenCodeRecoveryOutcome.Accepted => RecoveryActionResult.Accepted,
            OpenCodeRecoveryOutcome.Rejected => RecoveryActionResult.Failed,
            _ => RecoveryActionResult.Ambiguous
        };
    }

    private bool CanRecoverErrorLocked(RecoverySessionEvidence evidence) => RecoveryActiveLocked &&
        _pendingMessageId is null && !_restartRequested && !_abortActionInFlight &&
        evidence.Status == OpenCodeRecoveryStatus.Idle && evidence.LatestUserMessageId == _expectedUserMessageId &&
        !evidence.HasRunningTools && !evidence.HasBusyDescendants &&
        !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
        !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants &&
        CanAutoRetryLocked(evidence);

    // With Loop on, failures the gateway did not label as busy are retried too, on the 1·3·10-minute schedule without limit
    // (사용자: 멈추면 어떻게든 다시 실행해 계속 이어가게). Problems only a person can fix still wait (see CanRetryInLoop).
    private bool BroadErrorRetryLocked => _manualErrorRetryRequested || ContinuousOptionEnabledLocked;

    private bool CanAutoRetryLocked(RecoverySessionEvidence evidence) =>
        _manualErrorRetryRequested ? OpenCodeFailureClassifier.CanRetryManually(evidence) :
        ContinuousOptionEnabledLocked ? OpenCodeFailureClassifier.CanRetryInLoop(evidence) :
        OpenCodeFailureClassifier.CanRetryAutomatically(evidence);

    // The current request failed in a way only a person can fix (credentials, permissions, billing, request shape).
    public bool WaitsForPersonAfterError
    {
        get
        {
            lock (_gate)
                return _lastVerifiedEvidence is { HasErrorMarker: true } evidence && evidence.LatestUserMessageId == _expectedUserMessageId &&
                    !CanAutoRetryLocked(evidence) && !OpenCodeFailureClassifier.CanCompact(evidence) &&
                    !(_abortAccepted && OpenCodeRecoveryClient.IsExpectedAbortError(evidence, _abortedLaunchToolFingerprint));
        }
    }

    private RecoveryObservation ToObservation(RecoverySessionEvidence evidence, bool validPlan) =>
        new(evidence.SessionId, _epoch, _userWork, _binding, _requestId,
            evidence.Status switch
            {
                OpenCodeRecoveryStatus.Idle => OpenCodeRecoveryExecutionState.Idle,
                OpenCodeRecoveryStatus.Busy => OpenCodeRecoveryExecutionState.Busy,
                OpenCodeRecoveryStatus.Retry => OpenCodeRecoveryExecutionState.Retry,
                _ => OpenCodeRecoveryExecutionState.Unknown
            }, ++_statusVersion, true,
            evidence.HasPendingPermission || evidence.HasPendingQuestion || evidence.HasPendingPermissionInDescendants || evidence.HasPendingQuestionInDescendants,
            evidence.HasErrorMarker && !(_abortAccepted && OpenCodeRecoveryClient.IsExpectedAbortError(evidence, _abortedLaunchToolFingerprint)),
            evidence.HasRunningTools || evidence.HasBusyDescendants ? 1 : 0,
            HasConfirmedTodoWorkLocked(evidence) && evidence.TotalTodoCount > 0, evidence.IncompleteTodoCount,
            validPlan, false, RecoveryActiveLocked, evidence.ProgressFingerprint)
        { ActivityFingerprint = evidence.ActivityFingerprint,
            HasCurrentUnfinishedRequest = HasUntrackedRequestLocked(evidence) || HasCurrentTodoWriteLocked(evidence),
            ErrorRecoveryAllowed = CanRecoverErrorLocked(evidence) || evidence.Status is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry &&
                RecoveryActiveLocked && evidence.LatestUserMessageId == _expectedUserMessageId &&
                (CanAutoRetryLocked(evidence) || OpenCodeFailureClassifier.CanCompact(evidence)),
            ManualErrorRecovery = _manualErrorRetryRequested,
            ErrorRetryAt = _errorRetryAt, ProviderRetryAt = _providerRetryAt, NativeRetryAt = EffectiveRetryAtLocked(evidence),
            HasConfirmedErrorResponse = evidence.LatestUserMessageId == _expectedUserMessageId && (evidence.HasConfirmedErrorResponse || _contextContinuation),
            HasConfirmedContinuationReceipt = _confirmedPendingReceipt,
            HasSuccessfulFinalResponse = evidence.LatestUserMessageId == _expectedUserMessageId && evidence.HasSuccessfulFinalResponse,
            HasCompletedReviewRequested = CanReviewCompletedLocked(evidence),
            StalledLaunchToolFingerprint = evidence.StalledLaunchToolFingerprint };

    private bool CanReviewCompletedLocked(RecoverySessionEvidence evidence) =>
        ContinuousOptionEnabledLocked && _nextCompletedReviewAt is { } next && _time.GetUtcNow() >= next &&
        HasSafeCompletedResponseLocked(evidence);

    // Loop reviews rely on the exact successful response, independently of native
    // todo/SSE completion reporting. Missing todos never authorize unfinished work.
    private bool HasSafeCompletedResponseLocked(RecoverySessionEvidence evidence) =>
        evidence.SessionId == _sessionId && !string.IsNullOrEmpty(_expectedUserMessageId) &&
        evidence.LatestUserMessageId == _expectedUserMessageId &&
        (evidence.TotalTodoCount == 0 || evidence.AllTodosCompleted) && evidence.HasSuccessfulFinalResponse &&
        evidence.Status == OpenCodeRecoveryStatus.Idle && !evidence.HasRunningTools && !evidence.HasBusyDescendants &&
        !evidence.HasErrorMarker && !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
        !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants;

    // A missed SSE event can be replaced only by the current turn's exact
    // completed todowrite input matching this fresh native todo snapshot.
    private bool HasConfirmedTodoWorkLocked(RecoverySessionEvidence evidence) =>
        _workConfirmed || HasCurrentTodoWriteLocked(evidence);

    private bool HasCurrentTodoWriteLocked(RecoverySessionEvidence evidence) =>
        evidence.HasCurrentUserTodoWrite && evidence.HasSuccessfulFinalResponse && !evidence.HasErrorMarker &&
        evidence.SessionId == _sessionId && evidence.LatestUserMessageId == _expectedUserMessageId;

    private bool HasUntrackedRequestLocked(RecoverySessionEvidence evidence) =>
        _sessionId == evidence.SessionId && !string.IsNullOrEmpty(_expectedUserMessageId) &&
        evidence.LatestUserMessageId == _expectedUserMessageId && !evidence.HasSuccessfulFinalResponse;

    private void UpdateVerifiedNotificationStallLocked(RecoverySessionEvidence evidence, DateTimeOffset now)
    {
        bool hasTools = evidence.HasRunningTools || evidence.HasBusyDescendants;
        string activity = evidence.ActivityFingerprint;
        bool hasPendingInput = evidence.HasPendingPermission || evidence.HasPendingQuestion ||
            evidence.HasPendingPermissionInDescendants || evidence.HasPendingQuestionInDescendants;
        bool exactCurrentRequest = _workConfirmed && _sessionId == evidence.SessionId &&
            !string.IsNullOrEmpty(_expectedUserMessageId) && evidence.LatestUserMessageId == _expectedUserMessageId;
        if (!exactCurrentRequest || evidence.Status != OpenCodeRecoveryStatus.Busy || hasPendingInput ||
            evidence.HasErrorMarker || evidence.HasSuccessfulFinalResponse || evidence.ProgressFingerprint is not { Length: > 0 } progress)
        {
            ResetNotificationStallLocked();
            return;
        }
        if (_notificationStallSince is null || _notificationStallSession != evidence.SessionId ||
            _notificationStallRequest != _expectedUserMessageId || _notificationStallProgress != progress ||
            _notificationStallActivity != activity || _notificationStallHasTools != hasTools || _notificationStallWork != _userWork || _notificationStallBinding != _binding)
        {
            _notificationStallSince = now;
            _notificationStallSession = evidence.SessionId;
            _notificationStallRequest = _expectedUserMessageId;
            _notificationStallProgress = progress;
            _notificationStallActivity = activity;
            _notificationStallHasTools = hasTools;
            _notificationStallWork = _userWork;
            _notificationStallBinding = _binding;
        }
        TimeSpan required = hasTools ? TimeSpan.FromMinutes(15) : TimeSpan.FromMinutes(5);
        _hasVerifiedNotificationStall = now >= _notificationStallSince.Value &&
            now - _notificationStallSince.Value >= required;
        _notificationStallLastVerifiedAt = _hasVerifiedNotificationStall ? now : null;
    }

    private void ResetNotificationStallLocked()
    {
        _hasVerifiedNotificationStall = false;
        _notificationStallLastVerifiedAt = null;
        _notificationStallSince = null;
        _notificationStallSession = _notificationStallRequest = _notificationStallProgress = _notificationStallActivity = null;
        _notificationStallWork = _notificationStallBinding = 0;
    }

    private bool CanRestartStalledLocked(RecoverySessionEvidence evidence) => !_restartRequested &&
        (RestartStalledProcessAsync is not null || RestartStalledProcessWithOutcomeAsync is not null) &&
        (_stalledRestartRetryAt is not { } retryAt || _time.GetUtcNow() >= retryAt) &&
        _stalledAbortAttemptedAt is { } attempted &&
        _time.GetUtcNow() - attempted >= TimeSpan.FromMinutes(2) &&
        IsStalledExecution(evidence, _time.GetUtcNow()) &&
        (EffectiveRetryAtLocked(evidence) is not { } providerRetry || _time.GetUtcNow() >= providerRetry) &&
        evidence.LatestUserMessageId == _stalledAbortRequest &&
        evidence.ActivityFingerprint == _stalledAbortActivity && evidence.ProgressFingerprint == _stalledAbortProgress &&
        !evidence.HasRunningTools && !evidence.HasBusyDescendants && !evidence.HasSuccessfulFinalResponse &&
        (!evidence.HasErrorMarker || (CanAutoRetryLocked(evidence) || OpenCodeFailureClassifier.CanCompact(evidence))) &&
        !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
        !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants;

    private static bool IsStalledExecution(RecoverySessionEvidence evidence, DateTimeOffset now) =>
        evidence.Status == OpenCodeRecoveryStatus.Busy || evidence.Status == OpenCodeRecoveryStatus.Retry &&
        (evidence.NativeRetryAt is not { } retryAt || now >= retryAt);

    private DateTimeOffset? EffectiveRetryAtLocked(RecoverySessionEvidence evidence)
    {
        DateTimeOffset? native = evidence.Status == OpenCodeRecoveryStatus.Retry ? evidence.NativeRetryAt : null;
        DateTimeOffset? provider = evidence.HasErrorMarker ? _errorRetryAt : null;
        if (native is null) return provider;
        return provider is not null && provider > native ? provider : native;
    }

    private async Task RestartStalledAsync(long epoch, string session, string path, CancellationToken cancellation)
    {
        using (await ProjectRecoveryActionGate.AcquireAsync(_project, cancellation).ConfigureAwait(false))
        {
            var plan = await ReadPlanAsync(path, cancellation).ConfigureAwait(false);
            var fresh = await _client.ReadAsync(session, cancellation).ConfigureAwait(false);
            OpenCodeStalledRestart request;
            Func<OpenCodeStalledRestart, Task<bool>>? restart;
            Func<OpenCodeStalledRestart, Task<OpenCodeRestartOutcome>>? restartWithOutcome;
            lock (_gate)
            {
                if (!IsCurrentLocked(epoch) || !OwnsSessionLocked(session) || !fresh.IsAvailable || fresh.Evidence is not { } evidence ||
                    !ValidateEvidenceLocked(evidence, plan.Hash, plan.Valid) || !CanRestartStalledLocked(evidence)) return;
                _restartRequested = true;
                _isStalled = true;
                restart = RestartStalledProcessAsync;
                restartWithOutcome = RestartStalledProcessWithOutcomeAsync;
                string prompt = BuildContinuationPrompt(path) + "\n\n이전 OpenCode 요청이 정체되어 프로세스를 재시작했습니다. " +
                    "현재 파일과 실행 결과부터 확인해 이미 적용한 변경을 반복하지 마세요.\n원래 사용자 요청:\n" + _lastUserInstruction;
                request = new(session, _expectedUserMessageId!, path, plan.Hash!, prompt,
                    () => CanSend(epoch, session, path, plan.Hash),
                    async () =>
                    {
                        var final = await _client.ReadAsync(session, cancellation).ConfigureAwait(false);
                        lock (_gate)
                        {
                            return CanSend(epoch, session, path, plan.Hash) && final.IsAvailable && final.Evidence is { } current &&
                                current.LatestUserMessageId == evidence.LatestUserMessageId && IsStalledExecution(current, _time.GetUtcNow()) &&
                                (EffectiveRetryAtLocked(current) is not { } providerRetry || _time.GetUtcNow() >= providerRetry) &&
                                current.CurrentErrors.Select(error => error.RetryEvidenceId).SequenceEqual(evidence.CurrentErrors.Select(error => error.RetryEvidenceId)) &&
                                current.ActivityFingerprint == evidence.ActivityFingerprint && current.ProgressFingerprint == evidence.ProgressFingerprint &&
                                current.TodoFingerprint == evidence.TodoFingerprint && !current.HasRunningTools && !current.HasBusyDescendants &&
                                !current.HasSuccessfulFinalResponse &&
                                (!current.HasErrorMarker || CanAutoRetryLocked(current) || OpenCodeFailureClassifier.CanCompact(current)) &&
                                !current.HasPendingPermission && !current.HasPendingQuestion &&
                                !current.HasPendingPermissionInDescendants && !current.HasPendingQuestionInDescendants;
                        }
                    }) { OriginalInstruction = _lastUserInstruction,
                        ReconcileRecovery = _contextRecovery is not null ? GetConfirmedRecoverySnapshot() : null };
                SetStatusLocked("정체 복구 · 터미널 재시작 중");
            }
            OpenCodeRestartOutcome outcome = restartWithOutcome is not null
                ? await restartWithOutcome(request).ConfigureAwait(false)
                : await restart!(request).ConfigureAwait(false) ? OpenCodeRestartOutcome.Succeeded : OpenCodeRestartOutcome.Paused;
            lock (_gate)
            {
                if (IsCurrentLocked(epoch) && outcome == OpenCodeRestartOutcome.RetryLater)
                {
                    // Only the lifecycle owner can prove that no stop/start/send occurred.
                    // Recheck all native evidence on the next delayed attempt.
                    _restartRequested = false;
                    _stalledRestartRetryAttempts = Math.Min(int.MaxValue - 1, _stalledRestartRetryAttempts + 1);
                    _stalledRestartRetryAt = _time.GetUtcNow() + OpenCodeFailureClassifier.RetryDelay(_stalledRestartRetryAttempts);
                    SetStatusLocked("정체 복구 · 재시작 재확인 대기");
                }
                else if (IsCurrentLocked(epoch) && outcome == OpenCodeRestartOutcome.Paused)
                {
                    _isRecoveryPaused = true;
                    _hasUnfinishedWork = false;
                    SetStatusLocked("재시작 확인 필요 · 자동 복구 멈춤");
                }
            }
        }
    }

    private RecoveryObservation UnavailableObservation(string session) => new(session, _epoch, _userWork, _binding, _requestId,
        OpenCodeRecoveryExecutionState.Unknown, ++_statusVersion, false, false, false, 0, false, 0, false, false, _enabled, null);

    private void ClearNativeUserFenceLocked(RecoverySessionEvidence evidence, params string?[] verifiedIds)
    {
        if (_unverifiedNativeUserMessageId is { } observed && verifiedIds.Contains(observed) &&
            evidence.NativeMessages.Any(message => message.Role == "user" && message.Id == observed))
            _unverifiedNativeUserMessageId = null;
    }

    private bool ValidateEvidenceLocked(RecoverySessionEvidence evidence, string? planHash, bool valid)
    {
        bool waitingForOurMessage = _awaitingMessageUntil is { } until && _time.GetUtcNow() <= until &&
            evidence.LatestUserMessageId == _previousUserMessageId;
        bool exactAmbiguousMessage = _pendingMessageId is { } pending && evidence.LatestUserMessageId == pending;
        if (evidence.SessionId != _sessionId || (evidence.LatestUserMessageId != _expectedUserMessageId && !waitingForOurMessage && !exactAmbiguousMessage))
        {
            EmitDiagnosticLocked("request_changed", "evidence", "The latest native request no longer matches the pinned request.", requiresUserAction: true);
            InvalidateLocked(); SetStatusLocked("요청 변경 · 자동 진행 대기"); return false;
        }
        if (_planHash is not null && planHash != _planHash)
        {
            EmitDiagnosticLocked("plan_changed", "plan", "The bound plan changed while this request was active.", requiresUserAction: true);
            InvalidateLocked(); SetStatusLocked("MD 내용 변경 · 새 요청 대기"); return false;
        }
        if (!valid)
        {
            EmitDiagnosticLocked("plan_unavailable", "plan", "The bound plan file is missing or invalid.", requiresUserAction: true);
            SetStatusLocked("저장된 MD 확인 필요"); return false;
        }
        _planHash ??= planHash;
        ClearNativeUserFenceLocked(evidence, _expectedUserMessageId, _pendingMessageId);
        return true;
    }

    private bool CanSend(long epoch, string session, string path, string? hash)
    {
        lock (_gate)
        {
            if (_unverifiedNativeUserMessageId is not null || !RecoveryActiveLocked || !IsCurrentLocked(epoch) || !OwnsSessionLocked(session)) return false;
            try
            {
                var file = new FileInfo(path);
                if (!file.Exists || file.Length > 2 * 1024 * 1024) return false;
                return Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(File.ReadAllText(path)))) == hash;
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException) { return false; }
        }
    }

    private bool RecoveryActiveLocked => _manualErrorRetryRequested || (_continuousTaskInProgress
        ? ContinuousOptionEnabledLocked
        : _enabled || ContinuousOptionEnabledLocked);
    private bool ContinuousOptionEnabledLocked => _continuousImprovementEnabled &&
        (_continuousImprovementUntil is not { } until || until > _time.GetUtcNow());
    private bool IsCurrentLocked(long epoch) => !_disposed && (RecoveryActiveLocked || _observeCompletion) && _epoch == epoch && !_work.IsCancellationRequested && _canAct();
    private string OwnerKey(string session) => _project + "\n" + session;
    private bool OwnsSessionLocked(string session) { lock (OwnersGate) return Owners.TryGetValue(OwnerKey(session), out var owner) && ReferenceEquals(owner, this); }

    private void InvalidateLocked(bool preserveInput = false, bool invalidateSnapshot = true)
    {
        _unverifiedNativeUserMessageId = null;
        _contextRecovery = null;
        _contextWorkModel = null;
        _contextWorkAgent = _contextWorkVariant = null;
        _contextContinuation = false;
        if (invalidateSnapshot) _snapshotVersion++;
        _lastVerifiedEvidence = null;
        _confirmedPendingReceipt = false;
        _confirmedApiReceipt = false;
        _submittedPlanRead = null;
        _errorRetryAt = null;
        _errorRetryMessageId = null;
        _providerRetryAt = null;
        _errorRetryAttempts = 0;
        _manualErrorRetryRequested = false;
        if (!preserveInput) _localInput.Clear();
        if (_sessionId is { } session)
            lock (OwnersGate)
                if (Owners.TryGetValue(OwnerKey(session), out var owner) && ReferenceEquals(owner, this)) Owners.Remove(OwnerKey(session));
        _epoch++;
        _work.Cancel();
        _work.Dispose();
        _work = new CancellationTokenSource();
        _sessionId = _requestId = _expectedUserMessageId = _pendingMessageId = null;
        _previousUserMessageId = null;
        _awaitingMessageUntil = null;
        _abortAccepted = false;
        _abortedLaunchToolFingerprint = null;
        _stalledAbortAttemptedAt = null;
        _stalledRestartRetryAt = null;
        _stalledRestartRetryAttempts = 0;
        _stalledAbortActivity = _stalledAbortProgress = _stalledAbortRequest = null;
        _isStalled = _restartRequested = false;
        _abortActionInFlight = false;
        ResetNotificationStallLocked();
        _candidate = null;
        _localSubmissionAt = null;
        _apiSubmissionSession = _apiSubmissionMessage = null;
        _lastPollTimestamp = null;
        _planHash = null;
        _lastProgressFingerprint = null;
        _lastSubstantiveProgressAt = null;
        _workConfirmed = false;
        _continuousTaskInProgress = false;
        _reviewCompletionMessage = _reviewTodoFingerprint = _reviewProgressFingerprint = null;
        _recommendedPlanMessageId = null;
        _recommendedPlanResult = null;
        _recommendedPlanFallback = false;
        _recommendedPlanFailures = 0;
        _recommendedPlanRetryAt = null;
        _nextCompletedReviewAt = null;
        _unchangedReviewCycles = 0;
        _isRecoveryPaused = false;
        _hasUnfinishedWork = _hasVerifiedCompletion = false;
        _policy = new();
    }

    private void ShowDecisionLocked(RecoveryDecision decision)
    {
        _isStalled = decision.Phase is RecoveryPhase.StalledSuspected or RecoveryPhase.AbortRequested or
            RecoveryPhase.AwaitingFreshIdleAfterAbort or RecoveryPhase.Paused || _restartRequested;
        if (decision.Action == RecoveryAction.Pause)
        {
            EmitDiagnosticLocked("recovery_paused", decision.Phase.ToString(), "Recovery is paused and needs user attention.", requiresUserAction: true);
            SetStatusLocked("자동 진행 확인 필요");
            return;
        }
        if (ContinuousOptionEnabledLocked && _lastVerifiedEvidence is { } completed &&
            HasSafeCompletedResponseLocked(completed) && _nextCompletedReviewAt is { } next &&
            decision.Phase is RecoveryPhase.Idle or RecoveryPhase.IdleSettling or RecoveryPhase.ReadyToContinue or RecoveryPhase.RetryDelay)
        {
            int seconds = Math.Max(0, (int)Math.Ceiling((next - _time.GetUtcNow()).TotalSeconds));
            SetStatusLocked(seconds > 0 ? $"Loop · 개선 검토 대기 · {seconds}초 후" : "Loop · 개선 검토 준비 중");
            return;
        }
        string diagnosticCode = decision.Phase switch
        {
            RecoveryPhase.StalledSuspected or RecoveryPhase.AbortRequested or RecoveryPhase.AwaitingFreshIdleAfterAbort => "stall_recovery_wait",
            RecoveryPhase.WaitingForNativeRetry => "native_retry_wait",
            _ => "recovery_wait"
        };
        EmitDiagnosticLocked(diagnosticCode, decision.Phase.ToString(), SafeReason(decision.Reason),
            requiresUserAction: decision.Phase is RecoveryPhase.Paused or RecoveryPhase.WaitingForInput);
        SetStatusLocked(decision.Phase switch
        {
            RecoveryPhase.StalledSuspected => "정체 의심 · 복구 대기",
            RecoveryPhase.IdleSettling or RecoveryPhase.ReadyToContinue => "미완료 · 자동 재개 대기",
            RecoveryPhase.AwaitingFreshIdleAfterAbort => "중단 확인 대기",
            RecoveryPhase.AwaitingNativeResponse => "자동 재개 응답 대기",
            RecoveryPhase.WaitingForNativeRetry => "OpenCode 재시도 대기",
            RecoveryPhase.RetryDelay => "재개 간격 대기",
            RecoveryPhase.Paused => "자동 진행 확인 필요",
            _ => ""
        });
    }

    private void SetStatusLocked(string text)
    {
        if (_status == text) return;
        _status = text;
        var handlers = StatusChanged;
        if (handlers is null) return;
        foreach (Action<string> handler in handlers.GetInvocationList())
        {
            try { handler(text); }
            catch { /* An observer must not interrupt a recovery decision or side effect. */ }
        }
    }

    private void EmitDiagnosticLocked(string code, string phase, string reason, string? messageId = null,
        string? errorCode = null, string? exceptionType = null, bool requiresUserAction = false)
    {
        if (_disposed || (!_enabled && !ContinuousOptionEnabledLocked && !_observeCompletion)) return;
        DateTimeOffset now = _time.GetUtcNow();
        string? sessionId = _sessionId ?? _candidate?.SessionId;
        string safeCode = SafeCode(code) ?? "state";
        string safePhase = SafeCode(phase) ?? "unknown";
        string key = string.Join("|", safeCode, safePhase, sessionId, messageId ?? _expectedUserMessageId, errorCode, exceptionType);
        if (code != "health_snapshot" && _diagnosticLastEmitted.TryGetValue(key, out DateTimeOffset previous) &&
            now >= previous && now - previous < TimeSpan.FromMinutes(10)) return;
        _diagnosticLastEmitted[key] = now;
        if (_diagnosticLastEmitted.Count > 128)
        {
            foreach (string oldKey in _diagnosticLastEmitted.Where(pair => now - pair.Value >= TimeSpan.FromMinutes(10))
                         .Select(pair => pair.Key).ToArray()) _diagnosticLastEmitted.Remove(oldKey);
        }
        var diagnostic = new OpenCodeAutoResumeDiagnostic(now, safeCode, safePhase, reason,
            sessionId, messageId ?? _pendingMessageId ?? _expectedUserMessageId, _lastSubstantiveProgressAt,
            SafeCode(errorCode), SafeCode(exceptionType), requiresUserAction);
        var handlers = DiagnosticEmitted;
        if (handlers is null) return;
        foreach (Action<OpenCodeAutoResumeDiagnostic> handler in handlers.GetInvocationList())
        {
            try { handler(diagnostic); }
            catch { /* Diagnostics are observational and cannot alter recovery safety. */ }
        }
    }

    private static string SafeReason(string? reason) => reason switch
    {
        "Permission or question input is pending." => "Permission or question input is pending.",
        "OpenCode is waiting for permission or a question response." => "OpenCode is waiting for permission or a question response.",
        "OpenCode reported an error for the current request." => "OpenCode reported an error for the current request.",
        "OpenCode reports an error; automatic recovery is paused." => "OpenCode reports an error; automatic recovery is paused.",
        "OpenCode is in its native retry wait; recovery will not interrupt it." => "OpenCode is in its native retry wait; recovery will not interrupt it.",
        "The plan file is invalid." => "The bound plan is invalid.",
        "A known unfinished native todo task remains." => "A known unfinished native todo task remains.",
        _ => "Recovery is waiting for fresh native evidence."
    };

    private const string BoundedAppVerificationInstruction = "\n\nWhen verifying an app you created, run it only as a bounded 60–120 second smoke check. Keep the exact child process handle or PID you started and terminate only that owned process tree in a finally/cleanup step, then verify it exited. Do not leave a foreground server running, use an unbounded wait, or kill by process name. If cleanup or exit cannot be verified, report that clearly and stop.";

    private static string BuildContinuationPrompt(string planPath) => BuildContinuationPromptCore(planPath) + BoundedAppVerificationInstruction;

    private string BuildErrorRecoveryPrompt(string planPath) => BuildContinuationPrompt(planPath) +
        "\n\n이전 요청에서 오류가 발생했습니다. 현재 파일·변경분·검증 결과부터 확인하고 이미 완료한 작업을 반복하지 마세요. 원래 사용자 요청을 보존해 남은 작업만 이어가세요.\n원래 사용자 요청:\n" + _lastUserInstruction;

    private static string BuildImprovementReviewPrompt(string planPath) =>
        "Loop 지속 개선: 연결된 plan.md " + JsonSerializer.Serialize(planPath) +
        "와 현재 프로젝트의 실제 코드·변경분·실행 결과·유효한 검증 근거를 다시 검토하세요. 완료된 todo는 완료로 유지하고 이미 한 구현을 반복하거나 무관한 기능을 추가하지 마세요. " +
        "현재 프로젝트와 플랜 범위 안에서 근거 있는 누락·버그·검증 공백·사용성 개선 후보를 찾고, 사용자가 원하는 서비스에 가장 도움이 되는 개선을 선택하세요. " +
        "먼저 발견 근거와 개선 목표·완료 기준을 짧게 기록하고 todo로 만든 뒤, 변경 규모가 커도 주저하지 말고 필요한 만큼 구현과 검증을 실제로 수행해 결과를 확인하세요. " +
        "근거 있는 개선이 없으면 변경을 억지로 만들지 말고 검토한 결과와 개선이 없는 이유를 보고하세요. 앱이 간격을 두고 재점검하므로 동일 구현을 다시 수행하지 마세요. " +
        "사용자 중단·종료 예약·승인·질문 대기를 존중하고 안전하게 진행할 수 없으면 이유를 남기고 기다리세요." + BoundedAppVerificationInstruction;

    private static string BuildContinuationPromptCore(string planPath) =>
        "연결된 plan.md " + JsonSerializer.Serialize(planPath) +
        "를 다시 읽고 현재 코드·변경분·검증 근거와 미완료 todo를 요구사항별로 대조하세요. 끝난 작업은 반복하지 말고 이미 충족된 항목은 근거를 남겨 todo만 완료로 정리하세요. 플랜이나 todo의 미완료 표시만으로 재구현하지 마세요. 실제 누락·결함이 남아 있으면 사용자에게 영향이 큰 것부터 남은 todo를 이어서 끝까지 구현·검증하세요. 변경 규모 때문에 작업을 줄이지 말고, todo는 실제 결과로만 갱신하세요. 기존 검증이 여전히 유효하면 재사용하고, 모두 충족되었으면 변경 없이 완료 근거를 보고하고 멈추세요. 승인이나 질문이 필요하거나 안전하게 진전할 수 없으면 사유를 남기고 멈추세요.";

    private static async Task<(bool Valid, string? Hash)> ReadPlanAsync(string path, CancellationToken token)
    {
        try
        {
            var file = new FileInfo(path);
            if (!file.Exists || file.Length == 0 || file.Length > 2 * 1024 * 1024) return (false, null);
            string text = await File.ReadAllTextAsync(path, token).ConfigureAwait(false);
            return (!string.IsNullOrWhiteSpace(text), Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(text))));
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException) { return (false, null); }
    }

    public void Dispose()
    {
        lock (_gate)
        {
            if (_disposed) return;
            InvalidateLocked(invalidateSnapshot: false);
            _disposed = true;
            _lifetime.Cancel();
            _work.Cancel();
            _client.Dispose();
        }
    }
}
}
#endregion
#endif

