#if TN_WPF || TN_SOURCE_SERVICES_OPENCODECONVERSATIONCLIENT_CS
#region Services/OpenCodeConversationClient.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Net;
using global::System.Net.Http;
using global::System.Net.Http.Headers;
using global::System.Text;
using global::System.Text.Json;


/// <summary>Typed, directory-scoped HTTP access to one headless OpenCode server.</summary>
public sealed partial class OpenCodeConversationClient : IDisposable
{
    private const int MaximumResponseBytes = 4 * 1024 * 1024;
    private const int MaximumRequestBytes = 1024 * 1024;
    private const int MaximumSessionScopeDescendants = 100;
    private const int MaximumSessionScopeDepth = 16;
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(15);
    private static readonly TimeSpan SessionScopeTimeout = TimeSpan.FromSeconds(5);
    private readonly Uri _endpoint;
    private readonly string _directory;
    private readonly HttpClient _httpClient;
    private readonly bool _ownsClient;
    private readonly AuthenticationHeaderValue? _authorization;
    private bool _disposed;

    public OpenCodeConversationClient(Uri endpoint, string directory, HttpClient? httpClient = null)
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        ArgumentException.ThrowIfNullOrWhiteSpace(directory);
        if (!endpoint.IsAbsoluteUri || endpoint.Scheme != Uri.UriSchemeHttp || !endpoint.IsLoopback ||
            !string.IsNullOrEmpty(endpoint.UserInfo) || !string.IsNullOrEmpty(endpoint.Query) || !string.IsNullOrEmpty(endpoint.Fragment))
            throw new ArgumentException("The OpenCode endpoint must be an absolute loopback HTTP URI without credentials, query, or fragment.", nameof(endpoint));
        _endpoint = new Uri(endpoint.GetLeftPart(UriPartial.Authority) + endpoint.AbsolutePath.TrimEnd('/') + "/", UriKind.Absolute);
        _directory = Path.GetFullPath(directory);
        if (Environment.GetEnvironmentVariable("OPENCODE_SERVER_PASSWORD") is { Length: > 0 } password)
            _authorization = new AuthenticationHeaderValue("Basic", Convert.ToBase64String(Encoding.UTF8.GetBytes((Environment.GetEnvironmentVariable("OPENCODE_SERVER_USERNAME") ?? "opencode") + ":" + password)));
        if (httpClient is null)
        {
            _httpClient = new HttpClient(new HttpClientHandler { UseProxy = false, AllowAutoRedirect = false }) { Timeout = Timeout.InfiniteTimeSpan };
            _ownsClient = true;
        }
        else _httpClient = httpClient;
    }

    public Task<JsonElement> ListSessionsAsync(CancellationToken cancellationToken = default) => GetJsonAsync(BuildEndpoint("/session"), cancellationToken);

    public Task<JsonElement> CreateSessionAsync(string title, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(title);
        return SendJsonAsync(HttpMethod.Post, BuildEndpoint("/session"), new { title }, cancellationToken);
    }

    public async Task<JsonElement> GetSessionAsync(string sessionID, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sessionID);
        JsonElement session = await GetJsonAsync(BuildSessionEndpoint(sessionID), cancellationToken).ConfigureAwait(false);
        if (GetString(session, "id") != sessionID)
            throw new InvalidDataException("OpenCode returned a different session ID than requested.");
        string? directory = GetString(session, "directory");
        if (string.IsNullOrWhiteSpace(directory) || !DirectoriesEqual(directory, _directory))
            throw new InvalidDataException("OpenCode returned a session outside the selected project directory.");
        if (GetString(session, "parentID") is not null)
            throw new InvalidDataException("The requested session is not a root session.");
        return session;
    }

    /// <summary>Updates the old app default title only for a verified root session in this project.</summary>
    public async Task<bool> RenameDefaultSessionAsync(string sessionID, string projectTitle, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(projectTitle);
        if (projectTitle.Length > 256) throw new ArgumentOutOfRangeException(nameof(projectTitle));
        JsonElement existing = await GetSessionAsync(sessionID, cancellationToken).ConfigureAwait(false);
        if (GetString(existing, "title") != "Terminal Notes" || projectTitle == "Terminal Notes") return false;

        await SendNoContentAsync(HttpMethod.Patch, BuildSessionEndpoint(sessionID), new { title = projectTitle }, cancellationToken)
            .ConfigureAwait(false);
        JsonElement updated = await GetSessionAsync(sessionID, cancellationToken).ConfigureAwait(false);
        if (GetString(updated, "title") != projectTitle)
            throw new InvalidDataException("OpenCode did not retain the project session title.");
        return true;
    }

    /// <summary>Returns the verified root session and its bounded same-project descendants.</summary>
    public async Task<IReadOnlySet<string>> ReadSessionScopeAsync(string rootSessionID, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(rootSessionID);
        if (!IsValidSessionID(rootSessionID)) throw new ArgumentException("The root session ID is malformed.", nameof(rootSessionID));
        using var scopeTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        scopeTimeout.CancelAfter(SessionScopeTimeout);
        CancellationToken token = scopeTimeout.Token;

        JsonElement root = await GetSessionAsync(rootSessionID, token).ConfigureAwait(false);
        if (HasNonNullProperty(root, "parentID"))
            throw new InvalidDataException("The requested session is not a root session.");

        var scope = new HashSet<string>(StringComparer.Ordinal) { rootSessionID };
        var pending = new Queue<(string SessionID, int Depth)>();
        pending.Enqueue((rootSessionID, 0));
        int descendantCount = 0;
        while (pending.Count > 0)
        {
            (string parentID, int depth) = pending.Dequeue();
            JsonElement children = await GetJsonAsync(BuildSessionEndpoint(parentID, "/children"), token).ConfigureAwait(false);
            if (children.ValueKind != JsonValueKind.Array)
                throw new InvalidDataException("OpenCode returned a malformed session children list.");
            if (children.GetArrayLength() > 0 && depth >= MaximumSessionScopeDepth)
                throw new InvalidDataException("The session tree exceeds the bounded depth.");

            foreach (JsonElement child in children.EnumerateArray())
            {
                if (child.ValueKind != JsonValueKind.Object)
                    throw new InvalidDataException("OpenCode returned a malformed child session.");
                string? childID = GetString(child, "id");
                if (!IsValidSessionID(childID))
                    throw new InvalidDataException("OpenCode returned a malformed child session ID.");
                if (!string.Equals(GetString(child, "parentID"), parentID, StringComparison.Ordinal))
                    throw new InvalidDataException("A child session did not match its direct parent.");
                string? childDirectory = GetString(child, "directory");
                if (string.IsNullOrWhiteSpace(childDirectory) || !DirectoriesEqual(childDirectory, _directory))
                    throw new InvalidDataException("OpenCode returned a child session outside the selected project directory.");
                if (!scope.Add(childID!))
                    throw new InvalidDataException("The OpenCode session tree contains a duplicate or cyclic child ID.");
                descendantCount++;
                if (descendantCount > MaximumSessionScopeDescendants)
                    throw new InvalidDataException("The session tree exceeds the bounded session count.");
                pending.Enqueue((childID!, depth + 1));
            }
        }
        return scope;
    }

    public Task<JsonElement> ReadMessagesAsync(string sessionID, CancellationToken cancellationToken = default) =>
        GetJsonAsync(BuildSessionEndpoint(sessionID, "/message"), cancellationToken);

    public Task<JsonElement> ReadStatusAsync(CancellationToken cancellationToken = default) => GetJsonAsync(BuildEndpoint("/session/status"), cancellationToken);
    public Task<JsonElement> ReadPermissionsAsync(CancellationToken cancellationToken = default) => GetJsonAsync(BuildEndpoint("/permission"), cancellationToken);
    public Task<JsonElement> ReadQuestionsAsync(CancellationToken cancellationToken = default) => GetJsonAsync(BuildEndpoint("/question"), cancellationToken);
    public Task<JsonElement> ReadProvidersAsync(CancellationToken cancellationToken = default) => GetJsonAsync(BuildEndpoint("/provider"), cancellationToken);
    public Task<JsonElement> ReadAgentsAsync(CancellationToken cancellationToken = default) => GetJsonAsync(BuildEndpoint("/agent"), cancellationToken);

    public Task SendAsync(string sessionID, string text, string messageID, string? model = null, string? agent = null, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sessionID);
        ArgumentNullException.ThrowIfNull(text);
        ArgumentException.ThrowIfNullOrWhiteSpace(messageID);
        if (text.Length > 256 * 1024) throw new ArgumentException("The message exceeds the bounded request size.", nameof(text));
        object? modelValue = null;
        if (!string.IsNullOrWhiteSpace(model))
        {
            int separator = model.IndexOf('/');
            if (separator <= 0 || separator == model.Length - 1)
                throw new ArgumentException("A model must use the providerID/modelID form.", nameof(model));
            modelValue = new { providerID = model[..separator], modelID = model[(separator + 1)..] };
        }
        var body = new Dictionary<string, object?>
        {
            ["messageID"] = messageID,
            ["parts"] = new[] { new { type = "text", text, metadata = new { terminalnotes = new { requestID = messageID } } } }
        };
        if (modelValue is not null) body["model"] = modelValue;
        if (!string.IsNullOrWhiteSpace(agent)) body["agent"] = agent;
        return SendNoContentAsync(HttpMethod.Post, BuildSessionEndpoint(sessionID, "/prompt_async"), body, cancellationToken);
    }

    public Task AbortAsync(string sessionID, CancellationToken cancellationToken = default) =>
        SendNoContentAsync(HttpMethod.Post, BuildSessionEndpoint(sessionID, "/abort"), new { }, cancellationToken);

    // OpenCode reads skills (and config) once per instance; resetting the instance makes the next request read them again.
    // It is how OpenCode itself applies a config change: sessions stay stored and an attached TUI reloads on its own.
    public Task DisposeInstanceAsync(CancellationToken cancellationToken = default) =>
        SendNoContentAsync(HttpMethod.Post, BuildEndpoint("/instance/dispose"), new { }, cancellationToken);

    public Task AnswerPermissionAsync(string requestID, string reply, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(requestID);
        if (reply is not ("once" or "always" or "reject")) throw new ArgumentOutOfRangeException(nameof(reply), "Permission reply must be once, always, or reject.");
        return SendNoContentAsync(HttpMethod.Post, BuildEndpoint("/permission/" + Uri.EscapeDataString(requestID) + "/reply"), new { reply }, cancellationToken);
    }

    public Task ReplyQuestionAsync(string requestID, string[][] answers, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(requestID);
        ArgumentNullException.ThrowIfNull(answers);
        return SendNoContentAsync(HttpMethod.Post, BuildEndpoint("/question/" + Uri.EscapeDataString(requestID) + "/reply"), new { answers }, cancellationToken);
    }

    public Task RejectQuestionAsync(string requestID, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(requestID);
        return SendNoContentAsync(HttpMethod.Post, BuildEndpoint("/question/" + Uri.EscapeDataString(requestID) + "/reject"), new { }, cancellationToken);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        if (_ownsClient) _httpClient.Dispose();
    }

    private async Task<JsonElement> GetJsonAsync(Uri uri, CancellationToken cancellationToken)
    {
        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(RequestTimeout);
        using var request = new HttpRequestMessage(HttpMethod.Get, uri);
        using HttpResponseMessage response = await SendAsync(request, timeout.Token).ConfigureAwait(false);
        await EnsureSuccessAsync(response, timeout.Token).ConfigureAwait(false);
        byte[] bytes = await ReadBoundedAsync(response, timeout.Token).ConfigureAwait(false);
        using JsonDocument document = JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 64, CommentHandling = JsonCommentHandling.Disallow });
        return document.RootElement.Clone();
    }

    private async Task<JsonElement> SendJsonAsync(HttpMethod method, Uri uri, object body, CancellationToken cancellationToken)
    {
        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(RequestTimeout);
        using HttpRequestMessage request = CreateJsonRequest(method, uri, body);
        using HttpResponseMessage response = await SendAsync(request, timeout.Token).ConfigureAwait(false);
        await EnsureSuccessAsync(response, timeout.Token).ConfigureAwait(false);
        byte[] bytes = await ReadBoundedAsync(response, timeout.Token).ConfigureAwait(false);
        using JsonDocument document = JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 64, CommentHandling = JsonCommentHandling.Disallow });
        return document.RootElement.Clone();
    }

    private async Task SendNoContentAsync(HttpMethod method, Uri uri, object body, CancellationToken cancellationToken)
    {
        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        timeout.CancelAfter(RequestTimeout);
        using HttpRequestMessage request = CreateJsonRequest(method, uri, body);
        using HttpResponseMessage response = await SendAsync(request, timeout.Token).ConfigureAwait(false);
        await EnsureSuccessAsync(response, timeout.Token).ConfigureAwait(false);
        _ = await ReadBoundedAsync(response, timeout.Token).ConfigureAwait(false);
    }

    private HttpRequestMessage CreateJsonRequest(HttpMethod method, Uri uri, object body)
    {
        byte[] payload = JsonSerializer.SerializeToUtf8Bytes(body);
        if (payload.Length > MaximumRequestBytes) throw new InvalidDataException("The OpenCode request exceeds the bounded payload size.");
        return new HttpRequestMessage(method, uri)
        {
            Content = new ByteArrayContent(payload) { Headers = { ContentType = new MediaTypeHeaderValue("application/json") } }
        };
    }

    private async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (request.RequestUri is null || !IsAllowedUri(request.RequestUri))
            throw new InvalidOperationException("An OpenCode request must stay on the configured loopback server.");
        if (_authorization is not null) request.Headers.Authorization = _authorization;
        HttpResponseMessage response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
        if (response.RequestMessage?.RequestUri is not Uri finalUri || !IsAllowedUri(finalUri))
        {
            response.Dispose();
            throw new InvalidOperationException("OpenCode redirected a loopback request to another address.");
        }
        return response;
    }

    private static async Task EnsureSuccessAsync(HttpResponseMessage response, CancellationToken cancellationToken)
    {
        if (response.IsSuccessStatusCode) return;
        _ = await ReadBoundedAsync(response, cancellationToken).ConfigureAwait(false);
        throw new HttpRequestException($"OpenCode returned HTTP {(int)response.StatusCode}.", null, response.StatusCode);
    }

    private static async Task<byte[]> ReadBoundedAsync(HttpResponseMessage response, CancellationToken cancellationToken)
    {
        if (response.Content.Headers.ContentLength is long length && length > MaximumResponseBytes)
            throw new InvalidDataException("OpenCode returned a response larger than the allowed limit.");
        await using Stream stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        using var output = new MemoryStream();
        byte[] buffer = new byte[16 * 1024];
        while (true)
        {
            int read = await stream.ReadAsync(buffer.AsMemory(), cancellationToken).ConfigureAwait(false);
            if (read == 0) break;
            if (output.Length + read > MaximumResponseBytes) throw new InvalidDataException("OpenCode returned a response larger than the allowed limit.");
            output.Write(buffer, 0, read);
        }
        return output.ToArray();
    }

    private Uri BuildEndpoint(string path)
    {
        string prefix = _endpoint.GetLeftPart(UriPartial.Authority) + _endpoint.AbsolutePath.TrimEnd('/');
        return new Uri(prefix + path + "?directory=" + Uri.EscapeDataString(_directory), UriKind.Absolute);
    }

    private Uri BuildSessionEndpoint(string sessionID, string suffix = "") =>
        BuildEndpoint("/session/" + Uri.EscapeDataString(sessionID) + suffix);

    private bool IsAllowedUri(Uri uri) => uri.IsAbsoluteUri && uri.IsLoopback && uri.Scheme == _endpoint.Scheme &&
        string.Equals(uri.Host, _endpoint.Host, StringComparison.OrdinalIgnoreCase) && uri.Port == _endpoint.Port;

    private static string? GetString(JsonElement value, string property) =>
        value.ValueKind == JsonValueKind.Object && value.TryGetProperty(property, out JsonElement item) && item.ValueKind == JsonValueKind.String ? item.GetString() : null;

    private static bool HasNonNullProperty(JsonElement value, string property) =>
        value.ValueKind == JsonValueKind.Object && value.TryGetProperty(property, out JsonElement item) && item.ValueKind != JsonValueKind.Null;

    private static bool IsValidSessionID(string? sessionID) => sessionID is not null && sessionID.Length is >= 4 and <= 128 &&
        sessionID.All(character => char.IsAsciiLetterOrDigit(character) || character is '_' or '-');

    private static bool DirectoriesEqual(string first, string second)
    {
        try { return string.Equals(Path.TrimEndingDirectorySeparator(Path.GetFullPath(first)), Path.TrimEndingDirectorySeparator(Path.GetFullPath(second)), StringComparison.OrdinalIgnoreCase); }
        catch (Exception ex) when (ex is ArgumentException or IOException or UnauthorizedAccessException or NotSupportedException) { return false; }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODECONVERSATIONCLIENT_PLANMAKER_CS
#region Services/OpenCodeConversationClient.PlanMaker.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Net.Http;
using global::System.Text.Json;


public sealed partial class OpenCodeConversationClient
{
    internal async Task<string?> ReadPlanMakerModelAsync(string sourceSessionId, JsonElement agents, CancellationToken token)
    {
        JsonElement messages = await ReadMessagesAsync(sourceSessionId, token).ConfigureAwait(false);
        if (messages.ValueKind == JsonValueKind.Array)
        {
            JsonElement[] sourceMessages = messages.EnumerateArray()
                .Where(message => message.ValueKind == JsonValueKind.Object && message.TryGetProperty("info", out var info) &&
                    GetString(info, "sessionID") == sourceSessionId)
                .Reverse().ToArray();
            foreach (JsonElement message in sourceMessages)
            {
                JsonElement info = message.GetProperty("info");
                if (GetString(info, "role") != "user") continue;
                string? model = ReadExactPlanMakerModel(info.TryGetProperty("model", out var nested) ? nested : info);
                if (model is not null) return model;
            }
        }
        return await ReadConfiguredPlanMakerModelAsync(agents, token).ConfigureAwait(false);
    }

    // The model PlanMaker uses when no earlier request names one; the plan cleanup uses it too.
    internal async Task<string?> ReadConfiguredPlanMakerModelAsync(JsonElement agents, CancellationToken token)
    {
        // Read only explicit configuration. Provider display names and catalog defaults
        // cannot establish the user's selected model and must never become request IDs.
        try
        {
            JsonElement config = await GetJsonAsync(BuildEndpoint("/config"), token).ConfigureAwait(false);
            if (config.ValueKind == JsonValueKind.Object && config.TryGetProperty("model", out var configured) &&
                configured.ValueKind is not (JsonValueKind.Null or JsonValueKind.Undefined))
            {
                if (ReadExactPlanMakerModel(configured) is { } model) return model;
                throw new InvalidOperationException("OpenCode에 설정된 모델 ID가 provider/model 형식이 아닙니다. 모델 설정을 확인한 뒤 다시 시도하세요.");
            }
        }
        catch (HttpRequestException) { }

        if (agents.ValueKind == JsonValueKind.Array)
        {
            foreach (JsonElement agent in agents.EnumerateArray())
                if (GetString(agent, "name") == "plan" && agent.TryGetProperty("model", out var configured) &&
                    configured.ValueKind is not (JsonValueKind.Null or JsonValueKind.Undefined))
                {
                    if (ReadExactPlanMakerModel(configured) is { } model) return model;
                    throw new InvalidOperationException("OpenCode의 plan 에이전트에 설정된 모델 ID가 provider/model 형식이 아닙니다. 모델 설정을 확인한 뒤 다시 시도하세요.");
                }
        }
        // Omit prompt.model when no model is explicit so OpenCode can select its native default.
        return null;
    }

    internal static string? ReadPlanMakerRequestModel(JsonElement messages, string sessionId, string messageId)
    {
        if (messages.ValueKind != JsonValueKind.Array) return null;
        foreach (JsonElement message in messages.EnumerateArray())
        {
            if (message.ValueKind != JsonValueKind.Object || !message.TryGetProperty("info", out var info) ||
                info.ValueKind != JsonValueKind.Object || GetString(info, "id") != messageId ||
                GetString(info, "sessionID") != sessionId || GetString(info, "role") != "user") continue;
            return info.TryGetProperty("model", out var model) ? ReadExactPlanMakerModel(model) : null;
        }
        return null;
    }

    private static string? ReadExactPlanMakerModel(JsonElement value)
    {
        if (value.ValueKind == JsonValueKind.Object)
        {
            string? provider = GetString(value, "providerID"), model = GetString(value, "modelID");
            return !string.IsNullOrWhiteSpace(provider) && !provider.Contains('/') && !string.IsNullOrWhiteSpace(model)
                ? provider + "/" + model : null;
        }
        if (value.ValueKind != JsonValueKind.String || value.GetString() is not { } reference) return null;
        int separator = reference.IndexOf('/');
        return separator > 0 && separator < reference.Length - 1 &&
            !string.IsNullOrWhiteSpace(reference[..separator]) && !string.IsNullOrWhiteSpace(reference[(separator + 1)..])
            ? reference : null;
    }

    internal async Task<IReadOnlyDictionary<string, bool>> ReadPlanMakerToolsAsync(CancellationToken token)
    {
        JsonElement tools = await GetJsonAsync(BuildEndpoint("/experimental/tool/ids"), token);
        if (tools.ValueKind != JsonValueKind.Array)
            throw new InvalidDataException("플랜 생성에 필요한 OpenCode 도구 목록을 확인하지 못했습니다.");
        var restricted = new Dictionary<string, bool>(StringComparer.Ordinal) { ["*"] = false };
        foreach (JsonElement tool in tools.EnumerateArray())
        {
            if (tool.ValueKind != JsonValueKind.String || tool.GetString() is not { Length: > 0 } name)
                throw new InvalidDataException("OpenCode 도구 목록 형식이 호환되지 않습니다.");
            restricted[name] = name == "question";
        }
        if (!restricted.ContainsKey("question"))
            throw new InvalidDataException("이 OpenCode 버전은 플랜 생성용 질문 도구를 제공하지 않습니다.");
        return restricted;
    }

    internal Task<JsonElement> CreatePlanMakerSessionAsync(CancellationToken token) =>
        SendJsonAsync(HttpMethod.Post, BuildEndpoint("/session"), new
        {
            title = "Terminal Notes · 플랜 만들기",
            permission = new[]
            {
                new { permission = "*", pattern = "*", action = "deny" },
                new { permission = "question", pattern = "*", action = "allow" }
            }
        }, token);

    internal static void VerifyPlanMakerPermissions(JsonElement session)
    {
        if (!session.TryGetProperty("permission", out var rules) || rules.ValueKind != JsonValueKind.Array || rules.GetArrayLength() != 2 ||
            !IsRule(rules[0], "*", "deny") || !IsRule(rules[1], "question", "allow"))
            throw new InvalidDataException("OpenCode가 플랜 대화의 질문 전용 권한을 보존하지 않았습니다. 이 서버에서는 안전하게 플랜을 생성할 수 없습니다.");
    }

    private static bool IsRule(JsonElement rule, string permission, string action) =>
        rule.TryGetProperty("permission", out var name) && name.GetString() == permission &&
        rule.TryGetProperty("pattern", out var pattern) && pattern.GetString() == "*" &&
        rule.TryGetProperty("action", out var mode) && mode.GetString() == action;

    // tools is intentionally omitted: legacy servers can overwrite session permissions from that map.
    internal Task SendPlanMakerAsync(string sessionId, string prompt, string messageId, CancellationToken token, string? model = null) =>
        SendAsync(sessionId, prompt, messageId, model, "plan", token);

#if TN_WPF || TN_SOURCE_SERVICES_PLANMAKERWORKFLOW_CS
    // One model request, no transport/model retries, on the existing client/server.
    // The native question remains untouched until the caller revalidates ownership.
    internal async Task<(string? Label, string Reason)> RepairPlanMakerRecommendationAsync(JsonElement question, string? model,
        Func<CancellationToken, Task<bool>> stillCurrent, CancellationToken token, TimeSpan? timeout = null)
    {
        using var bounded = CancellationTokenSource.CreateLinkedTokenSource(token);
        // Self-hosted models can take well over 30 seconds even for this short answer.
        bounded.CancelAfter(timeout ?? TimeSpan.FromSeconds(90));
        string? helper = null;
        string message = "msg_" + Guid.NewGuid().ToString("N");
        async Task VerifyAsync()
        {
            bounded.Token.ThrowIfCancellationRequested();
            if (!await stillCurrent(bounded.Token).ConfigureAwait(false))
                throw new OperationCanceledException("The pending recommendation or its input ownership changed.", bounded.Token);
        }
        try
        {
            await VerifyAsync().ConfigureAwait(false);
            JsonElement created = await SendJsonAsync(HttpMethod.Post, BuildEndpoint("/session"), new
            {
                title = "Terminal Notes · PlanMaker recommendation repair",
                permission = new[] { new { permission = "*", pattern = "*", action = "deny" } }
            }, bounded.Token).ConfigureAwait(false);
            helper = GetString(created, "id") ?? throw new InvalidDataException("The recommendation helper session has no identity.");
            VerifyHelperPermissions(created);
            await VerifyAsync().ConfigureAwait(false);
            await SendPlanMakerAsync(helper, PlanMakerWorkflow.BuildRecommendationRepairPrompt(question), message, bounded.Token, model).ConfigureAwait(false);
            while (true)
            {
                await VerifyAsync().ConfigureAwait(false);
                VerifyHelperPermissions(await GetSessionAsync(helper, bounded.Token).ConfigureAwait(false));
                JsonElement permissions = await ReadPermissionsAsync(bounded.Token).ConfigureAwait(false);
                JsonElement questions = await ReadQuestionsAsync(bounded.Token).ConfigureAwait(false);
                if (permissions.ValueKind != JsonValueKind.Array || questions.ValueKind != JsonValueKind.Array ||
                    permissions.EnumerateArray().Concat(questions.EnumerateArray()).Any(item => GetString(item, "sessionID") == helper))
                    throw new InvalidDataException("추천 확인 중 모델이 질문이나 승인을 요청했습니다.");
                JsonElement messages = await ReadMessagesAsync(helper, bounded.Token).ConfigureAwait(false);
                if (messages.ValueKind != JsonValueKind.Array) throw new InvalidDataException("추천 확인 응답 형식이 올바르지 않습니다.");
                JsonElement latest = default;
                foreach (JsonElement item in messages.EnumerateArray())
                {
                    if (!item.TryGetProperty("info", out var info) || GetString(info, "role") != "assistant") continue;
                    if (GetString(info, "sessionID") != helper || GetString(info, "parentID") != message)
                        throw new InvalidDataException("추천 확인 응답이 요청과 연결되지 않았습니다.");
                    latest = item;
                }
                if (latest.ValueKind != JsonValueKind.Undefined)
                {
                    JsonElement info = latest.GetProperty("info");
                    if (info.TryGetProperty("error", out var error) && error.ValueKind is not (JsonValueKind.Null or JsonValueKind.Undefined))
                        throw new InvalidDataException("설정된 모델이 추천을 고르지 못했습니다.");
                    if (latest.TryGetProperty("parts", out var parts) && parts.ValueKind == JsonValueKind.Array)
                    {
                        if (parts.EnumerateArray().Any(part => GetString(part, "type") == "tool"))
                            throw new InvalidDataException("추천 확인 중 모델이 도구를 쓰려고 했습니다.");
                        if (GetString(info, "finish") == "stop" && info.TryGetProperty("time", out var time) &&
                            time.TryGetProperty("completed", out var completed) && completed.ValueKind == JsonValueKind.Number)
                        {
                            JsonElement statuses = await ReadStatusAsync(bounded.Token).ConfigureAwait(false);
                            if (statuses.ValueKind == JsonValueKind.Object && (!statuses.TryGetProperty(helper, out var status) || GetString(status, "type") == "idle"))
                            {
                                await VerifyAsync().ConfigureAwait(false);
                                return PlanMakerWorkflow.ReadRepairedRecommendation(question, string.Concat(parts.EnumerateArray()
                                    .Where(part => GetString(part, "type") == "text").Select(part => GetString(part, "text"))));
                            }
                        }
                    }
                }
                await Task.Delay(150, bounded.Token).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException exception) when (!token.IsCancellationRequested && bounded.IsCancellationRequested)
        { throw new IOException("추천 확인 시간이 초과되었습니다.", exception); }
        finally
        {
            if (helper is not null)
            {
                using var cleanup = new CancellationTokenSource(TimeSpan.FromSeconds(3));
                try { await AbortAsync(helper, cleanup.Token).ConfigureAwait(false); }
                catch (Exception exception) { System.Diagnostics.Trace.WriteLine(exception); }
            }
        }
    }

    // Tools that could change files, run commands, reach the network, start agents or ask
    // questions. A blanket "*" deny would also strip the request of OpenCode's tool list,
    // which OpenCode's free tier rejects as "not from within OpenCode".
    private static readonly string[] SideEffectTools = ["edit", "bash", "webfetch", "websearch", "codesearch", "task", "question", "external_directory"];

    // One bounded request in a fresh side-effect-free session; returns the assistant's text.
    // A long plan takes a long time to rewrite. The request fails only when the session is neither
    // working nor growing its answer for `idleLimit`; `timeout` is just an overall safety cap.
    internal async Task<string> CompleteToolLessPromptAsync(string title, string prompt, string? model,
        CancellationToken token, TimeSpan timeout, TimeSpan? idleLimit = null, Action<int>? progress = null)
    {
        using var bounded = CancellationTokenSource.CreateLinkedTokenSource(token);
        bounded.CancelAfter(timeout);
        TimeSpan idle = idleLimit ?? timeout;
        DateTimeOffset lastProgressAt = DateTimeOffset.UtcNow;
        long lastProgress = -1;
        bool stalled = false;
        string? helper = null;
        string message = "msg_" + Guid.NewGuid().ToString("N");
        try
        {
            JsonElement created = await SendJsonAsync(HttpMethod.Post, BuildEndpoint("/session"), new
            {
                title,
                permission = SideEffectTools.Select(tool => new { permission = tool, pattern = "*", action = "deny" }).ToArray()
            }, bounded.Token).ConfigureAwait(false);
            helper = GetString(created, "id") ?? throw new InvalidDataException("정리 세션을 만들지 못했습니다.");
            VerifySideEffectFreePermissions(created);
            await SendPlanMakerAsync(helper, prompt, message, bounded.Token, model).ConfigureAwait(false);
            while (true)
            {
                bounded.Token.ThrowIfCancellationRequested();
                VerifySideEffectFreePermissions(await GetSessionAsync(helper, bounded.Token).ConfigureAwait(false));
                JsonElement permissions = await ReadPermissionsAsync(bounded.Token).ConfigureAwait(false);
                JsonElement questions = await ReadQuestionsAsync(bounded.Token).ConfigureAwait(false);
                if (permissions.ValueKind != JsonValueKind.Array || questions.ValueKind != JsonValueKind.Array ||
                    permissions.EnumerateArray().Concat(questions.EnumerateArray()).Any(item => GetString(item, "sessionID") == helper))
                    throw new InvalidDataException("모델이 정리 대신 질문이나 승인을 요청했습니다.");
                JsonElement messages = await ReadMessagesAsync(helper, bounded.Token).ConfigureAwait(false);
                if (messages.ValueKind != JsonValueKind.Array) throw new InvalidDataException("정리 응답 형식이 올바르지 않습니다.");
                JsonElement latest = default;
                foreach (JsonElement item in messages.EnumerateArray())
                {
                    if (!item.TryGetProperty("info", out var info) || GetString(info, "role") != "assistant") continue;
                    if (GetString(info, "sessionID") != helper || GetString(info, "parentID") != message)
                        throw new InvalidDataException("정리 응답이 요청과 연결되지 않았습니다.");
                    latest = item;
                }
                if (latest.ValueKind != JsonValueKind.Undefined)
                {
                    JsonElement info = latest.GetProperty("info");
                    if (info.TryGetProperty("error", out var error) && error.ValueKind is not (JsonValueKind.Null or JsonValueKind.Undefined))
                    {
                        string? detail = error.ValueKind == JsonValueKind.Object && error.TryGetProperty("data", out var data) &&
                            data.ValueKind == JsonValueKind.Object ? GetString(data, "message") : null;
                        detail ??= error.ValueKind == JsonValueKind.Object ? GetString(error, "name") : error.ToString();
                        throw new InvalidDataException("설정된 모델이 정리 요청을 처리하지 못했습니다" +
                            (string.IsNullOrWhiteSpace(detail) ? "." : " · " + (detail.Length > 300 ? detail[..300] + "…" : detail)));
                    }
                    if (latest.TryGetProperty("parts", out var parts) && parts.ValueKind == JsonValueKind.Array)
                    {
                        // Any growth of text, reasoning or steps is progress.
                        long received = parts.EnumerateArray().Sum(part => (long)(GetString(part, "text")?.Length ?? 0) + 1);
                        if (received != lastProgress)
                        {
                            lastProgress = received;
                            lastProgressAt = DateTimeOffset.UtcNow;
                            progress?.Invoke(parts.EnumerateArray().Where(part => GetString(part, "type") == "text")
                                .Sum(part => GetString(part, "text")?.Length ?? 0));
                        }
                        if (GetString(info, "finish") == "stop" && info.TryGetProperty("time", out var time) &&
                            time.TryGetProperty("completed", out var completed) && completed.ValueKind == JsonValueKind.Number)
                            return string.Concat(parts.EnumerateArray()
                                .Where(part => GetString(part, "type") == "text").Select(part => GetString(part, "text")));
                    }
                }
                // OpenCode publishes the answer only when it is complete, so a long rewrite shows no text
                // for minutes. While the session reports busy the model is still working.
                JsonElement statuses = await ReadStatusAsync(bounded.Token).ConfigureAwait(false);
                if (statuses.ValueKind == JsonValueKind.Object && statuses.TryGetProperty(helper, out var helperStatus) &&
                    GetString(helperStatus, "type") is "busy" or "retry")
                    lastProgressAt = DateTimeOffset.UtcNow;
                if (DateTimeOffset.UtcNow - lastProgressAt > idle)
                {
                    stalled = true;
                    throw new IOException($"모델 응답이 {idle.TotalMinutes:0}분 동안 진행되지 않았습니다.");
                }
                await Task.Delay(250, bounded.Token).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException exception) when (!token.IsCancellationRequested && bounded.IsCancellationRequested && !stalled)
        { throw new IOException($"플랜 정리가 최대 {timeout.TotalMinutes:0}분 안에 끝나지 않았습니다.", exception); }
        finally
        {
            if (helper is not null)
            {
                using var cleanup = new CancellationTokenSource(TimeSpan.FromSeconds(3));
                try { await AbortAsync(helper, cleanup.Token).ConfigureAwait(false); }
                catch (Exception exception) { System.Diagnostics.Trace.WriteLine(exception); }
            }
        }
    }

    private static void VerifySideEffectFreePermissions(JsonElement session)
    {
        if (!session.TryGetProperty("permission", out var rules) || rules.ValueKind != JsonValueKind.Array ||
            SideEffectTools.Any(tool => !rules.EnumerateArray().Any(rule => IsRule(rule, tool, "deny"))) ||
            rules.EnumerateArray().Any(rule => GetString(rule, "action") != "deny"))
            throw new InvalidDataException("정리 세션의 도구 제한이 유지되지 않아 중단했습니다.");
    }

    private static void VerifyHelperPermissions(JsonElement session)
    {
        if (!session.TryGetProperty("permission", out var rules) || rules.ValueKind != JsonValueKind.Array || rules.GetArrayLength() != 1 ||
            !IsRule(rules[0], "*", "deny"))
            throw new InvalidDataException("The recommendation helper did not preserve its no-tool permissions; answer manually.");
    }
#endif
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEFAILURECLASSIFIER_CS
#region Services/OpenCodeFailureClassifier.cs
namespace TerminalNotes.Services
{

/// <summary>Classifies structured native failures without inspecting terminal text or secrets.</summary>
public static class OpenCodeFailureClassifier
{
    public static bool CanRetryAutomatically(RecoverySessionEvidence evidence) =>
        evidence.CurrentErrors.Count > 0 && evidence.CurrentErrors.All(error =>
            error.ParentUserMessageId is not null && error.ParentUserMessageId == evidence.LatestUserMessageId && IsTransient(error));

    public static bool CanRetryManually(RecoverySessionEvidence evidence) =>
        evidence.CurrentErrors.Count > 0 && evidence.CurrentErrors.All(error =>
            error.ParentUserMessageId is not null && error.ParentUserMessageId == evidence.LatestUserMessageId &&
            error.Type is not ("MessageAbortedError" or "ToolExecutionAborted" or "PermissionDeniedError" or "QuestionRejectedError"));

    // Loop runs unattended, so it also retries failures the gateway did not label as busy (사용자: 멈추면 어떻게든 다시
    // 실행해 계속 이어가게). Credentials, permissions, billing, context length and request-shape problems still wait for a
    // person (2026-10-20 지시), as do the user's own stop and refused permissions or questions.
    public static bool CanRetryInLoop(RecoverySessionEvidence evidence) =>
        evidence.CurrentErrors.Count > 0 && evidence.CurrentErrors.All(error =>
            error.ParentUserMessageId is not null && error.ParentUserMessageId == evidence.LatestUserMessageId &&
            (IsTransient(error) || !NeedsPerson(error)));

    private static bool NeedsPerson(RecoveryErrorEvidence error) =>
        error.StatusCode is 401 or 403 || error.HasVerifiedContextOverflow ||
        error.Type is "ProviderAuthError" or "PermissionDeniedError" or "QuestionRejectedError" or "MessageAbortedError" or
            "ToolExecutionAborted" or "ContextOverflowError" ||
        !string.IsNullOrWhiteSpace(error.Message) &&
            NeedsPersonMarkers.Any(marker => error.Message.Contains(marker, StringComparison.OrdinalIgnoreCase));

    public static bool IsContextOverflow(RecoveryErrorEvidence error) =>
        error.StatusCode is not (401 or 403) &&
        (error.Type == "ContextOverflowError" || error.HasVerifiedContextOverflow);

    public static bool CanCompact(RecoverySessionEvidence evidence) =>
        evidence.CurrentErrors.Count > 0 && evidence.CurrentErrors.All(error =>
            error.ParentUserMessageId == evidence.LatestUserMessageId && error.ParentUserMessageId is not null && IsContextOverflow(error));

    private static bool IsTransient(RecoveryErrorEvidence error)
    {
        if (error.StatusCode is 401 or 403 || error.Type is "ProviderAuthError" or "PermissionDeniedError" or "QuestionRejectedError") return false;
        // A provider can decline its own immediate retry of a rate limit while a
        // later scheduled probe remains valid. This never changes credentials/limits.
        if (error.StatusCode is 429 or 503) return true;
        if (error.Type == "APIError" && error.IsRetryable != false && (error.IsRetryable == true ||
                error.StatusCode is 408 or 429 or >= 500))
            return true;
        if (error.Type is "RateLimitError" or "QuotaExceededError")
            return error.IsRetryable == true || error.RetryAfterUtc is not null || error.RetryAfterDelay is not null;
        if (error.Type is "NetworkError" or "ConnectionError" or "TimeoutError") return true;
        // Gateways in front of a shared (self-hosted) model often report overload, request limits and dropped
        // connections only in the message text, under a generic error type or a wrong status/retry flag.
        return error.Type is "APIError" or "UnknownError" or "ProviderError" or "message_error" or "Error" &&
            LooksLikeBusyOrDroppedService(error.Message);
    }

    private static readonly string[] BusyServiceMarkers =
    [
        "rate limit", "ratelimit", "rate_limit", "too many requests", "overload", "over capacity", "at capacity", "capacity exceeded",
        "server is busy", "server busy", "service busy", "is busy", "temporarily unavailable", "service unavailable", "bad gateway",
        "gateway timeout", "timed out", "timeout", "time out", "try again later", "please try again", "econnreset", "econnrefused",
        "etimedout", "socket hang up", "fetch failed", "network error", "connection reset", "connection closed", "connection error",
        "connection refused", "connection lost", "stream ended", "upstream", "terminated", "429", "502", "503", "504", "529",
        "요청이 많", "요청량", "사용량이 많", "사용자가 많", "과부하", "혼잡", "잠시 후", "다시 시도", "일시적", "처리할 수 없",
        "대기열", "시간 초과", "타임아웃", "연결이 끊", "연결 오류", "응답이 없"
    ];

    // Never retried automatically: credentials, permissions, billing and request-shape problems need a person.
    private static readonly string[] NeedsPersonMarkers =
    [
        "unauthorized", "api key", "apikey", "authentication", "forbidden", "permission denied", "insufficient_quota",
        "billing", "payment", "credit", "context length", "context window", "maximum context", "too long", "token limit",
        "invalid request", "model not found", "does not exist", "인증", "권한", "결제", "토큰 한도", "컨텍스트"
    ];

    internal static bool LooksLikeBusyOrDroppedService(string? message)
    {
        if (string.IsNullOrWhiteSpace(message)) return false;
        return !NeedsPersonMarkers.Any(marker => message.Contains(marker, StringComparison.OrdinalIgnoreCase)) &&
            BusyServiceMarkers.Any(marker => message.Contains(marker, StringComparison.OrdinalIgnoreCase));
    }

    public static TimeSpan RetryDelay(int attempt) => TimeSpan.FromMinutes(attempt switch { <= 1 => 1, 2 => 3, _ => 10 });

    public static DateTimeOffset RetryAt(RecoverySessionEvidence evidence, DateTimeOffset now, int attempt)
    {
        DateTimeOffset result = now + RetryDelay(attempt);
        DateTimeOffset? provider = ProviderRetryAt(evidence, now);
        return provider is not null && provider > result ? provider.Value : result;
    }

    public static DateTimeOffset? ProviderRetryAt(RecoverySessionEvidence evidence, DateTimeOffset now)
    {
        DateTimeOffset? result = null;
        foreach (var error in evidence.CurrentErrors)
        {
            if (error.RetryAfterUtc is { } deadline && (result is null || deadline > result)) result = deadline;
            if (error.RetryAfterDelay is { } delay)
            {
                DateTimeOffset delayed = delay > DateTimeOffset.MaxValue - now ? DateTimeOffset.MaxValue : now + delay;
                if (result is null || delayed > result) result = delayed;
            }
        }
        return result;
    }

    public static string DisplayReason(RecoverySessionEvidence evidence) =>
        evidence.CurrentErrors.Any(error => error.StatusCode is 401 or 403 || error.Type == "ProviderAuthError")
            ? "인증 설정 확인 후 수동 재시도"
            : evidence.CurrentErrors.Any(error => error.StatusCode == 503) ? "서버 과부하·응답 중단 · 자동 재시도 대기"
            : evidence.CurrentErrors.Any(error => error.StatusCode == 429) ? "요청 제한 · 자동 재시도 대기"
            : evidence.CurrentErrors.Any(error => LooksLikeBusyOrDroppedService(error.Message)) ? "서비스 혼잡·연결 끊김 · 자동 재시도 대기"
            : CanRetryAutomatically(evidence) ? "일시 연결·서버 오류"
            : "오류 확인 후 수동 재시도";
}

/// <summary>A confirmed locally submitted request retained across an owned host exit.</summary>
public sealed record OpenCodeErrorRestart(
    string SessionId, string UserMessageId, string PlanPath, string PlanHash,
    string Prompt, string OriginalInstruction, Func<bool> CanRestart)
{
    public bool ReconcileOnly { get; init; }
    public OpenCodeContextRecoverySnapshot? ContextRecovery { get; init; }
    public bool AutomaticRetryEnabled { get; init; }
    public int RetryAttempt { get; init; }
    public DateTimeOffset? NotBeforeUtc { get; init; }
    public bool RequiresContinuousImprovement { get; init; }
}

public sealed record OpenCodeContextRecoverySnapshot(
    string RequestId, string ExpectedUserMessageId, RecoveryNativeMessage Source,
    RecoveryModelSelection? SummaryModel, string? MarkerId, bool NativeAuto, bool Dispatched,
    bool SummaryCompleted, bool AmbiguousReplay, string? ErrorEvidence,
    DateTimeOffset? RetryAt, DateTimeOffset? ProviderRetryAt, int Attempts, bool WorkConfirmed);

public enum OpenCodeRestartOutcome { Succeeded, RetryLater, Paused }
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEHEADLESSHOST_CS
#region Services/OpenCodeHeadlessHost.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Diagnostics;
using global::System.Net;
using global::System.Net.Http;
using global::System.Net.Http.Headers;
using global::System.Text;
using global::System.Text.Json;
using global::System.Text.Json.Nodes;


/// <summary>Owns one hidden, loopback-only OpenCode HTTP server process.</summary>
public sealed class OpenCodeHeadlessHost : IDisposable
{
    private static readonly TimeSpan StartupTimeout = TimeSpan.FromSeconds(20);
    private static readonly TimeSpan HealthRequestTimeout = TimeSpan.FromSeconds(1);
    private readonly object _gate = new();
    private Process? _process;
    private OwnedWindowsProcess? _ownedProcess;
    private bool _starting;
    private bool _disposed;
    private int? _adopt;

    public OpenCodeHeadlessHost(Uri endpoint)
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        if (!endpoint.IsAbsoluteUri || endpoint.Scheme != Uri.UriSchemeHttp || !endpoint.IsLoopback ||
            !string.IsNullOrEmpty(endpoint.UserInfo) || !string.IsNullOrEmpty(endpoint.Query) ||
            !string.IsNullOrEmpty(endpoint.Fragment))
            throw new ArgumentException("The OpenCode endpoint must be an absolute loopback HTTP URI without credentials, query, or fragment.", nameof(endpoint));
        Endpoint = new Uri(endpoint.GetLeftPart(UriPartial.Authority).TrimEnd('/') + "/", UriKind.Absolute);
    }

    public Uri Endpoint { get; private set; }
    public bool IsRunning => _process is { HasExited: false };
    public uint? ProcessId => _process is { HasExited: false } process ? unchecked((uint)process.Id) : null;
    public int? ExitCode => _process is { HasExited: true } process ? process.ExitCode : null;
    public event Action<int>? Exited;

    /// <summary>The next start takes this running server (kept after the app closed, see KeptServers) instead of launching one.</summary>
    internal void AdoptOnStart(int processId) => _adopt = processId;

    /// <summary>Lets the running server outlive the app: no longer stopped with the app or by <see cref="Dispose"/>. Its process id,
    /// or null when there is none the app launched.</summary>
    internal int? Detach()
    {
        OwnedWindowsProcess? owner;
        Process? process;
        lock (_gate)
        {
            owner = _ownedProcess;
            process = _process;
            if (process is not { HasExited: false }) return null;
            _process = null;
            _ownedProcess = null;
        }
        if (owner is null)
        {
            // A server taken back from an earlier run is in no job of this app: it is only let go.
            process.Exited -= OnProcessExited;
            int id = process.Id;
            process.Dispose();
            return id;
        }
        try { return owner.Release(); }
        catch (Exception exception) when (exception is InvalidOperationException or System.ComponentModel.Win32Exception) { return null; }
    }

    public Task StartAsync(string directory, string? configContent, CancellationToken cancellationToken = default) =>
        StartAsync(directory, configContent, autoMode: false, cancellationToken: cancellationToken);

    public async Task StartAsync(string directory, string? configContent, bool autoMode, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(directory);
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (!OperatingSystem.IsWindows()) throw new PlatformNotSupportedException("The headless OpenCode host currently supports Windows only.");
        string workingDirectory = Path.GetFullPath(directory);
        if (!Directory.Exists(workingDirectory)) throw new DirectoryNotFoundException("The selected project directory does not exist.");
        Process? previous;
        OwnedWindowsProcess? previousOwner;
        lock (_gate)
        {
            if (_starting || _process is { HasExited: false }) throw new InvalidOperationException("The OpenCode headless server is already starting or running.");
            previous = _process;
            previousOwner = _ownedProcess;
            _process = null;
            _ownedProcess = null;
            _starting = true;
        }
        int port = Endpoint.Port;
        Process? process = null;
        OwnedWindowsProcess? owner = null;
        try
        {
            try { previousOwner?.Dispose(); }
            finally { previous?.Dispose(); }
            string? effectiveConfig = configContent;
            if (autoMode)
                effectiveConfig = MergeAutoPermission(configContent ?? Environment.GetEnvironmentVariable("OPENCODE_CONFIG_CONTENT"));

            int? adoptId = _adopt;
            _adopt = null;
            if (adoptId is int adopted)
            {
                // The kept server: watched like one the app launched; stopped like one when the terminal closes.
                process = Process.GetProcessById(adopted);
                process.EnableRaisingEvents = true;
                process.Exited += OnProcessExited;
                if (process.HasExited) throw new InvalidOperationException("The kept OpenCode server already exited.");
            }
            else
            {
                AutoInstallDetectionResult command = AutoInstall.RequireNative(
                    await new OpenCodeInstallationService().CheckAsync(cancellationToken).ConfigureAwait(false));
                if (!command.IsInstalled || string.IsNullOrWhiteSpace(command.Path))
                    throw new InvalidOperationException("OpenCode를 시작할 수 없습니다 · " + command.Message);
                ProcessStartInfo startInfo = CreateStartInfo(command.Path, workingDirectory, port, effectiveConfig);
                // Its output is not read: NUL, so a server kept after the app closes never writes into a closed pipe.
                owner = OwnedWindowsProcess.Start(startInfo, exited: OnProcessExited, quietOutput: true);
                process = owner.Process;
            }

            lock (_gate)
            {
                ObjectDisposedException.ThrowIf(_disposed, this);
                _process = process;
                _ownedProcess = owner;
                _starting = false;
            }
            process = null;
            owner = null;

            Uri endpoint = new($"http://127.0.0.1:{port}/");
            using var client = CreateHealthClient();
            using var startup = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            startup.CancelAfter(StartupTimeout);
            while (!startup.IsCancellationRequested)
            {
                Process? active;
                lock (_gate) active = _process;
                if (active is null || active.HasExited)
                    throw new InvalidOperationException("The OpenCode server exited before becoming ready.");
                try
                {
                    using var requestTimeout = CancellationTokenSource.CreateLinkedTokenSource(startup.Token);
                    requestTimeout.CancelAfter(HealthRequestTimeout);
                    using HttpResponseMessage response = await client.GetAsync(new Uri(endpoint, "global/health"), requestTimeout.Token).ConfigureAwait(false);
                    if (response.IsSuccessStatusCode)
                    {
                        if (response.RequestMessage?.RequestUri is not Uri finalUri || finalUri != new Uri(endpoint, "global/health"))
                            throw new InvalidOperationException("OpenCode redirected the loopback health request.");
                        await using Stream body = await response.Content.ReadAsStreamAsync(requestTimeout.Token).ConfigureAwait(false);
                        byte[] healthBytes = await ReadBoundedAsync(body, 64 * 1024, requestTimeout.Token).ConfigureAwait(false);
                        using JsonDocument health = JsonDocument.Parse(healthBytes, new JsonDocumentOptions { MaxDepth = 16 });
                        if (health.RootElement.TryGetProperty("healthy", out JsonElement healthy) && healthy.ValueKind == JsonValueKind.True)
                        {
                            Endpoint = endpoint;
                            return;
                        }
                    }
                }
                catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested && !startup.IsCancellationRequested) { }
                catch (OperationCanceledException) when (startup.IsCancellationRequested) { break; }
                catch (HttpRequestException) { }
                catch (JsonException) { }
                try { await Task.Delay(150, startup.Token).ConfigureAwait(false); }
                catch (OperationCanceledException) when (startup.IsCancellationRequested) { break; }
            }
            cancellationToken.ThrowIfCancellationRequested();
            throw new TimeoutException("OpenCode did not become ready within the startup timeout.");
        }
        catch
        {
            try
            {
                if (owner is not null) owner.Dispose();
                else if (process is not null) { try { await StopOwnedProcessAsync(process).ConfigureAwait(false); } finally { process.Dispose(); } }
            }
            finally
            {
                try { await StopAsync().ConfigureAwait(false); }
                finally { lock (_gate) _starting = false; }
            }
            throw;
        }
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        Process? process;
        OwnedWindowsProcess? owner;
        lock (_gate)
        {
            process = _process;
            owner = _ownedProcess;
            _process = null;
            _ownedProcess = null;
        }
        if (process is not null)
        {
            try { if (owner is not null) owner.Dispose(); else StopOwnedProcessAsync(process).GetAwaiter().GetResult(); }
            catch { }
            process.Dispose();
        }
    }

    private async Task StopAsync()
    {
        Process? process;
        OwnedWindowsProcess? owner;
        lock (_gate)
        {
            process = _process;
            owner = _ownedProcess;
            _process = null;
            _ownedProcess = null;
        }
        if (process is not null)
        {
            try
            {
                if (owner is not null) await owner.StopAsync().ConfigureAwait(false);
                else await StopOwnedProcessAsync(process).ConfigureAwait(false);
            }
            finally
            {
                try { owner?.Dispose(); }
                finally { process.Dispose(); }
            }
        }
    }

    private void OnProcessExited(object? sender, EventArgs args)
    {
        if (sender is not Process process) return;
        int code;
        try { code = process.ExitCode; }
        catch (InvalidOperationException) { return; }
        Exited?.Invoke(code);
    }

    // The native opencode.exe itself (AutoInstall.RequireNative); there is no shell around it.
    private static ProcessStartInfo CreateStartInfo(string commandPath, string directory, int port, string? configContent)
    {
        if (!Path.GetExtension(commandPath).Equals(".exe", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException(AutoInstall.NativeMissing(commandPath));
        var info = new ProcessStartInfo
        {
            WorkingDirectory = directory,
            UseShellExecute = false,
            CreateNoWindow = true,
            WindowStyle = ProcessWindowStyle.Hidden,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };
        if (configContent is not null) info.Environment["OPENCODE_CONFIG_CONTENT"] = configContent;
        info.FileName = commandPath;
        info.ArgumentList.Add("serve"); info.ArgumentList.Add("--hostname"); info.ArgumentList.Add("127.0.0.1");
        info.ArgumentList.Add("--port"); info.ArgumentList.Add(port.ToString(System.Globalization.CultureInfo.InvariantCulture));
        return info;
    }

    private static HttpClient CreateHealthClient()
    {
        var client = new HttpClient(new HttpClientHandler { UseProxy = false, AllowAutoRedirect = false }) { Timeout = Timeout.InfiniteTimeSpan };
        if (Environment.GetEnvironmentVariable("OPENCODE_SERVER_PASSWORD") is { Length: > 0 } password)
            client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Basic", Convert.ToBase64String(Encoding.UTF8.GetBytes((Environment.GetEnvironmentVariable("OPENCODE_SERVER_USERNAME") ?? "opencode") + ":" + password)));
        return client;
    }

    private static async Task StopOwnedProcessAsync(Process process)
    {
        try { if (!process.HasExited) process.Kill(entireProcessTree: true); }
        catch (InvalidOperationException) when (process.HasExited) { }
        catch (System.ComponentModel.Win32Exception) when (process.HasExited) { }
        try { await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(5)).ConfigureAwait(false); }
        catch (TimeoutException) { }
    }

    private static async Task<byte[]> ReadBoundedAsync(Stream stream, int maximumBytes, CancellationToken cancellationToken)
    {
        using var output = new MemoryStream(Math.Min(maximumBytes, 4096));
        byte[] buffer = new byte[4096];
        while (true)
        {
            int read = await stream.ReadAsync(buffer.AsMemory(), cancellationToken).ConfigureAwait(false);
            if (read == 0) return output.ToArray();
            if (output.Length + read > maximumBytes) throw new InvalidDataException("OpenCode health response exceeded the bounded size.");
            output.Write(buffer, 0, read);
        }
    }

    private static string MergeAutoPermission(string? configContent)
    {
        JsonObject config;
        if (string.IsNullOrWhiteSpace(configContent)) config = new JsonObject();
        else
        {
            JsonNode? parsed = JsonNode.Parse(configContent);
            config = parsed as JsonObject ?? throw new InvalidDataException("OpenCode inline config must be a JSON object.");
        }
        // Everything is allowed, except the global skills the task turned off (they stay hidden).
        var denied = TaskSkillSwitches.Denied(config);
        if (denied.Count == 0) config["permission"] = JsonValue.Create("allow");
        else
        {
            var skill = new JsonObject { ["*"] = "allow" };
            foreach (string name in denied) skill[name] = "deny";
            config["permission"] = new JsonObject { ["*"] = "allow", ["skill"] = skill };
        }
        return config.ToJsonString(new JsonSerializerOptions { WriteIndented = false });
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEINSTALLATIONSERVICE_CS
#region Services/OpenCodeInstallationService.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Diagnostics;
using global::System.ComponentModel;
using global::System.Runtime.InteropServices;
using global::System.Text;
using global::System.Text.RegularExpressions;
using global::System.Text.Json;
using global::System.Reflection.PortableExecutable;


public sealed record OpenCodeVersionProbeResult(bool Succeeded, string? Version = null, string? Error = null);

/// <summary>Runs the version check for one resolved Windows OpenCode command.</summary>
public interface IOpenCodeCommandRunner
{
    Task<OpenCodeVersionProbeResult> ProbeVersionAsync(
        string commandPath,
        string searchPath,
        CancellationToken cancellationToken);
}

/// <summary>
/// Read-only OpenCode discovery. It probes PATH commands and the app's per-user bin location;
/// it does not download, replace, or otherwise install files.
/// </summary>
public sealed class OpenCodeInstallationService
{
    private static readonly string[] CommandExtensions = [".exe", ".cmd", ".ps1"];
    private static readonly string[] NativeWindowsX64Packages = [
        "opencode-windows-x64",
        "opencode-windows-x64-baseline"];
    private const long SmallBrokenWrapperLimit = 64 * 1024;
    private const string BrokenWrapperMarker = "opencode-ai's postinstall script was not run";
    private readonly IOpenCodeCommandRunner _commandRunner;
    private readonly Func<IReadOnlyList<string>> _searchPaths;
    private readonly Func<string?> _processPath;
    private readonly Action<string> _setProcessPath;
    private readonly string _managedBinPath;

    public OpenCodeInstallationService(
        IOpenCodeCommandRunner? commandRunner = null,
        Func<IReadOnlyList<string>>? searchPaths = null,
        Func<string?>? processPath = null,
        Action<string>? setProcessPath = null,
        string? managedBinPath = null)
    {
        _commandRunner = commandRunner ?? new WindowsOpenCodeCommandRunner();
        _searchPaths = searchPaths ?? GetEnvironmentSearchPaths;
        _processPath = processPath ?? (() => Environment.GetEnvironmentVariable("PATH"));
        _setProcessPath = setProcessPath ?? (value => Environment.SetEnvironmentVariable("PATH", value, EnvironmentVariableTarget.Process));
        _managedBinPath = managedBinPath ?? GetManagedBinPath();
    }

    public Task<AutoInstallDetectionResult> CheckAsync(CancellationToken cancellationToken = default) =>
        Task.Run(() => CheckCoreAsync(cancellationToken), cancellationToken);

    private async Task<AutoInstallDetectionResult> CheckCoreAsync(CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();

        IReadOnlyList<string> paths;
        try
        {
            paths = GetDistinctPaths(_searchPaths().Append(_managedBinPath));
        }
        catch (Exception exception) when (exception is not OperationCanceledException)
        {
            return new AutoInstallDetectionResult(false,
                "Could not read the OpenCode command search paths (" + exception.GetType().Name + ").");
        }

        string childSearchPath = string.Join(Path.PathSeparator, paths);
        bool foundCandidate = false;
        var failures = new List<string>();
        foreach (string directory in paths)
        {
            cancellationToken.ThrowIfCancellationRequested();
            bool foundCommandShim = false;
            bool foundPowerShellShim = false;
            bool commandShimFailed = true;
            bool powerShellShimFailed = true;
            foreach (string extension in CommandExtensions)
            {
                string commandPath;
                try
                {
                    commandPath = Path.Combine(directory, "opencode" + extension);
                    if (!File.Exists(commandPath))
                        continue;
                }
                catch (Exception exception) when (exception is ArgumentException or IOException or UnauthorizedAccessException or NotSupportedException)
                {
                    continue;
                }

                foundCandidate = true;
                if (extension.Equals(".cmd", StringComparison.OrdinalIgnoreCase)) foundCommandShim = true;
                if (extension.Equals(".ps1", StringComparison.OrdinalIgnoreCase)) foundPowerShellShim = true;
                // npm shims can invoke an .exe-named text placeholder. Trying the
                // shim first raises Windows compatibility dialogs before fallback.
                if (IsKnownBrokenNpmShim(commandPath) ||
                    extension.Equals(".exe", StringComparison.OrdinalIgnoreCase) && IsSmallBrokenWrapper(commandPath))
                {
                    failures.Add($"{commandPath}: npm postinstall placeholder; command not started");
                    continue;
                }
                OpenCodeVersionProbeResult probe;
                try
                {
                    probe = await _commandRunner.ProbeVersionAsync(commandPath, childSearchPath, cancellationToken).ConfigureAwait(false);
                }
                catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
                {
                    throw;
                }
                catch (Exception exception)
                {
                    probe = new OpenCodeVersionProbeResult(false, Error: DescribeProbeException(exception));
                }

                if (!probe.Succeeded || string.IsNullOrWhiteSpace(probe.Version))
                {
                    failures.Add($"{commandPath}: {DescribeProbeFailure(probe)}");
                    continue;
                }

                if (extension.Equals(".cmd", StringComparison.OrdinalIgnoreCase)) commandShimFailed = false;
                if (extension.Equals(".ps1", StringComparison.OrdinalIgnoreCase)) powerShellShimFailed = false;

                RefreshProcessPathIfNeeded(directory, paths);
                return new AutoInstallDetectionResult(
                    true,
                    $"OpenCode {probe.Version} is available.",
                    commandPath,
                    probe.Version);
            }

            if ((foundCommandShim || foundPowerShellShim) && commandShimFailed && powerShellShimFailed)
            {
                AutoInstallDetectionResult? native = await TryExistingNativePayloadAsync(
                    directory, childSearchPath, paths, cancellationToken).ConfigureAwait(false);
                if (native is not null)
                    return native;
            }
        }

        string message = foundCandidate
            ? "OpenCode candidates were found, but none passed the version check: " + string.Join("; ", failures)
            : "OpenCode is not installed or is not available on PATH.";
        return new AutoInstallDetectionResult(false, message);
    }

    private async Task<AutoInstallDetectionResult?> TryExistingNativePayloadAsync(
        string directory,
        string childSearchPath,
        IReadOnlyList<string> refreshedPaths,
        CancellationToken cancellationToken)
    {
        if (!OperatingSystem.IsWindows() ||
            !Environment.Is64BitProcess ||
            RuntimeInformation.ProcessArchitecture != Architecture.X64)
            return null;

        string packageRoot = Path.Combine(directory, "node_modules", "opencode-ai");
        string manifestPath = Path.Combine(packageRoot, "package.json");
        if (!TryReadPackageManifest(manifestPath, "opencode-ai", out string? packageVersion) ||
            string.IsNullOrWhiteSpace(packageVersion))
            return null;

        string brokenWrapperPath = Path.Combine(packageRoot, "bin", "opencode.exe");
        if (!IsSmallBrokenWrapper(brokenWrapperPath))
            return null;

        string nativeSearchPath = string.Join(Path.PathSeparator,
            new[] { Path.Combine(packageRoot, "node_modules") }.Concat(refreshedPaths));
        foreach (string packageName in NativeWindowsX64Packages)
        {
            cancellationToken.ThrowIfCancellationRequested();
            string nativeRoot = Path.Combine(packageRoot, "node_modules", packageName);
            string nativeManifest = Path.Combine(nativeRoot, "package.json");
            if (!TryReadPackageManifest(nativeManifest, packageName, out string? nativeVersion) ||
                !string.Equals(nativeVersion, packageVersion, StringComparison.Ordinal))
                continue;

            string nativeExecutable = Path.Combine(nativeRoot, "bin", "opencode.exe");
            if (!File.Exists(nativeExecutable)) continue;
            OpenCodeVersionProbeResult probe;
            try
            {
                probe = await _commandRunner.ProbeVersionAsync(
                    nativeExecutable, nativeSearchPath, cancellationToken).ConfigureAwait(false);
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                throw;
            }
            catch (Exception exception)
            {
                probe = new OpenCodeVersionProbeResult(false, Error: DescribeProbeException(exception));
            }

            if (!probe.Succeeded || string.IsNullOrWhiteSpace(probe.Version) ||
                !string.Equals(probe.Version, packageVersion, StringComparison.Ordinal))
                continue;

            string nativeDirectory = Path.GetDirectoryName(nativeExecutable)!;
            RefreshProcessPathIfNeeded(nativeDirectory, refreshedPaths);
            return new AutoInstallDetectionResult(
                true,
                $"OpenCode {probe.Version} is available via the existing native payload ({nativeExecutable}).",
                nativeExecutable,
                probe.Version);
        }

        return null;
    }

    /// <summary>The native opencode.exe behind a resolved OpenCode command: the command itself when it is one, or for npm's
    /// shims (opencode.cmd · .ps1) the node_modules\opencode-ai\bin\opencode.exe they run once npm placed the real program
    /// there. Null when there is none (a placeholder, another wrapper): such a command keeps its shell.</summary>
    internal static string? NativeExecutable(string commandPath)
    {
        if (string.IsNullOrWhiteSpace(commandPath)) return null;
        string candidate = Path.GetExtension(commandPath).Equals(".exe", StringComparison.OrdinalIgnoreCase) ? commandPath
            : Path.Combine(Path.GetDirectoryName(Path.GetFullPath(commandPath)) ?? "", "node_modules", "opencode-ai", "bin", "opencode.exe");
        try
        {
            using FileStream stream = File.OpenRead(candidate);
            if (stream.Length <= SmallBrokenWrapperLimit) return null;
            using var pe = new System.Reflection.PortableExecutable.PEReader(stream);
            return pe.PEHeaders.PEHeader is null ? null : Path.GetFullPath(candidate);
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or BadImageFormatException or ArgumentException or NotSupportedException)
        {
            return null;
        }
    }

    internal static bool IsKnownBrokenNpmShim(string commandPath)
    {
        string extension = Path.GetExtension(commandPath);
        if (!extension.Equals(".cmd", StringComparison.OrdinalIgnoreCase) &&
            !extension.Equals(".ps1", StringComparison.OrdinalIgnoreCase)) return false;
        try
        {
            using FileStream stream = File.OpenRead(commandPath);
            if (stream.Length > SmallBrokenWrapperLimit) return false;
            using var reader = new StreamReader(stream, Encoding.UTF8, detectEncodingFromByteOrderMarks: true);
            string shim = reader.ReadToEnd().Replace('\\', '/');
            if (!shim.Contains("node_modules/opencode-ai/bin/opencode.exe", StringComparison.OrdinalIgnoreCase)) return false;
            return IsSmallBrokenWrapper(Path.Combine(Path.GetDirectoryName(commandPath)!,
                "node_modules", "opencode-ai", "bin", "opencode.exe"));
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or DecoderFallbackException)
        {
            return false;
        }
    }

    private static bool IsSmallBrokenWrapper(string path)
    {
        try
        {
            using FileStream stream = File.OpenRead(path);
            if (stream.Length > SmallBrokenWrapperLimit) return false;
            using var reader = new StreamReader(stream, Encoding.UTF8, detectEncodingFromByteOrderMarks: true);
            return reader.ReadToEnd().Contains(BrokenWrapperMarker, StringComparison.Ordinal);
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or DecoderFallbackException)
        {
            return false;
        }
    }

    private static bool TryReadPackageManifest(string path, string expectedName, out string? version)
    {
        version = null;
        try
        {
            using FileStream stream = File.OpenRead(path);
            if (stream.Length > SmallBrokenWrapperLimit) return false;
            using JsonDocument document = JsonDocument.Parse(stream);
            JsonElement root = document.RootElement;
            if (!root.TryGetProperty("name", out JsonElement name) ||
                !string.Equals(name.GetString(), expectedName, StringComparison.Ordinal) ||
                !root.TryGetProperty("version", out JsonElement value))
                return false;
            version = value.GetString();
            return !string.IsNullOrWhiteSpace(version);
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or
            DecoderFallbackException or InvalidOperationException)
        {
            return false;
        }
    }

    private static string DescribeProbeFailure(OpenCodeVersionProbeResult probe)
    {
        string reason = probe.Error?.Trim() ?? "version probe failed";
        if (reason.Length == 0) return "version probe failed";
        string lowered = reason.ToLowerInvariant();
        Match win32Code = Regex.Match(reason, @"Win32\s+error\s+(?<code>\d+)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        if (win32Code.Success)
        {
            string code = win32Code.Groups["code"].Value;
            return code is "193" or "216"
                ? $"not a valid Windows executable (Win32 error {code})"
                : $"command start failed (Win32 error {code})";
        }
        if (lowered.Contains("not a valid win32", StringComparison.Ordinal) ||
            lowered.Contains("not a valid windows executable", StringComparison.Ordinal))
            return "not a valid Windows executable";
        if (lowered.Contains("timed out", StringComparison.Ordinal) || lowered.Contains("timeout", StringComparison.Ordinal))
            return "version check timed out";
        if (lowered.Contains("exit code", StringComparison.Ordinal) ||
            lowered.Contains("exited with code", StringComparison.Ordinal) ||
            lowered.Contains("nonzero", StringComparison.Ordinal))
        {
            Match exitCode = Regex.Match(reason, @"exit(?:ed)?\s+with\s+code\s+(?<code>-?\d+)",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
            return exitCode.Success
                ? $"command exited with code {exitCode.Groups["code"].Value} without a valid OpenCode version"
                : "command exited unsuccessfully without a valid OpenCode version";
        }
        if (lowered.Contains("returned no valid", StringComparison.Ordinal) ||
            lowered.Contains("no valid opencode version", StringComparison.Ordinal))
            return "command returned no valid OpenCode version";
        if (lowered.Contains("access denied", StringComparison.Ordinal))
            return "command start failed (access denied)";
        if (lowered.Contains("file not found", StringComparison.Ordinal) ||
            lowered.Contains("could not find", StringComparison.Ordinal))
            return "command start failed (file not found)";
        return "version probe failed";
    }

    internal static string DescribeProbeException(Exception exception) => exception switch
    {
        Win32Exception win32 when win32.NativeErrorCode is 193 or 216 =>
            $"not a valid Windows executable (Win32 error {win32.NativeErrorCode})",
        Win32Exception win32 => $"command start failed (Win32 error {win32.NativeErrorCode})",
        UnauthorizedAccessException => "command start failed (access denied)",
        FileNotFoundException => "command start failed (file not found)",
        TimeoutException => "version check timed out",
        _ => "command probe failed (" + exception.GetType().Name + ")"
    };

    private void RefreshProcessPathIfNeeded(string detectedDirectory, IReadOnlyList<string> refreshedPaths)
    {
        string currentPath = _processPath() ?? string.Empty;
        string[] currentEntries = GetDistinctPaths(currentPath.Split(Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries));
        string[] allEntries = [detectedDirectory, .. GetDistinctPaths(currentEntries.Concat(refreshedPaths))
            .Where(path => !PathsEqual(path, detectedDirectory))];
        string updatedPath = string.Join(Path.PathSeparator, allEntries);
        if (string.Equals(currentPath, updatedPath, StringComparison.OrdinalIgnoreCase))
            return;

        try
        {
            _setProcessPath(updatedPath);
        }
        catch
        {
            // Detection still succeeded; this best-effort refresh only helps later child processes.
        }
    }

    private static IReadOnlyList<string> GetEnvironmentSearchPaths()
    {
        var values = new List<string>();
        AddPathValue(Environment.GetEnvironmentVariable("PATH", EnvironmentVariableTarget.Process));
        AddPathValue(Environment.GetEnvironmentVariable("PATH", EnvironmentVariableTarget.User));
        AddPathValue(Environment.GetEnvironmentVariable("PATH", EnvironmentVariableTarget.Machine));
        return GetDistinctPaths(values);

        void AddPathValue(string? value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return;

            string expanded = Environment.ExpandEnvironmentVariables(value);
            values.AddRange(expanded.Split(Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries));
        }
    }

    private static string GetManagedBinPath()
    {
        string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        if (string.IsNullOrWhiteSpace(localAppData))
            return Path.Combine(AppContext.BaseDirectory, "OpenCode", "bin");
        return Path.Combine(localAppData, "TerminalNotes", "OpenCode", "bin");
    }

    private static string[] GetDistinctPaths(IEnumerable<string> values)
    {
        var result = new List<string>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (string value in values)
        {
            string trimmed = value.Trim().Trim('"');
            if (trimmed.Length == 0)
                continue;

            try
            {
                string normalized = Path.GetFullPath(Environment.ExpandEnvironmentVariables(trimmed));
                string key = Path.TrimEndingDirectorySeparator(normalized);
                if (seen.Add(key))
                    result.Add(key);
            }
            catch (Exception exception) when (exception is ArgumentException or IOException or UnauthorizedAccessException or NotSupportedException)
            {
                // An invalid PATH segment cannot contain a launchable command.
            }
        }

        return result.ToArray();
    }

    private static bool PathsEqual(string left, string right)
    {
        try
        {
            return string.Equals(
                Path.TrimEndingDirectorySeparator(Path.GetFullPath(left)),
                Path.TrimEndingDirectorySeparator(Path.GetFullPath(right)),
                StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return string.Equals(left, right, StringComparison.OrdinalIgnoreCase);
        }
    }
}

internal sealed class WindowsOpenCodeCommandRunner : IOpenCodeCommandRunner
{
    private const int OutputLimit = 4096;

    public async Task<OpenCodeVersionProbeResult> ProbeVersionAsync(
        string commandPath,
        string searchPath,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        string extension = Path.GetExtension(commandPath);
        if (OpenCodeInstallationService.IsKnownBrokenNpmShim(commandPath))
            return new OpenCodeVersionProbeResult(false, Error: "npm postinstall placeholder; command not started");
        if (extension.Equals(".exe", StringComparison.OrdinalIgnoreCase))
        {
            try
            {
                using FileStream stream = File.OpenRead(commandPath);
                using var pe = new PEReader(stream);
                if (pe.PEHeaders.PEHeader is null)
                    return new OpenCodeVersionProbeResult(false, Error: "not a valid Windows executable (invalid PE header; not started)");
            }
            catch (BadImageFormatException)
            {
                return new OpenCodeVersionProbeResult(false, Error: "not a valid Windows executable (invalid PE header; not started)");
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
            {
                return new OpenCodeVersionProbeResult(false, Error: OpenCodeInstallationService.DescribeProbeException(exception));
            }
        }
        var startInfo = new ProcessStartInfo
        {
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
            WindowStyle = ProcessWindowStyle.Hidden
        };
        startInfo.Environment["PATH"] = searchPath;

        if (extension.Equals(".exe", StringComparison.OrdinalIgnoreCase))
        {
            startInfo.FileName = commandPath;
            startInfo.ArgumentList.Add("--version");
        }
        else if (extension.Equals(".cmd", StringComparison.OrdinalIgnoreCase))
        {
            if (commandPath.IndexOfAny(['%', '\r', '\n', '"']) >= 0)
                return new OpenCodeVersionProbeResult(false, Error: "The command path contains characters unsafe for cmd.exe.");

            startInfo.FileName = Environment.GetEnvironmentVariable("ComSpec") ?? "cmd.exe";
            // cmd.exe does not follow the normal argv quoting rules, so use its documented
            // /c double-quote form after rejecting expansion and quote characters above.
            startInfo.Arguments = $"/d /s /c \"\"{commandPath}\" --version\"";
        }
        else if (extension.Equals(".ps1", StringComparison.OrdinalIgnoreCase))
        {
            string systemDirectory = Environment.GetFolderPath(Environment.SpecialFolder.System);
            startInfo.FileName = Path.Combine(systemDirectory, "WindowsPowerShell", "v1.0", "powershell.exe");
            startInfo.ArgumentList.Add("-NoLogo");
            startInfo.ArgumentList.Add("-NoProfile");
            startInfo.ArgumentList.Add("-NonInteractive");
            startInfo.ArgumentList.Add("-ExecutionPolicy");
            startInfo.ArgumentList.Add("Bypass");
            startInfo.ArgumentList.Add("-File");
            startInfo.ArgumentList.Add(commandPath);
            startInfo.ArgumentList.Add("--version");
        }
        else
        {
            return new OpenCodeVersionProbeResult(false, Error: "Unsupported OpenCode command type.");
        }

        var standardOutput = new BoundedTextBuffer(OutputLimit);

        try
        {
            using var owner = OwnedWindowsProcess.Start(startInfo, standardOutput.Append);
            Process process = owner.Process;

            using var timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            timeout.CancelAfter(TerminalExecutionTiming.InstallationProbeTimeout);
            try
            {
                await process.WaitForExitAsync(timeout.Token).ConfigureAwait(false);
                await owner.OutputDrained.WaitAsync(timeout.Token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                await owner.StopAsync().ConfigureAwait(false);
                if (cancellationToken.IsCancellationRequested)
                    throw;
                return new OpenCodeVersionProbeResult(false, Error: "The OpenCode version check timed out.");
            }

            string output = standardOutput.ToString();
            Match match = Regex.Match(
                output,
                @"(?:^|\s)(?:OpenCode\s+)?v?(?<version>\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)(?:\s|$)",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant | RegexOptions.Multiline);
            string? version = match.Success ? match.Groups["version"].Value : null;
            if (process.ExitCode != 0)
            {
                return new OpenCodeVersionProbeResult(false,
                    Error: $"The command exited with code {process.ExitCode} without a valid OpenCode version.");
            }
            if (string.IsNullOrWhiteSpace(version))
                return new OpenCodeVersionProbeResult(false, Error: "The command returned no valid OpenCode version.");

            return new OpenCodeVersionProbeResult(true, version);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is not OperationCanceledException)
        {
            return new OpenCodeVersionProbeResult(false, Error: OpenCodeInstallationService.DescribeProbeException(exception));
        }
    }

    private static void TryKill(Process process)
    {
        try
        {
            if (!process.HasExited)
                process.Kill(entireProcessTree: true);
        }
        catch
        {
            // The process may have exited between the check and the kill.
        }
    }

    private sealed class BoundedTextBuffer(int limit)
    {
        private readonly StringBuilder _value = new();
        private readonly object _gate = new();

        public void Append(string text)
        {
            lock (_gate)
            {
                int remaining = limit - _value.Length;
                if (remaining > 0) _value.Append(text.AsSpan(0, Math.Min(text.Length, remaining)));
            }
        }

        public void AppendLine(string? line)
        {
            if (line is null)
                return;
            lock (_gate)
            {
                if (_value.Length >= limit)
                    return;
                int remaining = limit - _value.Length;
                _value.Append(line.AsSpan(0, Math.Min(line.Length, remaining)));
                if (_value.Length < limit)
                    _value.AppendLine();
            }
        }

        public override string ToString()
        {
            lock (_gate)
                return _value.ToString();
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODEPROJECTCONTEXT_CS
#region Services/OpenCodeProjectContext.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Text.Json;
using global::System.Text.Json.Nodes;


/// <summary>
/// Global skills a task turns off in its skills window. The list lives in the task's own skills folder
/// (&lt;task&gt;\.opencode\skills\.terminal-notes\global-off.json, which travels with the folder) and reaches OpenCode as
/// permission.skill deny rules in that task's sessions, which hide those skills from the agent (OpenCode 1.18).
/// </summary>
public static class TaskSkillSwitches
{
    public static string FilePath(string project) =>
        Path.Combine(Path.GetFullPath(project), ".opencode", "skills", ".terminal-notes", "global-off.json");

    public static IReadOnlyList<string> Off(string project)
    {
        try
        {
            string path = FilePath(project);
            if (!File.Exists(path)) return [];
            return (JsonSerializer.Deserialize<string[]>(File.ReadAllText(path)) ?? [])
                .Where(name => !string.IsNullOrWhiteSpace(name)).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray();
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or ArgumentException) { return []; }
    }

    /// <summary>Turns a global skill off (or back on) for this task's next OpenCode sessions.</summary>
    public static void Set(string project, string name, bool off)
    {
        var names = Off(project).ToHashSet(StringComparer.Ordinal);
        if (!(off ? names.Add(name) : names.Remove(name))) return;
        string path = FilePath(project);
        if (names.Count == 0) { File.Delete(path); return; }
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        string temporary = path + "." + Guid.NewGuid().ToString("N") + ".tmp";
        File.WriteAllText(temporary, JsonSerializer.Serialize(names.Order(StringComparer.Ordinal).ToArray()));
        File.Move(temporary, path, overwrite: true);
    }

    /// <summary>Adds "deny" for each skill this task turned off, keeping the rest of the permission config.</summary>
    public static void AddDenies(JsonObject config, string project)
    {
        var names = Off(project);
        if (names.Count == 0) return;
        // A flat action ("allow", "ask") applies to every tool: kept as "*" so the skill rules can follow it.
        JsonObject permission = config["permission"] switch
        {
            JsonObject existing => existing,
            JsonValue action => new JsonObject { ["*"] = action.DeepClone() },
            _ => new JsonObject()
        };
        config["permission"] = permission;
        JsonObject skill = permission["skill"] switch
        {
            JsonObject existing => existing,
            JsonValue action => new JsonObject { ["*"] = action.DeepClone() },
            _ => new JsonObject()
        };
        permission["skill"] = skill;
        foreach (string name in names) skill[name] = "deny";
    }

    /// <summary>The skill deny rules in a config, for Auto Mode to keep when it allows everything else.</summary>
    public static IReadOnlyList<string> Denied(JsonObject config) =>
        (config["permission"] as JsonObject)?["skill"] is JsonObject skill
            ? skill.Where(pair => pair.Key != "*" && pair.Value is JsonValue value && value.TryGetValue(out string? action) && action == "deny")
                .Select(pair => pair.Key).ToArray()
            : [];
}

/// <summary>
/// Holds the per-terminal OpenCode instruction file that points at its currently
/// bound project plan. OpenCode rereads configured instruction files before each
/// model request, so the file can be updated without restarting the TUI.
/// </summary>
public sealed class OpenCodeProjectContext : IDisposable
{
    // Hosts and integration tests can isolate process data without changing the user's profile.
    internal static string DataDirectory => AppContext.GetData("TerminalNotes.DataDirectory") is string directory
        ? Path.GetFullPath(directory)
        : Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "TerminalNotes");
    private readonly object _gate = new();
    private readonly string _workingDirectory;
    private string? _projectName;
    private bool _disposed;

    public string InstructionFilePath { get; }

    public OpenCodeProjectContext(string workingDirectory, string? planDocumentPath = null, string? projectName = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(workingDirectory);
        _workingDirectory = Path.GetFullPath(workingDirectory);
        string directory = Path.Combine(DataDirectory, "OpenCodeProjectContext");
        Directory.CreateDirectory(directory);
        InstructionFilePath = Path.Combine(directory, Guid.NewGuid().ToString("N") + ".md");
        UpdatePlanDocumentContext(planDocumentPath, projectName);
    }

    /// <summary>
    /// Atomically changes the linked plan reference. The plan itself is never read
    /// or written by this service.
    /// </summary>
    public void UpdatePlanDocumentContext(string? planDocumentPath, string? projectName = null)
    {
        lock (_gate)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            string? nextProjectName = projectName ?? _projectName;
            string content = CreateInstructions(planDocumentPath, nextProjectName);
            string temporaryPath = InstructionFilePath + "." + Guid.NewGuid().ToString("N") + ".tmp";
            try
            {
                File.WriteAllText(temporaryPath, content, new System.Text.UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
                File.Move(temporaryPath, InstructionFilePath, overwrite: true);
                _projectName = nextProjectName;
            }
            finally
            {
                if (File.Exists(temporaryPath))
                    File.Delete(temporaryPath);
            }
        }
    }

    /// <summary>
    /// Adds this pane's instruction file to OpenCode's documented inline config,
    /// preserving all valid inherited settings and configured instruction paths.
    /// </summary>
    public string CreateProcessConfigContent(string? existingConfigContent)
    {
        JsonObject config;
        if (string.IsNullOrWhiteSpace(existingConfigContent))
        {
            config = new JsonObject();
        }
        else
        {
            JsonNode? parsed;
            try
            {
                parsed = JsonNode.Parse(existingConfigContent, documentOptions: new JsonDocumentOptions
                {
                    AllowTrailingCommas = true,
                    CommentHandling = JsonCommentHandling.Skip
                });
            }
            catch (JsonException exception)
            {
                throw new InvalidOperationException(
                    "The inherited OPENCODE_CONFIG_CONTENT is not valid JSON/JSONC; TerminalNotes cannot safely add its plan instructions.",
                    exception);
            }

            config = parsed as JsonObject
                ?? throw new InvalidOperationException(
                    "The inherited OPENCODE_CONFIG_CONTENT must be a JSON object so TerminalNotes can preserve it and add plan instructions.");
        }

        string globalInstructions = GlobalAgentInstructions.EnsureFile();
        AddInstructionPath(config, globalInstructions);
        AddInstructionPath(config, InstructionFilePath);
        // Global skills this task turned off.
        TaskSkillSwitches.AddDenies(config, _workingDirectory);

        return config.ToJsonString(new JsonSerializerOptions { WriteIndented = false });
    }

    private static void AddInstructionPath(JsonObject config, string path)
    {
        if (config.TryGetPropertyValue("instructions", out JsonNode? existingInstructions))
        {
            if (existingInstructions is not JsonArray instructionArray)
            {
                throw new InvalidOperationException(
                    "OPENCODE_CONFIG_CONTENT.instructions must be an array; TerminalNotes cannot safely add its instructions.");
            }

            if (!instructionArray.Any(node => node is JsonValue value && value.TryGetValue<string>(out string? existingPath) &&
                string.Equals(existingPath, path, StringComparison.OrdinalIgnoreCase)))
            {
                instructionArray.Add(path);
            }
        }
        else
        {
            config["instructions"] = new JsonArray(JsonValue.Create(path));
        }
    }

    private const string ResumeInstructions = """
        ## 작업 재개 및 추가 입력

        중단 후 재개하거나 새 세션으로 연결되어도 처음부터 다시 시작하지 마세요. 최신 요청과 계획의 요구사항을 항목별로 현재 코드·변경분·기존 대화/전달된 실행 결과·native todo와 대조해 완료, 일부 구현, 미완료를 구분하세요. pending todo나 계획에 항목이 남았다는 이유만으로 다시 구현하지 마세요. 이미 구현되어 정상 동작하는 기능은 보존하고 다시 구현하지 마세요. 모두 충족되었으면 근거를 확인하고 stale todo만 정리하며 코드 변경 없이 멈추세요. 일부 미충족이거나 구체 결함이 확인된 경우에만 그 부분을 최소 수정하세요. 유효한 기존 검증이 있으면 코드 변경 없이 다시 돌릴 필요가 없습니다. 구현 도중 끊겨 완료 여부가 불명확한 변경은 현재 파일을 확인한 뒤 이어서 보완하세요. 재구현이 꼭 필요하면 기존 구현의 구체적인 결함과 수정 이유를 먼저 밝히세요. 저장된 기록이나 idle 상태만으로 완료를 추정하지 마세요.
        """;

    private string CreateInstructions(string? planDocumentPath, string? projectName)
    {
        string? fullPath = string.IsNullOrWhiteSpace(planDocumentPath)
            ? null
            : Path.GetFullPath(planDocumentPath, _workingDirectory);

        if (fullPath is not null && !string.Equals(Path.GetExtension(fullPath), ".md", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("The linked plan document must be a Markdown (.md) file.", nameof(planDocumentPath));

        if (fullPath is null)
        {
            return $"""
                # TerminalNotes linked plan context

                This terminal is bound to project {DisplayProjectName(projectName)} at directory {MarkdownCodeSpan(_workingDirectory)}. Keep all project file edits, builds, and commands within this directory. If the user names another project, ask them to select that project in TerminalNotes before acting.

                No project plan Markdown file is currently linked. Greetings and simple questions can be answered without a plan. Before implementation or build work, ask the user to select or save a nonempty linked plan. Do not invent plan content.

                {ResumeInstructions}

                Do not start work or run commands merely because this session opened. Wait for a user request.
                """;
        }

        return $"""
            # TerminalNotes linked plan context

            This terminal is bound to project {DisplayProjectName(projectName)} at directory {MarkdownCodeSpan(_workingDirectory)}. Keep all project file edits, builds, and commands within this directory. If the user names another project, ask them to select that project in TerminalNotes before acting.

            Treat the latest contents of the linked file as the project's implementation requirements, combined with the user's current request. A newer explicit correction in an appended request supersedes the corresponding older requirement; preserve requirements it does not change. Ask only when the intended result remains ambiguous. The plan is the Markdown file at this absolute path:

            {MarkdownCodeSpan(fullPath)}

            Before implementation or build work for each user task, read the latest contents of that file. Greetings and simple questions can be answered without a plan. If implementation/build work is requested and the file is missing, empty, or unreadable, ask the user to save a nonempty plan and do not invent plan content.

            For implementation or build work, create or update OpenCode's native todo list for the current request before doing the work, and keep its statuses accurate as work proceeds. Mark completed or cancelled items accordingly; never leave completed work pending. Do not create todos for greetings or simple questions. TerminalNotes uses native unfinished todos to resume interrupted work, so do not report completion by prose alone. Do not rewrite the linked plan merely to record progress.

            {ResumeInstructions}

            Do not start work or run commands merely because this session opened. Wait for a user request.
            """;
    }

    private static string DisplayProjectName(string? value) =>
        string.IsNullOrWhiteSpace(value) ? "(unnamed)" : MarkdownCodeSpan(value);

    private static string MarkdownCodeSpan(string value)
    {
        int longestRun = 0;
        int currentRun = 0;
        foreach (char character in value)
        {
            if (character == '`')
            {
                currentRun++;
                longestRun = Math.Max(longestRun, currentRun);
            }
            else currentRun = 0;
        }
        string fence = new('`', longestRun + 1);
        bool needsPadding = value.StartsWith('`') || value.EndsWith('`') || value.StartsWith(' ') || value.EndsWith(' ');
        return needsPadding ? fence + " " + value + " " + fence : fence + value + fence;
    }

    public void Dispose()
    {
        lock (_gate)
        {
            if (_disposed)
                return;
            _disposed = true;
            try
            {
                if (File.Exists(InstructionFilePath))
                    File.Delete(InstructionFilePath);
            }
            catch (IOException) { }
            catch (UnauthorizedAccessException) { }
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODERECOVERYCLIENT_CS
#region Services/OpenCodeRecoveryClient.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Globalization;
using global::System.Net.Http;
using global::System.Net;
using global::System.Net.Http.Headers;
using global::System.Security.Cryptography;
using global::System.Text;
using global::System.Text.Json;


public enum OpenCodeRecoveryStatus
{
    Unknown,
    Idle,
    Busy,
    Retry
}

public enum OpenCodeRecoveryOutcome
{
    Accepted,
    Rejected,
    Ambiguous
}

public sealed record RecoverySessionEvidence(
    string SessionId,
    OpenCodeRecoveryStatus Status,
    string? ParentSessionId,
    string SessionDirectory,
    bool HasPendingPermission,
    bool HasPendingQuestion,
    bool HasPendingPermissionInDescendants,
    bool HasPendingQuestionInDescendants,
    int IncompleteTodoCount,
    int TotalTodoCount,
    string TodoFingerprint,
    string ProgressFingerprint,
    bool HasRunningTools,
    bool HasBusyDescendants,
    string? LatestUserMessageId,
    DateTimeOffset? LatestUserMessageCreated,
    string? LatestAssistantMessageId,
    string? LatestMessageId,
    bool HasErrorMarker,
    string? LatestErrorType,
    int? RetryAttempt,
    string? RetryMessage,
    long? RetryNext)
{
    public int CompletedTodoCount { get; init; }
    public bool HasCurrentUserTodoWrite { get; init; }
    public bool AllTodosCompleted { get; init; }
    public bool HasSuccessfulFinalResponse { get; init; }
    public string ActivityFingerprint { get; init; } = string.Empty;
    public string? StalledLaunchToolFingerprint { get; init; }
    public string? AbortCancellationToolFingerprint { get; init; }
    public IReadOnlyList<RecoveryErrorEvidence> CurrentErrors { get; init; } = Array.Empty<RecoveryErrorEvidence>();
    public bool HasConfirmedErrorResponse { get; init; }
    public IReadOnlyList<RecoveryNativeMessage> NativeMessages { get; init; } = Array.Empty<RecoveryNativeMessage>();
    // OpenCode's session.status retry.next is an absolute Unix millisecond time.
    public DateTimeOffset? NativeRetryAt
    {
        get
        {
            if (RetryNext is not { } next) return null;
            try { return DateTimeOffset.FromUnixTimeMilliseconds(next); }
            catch (ArgumentOutOfRangeException) { return DateTimeOffset.MaxValue; }
        }
    }
}

public sealed record RecoveryModelSelection(string ProviderId, string ModelId);

/// <summary>Bounded, structured native message metadata; never inferred from assistant prose.</summary>
public sealed record RecoveryNativeMessage(string Id, string Role)
{
    public string? ParentId { get; init; }
    public RecoveryModelSelection? Model { get; init; }
    public bool IsCompaction { get; init; }
    public bool CompactionAuto { get; init; }
    public string? Agent { get; init; }
    public string? Variant { get; init; }
    public string TextFingerprint { get; init; } = string.Empty;
    public string? RequestMarker { get; init; }
    public bool IsSummary { get; init; }
    public bool IsCompactionContinuation { get; init; }
    public bool IsFinished { get; init; }
    public bool SuccessfulFinish { get; init; }
    public IReadOnlyList<RecoveryErrorEvidence> Errors { get; init; } = Array.Empty<RecoveryErrorEvidence>();
}

public sealed record RecoveryErrorEvidence(string Type, string? ToolFingerprint)
{
    public bool IsToolExecutionError { get; init; }
    public bool HasVerifiedContextOverflow { get; init; }
    public int? StatusCode { get; init; }
    public bool? IsRetryable { get; init; }
    public string? ParentUserMessageId { get; init; }
    public DateTimeOffset? RetryAfterUtc { get; init; }
    public TimeSpan? RetryAfterDelay { get; init; }
    public string? RetryEvidenceId { get; init; }
    /// <summary>Provider message text (data.message and the start of data.responseBody), when OpenCode reports one.</summary>
    public string? Message { get; init; }
}

public sealed record OpenCodeRecoveryReadResult(
    bool IsAvailable,
    RecoverySessionEvidence? Evidence,
    string? ErrorCode = null,
    string? Error = null);

public sealed record OpenCodeRecoveryContinueResult(
    OpenCodeRecoveryOutcome Outcome,
    string MessageId,
    string? ErrorCode = null,
    string? Error = null)
{
    public bool IsAccepted => Outcome == OpenCodeRecoveryOutcome.Accepted;
    public bool IsAmbiguous => Outcome == OpenCodeRecoveryOutcome.Ambiguous;
}

public sealed record OpenCodeRecoveryActionResult(
    OpenCodeRecoveryOutcome Outcome,
    string? ErrorCode = null,
    string? Error = null)
{
    public bool IsAccepted => Outcome == OpenCodeRecoveryOutcome.Accepted;
}

/// <summary>
/// Reads and controls one exact OpenCode root session through its loopback HTTP API.
/// This client never sends keystrokes to the terminal or invokes TUI-control routes.
/// </summary>
public sealed class OpenCodeRecoveryClient : IDisposable
{
    private const int MaximumJsonPayloadBytes = 2 * 1024 * 1024;
    private const int MaximumSessionListBytes = 2 * 1024 * 1024;
    private const int MaximumSessions = 200;
    private const int MaximumDescendants = 100;
    private const int MaximumDescendantDepth = 16;
    private const int MaximumMessages = 50;
    private const int MaximumPromptCharacters = 16 * 1024;
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(3);
    private static readonly TimeSpan ReadTimeout = TimeSpan.FromSeconds(12);
    private static readonly object MessageIdGate = new();
    private static long _lastMessageTimestamp;
    private static long _messageCounter;

    private readonly Uri _serverUri;
    private readonly string _directory;
    private readonly HttpClient _httpClient;
    private readonly bool _ownsHttpClient;
    private readonly string? _authorization;
    private bool _disposed;

    public OpenCodeRecoveryClient(Uri serverUri, string directory, HttpClient? httpClient = null)
    {
        ArgumentNullException.ThrowIfNull(serverUri);
        ArgumentException.ThrowIfNullOrWhiteSpace(directory);

        if (!serverUri.IsAbsoluteUri || (serverUri.Scheme != Uri.UriSchemeHttp && serverUri.Scheme != Uri.UriSchemeHttps))
            throw new ArgumentException("The OpenCode server URI must be an absolute HTTP URI.", nameof(serverUri));
        if (!serverUri.IsLoopback)
            throw new ArgumentException("The OpenCode recovery server must use a loopback address.", nameof(serverUri));
        if (!string.IsNullOrEmpty(serverUri.UserInfo))
            throw new ArgumentException("Credentials must be supplied through OpenCode server environment settings.", nameof(serverUri));
        if (!string.IsNullOrEmpty(serverUri.Query) || !string.IsNullOrEmpty(serverUri.Fragment))
            throw new ArgumentException("The OpenCode server URI cannot include a query or fragment.", nameof(serverUri));

        _serverUri = serverUri;
        _directory = Path.GetFullPath(directory);
        _authorization = CreateAuthorizationHeader();
        if (httpClient is null)
        {
            _httpClient = new HttpClient(new HttpClientHandler
            {
                UseProxy = false,
                AllowAutoRedirect = false
            });
            _httpClient.Timeout = Timeout.InfiniteTimeSpan;
            _ownsHttpClient = true;
        }
        else
        {
            _httpClient = httpClient;
        }
    }

    /// <summary>
    /// Creates the same ascending, time-sortable message ID shape used by
    /// OpenCode 1.18.31 (`Identifier.ascending("message")`).
    /// </summary>
    public static string CreateMessageId()
    {
        long timestamp;
        long counter;
        lock (MessageIdGate)
        {
            long current = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            timestamp = Math.Max(current, _lastMessageTimestamp);
            if (timestamp == _lastMessageTimestamp)
                _messageCounter++;
            else
                _messageCounter = 1;
            _lastMessageTimestamp = timestamp;
            counter = _messageCounter;
        }

        ulong encoded = checked((ulong)timestamp * 0x1000UL + (ulong)counter);
        Span<byte> timeBytes = stackalloc byte[6];
        for (int index = 5; index >= 0; index--)
        {
            timeBytes[index] = (byte)(encoded & 0xff);
            encoded >>= 8;
        }

        const string alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        byte[] randomBytes = RandomNumberGenerator.GetBytes(14);
        Span<char> randomSuffix = stackalloc char[14];
        for (int index = 0; index < randomSuffix.Length; index++)
            randomSuffix[index] = alphabet[randomBytes[index] % alphabet.Length];
        return "msg_" + Convert.ToHexStringLower(timeBytes) + randomSuffix.ToString();
    }

    /// <summary>Reads fresh evidence for one listed, exact, root session.</summary>
    public async Task<OpenCodeRecoveryReadResult> ReadAsync(string sessionId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sessionId);
        ObjectDisposedException.ThrowIf(_disposed, this);

        using var operationTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        operationTimeout.CancelAfter(ReadTimeout);
        CancellationToken token = operationTimeout.Token;

        try
        {
            JsonElement listedSession;
            JsonElement detailedSession;
            using (JsonDocument listDocument = await GetJsonAsync(
                       BuildEndpoint("/session", query: $"limit={MaximumSessions.ToString(CultureInfo.InvariantCulture)}"),
                       token,
                       MaximumSessionListBytes).ConfigureAwait(false))
            {
                JsonElement list = RequireArray(listDocument.RootElement, "session list");
                JsonElement[] matching = list.EnumerateArray()
                    .Where(item => StringEquals(GetString(item, "id"), sessionId))
                    .ToArray();
                if (matching.Length == 0)
                    return Unavailable("session_missing", "The exact session ID is not present in the directory-scoped session list.");
                if (matching.Length != 1)
                    return Unavailable("session_ambiguous", "The directory-scoped session list returned the exact session ID more than once.");
                listedSession = matching[0].Clone();
            }

            using (JsonDocument detailDocument = await GetJsonAsync(BuildSessionEndpoint(sessionId), token).ConfigureAwait(false))
                detailedSession = detailDocument.RootElement.Clone();

            if (!ValidateSessionIdentity(listedSession, sessionId, out string? identityError) ||
                !ValidateSessionIdentity(detailedSession, sessionId, out identityError))
                return Unavailable("identity_mismatch", identityError ?? "The session identity does not match the requested root session.");

            if (GetString(listedSession, "parentID") is not null || GetString(detailedSession, "parentID") is not null)
                return Unavailable("not_root_session", "Recovery is restricted to an exact root session.");

            string? parentSessionId = GetString(detailedSession, "parentID");
            string sessionDirectory = GetString(detailedSession, "directory")!;

            List<(string Id, int Depth)> descendants = await ReadDescendantsAsync(sessionId, token).ConfigureAwait(false);
            HashSet<string> sessionIds = new(StringComparer.Ordinal) { sessionId };
            foreach ((string descendantId, _) in descendants)
                sessionIds.Add(descendantId);

            Task<JsonDocument> statusTask = GetJsonAsync(BuildEndpoint("/session/status"), token);
            Task<JsonDocument> todoTask = GetJsonAsync(BuildSessionEndpoint(sessionId, "/todo"), token);
            Task<JsonDocument> messagesTask = GetJsonAsync(
                BuildSessionEndpoint(sessionId, "/message", $"limit={MaximumMessages.ToString(CultureInfo.InvariantCulture)}"),
                token,
                MaximumJsonPayloadBytes);
            Task<JsonDocument> permissionTask = GetJsonAsync(BuildEndpoint("/permission"), token);
            Task<JsonDocument> questionTask = GetJsonAsync(BuildEndpoint("/question"), token);

            await Task.WhenAll(statusTask, todoTask, messagesTask, permissionTask, questionTask).ConfigureAwait(false);
            using JsonDocument statusDocument = await statusTask.ConfigureAwait(false);
            using JsonDocument todoDocument = await todoTask.ConfigureAwait(false);
            using JsonDocument messagesDocument = await messagesTask.ConfigureAwait(false);
            using JsonDocument permissionDocument = await permissionTask.ConfigureAwait(false);
            using JsonDocument questionDocument = await questionTask.ConfigureAwait(false);

            JsonElement statuses = RequireObject(statusDocument.RootElement, "session status map");
            JsonElement rootStatus = statuses.TryGetProperty(sessionId, out JsonElement directStatus)
                ? directStatus
                : default;
            OpenCodeRecoveryStatus status = rootStatus.ValueKind == JsonValueKind.Undefined
                ? OpenCodeRecoveryStatus.Idle
                : ParseStatus(rootStatus);
            if (status == OpenCodeRecoveryStatus.Unknown)
                return Unavailable("invalid_status", "OpenCode returned an unknown status for the exact session.");

            JsonElement todosElement = RequireArray(todoDocument.RootElement, "session todos");
            (int incompleteTodos, int totalTodos, int completedTodos, string todoFingerprint) = ParseTodos(todosElement);

            JsonElement messagesElement = RequireArray(messagesDocument.RootElement, "session messages");
            JsonElement[] messageRows = messagesElement.EnumerateArray().ToArray();
            if (!messageRows.Any(row => GetString(GetProperty(row, "info"), "role") == "user") &&
                messageRows.Length == MaximumMessages)
            {
                string? parentUserId = GetTruncatedAssistantParentId(messageRows, sessionId);
                if (parentUserId is null)
                    return Unavailable("current_user_unavailable", "The capped assistant-message window does not identify one exact current user parent.");
                JsonElement parentUser = await ReadExactUserParentAsync(sessionId, parentUserId, token).ConfigureAwait(false);
                messageRows = [parentUser, .. messageRows];
            }
            MessageEvidence messages = ParseMessages(messageRows, sessionId, _directory, status);

            HashSet<string> pendingPermissionIds = GetPendingSessionIds(permissionDocument.RootElement, "permissions");
            HashSet<string> pendingQuestionIds = GetPendingSessionIds(questionDocument.RootElement, "questions");
            bool hasPendingPermission = pendingPermissionIds.Contains(sessionId);
            bool hasPendingQuestion = pendingQuestionIds.Contains(sessionId);
            bool hasPendingPermissionInDescendants = pendingPermissionIds.Any(id => sessionIds.Contains(id) && id != sessionId);
            bool hasPendingQuestionInDescendants = pendingQuestionIds.Any(id => sessionIds.Contains(id) && id != sessionId);

            bool hasBusyDescendants = false;
            foreach ((string descendantId, _) in descendants)
            {
                if (!statuses.TryGetProperty(descendantId, out JsonElement descendantStatus))
                    continue; // The v1 status map omits idle sessions.
                if (ParseStatus(descendantStatus) is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry)
                    hasBusyDescendants = true;
                else if (ParseStatus(descendantStatus) == OpenCodeRecoveryStatus.Unknown)
                    return Unavailable("invalid_descendant_status", "OpenCode returned an unknown descendant status.");
            }

            string progressFingerprint = CreateProgressFingerprint(messages.CompletedToolEvidence, completedTodos);
            var evidence = new RecoverySessionEvidence(
                sessionId,
                status,
                parentSessionId,
                sessionDirectory,
                hasPendingPermission,
                hasPendingQuestion,
                hasPendingPermissionInDescendants,
                hasPendingQuestionInDescendants,
                incompleteTodos,
                totalTodos,
                todoFingerprint,
                progressFingerprint,
                messages.HasRunningTools,
                hasBusyDescendants,
                messages.LatestUserMessageId,
                messages.LatestUserMessageCreated,
                messages.LatestAssistantMessageId,
                messages.LatestMessageId,
                messages.HasErrorMarker,
                messages.LatestErrorType,
                status == OpenCodeRecoveryStatus.Retry ? GetInt32(rootStatus, "attempt") : null,
                status == OpenCodeRecoveryStatus.Retry ? GetString(rootStatus, "message") : null,
                status == OpenCodeRecoveryStatus.Retry ? GetInt64(rootStatus, "next") : null)
            {
                AllTodosCompleted = totalTodos > 0 && todosElement.EnumerateArray().All(todo => GetString(todo, "status") == "completed"),
                HasCurrentUserTodoWrite = incompleteTodos > 0 && messages.CurrentUserTodoWriteFingerprint == todoFingerprint,
                HasSuccessfulFinalResponse = messages.HasSuccessfulFinalResponse,
                CompletedTodoCount = completedTodos,
                ActivityFingerprint = messages.ActivityFingerprint,
                StalledLaunchToolFingerprint = messages.StalledLaunchToolFingerprint,
                AbortCancellationToolFingerprint = messages.AbortCancellationToolFingerprint,
                CurrentErrors = messages.CurrentErrors,
                HasConfirmedErrorResponse = messages.HasConfirmedErrorResponse,
                NativeMessages = messages.NativeMessages
            };
            return new OpenCodeRecoveryReadResult(true, evidence);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (OperationCanceledException)
        {
            return Unavailable("timeout", "The OpenCode recovery read exceeded its bounded timeout.");
        }
        catch (RecoveryProtocolException exception)
        {
            return Unavailable(exception.Code, exception.Message);
        }
        catch (HttpRequestException exception)
        {
            return Unavailable("disconnected", "The OpenCode loopback server could not complete the recovery read.", exception);
        }
        catch (IOException exception)
        {
            return Unavailable("invalid_response", "The OpenCode response could not be read safely.", exception);
        }
        catch (JsonException exception)
        {
            return Unavailable("invalid_response", "OpenCode returned malformed recovery JSON.", exception);
        }
    }

    /// <summary>
    /// Sends a continuation into the same session. The supplied user message ID is
    /// checked before POST and reconciled after a lost response; the request is never retried.
    /// </summary>
    public async Task<OpenCodeRecoveryContinueResult> ContinueAsync(
        string sessionId,
        string prompt,
        string messageId,
        CancellationToken cancellationToken = default,
        string? expectedUserMessageId = null,
        bool allowAbortedTurn = false,
        Func<bool>? canSend = null,
        string? expectedProgressFingerprint = null,
        string? expectedTodoFingerprint = null,
        bool allowUntrackedWork = false,
        string? expectedActivityFingerprint = null,
        string? expectedStalledLaunchToolFingerprint = null,
        bool allowCompletedReview = false,
        bool allowErrorRecovery = false,
        bool manualErrorRecovery = false,
        DateTimeOffset? providerRetryAt = null,
        Func<DateTimeOffset>? retryClock = null,
        string? expectedRetryEvidence = null,
        RecoveryModelSelection? model = null, string? agent = null, string? variant = null,
        bool requireCurrentUserTodoWrite = false)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sessionId);
        ArgumentException.ThrowIfNullOrWhiteSpace(prompt);
        ValidateMessageId(messageId);
        ObjectDisposedException.ThrowIf(_disposed, this);

        if (prompt.Length > MaximumPromptCharacters)
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "payload_too_large", "The continuation exceeds the bounded prompt size.");

        OpenCodeRecoveryReadResult read = await ReadAsync(sessionId, cancellationToken).ConfigureAwait(false);
        if (!read.IsAvailable || read.Evidence is null)
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, read.ErrorCode ?? "identity_unavailable", read.Error ?? "The exact session could not be verified.");
        RecoverySessionEvidence evidence = read.Evidence;
        if (requireCurrentUserTodoWrite && (!evidence.HasCurrentUserTodoWrite || !evidence.HasSuccessfulFinalResponse))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Current-request native todo ownership changed before dispatch.");
        if (providerRetryAt is { } mandatory && (retryClock ?? (() => DateTimeOffset.UtcNow))() < mandatory)
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "The provider deadline has not elapsed; no continuation was sent.");
        if (allowErrorRecovery && !IsProviderRetryReady(evidence, providerRetryAt, expectedRetryEvidence, (retryClock ?? (() => DateTimeOffset.UtcNow))()))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "The provider retry deadline or structured failure changed before dispatch.");
        if (expectedUserMessageId is not null && !StringEquals(evidence.LatestUserMessageId, expectedUserMessageId))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "user_message_changed", "The latest user message no longer matches the recovery target.");
        if (expectedProgressFingerprint is not null &&
            !StringEquals(evidence.ProgressFingerprint, expectedProgressFingerprint))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Substantive native progress changed after the recovery decision.");
        if (expectedTodoFingerprint is not null && !StringEquals(evidence.TodoFingerprint, expectedTodoFingerprint))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Native todos changed after the recovery decision.");
        if (expectedActivityFingerprint is not null && !StringEquals(evidence.ActivityFingerprint, expectedActivityFingerprint))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Current-turn native activity changed after the recovery decision.");

        bool expectedAbort = allowAbortedTurn && expectedUserMessageId is not null &&
            StringEquals(evidence.LatestUserMessageId, expectedUserMessageId) &&
            IsExpectedAbortError(evidence, expectedStalledLaunchToolFingerprint);
        bool retryableError = allowErrorRecovery && expectedUserMessageId is not null &&
            (manualErrorRecovery ? OpenCodeFailureClassifier.CanRetryManually(evidence) : OpenCodeFailureClassifier.CanRetryAutomatically(evidence));
        if (evidence.Status != OpenCodeRecoveryStatus.Idle ||
            evidence.HasPendingPermission || evidence.HasPendingQuestion ||
            evidence.HasPendingPermissionInDescendants || evidence.HasPendingQuestionInDescendants ||
            evidence.HasBusyDescendants || evidence.HasRunningTools ||
            (evidence.IncompleteTodoCount == 0 && !retryableError && !CanAllowUntrackedWork(evidence, allowUntrackedWork, expectedUserMessageId) &&
                !CanAllowCompletedReview(evidence, allowCompletedReview, expectedUserMessageId)) ||
            (evidence.HasErrorMarker && !expectedAbort && !retryableError))
        {
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "session_not_ready", "The exact session or one of its descendants is active or waiting for input.");
        }

        cancellationToken.ThrowIfCancellationRequested();
        try
        {
            using var preflightTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            preflightTimeout.CancelAfter(RequestTimeout);
            ExistingMessage existing = await ReadMessageByIdAsync(sessionId, messageId, preflightTimeout.Token).ConfigureAwait(false);
            if (existing.Exists)
            {
                if (existing.IsExactUserMessage)
                    return ContinueResult(OpenCodeRecoveryOutcome.Accepted, messageId, "message_already_present", "The exact user message ID is already present; no POST was sent.");
                return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "message_id_conflict", "The supplied message ID already belongs to another message.");
            }
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception exception) when (exception is HttpRequestException or RecoveryProtocolException or IOException or JsonException or OperationCanceledException)
        {
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "message_preflight_failed", "The user message ID could not be checked; no prompt was sent.", exception);
        }

        var promptPayload = new Dictionary<string, object>
        {
            ["messageID"] = messageId,
            ["parts"] = new[] { new { type = "text", text = prompt, metadata = new { terminalnotes = new { requestID = messageId } } } }
        };
        if (model is not null) promptPayload["model"] = new { providerID = model.ProviderId, modelID = model.ModelId };
        if (agent is not null) promptPayload["agent"] = agent;
        if (variant is not null) promptPayload["variant"] = variant;
        byte[] payload = JsonSerializer.SerializeToUtf8Bytes(promptPayload);
        if (payload.Length > MaximumJsonPayloadBytes)
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "payload_too_large", "The continuation request exceeds the bounded payload size.");

        // Message-ID lookup performs another network round trip, so refresh the
        // approved evidence after it and immediately before the POST.
        OpenCodeRecoveryReadResult finalRead = await ReadAsync(sessionId, cancellationToken).ConfigureAwait(false);
        if (!finalRead.IsAvailable || finalRead.Evidence is null)
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, finalRead.ErrorCode ?? "identity_unavailable", finalRead.Error ?? "The exact session could not be verified.");
        RecoverySessionEvidence finalEvidence = finalRead.Evidence;
        if (requireCurrentUserTodoWrite && (!finalEvidence.HasCurrentUserTodoWrite || !finalEvidence.HasSuccessfulFinalResponse))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Current-request native todo ownership changed before dispatch.");
        if (providerRetryAt is { } finalMandatory && (retryClock ?? (() => DateTimeOffset.UtcNow))() < finalMandatory)
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "The provider deadline has not elapsed; no continuation was sent.");
        if (allowErrorRecovery && !IsProviderRetryReady(finalEvidence, providerRetryAt, expectedRetryEvidence, (retryClock ?? (() => DateTimeOffset.UtcNow))()))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "The provider retry deadline or structured failure changed before dispatch.");
        if (expectedUserMessageId is not null && !StringEquals(finalEvidence.LatestUserMessageId, expectedUserMessageId))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "user_message_changed", "The latest user message changed before dispatch.");
        if (expectedProgressFingerprint is not null &&
            !StringEquals(finalEvidence.ProgressFingerprint, expectedProgressFingerprint))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Substantive native progress changed before dispatch.");
        if (expectedTodoFingerprint is not null && !StringEquals(finalEvidence.TodoFingerprint, expectedTodoFingerprint))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Native todos changed before dispatch.");
        if (expectedActivityFingerprint is not null && !StringEquals(finalEvidence.ActivityFingerprint, expectedActivityFingerprint))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "progress_changed", "Current-turn native activity changed before dispatch.");
        bool finalExpectedAbort = allowAbortedTurn && expectedUserMessageId is not null &&
            StringEquals(finalEvidence.LatestUserMessageId, expectedUserMessageId) &&
            IsExpectedAbortError(finalEvidence, expectedStalledLaunchToolFingerprint);
        bool finalRetryableError = allowErrorRecovery && expectedUserMessageId is not null &&
            (manualErrorRecovery ? OpenCodeFailureClassifier.CanRetryManually(finalEvidence) : OpenCodeFailureClassifier.CanRetryAutomatically(finalEvidence));
        if (allowErrorRecovery && (!retryableError || !finalRetryableError))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "error_changed", "The exact native failure changed before dispatch.");
        bool allowFinalUntrackedWork = CanAllowUntrackedWork(finalEvidence, allowUntrackedWork, expectedUserMessageId);
        if (!IsContinuationReady(finalEvidence, finalExpectedAbort || finalRetryableError, finalRetryableError || allowFinalUntrackedWork ||
            CanAllowCompletedReview(finalEvidence, allowCompletedReview, expectedUserMessageId)))
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "session_not_ready", "The exact session or one of its descendants became active or blocked before dispatch.");

        using var request = new HttpRequestMessage(HttpMethod.Post, BuildSessionEndpoint(sessionId, "/prompt_async"));
        request.Content = new ByteArrayContent(payload);
        request.Content.Headers.ContentType = new MediaTypeHeaderValue("application/json");
        if (canSend is not null && !canSend())
            return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "recovery_guard_changed", "Recovery ownership, project context, or the target turn changed before dispatch.");
        cancellationToken.ThrowIfCancellationRequested();
        try
        {
            using HttpResponseMessage response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
            if (response.IsSuccessStatusCode)
                return ContinueResult(OpenCodeRecoveryOutcome.Accepted, messageId);
            if ((int)response.StatusCode is >= 400 and < 500)
                return ContinueResult(OpenCodeRecoveryOutcome.Rejected, messageId, "http_rejected", $"OpenCode rejected the continuation with HTTP {(int)response.StatusCode}.");

            bool confirmed = await TryConfirmMessageAsync(sessionId, messageId, cancellationToken).ConfigureAwait(false);
            return confirmed
                ? ContinueResult(OpenCodeRecoveryOutcome.Accepted, messageId, "message_confirmed", "The exact user message is present after an uncertain HTTP response.")
                : ContinueResult(OpenCodeRecoveryOutcome.Ambiguous, messageId, "response_ambiguous", "The continuation response was uncertain and the message could not be confirmed; it was not resent.");
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            return ContinueResult(OpenCodeRecoveryOutcome.Ambiguous, messageId, "cancelled_after_send", "The request was cancelled after dispatch may have begun; verify this message ID before taking further action.");
        }
        catch (Exception exception) when (exception is HttpRequestException or IOException or OperationCanceledException)
        {
            bool confirmed = await TryConfirmMessageAsync(sessionId, messageId, cancellationToken).ConfigureAwait(false);
            return confirmed
                ? ContinueResult(OpenCodeRecoveryOutcome.Accepted, messageId, "message_confirmed", "The exact user message is present after the HTTP response was lost.")
                : ContinueResult(OpenCodeRecoveryOutcome.Ambiguous, messageId, "response_ambiguous", "The continuation response was lost and the message could not be confirmed; it was not resent.", exception);
        }
    }

    /// <summary>Reads the native effective compaction-agent selection without changing configuration.</summary>
    public async Task<RecoveryModelSelection?> GetCompactionModelAsync(RecoveryModelSelection workModel, CancellationToken cancellationToken = default)
    {
        try
        {
            using JsonDocument agents = await GetJsonAsync(BuildEndpoint("/agent"), cancellationToken, MaximumJsonPayloadBytes).ConfigureAwait(false);
            if (agents.RootElement.ValueKind != JsonValueKind.Array) return null;
            var compaction = agents.RootElement.EnumerateArray().Where(agent => GetString(agent, "name") == "compaction").ToArray();
            if (compaction.Length != 1 || GetProperty(compaction[0], "disable").ValueKind == JsonValueKind.True) return null;
            JsonElement model = GetProperty(compaction[0], "model");
            if (model.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined) return workModel;
            return ParseMessageModel(compaction[0]);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested) { throw; }
        catch (Exception exception) when (exception is RecoveryProtocolException or HttpRequestException or IOException or JsonException or OperationCanceledException) { return null; }
    }

    /// <summary>
    /// Native summarize is non-idempotent. This method sends at most once; even HTTP
    /// true only acknowledges the handler, and the caller must verify the new summary.
    /// </summary>
    public async Task<OpenCodeRecoveryActionResult> CompactAsync(string sessionId, string expectedUserMessageId,
        RecoveryModelSelection workModel, RecoveryModelSelection summaryModel, string expectedActivityFingerprint,
        string expectedProgressFingerprint, string expectedTodoFingerprint, Func<bool> canSend,
        DateTimeOffset? providerRetryAt = null, Func<DateTimeOffset>? retryClock = null,
        CancellationToken cancellationToken = default, string? expectedRetryEvidence = null, bool allowInterruptedCompaction = false)
    {
        bool Ready(RecoverySessionEvidence evidence) => evidence.LatestUserMessageId == expectedUserMessageId &&
            evidence.Status == OpenCodeRecoveryStatus.Idle && !evidence.HasRunningTools && !evidence.HasBusyDescendants &&
            !evidence.HasPendingPermission && !evidence.HasPendingQuestion && !evidence.HasPendingPermissionInDescendants &&
            !evidence.HasPendingQuestionInDescendants && evidence.ActivityFingerprint == expectedActivityFingerprint &&
            evidence.ProgressFingerprint == expectedProgressFingerprint && evidence.TodoFingerprint == expectedTodoFingerprint &&
            (OpenCodeFailureClassifier.CanCompact(evidence) ||
                evidence.NativeMessages.Any(message => message.Id == expectedUserMessageId && message.IsCompaction) &&
                (OpenCodeFailureClassifier.CanRetryAutomatically(evidence) ||
                    allowInterruptedCompaction && !evidence.HasErrorMarker && !evidence.HasSuccessfulFinalResponse &&
                    !evidence.NativeMessages.Any(message => message.Role == "assistant" && message.ParentId == expectedUserMessageId &&
                        (!message.IsSummary || message.IsFinished)))) &&
            IsProviderRetryReady(evidence, providerRetryAt, expectedRetryEvidence, (retryClock ?? (() => DateTimeOffset.UtcNow))()) &&
            (evidence.NativeRetryAt is null || (retryClock ?? (() => DateTimeOffset.UtcNow))() >= evidence.NativeRetryAt);
        var read = await ReadAsync(sessionId, cancellationToken).ConfigureAwait(false);
        if (read.Evidence is not { } evidence || !read.IsAvailable || !Ready(evidence))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "session_not_ready", "The exact overflow turn is unavailable, changed or blocked; no compaction was sent.");
        var selected = await GetCompactionModelAsync(workModel, cancellationToken).ConfigureAwait(false);
        if (selected != summaryModel)
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "compaction_model_changed", "The effective native compaction model changed; no compaction was sent.");
        var final = await ReadAsync(sessionId, cancellationToken).ConfigureAwait(false);
        if (!final.IsAvailable || final.Evidence is not { } fresh || !Ready(fresh) ||
            fresh.CurrentErrors.Select(error => error.RetryEvidenceId).SequenceEqual(evidence.CurrentErrors.Select(error => error.RetryEvidenceId)) == false)
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "progress_changed", "Native overflow evidence changed before compaction; no compaction was sent.");
        if (!canSend()) return ActionResult(OpenCodeRecoveryOutcome.Rejected, "recovery_guard_changed", "Recovery ownership changed; no compaction was sent.");
        cancellationToken.ThrowIfCancellationRequested();
        using var request = new HttpRequestMessage(HttpMethod.Post, BuildSessionEndpoint(sessionId, "/summarize"));
        request.Content = new ByteArrayContent(JsonSerializer.SerializeToUtf8Bytes(new
        { providerID = workModel.ProviderId, modelID = workModel.ModelId, auto = false }));
        request.Content.Headers.ContentType = new MediaTypeHeaderValue("application/json");
        try
        {
            using var response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
            // The native handler may already have persisted a compaction user before
            // returning any response, including errors. Never classify an HTTP error
            // after dispatch as proof that this mutation did not happen.
            return ActionResult(response.IsSuccessStatusCode ? OpenCodeRecoveryOutcome.Accepted : OpenCodeRecoveryOutcome.Ambiguous,
                response.IsSuccessStatusCode ? null : "compaction_response_ambiguous");
        }
        catch (Exception exception) when (exception is HttpRequestException or IOException or OperationCanceledException or RecoveryProtocolException)
        { return ActionResult(OpenCodeRecoveryOutcome.Ambiguous, "compaction_response_ambiguous", "Native compaction delivery must be reconciled before any further mutation.", exception); }
    }

    /// <summary>Aborts the verified exact root session using OpenCode's native abort endpoint.</summary>
    public async Task<OpenCodeRecoveryActionResult> AbortAsync(
        string sessionId,
        CancellationToken cancellationToken = default,
        string? expectedUserMessageId = null,
        Func<bool>? canSend = null,
        string? expectedProgressFingerprint = null,
        string? expectedTodoFingerprint = null,
        bool allowUntrackedWork = false,
        string? expectedActivityFingerprint = null,
        string? expectedStalledLaunchToolFingerprint = null,
        Func<DateTimeOffset>? retryClock = null,
        string? expectedRetryEvidence = null,
        DateTimeOffset? providerRetryAt = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sessionId);
        ObjectDisposedException.ThrowIf(_disposed, this);

        OpenCodeRecoveryReadResult read = await ReadAsync(sessionId, cancellationToken).ConfigureAwait(false);
        if (!read.IsAvailable || read.Evidence is null)
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, read.ErrorCode ?? "identity_unavailable", read.Error ?? "The exact session could not be verified.");
        RecoverySessionEvidence evidence = read.Evidence;
        if (providerRetryAt is { } scheduled && (retryClock ?? (() => DateTimeOffset.UtcNow))() < scheduled ||
            expectedRetryEvidence is not null && expectedRetryEvidence != string.Join("|", evidence.CurrentErrors.Select(error => error.RetryEvidenceId)) ||
            evidence.HasErrorMarker && !IsProviderRetryReady(evidence, providerRetryAt, expectedRetryEvidence, (retryClock ?? (() => DateTimeOffset.UtcNow))()))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "progress_changed", "Provider retry timing or structured error evidence changed before abort.");
        if (expectedUserMessageId is not null && !StringEquals(evidence.LatestUserMessageId, expectedUserMessageId))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "user_message_changed", "The latest user message no longer matches the abort target.");
        if (expectedProgressFingerprint is not null && !StringEquals(evidence.ProgressFingerprint, expectedProgressFingerprint) ||
            expectedTodoFingerprint is not null && !StringEquals(evidence.TodoFingerprint, expectedTodoFingerprint) ||
            expectedActivityFingerprint is not null && !StringEquals(evidence.ActivityFingerprint, expectedActivityFingerprint))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "progress_changed", "Native progress or current-turn activity changed after the recovery decision.");
        if (!IsAbortable(evidence, CanAllowUntrackedWork(evidence, allowUntrackedWork, expectedUserMessageId), expectedStalledLaunchToolFingerprint, (retryClock ?? (() => DateTimeOffset.UtcNow))()))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "session_not_abortable", "The exact session is not a stalled busy turn with incomplete work and no active tool, descendant, error, or input blocker.");

        // Re-read immediately before abort so newly observed activity disarms it.
        OpenCodeRecoveryReadResult finalRead = await ReadAsync(sessionId, cancellationToken).ConfigureAwait(false);
        if (!finalRead.IsAvailable || finalRead.Evidence is null)
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, finalRead.ErrorCode ?? "identity_unavailable", finalRead.Error ?? "The exact session could not be verified.");
        RecoverySessionEvidence finalEvidence = finalRead.Evidence;
        if (providerRetryAt is { } finalScheduled && (retryClock ?? (() => DateTimeOffset.UtcNow))() < finalScheduled ||
            expectedRetryEvidence is not null && expectedRetryEvidence != string.Join("|", finalEvidence.CurrentErrors.Select(error => error.RetryEvidenceId)) ||
            finalEvidence.HasErrorMarker && !IsProviderRetryReady(finalEvidence, providerRetryAt, expectedRetryEvidence, (retryClock ?? (() => DateTimeOffset.UtcNow))()))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "progress_changed", "Provider retry timing or structured error evidence changed before abort.");
        if (expectedUserMessageId is not null && !StringEquals(finalEvidence.LatestUserMessageId, expectedUserMessageId))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "user_message_changed", "The latest user message changed before abort.");
        if (expectedProgressFingerprint is not null && !StringEquals(finalEvidence.ProgressFingerprint, expectedProgressFingerprint) ||
            expectedTodoFingerprint is not null && !StringEquals(finalEvidence.TodoFingerprint, expectedTodoFingerprint) ||
            expectedActivityFingerprint is not null && !StringEquals(finalEvidence.ActivityFingerprint, expectedActivityFingerprint))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "progress_changed", "Native progress or current-turn activity changed before abort.");
        if (!IsAbortable(finalEvidence, CanAllowUntrackedWork(finalEvidence, allowUntrackedWork, expectedUserMessageId), expectedStalledLaunchToolFingerprint, (retryClock ?? (() => DateTimeOffset.UtcNow))()))
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "session_not_abortable", "The exact session is no longer a stalled busy turn with no active blocker.");

        using var request = new HttpRequestMessage(HttpMethod.Post, BuildSessionEndpoint(sessionId, "/abort"));
        request.Content = new ByteArrayContent("{}"u8.ToArray());
        request.Content.Headers.ContentType = new MediaTypeHeaderValue("application/json");
        if (canSend is not null && !canSend())
            return ActionResult(OpenCodeRecoveryOutcome.Rejected, "recovery_guard_changed", "Recovery ownership or project context changed before abort dispatch.");
        cancellationToken.ThrowIfCancellationRequested();
        try
        {
            using var actionTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            actionTimeout.CancelAfter(RequestTimeout);
            using HttpResponseMessage response = await SendAsync(request, actionTimeout.Token).ConfigureAwait(false);
            if (response.IsSuccessStatusCode)
            {
                byte[] responseBody = await ReadBoundedAsync(
                    await response.Content.ReadAsStreamAsync(actionTimeout.Token).ConfigureAwait(false),
                    1024,
                    actionTimeout.Token).ConfigureAwait(false);
                if (responseBody.Length == 0 || !bool.TryParse(Encoding.UTF8.GetString(responseBody), out bool aborted) || !aborted)
                    return ActionResult(OpenCodeRecoveryOutcome.Rejected, "abort_not_confirmed", "OpenCode did not confirm that the exact session was aborted.");
                return ActionResult(OpenCodeRecoveryOutcome.Accepted);
            }
            if ((int)response.StatusCode is >= 400 and < 500)
                return ActionResult(OpenCodeRecoveryOutcome.Rejected, "http_rejected", $"OpenCode rejected the abort with HTTP {(int)response.StatusCode}.");
            return ActionResult(OpenCodeRecoveryOutcome.Ambiguous, "response_ambiguous", "The abort response was uncertain.");
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            return ActionResult(OpenCodeRecoveryOutcome.Ambiguous, "cancelled_after_send", "The abort request may have reached OpenCode before cancellation.");
        }
        catch (Exception exception) when (exception is HttpRequestException or IOException or OperationCanceledException)
        {
            return ActionResult(OpenCodeRecoveryOutcome.Ambiguous, "response_ambiguous", "The abort response was lost.", exception);
        }
    }

    private static bool IsProviderRetryReady(RecoverySessionEvidence evidence, DateTimeOffset? anchoredDeadline, string? expectedEvidence, DateTimeOffset now)
    {
        if (anchoredDeadline is { } deadline && now < deadline) return false;
        if (expectedEvidence is not null && expectedEvidence != string.Join("|", evidence.CurrentErrors.Select(error => error.RetryEvidenceId))) return false;
        // A delay must be anchored by a verified observation; direct callers
        // without one cannot skip a newly published provider wait.
        if (evidence.CurrentErrors.Any(error => error.RetryAfterUtc is { } absolute && now < absolute)) return false;
        if ((anchoredDeadline is null || expectedEvidence is null) && OpenCodeFailureClassifier.ProviderRetryAt(evidence, now) is { } provider && now < provider) return false;
        return true;
    }

    private static bool CanAllowUntrackedWork(RecoverySessionEvidence evidence, bool allowUntrackedWork, string? expectedUserMessageId) =>
        allowUntrackedWork && !string.IsNullOrWhiteSpace(expectedUserMessageId) &&
        StringEquals(evidence.LatestUserMessageId, expectedUserMessageId) && !evidence.HasSuccessfulFinalResponse;

    private static bool CanAllowCompletedReview(RecoverySessionEvidence evidence, bool enabled, string? expectedUserMessageId) =>
        enabled && !string.IsNullOrWhiteSpace(expectedUserMessageId) &&
        StringEquals(evidence.LatestUserMessageId, expectedUserMessageId) &&
        (evidence.TotalTodoCount == 0 || evidence.AllTodosCompleted) && evidence.HasSuccessfulFinalResponse;

    private static bool IsAbortable(RecoverySessionEvidence evidence, bool allowUntrackedWork, string? expectedLaunchToolFingerprint, DateTimeOffset now) =>
        (evidence.Status == OpenCodeRecoveryStatus.Busy || evidence.Status == OpenCodeRecoveryStatus.Retry &&
            (evidence.NativeRetryAt is not { } retryAt || now >= retryAt)) && (evidence.IncompleteTodoCount > 0 || allowUntrackedWork) &&
        !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
        !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants &&
        (!evidence.HasRunningTools || expectedLaunchToolFingerprint is not null &&
            StringEquals(evidence.StalledLaunchToolFingerprint, expectedLaunchToolFingerprint)) &&
        !evidence.HasBusyDescendants && !evidence.HasSuccessfulFinalResponse &&
        (!evidence.HasErrorMarker || (OpenCodeFailureClassifier.CanRetryAutomatically(evidence) || OpenCodeFailureClassifier.CanCompact(evidence)));

    internal static bool IsExpectedAbortError(RecoverySessionEvidence evidence, string? expectedLaunchFingerprint) =>
        evidence.CurrentErrors.Count > 0 && evidence.CurrentErrors.All(error =>
            StringEquals(error.Type, "MessageAbortedError") ||
            expectedLaunchFingerprint is not null && StringEquals(error.Type, "ToolExecutionAborted") &&
            StringEquals(error.ToolFingerprint, expectedLaunchFingerprint));
    public void Dispose()
    {
        if (_disposed)
            return;
        _disposed = true;
        if (_ownsHttpClient)
            _httpClient.Dispose();
    }

    private static bool IsContinuationReady(RecoverySessionEvidence evidence, bool allowExpectedAbort, bool allowUntrackedWork) =>
        evidence.Status == OpenCodeRecoveryStatus.Idle &&
        !evidence.HasPendingPermission && !evidence.HasPendingQuestion &&
        !evidence.HasPendingPermissionInDescendants && !evidence.HasPendingQuestionInDescendants &&
        !evidence.HasBusyDescendants && !evidence.HasRunningTools && (evidence.IncompleteTodoCount > 0 || allowUntrackedWork) &&
        (!evidence.HasErrorMarker || allowExpectedAbort);

    private async Task<List<(string Id, int Depth)>> ReadDescendantsAsync(string rootSessionId, CancellationToken cancellationToken)
    {
        var result = new List<(string Id, int Depth)>();
        var pending = new Queue<(string Id, int Depth)>();
        var seen = new HashSet<string>(StringComparer.Ordinal) { rootSessionId };
        pending.Enqueue((rootSessionId, 0));

        while (pending.Count > 0)
        {
            (string parentId, int depth) = pending.Dequeue();
            if (depth >= MaximumDescendantDepth)
                throw new RecoveryProtocolException("descendant_limit", "The session tree exceeds the bounded recovery depth.");

            using JsonDocument childDocument = await GetJsonAsync(BuildSessionEndpoint(parentId, "/children"), cancellationToken).ConfigureAwait(false);
            JsonElement children = RequireArray(childDocument.RootElement, "session children");
            foreach (JsonElement child in children.EnumerateArray())
            {
                string? childId = GetString(child, "id");
                string? actualParentId = GetString(child, "parentID");
                if (string.IsNullOrWhiteSpace(childId) || !StringEquals(actualParentId, parentId))
                    throw new RecoveryProtocolException("invalid_child_identity", "A child session did not match its requested parent.");
                if (!ValidateSessionIdentity(child, childId, out string? error))
                    throw new RecoveryProtocolException("invalid_child_identity", error ?? "A child session did not match the configured directory.");
                if (!seen.Add(childId))
                    throw new RecoveryProtocolException("ambiguous_child_tree", "The OpenCode session tree contains a duplicate or cyclic child ID.");
                if (result.Count >= MaximumDescendants)
                    throw new RecoveryProtocolException("descendant_limit", "The session tree exceeds the bounded recovery session count.");

                int childDepth = depth + 1;
                result.Add((childId, childDepth));
                pending.Enqueue((childId, childDepth));
            }
        }

        return result;
    }

    private bool ValidateSessionIdentity(JsonElement session, string expectedSessionId, out string? error)
    {
        string? actualId = GetString(session, "id");
        string? actualDirectory = GetString(session, "directory");
        if (!StringEquals(actualId, expectedSessionId))
        {
            error = "OpenCode returned a different session ID than the one requested.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(actualDirectory) || !DirectoriesEqual(actualDirectory, _directory))
        {
            error = "OpenCode returned a session outside the configured project directory.";
            return false;
        }
        error = null;
        return true;
    }

    private async Task<JsonDocument> GetJsonAsync(Uri endpoint, CancellationToken cancellationToken, int maximumBytes = MaximumJsonPayloadBytes)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, endpoint);
        using HttpResponseMessage response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
        if (response.StatusCode == HttpStatusCode.NotFound)
            throw new RecoveryProtocolException("not_found", "An exact OpenCode recovery resource was not found.");
        if (!response.IsSuccessStatusCode)
            throw new RecoveryProtocolException("http_error", $"OpenCode returned HTTP {(int)response.StatusCode} for a recovery read.");
        if (response.RequestMessage?.RequestUri is Uri finalUri && !IsAllowedFinalUri(finalUri))
            throw new RecoveryProtocolException("redirect_rejected", "OpenCode redirected a loopback recovery request to another address.");

        using Stream stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        byte[] bytes = await ReadBoundedAsync(stream, maximumBytes, cancellationToken).ConfigureAwait(false);
        try
        {
            return JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 48, CommentHandling = JsonCommentHandling.Disallow });
        }
        catch (JsonException exception)
        {
            throw new RecoveryProtocolException("invalid_json", "OpenCode returned malformed recovery JSON.", exception);
        }
    }

    private async Task<byte[]> ReadBoundedAsync(Stream stream, int maximumBytes, CancellationToken cancellationToken)
    {
        using var output = new MemoryStream(Math.Min(maximumBytes, 64 * 1024));
        byte[] buffer = new byte[16 * 1024];
        while (true)
        {
            int read = await stream.ReadAsync(buffer.AsMemory(), cancellationToken).ConfigureAwait(false);
            if (read == 0)
                break;
            if (output.Length + read > maximumBytes)
                throw new RecoveryProtocolException("payload_too_large", "OpenCode returned a response that exceeds the bounded payload size.");
            output.Write(buffer, 0, read);
        }
        return output.ToArray();
    }

    private async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        if (request.RequestUri is null || !IsAllowedFinalUri(request.RequestUri))
            throw new RecoveryProtocolException("non_loopback_rejected", "A recovery request must stay on the configured loopback server.");
        if (_authorization is not null)
            request.Headers.Authorization = AuthenticationHeaderValue.Parse(_authorization);
        request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));

        using var requestTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        requestTimeout.CancelAfter(RequestTimeout);
        HttpResponseMessage response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, requestTimeout.Token).ConfigureAwait(false);
        if (response.RequestMessage?.RequestUri is Uri finalUri && !IsAllowedFinalUri(finalUri))
        {
            response.Dispose();
            throw new RecoveryProtocolException("redirect_rejected", "OpenCode redirected a loopback recovery request to another address.");
        }
        return response;
    }

    private static string? GetTruncatedAssistantParentId(IEnumerable<JsonElement> messages, string sessionId)
    {
        string? parentId = null;
        foreach (JsonElement row in messages)
        {
            JsonElement info = GetProperty(row, "info");
            string? rowParent = GetString(info, "parentID");
            if (GetString(info, "role") != "assistant" ||
                !StringEquals(GetString(info, "sessionID"), sessionId) ||
                string.IsNullOrWhiteSpace(rowParent) ||
                parentId is not null && !StringEquals(parentId, rowParent))
                return null;
            parentId ??= rowParent;
        }
        return parentId;
    }

    private async Task<JsonElement> ReadExactUserParentAsync(string sessionId, string parentId, CancellationToken cancellationToken)
    {
        using JsonDocument document = await GetJsonAsync(
            BuildSessionEndpoint(sessionId, "/message/" + Uri.EscapeDataString(parentId)),
            cancellationToken,
            MaximumJsonPayloadBytes).ConfigureAwait(false);
        JsonElement message = RequireObject(document.RootElement, "exact parent user message");
        JsonElement info = RequireObject(GetProperty(message, "info"), "exact parent user metadata");
        if (!StringEquals(GetString(info, "id"), parentId) ||
            !StringEquals(GetString(info, "sessionID"), sessionId) ||
            GetString(info, "role") != "user")
            throw new RecoveryProtocolException("invalid_current_user_parent", "The exact assistant parent was not a user message in the requested session.");
        _ = RequireArray(GetProperty(message, "parts"), "exact parent user message parts");
        return message.Clone();
    }
    private async Task<ExistingMessage> ReadMessageByIdAsync(string sessionId, string messageId, CancellationToken cancellationToken)
    {
        Uri endpoint = BuildSessionEndpoint(sessionId, "/message/" + Uri.EscapeDataString(messageId));
        using var request = new HttpRequestMessage(HttpMethod.Get, endpoint);
        using HttpResponseMessage response = await SendAsync(request, cancellationToken).ConfigureAwait(false);
        if (response.StatusCode == HttpStatusCode.NotFound)
            return new ExistingMessage(false, false);
        if (!response.IsSuccessStatusCode)
            throw new RecoveryProtocolException("message_lookup_failed", $"OpenCode returned HTTP {(int)response.StatusCode} while checking a message ID.");

        using Stream stream = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(false);
        byte[] bytes = await ReadBoundedAsync(stream, MaximumJsonPayloadBytes, cancellationToken).ConfigureAwait(false);
        using JsonDocument document = JsonDocument.Parse(bytes, new JsonDocumentOptions { MaxDepth = 48 });
        JsonElement info = GetProperty(document.RootElement, "info");
        return new ExistingMessage(
            true,
            StringEquals(GetString(info, "id"), messageId) &&
            StringEquals(GetString(info, "sessionID"), sessionId) &&
            StringEquals(GetString(info, "role"), "user"));
    }

    private async Task<bool> TryConfirmMessageAsync(string sessionId, string messageId, CancellationToken cancellationToken)
    {
        if (cancellationToken.IsCancellationRequested)
            return false;
        using var confirmTimeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        confirmTimeout.CancelAfter(RequestTimeout);
        try
        {
            ExistingMessage existing = await ReadMessageByIdAsync(sessionId, messageId, confirmTimeout.Token).ConfigureAwait(false);
            return existing.IsExactUserMessage;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            return false;
        }
        catch (Exception exception) when (exception is HttpRequestException or RecoveryProtocolException or IOException or JsonException or OperationCanceledException)
        {
            return false;
        }
    }

    private Uri BuildEndpoint(string path, string? query = null)
    {
        string root = _serverUri.GetLeftPart(UriPartial.Authority) + _serverUri.AbsolutePath.TrimEnd('/');
        string uri = root + path;
        List<string> queryParts = new();
        if (query is not null)
            queryParts.Add(query);
        queryParts.Add("directory=" + Uri.EscapeDataString(_directory));
        return new Uri(uri + "?" + string.Join("&", queryParts), UriKind.Absolute);
    }

    private Uri BuildSessionEndpoint(string sessionId, string suffix = "", string? query = null) =>
        BuildEndpoint("/session/" + Uri.EscapeDataString(sessionId) + suffix, query);

    private bool IsAllowedFinalUri(Uri uri) =>
        uri.IsAbsoluteUri && uri.IsLoopback &&
        string.Equals(uri.Scheme, _serverUri.Scheme, StringComparison.OrdinalIgnoreCase) &&
        string.Equals(uri.Host, _serverUri.Host, StringComparison.OrdinalIgnoreCase) &&
        uri.Port == _serverUri.Port;

    private static string? CreateAuthorizationHeader()
    {
        string? password = Environment.GetEnvironmentVariable("OPENCODE_SERVER_PASSWORD");
        if (string.IsNullOrEmpty(password))
            return null;
        string username = Environment.GetEnvironmentVariable("OPENCODE_SERVER_USERNAME") ?? "opencode";
        return "Basic " + Convert.ToBase64String(Encoding.UTF8.GetBytes(username + ":" + password));
    }

    private static bool DirectoriesEqual(string left, string right)
    {
        try
        {
            string leftFull = Path.TrimEndingDirectorySeparator(Path.GetFullPath(left));
            string rightFull = Path.TrimEndingDirectorySeparator(Path.GetFullPath(right));
            return string.Equals(leftFull, rightFull, OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
        }
        catch (ArgumentException)
        {
            return false;
        }
        catch (IOException)
        {
            return false;
        }
    }

    private static JsonElement RequireArray(JsonElement element, string resource) =>
        element.ValueKind == JsonValueKind.Array
            ? element
            : throw new RecoveryProtocolException("invalid_response", $"OpenCode returned an invalid {resource} response.");

    private static JsonElement RequireObject(JsonElement element, string resource) =>
        element.ValueKind == JsonValueKind.Object
            ? element
            : throw new RecoveryProtocolException("invalid_response", $"OpenCode returned an invalid {resource} response.");

    private static string? GetString(JsonElement element, string propertyName)
    {
        if (element.ValueKind != JsonValueKind.Object || !element.TryGetProperty(propertyName, out JsonElement value))
            return null;
        return value.ValueKind == JsonValueKind.String ? value.GetString() : null;
    }

    private static JsonElement GetProperty(JsonElement element, string propertyName) =>
        element.ValueKind == JsonValueKind.Object && element.TryGetProperty(propertyName, out JsonElement value)
            ? value
            : default;

    private static int? GetInt32(JsonElement element, string propertyName)
    {
        JsonElement value = GetProperty(element, propertyName);
        return value.ValueKind == JsonValueKind.Number && value.TryGetInt32(out int result) ? result : null;
    }

    private static long? GetInt64(JsonElement element, string propertyName)
    {
        JsonElement value = GetProperty(element, propertyName);
        return value.ValueKind == JsonValueKind.Number && value.TryGetInt64(out long result) ? result : null;
    }

    private static OpenCodeRecoveryStatus ParseStatus(JsonElement status)
    {
        string? type = GetString(status, "type");
        return type switch
        {
            "idle" => OpenCodeRecoveryStatus.Idle,
            "busy" => OpenCodeRecoveryStatus.Busy,
            "retry" => OpenCodeRecoveryStatus.Retry,
            _ => OpenCodeRecoveryStatus.Unknown
        };
    }

    private static (int Incomplete, int Total, int Completed, string Fingerprint) ParseTodos(JsonElement todos)
    {
        int incomplete = 0;
        int total = 0;
        int completed = 0;
        StringBuilder material = new();
        foreach (JsonElement todo in todos.EnumerateArray())
        {
            string? content = GetString(todo, "content");
            string? status = GetString(todo, "status");
            string? priority = GetString(todo, "priority");
            if (content is null || status is null || priority is null)
                throw new RecoveryProtocolException("invalid_todos", "OpenCode returned a todo without its required content, status, or priority.");
            if (status is not ("pending" or "in_progress" or "completed" or "cancelled"))
                throw new RecoveryProtocolException("invalid_todos", "OpenCode returned a todo with an unknown status.");
            total++;
            if (status is "pending" or "in_progress")
                incomplete++;
            if (status == "completed") completed++;
            AppendFingerprintField(material, content);
            AppendFingerprintField(material, status);
            AppendFingerprintField(material, priority);
        }
        return (incomplete, total, completed, Hash(material.ToString()));
    }

    private static string? ReadTodoWriteFingerprint(JsonElement input)
    {
        JsonElement todos = GetProperty(input, "todos");
        if (todos.ValueKind != JsonValueKind.Array) return null;
        try
        {
            var parsed = ParseTodos(todos);
            return parsed.Incomplete > 0 ? parsed.Fingerprint : null;
        }
        catch (RecoveryProtocolException) { return null; }
    }

    private static MessageEvidence ParseMessages(IEnumerable<JsonElement> messages, string sessionId, string projectDirectory, OpenCodeRecoveryStatus status)
    {
        var parsed = new List<ParsedMessage>();
        var completedToolEvidence = new SortedSet<string>(StringComparer.Ordinal);
        var activeToolEvidence = new List<(string Name, string Status, JsonElement Input)>();
        int index = 0;

        foreach (JsonElement row in messages)
        {
            JsonElement info = GetProperty(row, "info");
            if (info.ValueKind != JsonValueKind.Object)
                throw new RecoveryProtocolException("invalid_messages", "OpenCode returned a message without message metadata.");
            string? id = GetString(info, "id");
            string? role = GetString(info, "role");
            string? actualSessionId = GetString(info, "sessionID");
            if (string.IsNullOrWhiteSpace(id) || (role != "user" && role != "assistant"))
                throw new RecoveryProtocolException("invalid_messages", "OpenCode returned a message without a recognized ID or role.");
            if (actualSessionId is not null && !StringEquals(actualSessionId, sessionId))
                throw new RecoveryProtocolException("message_session_mismatch", "OpenCode returned a message from a different session.");

            DateTimeOffset? created = ParseCreatedTime(GetProperty(GetProperty(info, "time"), "created"));
            int messageIndex = index++;
            bool messageHasError = false;
            bool messageHasRunningTools = false;
            string? messageErrorType = null;
            var rowErrors = new List<RecoveryErrorEvidence>();

            if (GetProperty(info, "error").ValueKind is not (JsonValueKind.Undefined or JsonValueKind.Null))
            {
                messageHasError = true;
                messageErrorType = GetString(GetProperty(info, "error"), "name") ?? GetString(GetProperty(info, "error"), "type") ?? "message_error";
                JsonElement errorData = GetProperty(GetProperty(info, "error"), "data");
                JsonElement retryable = GetProperty(errorData, "isRetryable");
                var retryTiming = ParseProviderRetryTiming(GetProperty(errorData, "responseHeaders"));
                rowErrors.Add(new RecoveryErrorEvidence(messageErrorType, null)
                {
                    HasVerifiedContextOverflow = HasStructuredContextOverflow(errorData),
                    StatusCode = GetInt32(errorData, "statusCode"),
                    IsRetryable = retryable.ValueKind is JsonValueKind.True or JsonValueKind.False ? retryable.GetBoolean() : null,
                    ParentUserMessageId = GetString(info, "parentID"),
                    RetryAfterUtc = retryTiming.At,
                    RetryAfterDelay = retryTiming.Delay,
                    RetryEvidenceId = id + ":" + Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(
                        errorData.ValueKind == JsonValueKind.Undefined ? string.Empty : errorData.GetRawText()))),
                    Message = ErrorMessageText(GetProperty(info, "error"), errorData)
                });
            }

            JsonElement parts = GetProperty(row, "parts");
            if (parts.ValueKind != JsonValueKind.Array)
                throw new RecoveryProtocolException("invalid_messages", "OpenCode returned a message without a parts array.");
            parsed.Add(new ParsedMessage(id, role, created, messageIndex, messageHasError, messageErrorType, false)
            {
                Errors = rowErrors,
                Model = ParseMessageModel(info),
                RequestMarker = ReadRequestMarker(parts),
                Agent = GetString(info, "agent"), Variant = GetString(info, "variant"),
                TextFingerprint = Hash(string.Join("\n", parts.EnumerateArray().Where(part => GetString(part, "type") == "text").Select(part => GetString(part, "text") ?? string.Empty))),
                IsSummary = GetProperty(info, "summary").ValueKind == JsonValueKind.True,
                HasTextContent = parts.EnumerateArray().Any(part => GetString(part, "type") == "text" && !string.IsNullOrWhiteSpace(GetString(part, "text"))),
                IsCompaction = role == "user" && parts.EnumerateArray().Any(part => GetString(part, "type") == "compaction"),
                CompactionAuto = role == "user" && parts.EnumerateArray().Any(part => GetString(part, "type") == "compaction" && GetProperty(part, "auto").ValueKind == JsonValueKind.True),
                IsCompactionContinuation = role == "user" && parts.GetArrayLength() > 0 && parts.EnumerateArray().All(part =>
                    GetString(part, "type") == "text" && GetProperty(part, "synthetic").ValueKind == JsonValueKind.True &&
                    GetProperty(GetProperty(part, "metadata"), "compaction_continue").ValueKind == JsonValueKind.True)
            });
            if (role != "assistant")
                continue;

            StringBuilder activityEvidence = new();
            foreach (JsonElement part in parts.EnumerateArray())
            {
                string? partType = GetString(part, "type");
                if (partType is "text" or "reasoning")
                {
                    AppendFingerprintField(activityEvidence, partType);
                    AppendFingerprintField(activityEvidence, GetString(part, "text") ?? string.Empty);
                }
                else if (partType == "tool")
                {
                    JsonElement activityState = GetProperty(part, "state");
                    AppendFingerprintField(activityEvidence, "tool");
                    AppendFingerprintField(activityEvidence, GetString(part, "tool") ?? string.Empty);
                    AppendFingerprintField(activityEvidence, GetString(activityState, "status") ?? string.Empty);
                    JsonElement activityInput = GetProperty(activityState, "input");
                    AppendFingerprintField(activityEvidence, activityInput.ValueKind == JsonValueKind.Undefined ? string.Empty : activityInput.GetRawText());
                    JsonElement activityOutput = GetProperty(activityState, "output");
                    AppendFingerprintField(activityEvidence, activityOutput.ValueKind == JsonValueKind.Undefined ? string.Empty : activityOutput.GetRawText());
                    JsonElement activityError = GetProperty(activityState, "error");
                    AppendFingerprintField(activityEvidence, activityError.ValueKind == JsonValueKind.Undefined ? string.Empty : activityError.GetRawText());
                }
                if (partType == "tool")
                {
                    JsonElement state = GetProperty(part, "state");
                    string? toolStatus = GetString(state, "status");
                    // Only structured tool evidence can show work between polls. Text,
                    // reasoning, timestamps, and repeated assistant snapshots do not
                    // reset the no-progress limit.
                    JsonElement input = GetProperty(state, "input");
                    if (GetString(part, "tool") == "todowrite" && toolStatus == "completed")
                        parsed[^1] = parsed[^1] with
                        {
                            HasCompletedTodoWrite = true,
                            TodoWriteFingerprint = actualSessionId == sessionId ? ReadTodoWriteFingerprint(input) : null
                        };
                    if (toolStatus == "completed")
                        completedToolEvidence.Add((GetString(part, "tool") ?? string.Empty) + "\n" +
                            (input.ValueKind == JsonValueKind.Undefined ? string.Empty : input.GetRawText()));
                    if (toolStatus is "pending" or "running")
                        messageHasRunningTools = true;
                    if (toolStatus is "pending" or "running")
                        activeToolEvidence.Add((GetString(part, "tool") ?? string.Empty, toolStatus, input));
                    if (toolStatus == "error")
                    {
                        messageHasError = true;
                        bool isAbortCancellation = IsExactToolAbortOutput(state);
                        string errorType = isAbortCancellation ? "ToolExecutionAborted" : "tool_error";
                        messageErrorType ??= errorType;
                        string toolName = GetString(part, "tool") ?? string.Empty;
                        string? toolFingerprint = isAbortCancellation && input.ValueKind == JsonValueKind.Object
                            ? Hash(toolName + "\n" + input.GetRawText())
                            : null;
                        rowErrors.Add(new RecoveryErrorEvidence(errorType, toolFingerprint)
                        {
                            IsToolExecutionError = true,
                            ParentUserMessageId = GetString(info, "parentID")
                        });
                    }
                }
            }
            parsed[^1] = parsed[^1] with
            {
                HasErrorMarker = messageHasError,
                ErrorType = messageErrorType,
                HasRunningTools = messageHasRunningTools,
                Errors = rowErrors,
                ParentId = GetString(info, "parentID"),
                ActivityEvidence = activityEvidence.ToString(),
                // A model can finish with tool-calls before its tools finish.
                // Only a terminal finish or completed timestamp ends that turn.
                IsFinished = GetString(info, "finish") is not (null or "tool-calls") ||
                    created is not null && ParseCreatedTime(GetProperty(GetProperty(info, "time"), "completed")) is { } finishedAt && finishedAt >= created,
                SuccessfulFinish = GetString(info, "finish") == "stop" && created is not null &&
                    ParseCreatedTime(GetProperty(GetProperty(info, "time"), "completed")) is { } completed && completed >= created &&
                    parts.EnumerateArray().Any(part => GetString(part, "type") == "text" && !string.IsNullOrWhiteSpace(GetString(part, "text")))
            };
        }

        ParsedMessage? latestUser = FindLatest(parsed, "user");
        ParsedMessage? latestAssistant = FindLatest(parsed, "assistant");
        ParsedMessage? latest = parsed.OrderBy(item => item.Created ?? DateTimeOffset.MinValue).ThenBy(item => item.Index).LastOrDefault();
        int activeTurnStart = latestUser?.Index ?? latestAssistant?.Index ?? int.MaxValue;
        ParsedMessage[] activeTurnAssistants = parsed
            .Where(item => item.Role == "assistant" && item.Index >= activeTurnStart)
            .ToArray();
        // New queued user receipts can follow a still-streaming assistant in the
        // same busy session. Retain its safety/activity evidence, but never revive
        // finished historical turns or old messages while the session is idle.
        ParsedMessage[] priorOngoingAssistants = status is OpenCodeRecoveryStatus.Busy or OpenCodeRecoveryStatus.Retry
            ? parsed.Where(item => item.Role == "assistant" && item.Index < activeTurnStart && !item.IsFinished &&
                (item.HasRunningTools || item.ActivityEvidence.Length > 0)).ToArray()
            : [];
        ParsedMessage[] activeAssistants = priorOngoingAssistants.Concat(activeTurnAssistants).ToArray();
        ParsedMessage? lastTodoWrite = activeTurnAssistants.Where(item => item.HasCompletedTodoWrite)
            .OrderBy(item => item.Created ?? DateTimeOffset.MinValue).ThenBy(item => item.Index).LastOrDefault();
        string? currentUserTodoWriteFingerprint = latestUser is not null && lastTodoWrite is { IsSummary: false, HasErrorMarker: false, HasRunningTools: false } &&
            lastTodoWrite.ParentId == latestUser.Id && lastTodoWrite.Index > latestUser.Index &&
            latestUser.Created is { } userCreated && lastTodoWrite.Created is { } writtenAt && writtenAt >= userCreated
                ? lastTodoWrite.TodoWriteFingerprint : null;
        RecoveryErrorEvidence[] turnErrors = activeAssistants.SelectMany(item => item.Errors).ToArray();
        // Ordinary tool failures remain native diagnostics/activity while the model
        // handles them. They do not turn a later final or provider failure into a
        // session failure. Keep the full set around aborts so the narrowly scoped
        // expected-abort exception cannot hide another failed tool.
        bool hasAbortCancellation = turnErrors.Any(error => error.Type is "MessageAbortedError" or "ToolExecutionAborted");
        RecoveryErrorEvidence[] currentErrors = hasAbortCancellation ? turnErrors
            : turnErrors.Where(error => !error.IsToolExecutionError || error.Type != "tool_error").ToArray();
        bool hasRunningTools = activeAssistants.Any(item => item.HasRunningTools);
        StringBuilder activityMaterial = new();
        foreach (ParsedMessage assistant in activeAssistants)
            AppendFingerprintField(activityMaterial, assistant.ActivityEvidence);
        string activityFingerprint = Hash(activityMaterial.ToString());
        bool hasErrorMarker = currentErrors.Length > 0;
        string? latestErrorType = currentErrors.LastOrDefault()?.Type;
        RecoveryErrorEvidence[] abortErrors = currentErrors.Where(error => StringEquals(error.Type, "ToolExecutionAborted")).ToArray();
        // Never use a newer queued request to authorize aborting an older launch.
        string? stalledLaunchToolFingerprint = priorOngoingAssistants.Length == 0 && activeToolEvidence.Count == 1 && activeToolEvidence[0].Status == "running" &&
            IsGeneratedAppLaunch(activeToolEvidence[0].Name, activeToolEvidence[0].Input, projectDirectory)
                ? Hash(activeToolEvidence[0].Name + "\n" + activeToolEvidence[0].Input.GetRawText())
                : null;
        return new MessageEvidence(
            latestUser?.Id,
            latestUser?.Created,
            latestAssistant?.Id,
            latest?.Id,
            hasRunningTools,
            hasErrorMarker,
            latestErrorType,
            string.Join("\n", completedToolEvidence))
        {
            NativeMessages = parsed.Select(item => new RecoveryNativeMessage(item.Id, item.Role)
            {
                ParentId = item.ParentId, Model = item.Model, RequestMarker = item.RequestMarker, IsCompaction = item.IsCompaction,
                Agent = item.Agent, Variant = item.Variant, TextFingerprint = item.TextFingerprint,
                CompactionAuto = item.CompactionAuto, IsSummary = item.IsSummary,
                IsCompactionContinuation = item.IsCompactionContinuation, IsFinished = item.IsFinished,
                SuccessfulFinish = item.SuccessfulFinish,
                Errors = item.Errors
            }).ToArray(),
            HasSuccessfulFinalResponse = latestAssistant is { SuccessfulFinish: true, HasErrorMarker: false, IsSummary: false } &&
                latestAssistant.ParentId == latestUser?.Id && latest?.Id == latestAssistant.Id && !hasRunningTools,
            CurrentUserTodoWriteFingerprint = currentUserTodoWriteFingerprint,
            ActivityFingerprint = activityFingerprint,
            StalledLaunchToolFingerprint = stalledLaunchToolFingerprint,
            AbortCancellationToolFingerprint = abortErrors.Length == 1 ? abortErrors[0].ToolFingerprint : null,
            CurrentErrors = currentErrors,
            HasConfirmedErrorResponse = status == OpenCodeRecoveryStatus.Idle && currentErrors.Length > 0 &&
                currentErrors.All(error => error.ParentUserMessageId == latestUser?.Id && error.ParentUserMessageId is not null) && !hasRunningTools
        };
    }

    private static string? ReadRequestMarker(JsonElement parts)
    {
        string? marker = null;
        foreach (var part in parts.EnumerateArray())
        {
            if (GetString(part, "type") != "text") continue;
            string? value = GetString(GetProperty(GetProperty(part, "metadata"), "terminalnotes"), "requestID");
            if (value is null) continue;
            if (value.Length is 0 or > 256 || marker is not null && marker != value) return null;
            marker = value;
        }
        return marker;
    }

    private static RecoveryModelSelection? ParseMessageModel(JsonElement info)
    {
        JsonElement model = GetProperty(info, "model");
        string? provider = GetString(model, "providerID") ?? GetString(info, "providerID");
        string? modelId = GetString(model, "modelID") ?? GetString(info, "modelID");
        return !string.IsNullOrWhiteSpace(provider) && !string.IsNullOrWhiteSpace(modelId) ? new(provider, modelId) : null;
    }

    private static bool HasStructuredContextOverflow(JsonElement data)
    {
        if (GetInt32(data, "statusCode") == 413) return true;
        JsonElement body = GetProperty(data, "responseBody");
        if (body.ValueKind == JsonValueKind.Object)
            return GetString(GetProperty(body, "error"), "code") == "context_length_exceeded";
        if (body.ValueKind != JsonValueKind.String) return false;
        try
        {
            using JsonDocument document = JsonDocument.Parse(body.GetString()!, new JsonDocumentOptions { MaxDepth = 16 });
            return GetString(GetProperty(document.RootElement, "error"), "code") == "context_length_exceeded";
        }
        catch (JsonException) { return false; }
    }

    private static bool IsGeneratedAppLaunch(string toolName, JsonElement input, string projectDirectory)
    {
        if (toolName is not ("bash" or "shell" or "powershell")) return false;
        string? command = GetString(input, "command");
        if (string.IsNullOrWhiteSpace(command) || command.Length > 4096 || command.Contains('\n') || command.Contains('\r')) return false;
        foreach (char forbidden in new[] { ';', '|', '&', '>', '<', '`', '$' })
            if (command.Contains(forbidden)) return false;

        string workingDirectory = projectDirectory;
        string? suppliedWorkdir = GetString(input, "workdir");
        if (suppliedWorkdir is not null)
        {
            if (!TryResolveContainedPath(projectDirectory, projectDirectory, suppliedWorkdir, out string resolvedWorkdir) ||
                !Directory.Exists(resolvedWorkdir)) return false;
            workingDirectory = resolvedWorkdir;
        }

        List<string> args = TokenizeSimpleCommand(command);
        if (args.Count == 0) return false;
        if (args.Count == 1 && args[0].EndsWith(".exe", StringComparison.OrdinalIgnoreCase) &&
            TryResolveContainedPath(projectDirectory, workingDirectory, args[0], out string resolvedExecutable) &&
            File.Exists(resolvedExecutable) && IsAppPath(projectDirectory, resolvedExecutable) &&
            IsProjectApplicationOutput(projectDirectory, resolvedExecutable))
            return true;

        if (args[0].IndexOfAny([Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar]) >= 0 || Path.IsPathRooted(args[0]))
            return false;
        string executable = Path.GetFileName(args[0]);
        if (executable.Equals("dotnet", StringComparison.OrdinalIgnoreCase))
        {
            if (args.Count < 2 || !args[1].Equals("run", StringComparison.OrdinalIgnoreCase)) return false;
            string? projectFile = null;
            bool configurationSeen = false;
            for (int i = 2; i < args.Count; i++)
            {
                if (args[i].Equals("--project", StringComparison.OrdinalIgnoreCase) || args[i].Equals("-p", StringComparison.OrdinalIgnoreCase))
                {
                    if (projectFile is not null || ++i >= args.Count) return false;
                    projectFile = args[i];
                }
                else if (args[i].Equals("--configuration", StringComparison.OrdinalIgnoreCase) || args[i].Equals("-c", StringComparison.OrdinalIgnoreCase))
                {
                    if (configurationSeen || ++i >= args.Count || !IsSupportedAppConfiguration(args[i])) return false;
                    configurationSeen = true;
                }
                else if (args[i].StartsWith("--project=", StringComparison.OrdinalIgnoreCase))
                {
                    if (projectFile is not null || args[i].Length == "--project=".Length) return false;
                    projectFile = args[i]["--project=".Length..];
                }
                else if (args[i].StartsWith("--configuration=", StringComparison.OrdinalIgnoreCase))
                {
                    if (configurationSeen || !IsSupportedAppConfiguration(args[i]["--configuration=".Length..])) return false;
                    configurationSeen = true;
                }
                else if (args[i] is not ("--no-build" or "--no-restore")) return false;
            }
            if (projectFile is not null)
                return TryResolveContainedPath(projectDirectory, workingDirectory, projectFile, out string resolvedProject) &&
                    File.Exists(resolvedProject) && resolvedProject.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase) &&
                    IsAppPath(projectDirectory, resolvedProject) && !IsTestOrBuildName(Path.GetFileNameWithoutExtension(resolvedProject));
            string[] projects = Directory.Exists(workingDirectory)
                ? Directory.GetFiles(workingDirectory, "*.csproj", SearchOption.TopDirectoryOnly)
                : [];
            return projects.Length == 1 && IsAppPath(projectDirectory, projects[0]) &&
                !IsTestOrBuildName(Path.GetFileNameWithoutExtension(projects[0]));
        }

        if (executable.Equals("npm", StringComparison.OrdinalIgnoreCase) && args.Count == 3 &&
            args[1].Equals("run", StringComparison.OrdinalIgnoreCase) &&
            args[2] is "dev" or "start" or "preview")
        {
            string packagePath = Path.Combine(workingDirectory, "package.json");
            try
            {
                using JsonDocument package = JsonDocument.Parse(File.ReadAllText(packagePath));
                JsonElement scripts = GetProperty(package.RootElement, "scripts");
                return GetProperty(scripts, args[2]).ValueKind == JsonValueKind.String &&
                    !IsTestOrBuildName(GetString(scripts, args[2]) ?? string.Empty) && IsAppPath(projectDirectory, packagePath);
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException) { return false; }
        }

        if (args.Count != 2 || !(executable.Equals("node", StringComparison.OrdinalIgnoreCase) ||
            executable.Equals("node.exe", StringComparison.OrdinalIgnoreCase) || executable.Equals("python", StringComparison.OrdinalIgnoreCase) ||
            executable.Equals("python3", StringComparison.OrdinalIgnoreCase) || executable.Equals("python.exe", StringComparison.OrdinalIgnoreCase))) return false;
        string entry = args[1];
        string entryName = Path.GetFileNameWithoutExtension(entry);
        if (!entry.EndsWith(executable.StartsWith("python", StringComparison.OrdinalIgnoreCase) ? ".py" : ".js", StringComparison.OrdinalIgnoreCase) ||
            !entryName.Equals("app", StringComparison.OrdinalIgnoreCase) && !entryName.Equals("server", StringComparison.OrdinalIgnoreCase) &&
            !entryName.Equals("main", StringComparison.OrdinalIgnoreCase) && !entryName.Equals("index", StringComparison.OrdinalIgnoreCase) &&
            !entryName.Equals("web", StringComparison.OrdinalIgnoreCase)) return false;
        return TryResolveContainedPath(projectDirectory, workingDirectory, entry, out string resolvedEntry) &&
            File.Exists(resolvedEntry) && IsAppPath(projectDirectory, resolvedEntry);
    }

    private static bool IsSupportedAppConfiguration(string value) =>
        value.Equals("Debug", StringComparison.OrdinalIgnoreCase) || value.Equals("Release", StringComparison.OrdinalIgnoreCase);

    private static bool IsProjectApplicationOutput(string projectDirectory, string executablePath)
    {
        string relative = Path.GetRelativePath(Path.GetFullPath(projectDirectory), Path.GetFullPath(executablePath));
        string[] parts = relative.Split([Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar], StringSplitOptions.RemoveEmptyEntries);
        int outputIndex = Array.FindIndex(parts, part => part.Equals("bin", StringComparison.OrdinalIgnoreCase) ||
            part.Equals("dist", StringComparison.OrdinalIgnoreCase) || part.Equals("out", StringComparison.OrdinalIgnoreCase));
        if (outputIndex < 0 || outputIndex >= parts.Length - 1)
            return false;
        string name = Path.GetFileNameWithoutExtension(executablePath);
        if (IsTestOrBuildName(name)) return false;
        return !new[] { "msbuild", "csc", "vbc", "testhost", "vstest", "vstest.console", "installer", "setup", "uninstall", "nuget" }
            .Any(excluded => name.Equals(excluded, StringComparison.OrdinalIgnoreCase));
    }

    private static List<string> TokenizeSimpleCommand(string command)
    {
        var result = new List<string>();
        var token = new StringBuilder();
        char quote = '\0';
        bool started = false;
        foreach (char character in command)
        {
            if (quote != '\0')
            {
                if (character == quote) quote = '\0';
                else token.Append(character);
            }
            else if (character is '\'' or '"') { quote = character; started = true; }
            else if (char.IsWhiteSpace(character))
            {
                if (started) { result.Add(token.ToString()); token.Clear(); started = false; }
            }
            else { token.Append(character); started = true; }
        }
        if (quote != '\0') return [];
        if (started) result.Add(token.ToString());
        return result;
    }

    private static bool TryResolveContainedPath(string projectDirectory, string workingDirectory, string candidate, out string resolved)
    {
        try
        {
            resolved = Path.GetFullPath(Path.IsPathRooted(candidate) ? candidate : Path.Combine(workingDirectory, candidate));
            return IsAppPath(projectDirectory, resolved);
        }
        catch (Exception exception) when (exception is ArgumentException or IOException or NotSupportedException)
        {
            resolved = string.Empty;
            return false;
        }
    }

    private static bool IsAppPath(string projectDirectory, string candidate)
    {
        string root = Path.GetFullPath(projectDirectory).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar;
        string full = Path.GetFullPath(candidate);
        StringComparison comparison = OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        if (!full.StartsWith(root, comparison) && !string.Equals(full, root.TrimEnd(Path.DirectorySeparatorChar), comparison)) return false;
        string relative = Path.GetRelativePath(root, full);
        if (relative.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar).Any(IsTestOrBuildName)) return false;
        return HasNoReparsePointInPath(root.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar), relative);
    }

    private static bool HasNoReparsePointInPath(string root, string relative)
    {
        try
        {
            string current = root;
            if ((File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0) return false;
            if (relative == ".") return true;
            foreach (string part in relative.Split([Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar], StringSplitOptions.RemoveEmptyEntries))
            {
                current = Path.Combine(current, part);
                if ((File.Exists(current) || Directory.Exists(current)) &&
                    (File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0) return false;
            }
            return true;
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or ArgumentException or NotSupportedException)
        {
            return false;
        }
    }

    private static bool IsTestOrBuildName(string value) =>
        value.Contains("test", StringComparison.OrdinalIgnoreCase) || value.Contains("spec", StringComparison.OrdinalIgnoreCase) ||
        value.Contains("build", StringComparison.OrdinalIgnoreCase) || value.Contains("migration", StringComparison.OrdinalIgnoreCase) ||
        value.Contains("training", StringComparison.OrdinalIgnoreCase);

    private static bool IsExactToolAbortOutput(JsonElement state)
    {
        string? output = GetString(state, "output");
        string? error = GetString(state, "error");
        return string.Equals(output?.Trim(), "Tool execution aborted", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(error?.Trim(), "Tool execution aborted", StringComparison.OrdinalIgnoreCase);
    }

    private static ParsedMessage? FindLatest(IEnumerable<ParsedMessage> messages, string role) =>
        messages.Where(item => item.Role == role)
            .OrderBy(item => item.Created ?? DateTimeOffset.MinValue)
            .ThenBy(item => item.Index)
            .LastOrDefault();

    private static string? ErrorMessageText(JsonElement error, JsonElement data)
    {
        // Message only (never request content): data.message, the error's own message and the start of the provider body.
        var parts = new List<string>();
        foreach (var source in new[] { data, error })
            if (source.ValueKind == JsonValueKind.Object && GetString(source, "message") is { Length: > 0 } message) parts.Add(message);
        if (data.ValueKind == JsonValueKind.Object && GetString(data, "responseBody") is { Length: > 0 } body)
            parts.Add(body.Length > 600 ? body[..600] : body);
        return parts.Count == 0 ? null : string.Join(" | ", parts);
    }

    private static (DateTimeOffset? At, TimeSpan? Delay) ParseProviderRetryTiming(JsonElement headers)
    {
        DateTimeOffset? at = null;
        TimeSpan? delay = null;
        if (headers.ValueKind != JsonValueKind.Object) return (at, delay);
        foreach (JsonProperty header in headers.EnumerateObject())
        {
            string? value = header.Value.ValueKind == JsonValueKind.String ? header.Value.GetString() : null;
            if (value is null) continue;
            if (header.Name.Equals("retry-after", StringComparison.OrdinalIgnoreCase))
            {
                if (long.TryParse(value, global::System.Globalization.NumberStyles.None,
                    global::System.Globalization.CultureInfo.InvariantCulture, out long seconds) && seconds >= 0)
                    delay = TimeSpan.FromTicks(Math.Min(seconds, TimeSpan.MaxValue.Ticks / TimeSpan.TicksPerSecond) * TimeSpan.TicksPerSecond);
                else if (DateTimeOffset.TryParse(value, global::System.Globalization.CultureInfo.InvariantCulture,
                    global::System.Globalization.DateTimeStyles.AssumeUniversal, out var retryDate) && (at is null || retryDate > at)) at = retryDate;
            }
            else if (header.Name.Equals("x-ratelimit-reset", StringComparison.OrdinalIgnoreCase) &&
                long.TryParse(value, global::System.Globalization.NumberStyles.None,
                    global::System.Globalization.CultureInfo.InvariantCulture, out long reset) && reset >= 0)
            {
                try
                {
                    var resetDate = reset >= 1_000_000_000_000 ? DateTimeOffset.FromUnixTimeMilliseconds(reset) : DateTimeOffset.FromUnixTimeSeconds(reset);
                    if (at is null || resetDate > at) at = resetDate;
                }
                catch (ArgumentOutOfRangeException) { at = DateTimeOffset.MaxValue; }
            }
        }
        return (at, delay);
    }

    private static DateTimeOffset? ParseCreatedTime(JsonElement value)
    {
        if (value.ValueKind == JsonValueKind.Number && value.TryGetInt64(out long epochMilliseconds))
        {
            try { return DateTimeOffset.FromUnixTimeMilliseconds(epochMilliseconds); }
            catch (ArgumentOutOfRangeException) { return null; }
        }
        if (value.ValueKind == JsonValueKind.String && DateTimeOffset.TryParse(value.GetString(), CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out DateTimeOffset parsed))
            return parsed;
        return null;
    }

    private static HashSet<string> GetPendingSessionIds(JsonElement requests, string resource)
    {
        JsonElement array = RequireArray(requests, resource);
        HashSet<string> result = new(StringComparer.Ordinal);
        foreach (JsonElement item in array.EnumerateArray())
        {
            string? sessionId = GetString(item, "sessionID");
            if (string.IsNullOrWhiteSpace(sessionId))
                throw new RecoveryProtocolException("invalid_pending_input", $"OpenCode returned a {resource} entry without a session ID.");
            result.Add(sessionId);
        }
        return result;
    }

    private static string CreateProgressFingerprint(string completedToolEvidence, int completedTodoCount)
    {
        StringBuilder material = new();
        AppendFingerprintField(material, completedTodoCount.ToString(CultureInfo.InvariantCulture));
        AppendFingerprintField(material, completedToolEvidence);
        return Hash(material.ToString());
    }

    private static void AppendFingerprintField(StringBuilder builder, string value) =>
        builder.Append(value.Length.ToString(CultureInfo.InvariantCulture)).Append(':').Append(value).Append(';');

    private static string Hash(string material) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(material)));

    private static bool StringEquals(string? left, string? right) => string.Equals(left, right, StringComparison.Ordinal);

    private static void ValidateMessageId(string messageId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(messageId);
        if (messageId.Length > 128 || !messageId.StartsWith("msg_", StringComparison.Ordinal) ||
            messageId.Any(character => !(char.IsAsciiLetterOrDigit(character) || character is '_' or '-')))
            throw new ArgumentException("The OpenCode user message ID must be a bounded msg_ ID.", nameof(messageId));
    }

    private static OpenCodeRecoveryReadResult Unavailable(string code, string message, Exception? exception = null) =>
        new(false, null, code, exception is null ? message : message + " " + exception.GetType().Name + ".");

    private static OpenCodeRecoveryContinueResult ContinueResult(
        OpenCodeRecoveryOutcome outcome,
        string messageId,
        string? code = null,
        string? message = null,
        Exception? exception = null) =>
        new(outcome, messageId, code, exception is null ? message : message + " " + exception.GetType().Name + ".");

    private static OpenCodeRecoveryActionResult ActionResult(
        OpenCodeRecoveryOutcome outcome,
        string? code = null,
        string? message = null,
        Exception? exception = null) =>
        new(outcome, code, exception is null ? message : message + " " + exception.GetType().Name + ".");

    private sealed record ParsedMessage(
        string Id,
        string Role,
        DateTimeOffset? Created,
        int Index,
        bool HasErrorMarker,
        string? ErrorType,
        bool HasRunningTools)
    {
        public bool HasCompletedTodoWrite { get; init; }
        public string? TodoWriteFingerprint { get; init; }
        public string? Agent { get; init; }
        public string? Variant { get; init; }
        public string TextFingerprint { get; init; } = string.Empty;
        public string? RequestMarker { get; init; }
        public RecoveryModelSelection? Model { get; init; }
        public bool IsCompaction { get; init; }
        public bool CompactionAuto { get; init; }
        public bool IsSummary { get; init; }
        public bool IsCompactionContinuation { get; init; }
        public string? ParentId { get; init; }
        public string ActivityEvidence { get; init; } = string.Empty;
        public bool HasTextContent { get; init; }
        public bool SuccessfulFinish { get; init; }
        public bool IsFinished { get; init; }
        public IReadOnlyList<RecoveryErrorEvidence> Errors { get; init; } = Array.Empty<RecoveryErrorEvidence>();
    }

    private sealed record MessageEvidence(
        string? LatestUserMessageId,
        DateTimeOffset? LatestUserMessageCreated,
        string? LatestAssistantMessageId,
        string? LatestMessageId,
        bool HasRunningTools,
        bool HasErrorMarker,
        string? LatestErrorType,
        string CompletedToolEvidence)
    {
        public string? CurrentUserTodoWriteFingerprint { get; init; }
        public IReadOnlyList<RecoveryNativeMessage> NativeMessages { get; init; } = Array.Empty<RecoveryNativeMessage>();
        public bool HasSuccessfulFinalResponse { get; init; }
        public string ActivityFingerprint { get; init; } = string.Empty;
        public string? StalledLaunchToolFingerprint { get; init; }
        public string? AbortCancellationToolFingerprint { get; init; }
        public IReadOnlyList<RecoveryErrorEvidence> CurrentErrors { get; init; } = Array.Empty<RecoveryErrorEvidence>();
        public bool HasConfirmedErrorResponse { get; init; }
    }

    private sealed record ExistingMessage(bool Exists, bool IsExactUserMessage);

    private sealed class RecoveryProtocolException : Exception
    {
        public RecoveryProtocolException(string code, string message, Exception? innerException = null)
            : base(message, innerException) => Code = code;

        public string Code { get; }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_OPENCODERECOVERYPOLICY_CS
#region Services/OpenCodeRecoveryPolicy.cs
namespace TerminalNotes.Services
{
using global::System.Security.Cryptography;
using global::System.Text;


/// <summary>
/// A conservative, deterministic policy for deciding whether an OpenCode turn may be
/// continued or recovered. Callers provide native state and an already-filtered
/// substantive progress fingerprint; polling and heartbeat events must not change it.
/// </summary>
public sealed class OpenCodeRecoveryPolicy
{
    public static readonly TimeSpan IdleSettlePeriod = TimeSpan.FromSeconds(20);
    // A model that sends nothing for minutes while OpenCode's busy timer keeps counting usually resumes after a
    // cancel and resend (self-hosted services), so a response stall is cancelled and resent after 5 minutes.
    public static readonly TimeSpan StalledSuspectPeriod = TimeSpan.FromMinutes(3);
    public static readonly TimeSpan StalledAbortPeriod = TimeSpan.FromMinutes(5);
    // A stuck app-launch command (dev server and the like) keeps the longer interval.
    public static readonly TimeSpan StalledLaunchToolAbortPeriod = TimeSpan.FromMinutes(15);
    public static readonly TimeSpan ContinuationAcknowledgementTimeout = TimeSpan.FromMinutes(2);
    public static readonly TimeSpan MaximumObservationGap = TimeSpan.FromMinutes(2);
    private static readonly TimeSpan[] RetryDelays =
    [
        TimeSpan.FromMinutes(1),
        TimeSpan.FromMinutes(3),
        TimeSpan.FromMinutes(10)
    ];

    private readonly Dictionary<string, SessionState> _sessions = new(StringComparer.Ordinal);

    public void ObservePollingGap(RecoveryObservation observation, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(observation);
        if (string.IsNullOrWhiteSpace(observation.SessionId)) return;
        SessionState state = GetOrCreateState(observation, now);
        // An old accepted abort cannot prove continuous inactivity across a gap.
        // Keep pending/ambiguous actions, retry history and explicit pauses intact.
        state.AbortAcceptedStatusVersion = null;
        Evaluate(observation with { IsConnected = false, Status = OpenCodeRecoveryExecutionState.Unknown }, now);
    }

    public RecoveryDecision Evaluate(RecoveryObservation observation, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(observation);
        if (string.IsNullOrWhiteSpace(observation.SessionId))
            return RecoveryDecision.None("No exact OpenCode session is selected.");

        SessionState state = GetOrCreateState(observation, now);
        state.OfferedDecisionId = null;
        if (observation.ManualStopLatched)
            state.ManualStopLatched = true;
        if (state.ManualStopLatched)
            return RecoveryDecision.Pause("Manual stop is latched for this work request.", RecoveryPhase.Paused);

        if (state.LastEvaluationAt is DateTimeOffset previousEvaluationAt &&
            NonNegativeElapsed(now, previousEvaluationAt) > MaximumObservationGap)
        {
            ReconcileObservation(state, observation, now);
            state.OfferedDecisionId = null;
            state.SafetyBlockedSince ??= previousEvaluationAt;
            state.LastEvaluationAt = now;
            ResetActivityTimers(state, observation, now);
            return RecoveryDecision.None("A long polling gap suspended recovery; waiting for a fresh stable native interval.",
                observation.Status == OpenCodeRecoveryExecutionState.Busy ? RecoveryPhase.Busy : RecoveryPhase.IdleSettling);
        }

        state.LastEvaluationAt = now;
        ReconcileObservation(state, observation, now);
        state.OfferedDecisionId = null;

        if (IsSafetyGateActive(observation, now))
        {
            if (observation.Status == OpenCodeRecoveryExecutionState.Retry && observation.NativeRetryAt is { } nextRetry && now < nextRetry)
                state.AbortAcceptedStatusVersion = null;
            if (state.SafetyBlockedSince is null)
                state.SafetyBlockedSince = now;
            ResetActivityTimers(state, observation, now);
            return RecoveryDecision.None(GetSafetyGateReason(observation), GetSafetyGatePhase(observation));
        }

        if (state.SafetyBlockedSince is DateTimeOffset blockedSince)
        {
            if (state.ContinuationAcknowledgementDeadline is DateTimeOffset acknowledgementDeadline)
                state.ContinuationAcknowledgementDeadline = acknowledgementDeadline + NonNegativeElapsed(now, blockedSince);
            state.SafetyBlockedSince = null;
            ResetActivityTimers(state, observation, now);
            return RecoveryDecision.None("A recovery safety gate cleared; waiting for a fresh stable native interval.",
                observation.Status == OpenCodeRecoveryExecutionState.Busy ? RecoveryPhase.Busy : RecoveryPhase.IdleSettling,
                observation.Status == OpenCodeRecoveryExecutionState.Idle ? now + IdleSettlePeriod : null);
        }

        if (state.PendingDecisionId is Guid pendingId)
        {
            if (state.PendingResult == RecoveryActionResult.Ambiguous && ResolveAmbiguousAction(state, observation, now))
            {
                // Native evidence resolved the ambiguous send. Continue evaluating the
                // resulting state; never repeat the possibly accepted request.
            }
            else
            {
                return RecoveryDecision.None("A recovery action is still awaiting a result or native confirmation.", state.Phase);
            }
        }

        if (state.AwaitingContinuationStatusVersion is not null)
        {
            if (state.ContinuationAcknowledgementDeadline is DateTimeOffset deadline && now >= deadline)
            {
                state.Phase = RecoveryPhase.Paused;
                state.HardPaused = true;
                return RecoveryDecision.Pause(
                    "OpenCode did not acknowledge the continuation with native work or progress within two minutes.", state.Phase);
            }

            return RecoveryDecision.None("Waiting for native busy status or substantive progress after the continuation.",
                RecoveryPhase.AwaitingNativeResponse, state.ContinuationAcknowledgementDeadline);
        }

        if (state.HardPaused)
            return RecoveryDecision.Pause("Automatic recovery is paused for this user request.", RecoveryPhase.Paused);

        if (!HasCurrentRequest(observation))
            return RecoveryDecision.None("There is no confirmed current user request to recover.", RecoveryPhase.WaitingForEvidence);

        if (observation.RunningToolCount > 0 && observation.StalledLaunchToolFingerprint is null)
            return RecoveryDecision.None("An OpenCode tool is still running.", RecoveryPhase.Busy);

        if (state.AbortAcceptedStatusVersion is long waitingForIdleVersion)
        {
            if (observation.Status != OpenCodeRecoveryExecutionState.Idle || observation.NativeStatusVersion <= waitingForIdleVersion)
            {
                state.Phase = RecoveryPhase.AwaitingFreshIdleAfterAbort;
                return RecoveryDecision.None("Waiting for a fresh native idle event after the abort.", state.Phase);
            }

            state.AbortAcceptedStatusVersion = null;
            state.IdleSince = now;
            state.Phase = RecoveryPhase.IdleSettling;
        }

        if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry)
        {
            if (observation.RunningToolCount > 0 && observation.StalledLaunchToolFingerprint is null)
                return RecoveryDecision.None("An OpenCode tool is still running.", RecoveryPhase.Busy);

            if (state.NoProgressSince is not DateTimeOffset noProgressSince)
                return RecoveryDecision.None("Waiting for a stable native busy interval.", RecoveryPhase.Busy);

            TimeSpan stalledFor = NonNegativeElapsed(now, noProgressSince);
            if (stalledFor < StalledSuspectPeriod)
                return RecoveryDecision.None("OpenCode is busy and has not yet reached the stall review period.", RecoveryPhase.Busy);

            state.Phase = RecoveryPhase.StalledSuspected;
            if (!HasKnownUnfinishedWork(observation))
                return RecoveryDecision.None("OpenCode appears stalled, but no known unfinished native todo permits recovery.", state.Phase);

            if (state.NextEligibleAt is DateTimeOffset nextEligibleAt && now < nextEligibleAt)
                return RecoveryDecision.None("Recovery is waiting for its escalating retry delay.", state.Phase, nextEligibleAt);

            TimeSpan abortAfter = observation.StalledLaunchToolFingerprint is null ? StalledAbortPeriod : StalledLaunchToolAbortPeriod;
            if (stalledFor < abortAfter)
                return RecoveryDecision.None("OpenCode appears stalled; waiting before any recovery action.", state.Phase);

            if (observation.RunningToolCount != 0 && observation.StalledLaunchToolFingerprint is null)
                return RecoveryDecision.None("A tool is still running, so a stalled turn will not be interrupted.", state.Phase);

            return CreateDecision(state, observation, RecoveryAction.Abort,
                $"OpenCode has remained busy without substantive progress for {abortAfter.TotalMinutes:0} minutes.", state.Phase);
        }

        if (observation.Status == OpenCodeRecoveryExecutionState.Idle)
        {
            if (observation.HasError && observation.ErrorRecoveryAllowed)
            {
                if (observation.ProviderRetryAt is { } providerRetry && now < providerRetry)
                    return RecoveryDecision.None("The provider requires waiting until its retry deadline.", RecoveryPhase.RetryDelay, providerRetry);
                if (!observation.ManualErrorRecovery && observation.ErrorRetryAt is { } retryAt && now < retryAt)
                    return RecoveryDecision.None("A transient native failure is waiting for its retry delay.", RecoveryPhase.RetryDelay, retryAt);
                return CreateDecision(state, observation, RecoveryAction.Continue,
                    "The exact current native request failed and is eligible for retry.", RecoveryPhase.ReadyToContinue);
            }
            if (!HasKnownUnfinishedWork(observation))
                return RecoveryDecision.None("No known unfinished native todo task remains.", RecoveryPhase.Idle);

            if (state.NextEligibleAt is DateTimeOffset nextEligibleAt && now < nextEligibleAt)
                return RecoveryDecision.None("Recovery is waiting for its escalating retry delay.", state.Phase, nextEligibleAt);

            if (!state.HasWorkEvidence && !observation.HasCurrentUnfinishedRequest && !observation.HasCompletedReviewRequested)
                return RecoveryDecision.None("Waiting for native busy or substantive progress evidence for this request.", RecoveryPhase.WaitingForEvidence);

            if (state.IdleSince is not DateTimeOffset idleSince)
                return RecoveryDecision.None("Waiting for native idle evidence.", RecoveryPhase.WaitingForEvidence);

            TimeSpan idleFor = NonNegativeElapsed(now, idleSince);
            if (idleFor < IdleSettlePeriod)
                return RecoveryDecision.None("OpenCode is idle; allowing the native state to settle.", RecoveryPhase.IdleSettling,
                    idleSince + IdleSettlePeriod);

            return CreateDecision(state, observation, RecoveryAction.Continue,
                "OpenCode is idle and a known unfinished native todo task remains.", RecoveryPhase.ReadyToContinue);
        }

        return RecoveryDecision.None("OpenCode state is not eligible for recovery.", state.Phase);
    }

    /// <summary>Reserves a decision before dispatch so polling cannot dispatch it twice.</summary>
    public bool TryRecordActionAttempted(RecoveryDecision decision, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(decision);
        if (decision.Action is not (RecoveryAction.Continue or RecoveryAction.Abort) ||
            decision.DecisionId == Guid.Empty ||
            string.IsNullOrWhiteSpace(decision.SessionId) ||
            !_sessions.TryGetValue(decision.SessionId, out SessionState? state) ||
            state.OfferedDecisionId != decision.DecisionId ||
            !MatchesIdentity(state, decision))
        {
            return false;
        }

        if (state.PendingDecisionId is not null || state.NextEligibleAt is DateTimeOffset next && now < next)
            return false;

        state.PendingDecisionId = decision.DecisionId;
        state.OfferedDecisionId = null;
        state.PendingAction = decision.Action;
        state.PendingResult = null;
        state.PendingStatusVersion = decision.NativeStatusVersion;
        state.PendingAttemptAt = now;
        if (decision.Action == RecoveryAction.Abort)
            state.AbortAttemptsWithoutProgress++;
        else
            state.AttemptsWithoutProgress++;
        state.Phase = decision.Action == RecoveryAction.Abort
            ? RecoveryPhase.AbortRequested
            : RecoveryPhase.ContinuationRequested;
        return true;
    }

    /// <summary>
    /// Records the transport outcome for a reserved action. Ambiguous outcomes remain
    /// blocked until native status or substantive progress proves the action was handled.
    /// </summary>
    public bool RecordActionResult(Guid decisionId, RecoveryActionResult result, DateTimeOffset now)
    {
        SessionState? state = _sessions.Values.FirstOrDefault(candidate => candidate.PendingDecisionId == decisionId);
        if (state is null || state.PendingAction is null)
            return false;

        state.PendingResult = result;
        switch (result)
        {
            case RecoveryActionResult.Accepted:
                CompleteAcceptedAction(state, now);
                break;
            case RecoveryActionResult.Failed:
                RecoveryAction failedAction = state.PendingAction.Value;
                state.PendingDecisionId = null;
                state.PendingAction = null;
                state.PendingResult = null;
                state.NextEligibleAt = now + GetRetryDelay(failedAction == RecoveryAction.Abort
                    ? state.AbortAttemptsWithoutProgress
                    : state.AttemptsWithoutProgress);
                state.Phase = RecoveryPhase.RetryDelay;
                break;
            case RecoveryActionResult.Ambiguous:
                state.Phase = RecoveryPhase.AwaitingNativeResponse;
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(result), result, "Unknown recovery action result.");
        }

        return true;
    }

    private SessionState GetOrCreateState(RecoveryObservation observation, DateTimeOffset now)
    {
        if (!_sessions.TryGetValue(observation.SessionId, out SessionState? state))
        {
            state = new SessionState(observation, now);
            _sessions.Add(observation.SessionId, state);
            return state;
        }

        bool newSessionEpoch = state.SessionEpoch != observation.SessionEpoch;
        bool newUserWork = state.UserWorkGeneration != observation.UserWorkGeneration ||
                           !string.Equals(state.RequestId, observation.RequestId, StringComparison.Ordinal);
        bool newDocumentBinding = state.MarkdownBindingGeneration != observation.MarkdownBindingGeneration;

        if (newSessionEpoch || newUserWork)
        {
            state = new SessionState(observation, now);
            _sessions[observation.SessionId] = state;
        }
        else if (newDocumentBinding)
        {
            // A plan rebind resets timing and requires fresh activity evidence, while
            // preserving the work request's retry history and backoff.
            state.ResetEvidence(observation, now, preserveRetryHistory: true);
        }

        if (state.WasRecoveryEnabled == false && observation.RecoveryEnabled)
        {
            state.ResetEvidence(observation, now, preserveRetryHistory: false);
            state.ManualStopLatched = false;
            if (observation.Status == OpenCodeRecoveryExecutionState.Idle && HasKnownUnfinishedWork(observation))
                state.HasWorkEvidence = true;
        }

        state.WasRecoveryEnabled = observation.RecoveryEnabled;
        return state;
    }

    private static void ReconcileObservation(SessionState state, RecoveryObservation observation, DateTimeOffset now)
    {
        // A fast, successfully completed exact turn may never be observed Busy.
        // Its final response is an acknowledgement, even when it changed no todos.
        if ((observation.HasSuccessfulFinalResponse || observation.HasConfirmedErrorResponse) && state.AwaitingContinuationStatusVersion is not null &&
            state.ContinuationAcknowledgementStartedAt is { } started && now > started)
        {
            state.AwaitingContinuationStatusVersion = null;
            state.ContinuationAcknowledgementStartedAt = null;
            state.ContinuationAcknowledgementDeadline = null;
            state.Phase = RecoveryPhase.IdleSettling;
        }
        if (observation.IsConnected && observation.ActivityFingerprint is { } activity &&
            !string.Equals(state.LastActivityFingerprint, activity, StringComparison.Ordinal))
        {
            if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry) state.NoProgressSince = now;
            if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry)
                state.AbortAcceptedStatusVersion = null;
            state.LastActivityFingerprint = activity;
        }
        bool hasSubstantiveNativeEvidence = observation.IsConnected &&
            (observation.Status is OpenCodeRecoveryExecutionState.Idle or OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry) &&
            observation.ProgressFingerprint is not null;
        if (hasSubstantiveNativeEvidence &&
            !string.Equals(state.LastProgressFingerprint, observation.ProgressFingerprint, StringComparison.Ordinal))
        {
            if (state.HasBaselineFingerprint)
            {
                state.LastProgressAt = now;
                if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry)
                    state.AbortAcceptedStatusVersion = null;
                state.AttemptsWithoutProgress = 0;
                state.AbortAttemptsWithoutProgress = 0;
                state.NextEligibleAt = null;
                state.HasWorkEvidence = true;
                if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry)
                    state.NoProgressSince = now;
                else if (observation.Status == OpenCodeRecoveryExecutionState.Idle)
                    state.IdleSince = now;

                if (state.AwaitingContinuationStatusVersion is not null &&
                    state.ContinuationAcknowledgementStartedAt is DateTimeOffset acknowledgementStartedAt &&
                    now > acknowledgementStartedAt)
                {
                    state.AwaitingContinuationStatusVersion = null;
                    state.ContinuationAcknowledgementStartedAt = null;
                    state.ContinuationAcknowledgementDeadline = null;
                }
            }

            state.LastProgressFingerprint = observation.ProgressFingerprint;
            state.HasBaselineFingerprint = true;
        }

        if (observation.Status == OpenCodeRecoveryExecutionState.Busy)
        {
            if (state.LastObservedStatus is not (OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry))
            {
                state.BusySince = now;
                state.NoProgressSince = now;
                state.HasWorkEvidence = true;
            }
            else if (state.NoProgressSince is null)
            {
                state.NoProgressSince = now;
            }

            state.IdleSince = null;
            state.Phase = RecoveryPhase.Busy;
        }
        else if (observation.Status == OpenCodeRecoveryExecutionState.Idle)
        {
            bool freshIdleAfterAbort = state.Phase == RecoveryPhase.AwaitingFreshIdleAfterAbort &&
                                       state.AbortAcceptedStatusVersion is long abortVersion &&
                                       observation.NativeStatusVersion > abortVersion;
            if (state.LastObservedStatus == OpenCodeRecoveryExecutionState.Busy || freshIdleAfterAbort)
                state.IdleSince = now;
            else
                state.IdleSince ??= now;

            if (state.LastObservedStatus == OpenCodeRecoveryExecutionState.Busy)
                state.HasWorkEvidence = true;
            state.BusySince = null;
            state.NoProgressSince = null;
            if (state.Phase is not (RecoveryPhase.AbortRequested or RecoveryPhase.AwaitingFreshIdleAfterAbort or
                RecoveryPhase.ContinuationRequested or RecoveryPhase.AwaitingNativeResponse or RecoveryPhase.RetryDelay))
                state.Phase = RecoveryPhase.Idle;
        }
        else if (observation.Status == OpenCodeRecoveryExecutionState.Retry)
        {
            // Native retry attempts/messages are status churn, not model activity.
            // A published future deadline is handled by the safety gate above;
            // expired or missing deadlines receive the normal inactivity interval.
            state.NoProgressSince ??= now;
            state.BusySince ??= now;
            state.IdleSince = null;
            state.Phase = RecoveryPhase.WaitingForNativeRetry;
        }

        if (observation.RunningToolCount > 0)
        {
            state.ToolWasRunning = true;
            if (observation.StalledLaunchToolFingerprint is null)
                state.NoProgressSince = null;
            state.IdleSince = null;
        }
        else if (state.ToolWasRunning)
        {
            state.ToolWasRunning = false;
            if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry)
                state.NoProgressSince = now;
            else if (observation.Status == OpenCodeRecoveryExecutionState.Idle)
                state.IdleSince = now;
        }

        if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry &&
            state.AwaitingContinuationStatusVersion is long continuationVersion &&
            observation.NativeStatusVersion > continuationVersion)
        {
            state.AwaitingContinuationStatusVersion = null;
            state.ContinuationAcknowledgementStartedAt = null;
            state.ContinuationAcknowledgementDeadline = null;
        }

        state.LastObservedStatus = observation.Status;
        state.LastObservedStatusVersion = observation.NativeStatusVersion;
    }

    private static bool ResolveAmbiguousAction(SessionState state, RecoveryObservation observation, DateTimeOffset now)
    {
        if (state.PendingResult != RecoveryActionResult.Ambiguous || state.PendingAction is null)
            return false;

        bool newerNativeStatus = observation.NativeStatusVersion > state.PendingStatusVersion;
        bool progressAfterAttempt = state.LastProgressAt is DateTimeOffset progressAt && progressAt > state.PendingAttemptAt;
        bool resolved = state.PendingAction switch
        {
            RecoveryAction.Abort => newerNativeStatus && observation.Status == OpenCodeRecoveryExecutionState.Idle,
            RecoveryAction.Continue => observation.HasConfirmedContinuationReceipt ||
                (newerNativeStatus && observation.Status == OpenCodeRecoveryExecutionState.Busy) || progressAfterAttempt,
            _ => false
        };

        if (!resolved)
            return false;

        CompleteAcceptedAction(state, now);
        return true;
    }

    private static void CompleteAcceptedAction(SessionState state, DateTimeOffset now)
    {
        RecoveryAction action = state.PendingAction!.Value;
        long pendingVersion = state.PendingStatusVersion;
        state.PendingDecisionId = null;
        state.PendingAction = null;
        state.PendingResult = null;
        state.NextEligibleAt = null;
        if (action == RecoveryAction.Abort)
        {
            state.AbortAcceptedStatusVersion = pendingVersion;
            state.AwaitingContinuationStatusVersion = null;
            state.Phase = RecoveryPhase.AwaitingFreshIdleAfterAbort;
        }
        else
        {
            state.TotalCycles++;
            state.AwaitingContinuationStatusVersion = pendingVersion;
            state.ContinuationAcknowledgementStartedAt = now;
            state.ContinuationAcknowledgementDeadline = now + ContinuationAcknowledgementTimeout;
            state.AbortAcceptedStatusVersion = null;
            state.Phase = RecoveryPhase.AwaitingNativeResponse;
            state.NextEligibleAt = now + GetRetryDelay(state.AttemptsWithoutProgress);
        }
    }

    private static RecoveryDecision CreateDecision(
        SessionState state,
        RecoveryObservation observation,
        RecoveryAction action,
        string reason,
        RecoveryPhase phase)
    {
        state.Phase = phase;
        var decision = new RecoveryDecision(
            CreateDeterministicDecisionId(observation, action, state), action, phase, reason, null,
            observation.SessionId, observation.SessionEpoch, observation.UserWorkGeneration,
            observation.MarkdownBindingGeneration, observation.RequestId,
            observation.NativeStatusVersion);
        state.OfferedDecisionId = decision.DecisionId;
        return decision;
    }

    private static Guid CreateDeterministicDecisionId(
        RecoveryObservation observation,
        RecoveryAction action,
        SessionState state)
    {
        string identity = string.Join('\u001f',
            observation.SessionId,
            observation.SessionEpoch,
            observation.UserWorkGeneration,
            observation.MarkdownBindingGeneration,
            observation.RequestId ?? string.Empty,
            observation.ProgressFingerprint ?? string.Empty,
            (int)action,
            observation.NativeStatusVersion,
            state.AttemptsWithoutProgress,
            state.TotalCycles);
        byte[] digest = SHA256.HashData(Encoding.UTF8.GetBytes(identity));
        return new Guid(digest.AsSpan(0, 16));
    }

    private static bool MatchesIdentity(SessionState state, RecoveryDecision decision) =>
        state.SessionEpoch == decision.SessionEpoch &&
        state.UserWorkGeneration == decision.UserWorkGeneration &&
        state.MarkdownBindingGeneration == decision.MarkdownBindingGeneration &&
        string.Equals(state.RequestId, decision.RequestId, StringComparison.Ordinal);

    private static bool HasCurrentRequest(RecoveryObservation observation) =>
        !string.IsNullOrWhiteSpace(observation.RequestId);

    private static bool HasKnownUnfinishedWork(RecoveryObservation observation) =>
        observation.HasKnownTodoList && observation.UnfinishedTodoCount > 0 || observation.HasCurrentUnfinishedRequest || observation.HasCompletedReviewRequested;

    private static TimeSpan GetRetryDelay(int attemptCount) =>
        RetryDelays[Math.Clamp(attemptCount - 1, 0, RetryDelays.Length - 1)];

    private static TimeSpan NonNegativeElapsed(DateTimeOffset now, DateTimeOffset since) =>
        now <= since ? TimeSpan.Zero : now - since;

    private static bool IsSafetyGateActive(RecoveryObservation observation, DateTimeOffset now) =>
        !observation.RecoveryEnabled ||
        !observation.IsConnected ||
        observation.Status == OpenCodeRecoveryExecutionState.Unknown ||
        observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry &&
            observation.ProviderRetryAt is { } providerRetry && now < providerRetry ||
        observation.Status == OpenCodeRecoveryExecutionState.Retry && observation.NativeRetryAt is { } retryAt && now < retryAt ||
        observation.HasPendingApprovalOrQuestion ||
        observation.HasError && !observation.ErrorRecoveryAllowed ||
        !observation.IsMarkdownValid;

    private static string GetSafetyGateReason(RecoveryObservation observation)
    {
        if (!observation.RecoveryEnabled)
            return "Automatic recovery is disabled.";
        if (!observation.IsConnected || observation.Status == OpenCodeRecoveryExecutionState.Unknown)
            return "OpenCode status is disconnected or unavailable.";
        if (observation.Status == OpenCodeRecoveryExecutionState.Retry)
            return "OpenCode is in its native retry wait; recovery will not interrupt it.";
        if (observation.HasPendingApprovalOrQuestion)
            return "OpenCode is waiting for permission or a question response.";
        if (observation.HasError)
            return "OpenCode reports an error; automatic recovery is paused.";
        return "The saved plan document is not valid for this request.";
    }

    private static RecoveryPhase GetSafetyGatePhase(RecoveryObservation observation)
    {
        if (observation.Status == OpenCodeRecoveryExecutionState.Retry)
            return RecoveryPhase.WaitingForNativeRetry;
        if (observation.HasPendingApprovalOrQuestion)
            return RecoveryPhase.WaitingForInput;
        if (observation.HasError || !observation.IsMarkdownValid)
            return RecoveryPhase.Paused;
        return RecoveryPhase.WaitingForEvidence;
    }

    private static void ResetActivityTimers(SessionState state, RecoveryObservation observation, DateTimeOffset now)
    {
        state.BusySince = observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry && observation.RunningToolCount == 0 ? now : null;
        state.NoProgressSince = observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry && observation.RunningToolCount == 0 ? now : null;
        state.IdleSince = observation.Status == OpenCodeRecoveryExecutionState.Idle && observation.RunningToolCount == 0 ? now : null;
        state.ToolWasRunning = observation.RunningToolCount > 0;
    }

    private sealed class SessionState
    {
        public SessionState(RecoveryObservation observation, DateTimeOffset now)
        {
            SessionEpoch = observation.SessionEpoch;
            LastEvaluationAt = now;
            UserWorkGeneration = observation.UserWorkGeneration;
            MarkdownBindingGeneration = observation.MarkdownBindingGeneration;
            RequestId = observation.RequestId;
            LastProgressFingerprint = observation.ProgressFingerprint;
            LastActivityFingerprint = observation.ActivityFingerprint;
            HasBaselineFingerprint = true;
            LastProgressAt = now;
            LastObservedStatus = observation.Status;
            LastObservedStatusVersion = observation.NativeStatusVersion;
            WasRecoveryEnabled = observation.RecoveryEnabled;

            if (observation.Status == OpenCodeRecoveryExecutionState.Idle)
                IdleSince = now;
            else if (observation.Status == OpenCodeRecoveryExecutionState.Busy)
            {
                BusySince = now;
                NoProgressSince = now;
                HasWorkEvidence = true;
                Phase = RecoveryPhase.Busy;
            }
            else if (observation.Status == OpenCodeRecoveryExecutionState.Retry)
            {
                BusySince = now;
                NoProgressSince = now;
                Phase = RecoveryPhase.WaitingForNativeRetry;
            }
        }

        public long SessionEpoch { get; }
        public DateTimeOffset? LastEvaluationAt { get; set; }
        public Guid? OfferedDecisionId { get; set; }
        public long UserWorkGeneration { get; }
        public long MarkdownBindingGeneration { get; private set; }
        public string? RequestId { get; }
        public string? LastProgressFingerprint { get; set; }
        public string? LastActivityFingerprint { get; set; }
        public bool HasBaselineFingerprint { get; set; }
        public DateTimeOffset? LastProgressAt { get; set; }
        public DateTimeOffset? BusySince { get; set; }
        public DateTimeOffset? NoProgressSince { get; set; }
        public DateTimeOffset? IdleSince { get; set; }
        public DateTimeOffset? NextEligibleAt { get; set; }
        public OpenCodeRecoveryExecutionState LastObservedStatus { get; set; }
        public long LastObservedStatusVersion { get; set; }
        public bool HasWorkEvidence { get; set; }
        public int AttemptsWithoutProgress { get; set; }
        public int AbortAttemptsWithoutProgress { get; set; }
        public int TotalCycles { get; set; }
        public RecoveryPhase Phase { get; set; } = RecoveryPhase.WaitingForEvidence;
        public bool ManualStopLatched { get; set; }
        public bool WasRecoveryEnabled { get; set; }
        public Guid? PendingDecisionId { get; set; }
        public RecoveryAction? PendingAction { get; set; }
        public RecoveryActionResult? PendingResult { get; set; }
        public long PendingStatusVersion { get; set; }
        public DateTimeOffset PendingAttemptAt { get; set; }
        public long? AbortAcceptedStatusVersion { get; set; }
        public long? AwaitingContinuationStatusVersion { get; set; }
        public DateTimeOffset? ContinuationAcknowledgementStartedAt { get; set; }
        public DateTimeOffset? ContinuationAcknowledgementDeadline { get; set; }
        public bool HardPaused { get; set; }
        public bool ToolWasRunning { get; set; }
        public DateTimeOffset? SafetyBlockedSince { get; set; }

        public void ResetEvidence(RecoveryObservation observation, DateTimeOffset now, bool preserveRetryHistory)
        {
            DateTimeOffset? previousNextEligibleAt = NextEligibleAt;
            MarkdownBindingGeneration = observation.MarkdownBindingGeneration;
            LastProgressFingerprint = observation.ProgressFingerprint;
            LastActivityFingerprint = observation.ActivityFingerprint;
            HasBaselineFingerprint = true;
            LastProgressAt = now;
            LastEvaluationAt = now;
            BusySince = null;
            NoProgressSince = null;
            IdleSince = observation.Status == OpenCodeRecoveryExecutionState.Idle ? now : null;
            LastObservedStatus = observation.Status;
            LastObservedStatusVersion = observation.NativeStatusVersion;
            HasWorkEvidence = false;
            NextEligibleAt = preserveRetryHistory ? previousNextEligibleAt : null;
            Phase = RecoveryPhase.WaitingForEvidence;
            if (!preserveRetryHistory)
            {
                PendingDecisionId = null;
                PendingAction = null;
                PendingResult = null;
                AbortAcceptedStatusVersion = null;
                AwaitingContinuationStatusVersion = null;
                ContinuationAcknowledgementStartedAt = null;
                ContinuationAcknowledgementDeadline = null;
                AttemptsWithoutProgress = 0;
                AbortAttemptsWithoutProgress = 0;
                TotalCycles = 0;
                HardPaused = false;
            }
            if (observation.Status is OpenCodeRecoveryExecutionState.Busy or OpenCodeRecoveryExecutionState.Retry)
            {
                BusySince = now;
                NoProgressSince = now;
                HasWorkEvidence = true;
                Phase = RecoveryPhase.Busy;
            }
        }
    }
}

public sealed record RecoveryObservation(
    string SessionId,
    long SessionEpoch,
    long UserWorkGeneration,
    long MarkdownBindingGeneration,
    string? RequestId,
    OpenCodeRecoveryExecutionState Status,
    long NativeStatusVersion,
    bool IsConnected,
    bool HasPendingApprovalOrQuestion,
    bool HasError,
    int RunningToolCount,
    bool HasKnownTodoList,
    int UnfinishedTodoCount,
    bool IsMarkdownValid,
    bool ManualStopLatched,
    bool RecoveryEnabled,
    string? ProgressFingerprint)
{
    // Liveness prevents interrupting a streaming response, but never resets the no-progress retry budget.
    public string? ActivityFingerprint { get; init; }
    public bool HasCurrentUnfinishedRequest { get; init; }
    // An explicit Loop review is new work; completed native todos remain completed.
    public bool HasCompletedReviewRequested { get; init; }
    public bool HasSuccessfulFinalResponse { get; init; }
    public string? StalledLaunchToolFingerprint { get; init; }
    public bool ErrorRecoveryAllowed { get; init; }
    public bool ManualErrorRecovery { get; init; }
    public DateTimeOffset? ErrorRetryAt { get; init; }
    public DateTimeOffset? ProviderRetryAt { get; init; }
    public DateTimeOffset? NativeRetryAt { get; init; }
    public bool HasConfirmedErrorResponse { get; init; }
    public bool HasConfirmedContinuationReceipt { get; init; }
}

public sealed record RecoveryDecision(
    Guid DecisionId,
    RecoveryAction Action,
    RecoveryPhase Phase,
    string Reason,
    DateTimeOffset? RetryAfterUtc,
    string? SessionId,
    long SessionEpoch,
    long UserWorkGeneration,
    long MarkdownBindingGeneration,
    string? RequestId,
    long NativeStatusVersion)
{
    public static RecoveryDecision None(string reason, RecoveryPhase phase = RecoveryPhase.WaitingForEvidence, DateTimeOffset? retryAfterUtc = null) =>
        new(Guid.Empty, RecoveryAction.None, phase, reason, retryAfterUtc, null, 0, 0, 0, null, 0);

    public static RecoveryDecision Pause(string reason, RecoveryPhase phase = RecoveryPhase.Paused) =>
        new(Guid.Empty, RecoveryAction.Pause, phase, reason, null, null, 0, 0, 0, null, 0);
}

public enum OpenCodeRecoveryExecutionState
{
    Unknown,
    Idle,
    Busy,
    Retry
}

public enum RecoveryAction
{
    None,
    Continue,
    Abort,
    Pause
}

public enum RecoveryActionResult
{
    Accepted,
    Failed,
    Ambiguous
}

public enum RecoveryPhase
{
    WaitingForEvidence,
    Idle,
    IdleSettling,
    ReadyToContinue,
    Busy,
    StalledSuspected,
    AbortRequested,
    AwaitingFreshIdleAfterAbort,
    ContinuationRequested,
    AwaitingNativeResponse,
    WaitingForNativeRetry,
    WaitingForInput,
    RetryDelay,
    Paused
}
}
#endregion
#endif

