#if TN_WPF || TN_SOURCE_SERVICES_SINGLEPROJECTCONTINUOUSIMPROVEMENTSTORE_CS
#region Services/SingleProjectContinuousImprovementStore.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Security.Cryptography;
using global::System.Text;
using global::System.Text.Json;
using global::System.Threading;


/// <summary>Loop is 1 (by the plan) or 2 (Loop Full); preferences saved before the choice have none and are Loop 2.</summary>
public sealed record SingleProjectImprovementPreference(bool Enabled, DateTimeOffset? Until, bool RecommendPlan = true, int? Loop = null);

/// <summary>Persists continuous-improvement preferences for single-terminal projects.</summary>
public static class SingleProjectContinuousImprovementStore
{
    private static readonly object Gate = new();
    private static readonly string StorePath = Path.Combine(
        OpenCodeProjectContext.DataDirectory, "single-project-improvement.json");
    private static readonly string MutexName = "Local\\TerminalNotesImprovement_" +
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(StorePath.ToUpperInvariant()))[..12]);

    public static SingleProjectImprovementPreference? Read(string project)
    {
        string key = Canonicalize(project);
        lock (Gate)
        {
            using var mutex = new Mutex(false, MutexName);
            try { mutex.WaitOne(); }
            catch (AbandonedMutexException) { }
            try
            {
                Dictionary<string, SingleProjectImprovementPreference> records = ReadAll();
                return records.TryGetValue(key, out var preference) ? preference : null;
            }
            finally { mutex.ReleaseMutex(); }
        }
    }

    public static void Write(string project, bool enabled, DateTimeOffset? until, bool recommendPlan = false)
    {
        string key = Canonicalize(project);
        lock (Gate)
        {
            using var mutex = new Mutex(false, MutexName);
            try { mutex.WaitOne(); }
            catch (AbandonedMutexException) { }
            string temporaryPath = StorePath + "." + Guid.NewGuid().ToString("N") + ".tmp";
            try
            {
                Dictionary<string, SingleProjectImprovementPreference> records = ReadAll();
                records[key] = new(enabled, until, recommendPlan, recommendPlan ? 2 : 1);
                Directory.CreateDirectory(Path.GetDirectoryName(StorePath)!);
                File.WriteAllText(temporaryPath, JsonSerializer.Serialize(records));
                File.Move(temporaryPath, StorePath, overwrite: true);
            }
            finally
            {
                if (File.Exists(temporaryPath)) File.Delete(temporaryPath);
                mutex.ReleaseMutex();
            }
        }
    }

    private static Dictionary<string, SingleProjectImprovementPreference> ReadAll()
    {
        if (!File.Exists(StorePath)) return new(StringComparer.OrdinalIgnoreCase);
        try
        {
            return JsonSerializer.Deserialize<Dictionary<string, SingleProjectImprovementPreference>>(
                File.ReadAllText(StorePath)) is { } records
                ? new(records, StringComparer.OrdinalIgnoreCase)
                : throw new InvalidDataException("The single-project improvement settings are empty.");
        }
        catch (JsonException ex)
        {
            throw new InvalidDataException("The single-project improvement settings are malformed and were preserved.", ex);
        }
    }

    private static string Canonicalize(string project) =>
        Path.TrimEndingDirectorySeparator(Path.GetFullPath(project));
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_PROJECTSTARTSCHEDULESTORE_CS
#region Services/ProjectStartScheduleStore.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Security.Cryptography;
using global::System.Text;
using global::System.Text.Json;
using global::System.Threading;


/// <summary>A one-shot timed start of one task. Loop/LoopUntil are applied just before it starts. LoopFull: Loop 2 (true) or
/// Loop 1 (false); null (no Loop, or saved before the choice) follows the task's own.</summary>
public sealed record ProjectStartSchedule(DateTimeOffset StartAt, bool Loop, DateTimeOffset? LoopUntil = null, bool? LoopFull = null);

/// <summary>Persists timed task starts per project folder so they survive an app restart.</summary>
public static class ProjectStartScheduleStore
{
    private static readonly object Gate = new();
    private static readonly string StorePath = Path.Combine(
        OpenCodeProjectContext.DataDirectory, "project-start-schedules.json");
    private static readonly string MutexName = "Local\\TerminalNotesStartSchedule_" +
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(StorePath.ToUpperInvariant()))[..12]);

    public static Dictionary<string, ProjectStartSchedule> ReadAll()
    {
        lock (Gate)
        {
            using var mutex = new Mutex(false, MutexName);
            try { mutex.WaitOne(); }
            catch (AbandonedMutexException) { }
            try { return ReadAllCore(); }
            finally { mutex.ReleaseMutex(); }
        }
    }

    /// <summary>Sets or (with <paramref name="schedule"/> null) removes one project's schedule.</summary>
    public static void Write(string project, ProjectStartSchedule? schedule)
    {
        string key = Canonicalize(project);
        lock (Gate)
        {
            using var mutex = new Mutex(false, MutexName);
            try { mutex.WaitOne(); }
            catch (AbandonedMutexException) { }
            string temporaryPath = StorePath + "." + Guid.NewGuid().ToString("N") + ".tmp";
            try
            {
                Dictionary<string, ProjectStartSchedule> records = ReadAllCore();
                if (schedule is null ? !records.Remove(key) : records.TryGetValue(key, out var current) && current == schedule) return;
                if (schedule is not null) records[key] = schedule;
                Directory.CreateDirectory(Path.GetDirectoryName(StorePath)!);
                File.WriteAllText(temporaryPath, JsonSerializer.Serialize(records));
                File.Move(temporaryPath, StorePath, overwrite: true);
            }
            finally
            {
                if (File.Exists(temporaryPath)) File.Delete(temporaryPath);
                mutex.ReleaseMutex();
            }
        }
    }

    private static Dictionary<string, ProjectStartSchedule> ReadAllCore()
    {
        if (!File.Exists(StorePath)) return new(StringComparer.OrdinalIgnoreCase);
        try
        {
            return JsonSerializer.Deserialize<Dictionary<string, ProjectStartSchedule>>(
                File.ReadAllText(StorePath)) is { } records
                ? new(records, StringComparer.OrdinalIgnoreCase)
                : throw new InvalidDataException("The task start schedules are empty.");
        }
        catch (JsonException ex)
        {
            throw new InvalidDataException("The task start schedules are malformed and were preserved.", ex);
        }
    }

    private static string Canonicalize(string project) =>
        Path.TrimEndingDirectorySeparator(Path.GetFullPath(project));
}
}
