#if TN_WPF || TN_SOURCE_SERVICES_SLEEPPREVENTIONSERVICE_CS
#region Services/SleepPreventionService.cs
namespace TerminalNotes.Services
{
using global::System.ComponentModel;
using global::System.Runtime.InteropServices;
using global::Microsoft.Win32.SafeHandles;


/// <summary>One process-owned request for active work; never changes the user's power plan.</summary>
public sealed class SleepPreventionService : IDisposable
{
    private readonly Func<IDisposable> _acquire;
    private readonly TimeProvider _time;
    private IDisposable? _request;
    private DateTimeOffset _retryAt;
    private bool _disposed;
    public bool IsActive => _request is not null;
    public string? LastError { get; private set; }

    public SleepPreventionService(Func<IDisposable>? acquire = null, TimeProvider? timeProvider = null)
    {
        _acquire = acquire ?? NativeRequest.Acquire;
        _time = timeProvider ?? TimeProvider.System;
    }

    public void SetRequired(bool required)
    {
        if (_disposed) return;
        if (!required)
        {
            Release();
            LastError = null;
            _retryAt = default;
            return;
        }
        if (_request is not null || _time.GetUtcNow() < _retryAt) return;
        try
        {
            _request = _acquire();
            LastError = null;
        }
        catch (Win32Exception ex)
        {
            LastError = "자동 절전 방지 요청 실패 · " + ex.Message;
            _retryAt = _time.GetUtcNow().AddSeconds(30);
        }
    }

    // Windows can clear requests during a user-initiated sleep. Recreate on resume.
    public void ResetAfterResume()
    {
        if (_disposed) return;
        Release();
        _retryAt = default;
    }

    private void Release()
    {
        var request = _request;
        _request = null;
        request?.Dispose();
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        Release();
    }

    private sealed class NativeRequest(SafeFileHandle handle) : IDisposable
    {
        private const int DisplayRequired = 0, SystemRequired = 1, ExecutionRequired = 3;

        public static IDisposable Acquire()
        {
            var context = new ReasonContext { Version = 0, Flags = 1,
                SimpleReasonString = "Terminal Notes · 진행 중인 태스크" };
            var handle = PowerCreateRequest(ref context);
            if (handle.IsInvalid)
            {
                int error = Marshal.GetLastWin32Error();
                handle.Dispose();
                throw new Win32Exception(error);
            }
            var setRequests = new List<int>(3);
            try
            {
                Set(DisplayRequired);
                Set(SystemRequired);
                Set(ExecutionRequired);
                return new NativeRequest(handle);

                void Set(int type)
                {
                    if (!PowerSetRequest(handle, type)) throw new Win32Exception(Marshal.GetLastWin32Error());
                    setRequests.Add(type);
                }
            }
            catch
            {
                foreach (int type in setRequests) PowerClearRequest(handle, type);
                handle.Dispose();
                throw;
            }
        }

        public void Dispose()
        {
            if (handle.IsClosed) return;
            // Closing the handle also removes requests if Windows already cleared their counts.
            int[] requestTypes = [ExecutionRequired, SystemRequired, DisplayRequired];
            try { foreach (int type in requestTypes) PowerClearRequest(handle, type); }
            finally { handle.Dispose(); }
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct ReasonContext
        {
            public uint Version, Flags;
            [MarshalAs(UnmanagedType.LPWStr)] public string SimpleReasonString;
            // Reserve the full native union (Detailed uses three pointer-sized slots on x64).
            public IntPtr Reserved1, Reserved2;
        }

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern SafeFileHandle PowerCreateRequest(ref ReasonContext context);
        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool PowerSetRequest(SafeFileHandle request, int type);
        [DllImport("kernel32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool PowerClearRequest(SafeFileHandle request, int type);
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TASKNOTIFICATIONPOLICY_CS
#region Services/TaskNotificationPolicy.cs
namespace TerminalNotes.Services
{
using global::System.Globalization;


public enum TaskNotificationKind { Completed, Failed, Stalled, ResourceWaiting }

public sealed record TaskNotificationNotice(string ProjectKey, string AttemptId, TaskNotificationKind Kind);

public sealed record TaskNotificationObservation(
    string ProjectKey, string AttemptId, bool IsArmed, bool IsStopped, bool IsStarting,
    bool HasAcceptedSubmission, bool HasVerifiedCompletion, bool IsAwaitingInput,
    bool HasDefiniteFailure, bool HasVerifiedStall);

public sealed class TaskNotificationTracker
{
    private static readonly TimeSpan CompletionStability = TimeSpan.FromSeconds(3);
    private static readonly TimeSpan FailureStability = TimeSpan.FromSeconds(2);
    private static readonly TimeSpan StallStability = TimeSpan.FromSeconds(30);
    private static readonly TimeSpan MaximumObservationGap = TimeSpan.FromMinutes(2);
    private readonly object _gate = new();
    private readonly Dictionary<string, AttemptState> _attempts = new(StringComparer.OrdinalIgnoreCase);

    public TaskNotificationNotice? Observe(TaskNotificationObservation observation, DateTimeOffset now, bool notificationsAllowed)
    {
        ArgumentNullException.ThrowIfNull(observation);
        if (string.IsNullOrWhiteSpace(observation.ProjectKey) || string.IsNullOrWhiteSpace(observation.AttemptId)) return null;

        lock (_gate)
        {
            if (!_attempts.TryGetValue(observation.ProjectKey, out AttemptState? state) ||
                !string.Equals(state.AttemptId, observation.AttemptId, StringComparison.Ordinal))
                _attempts[observation.ProjectKey] = state = new AttemptState(observation.AttemptId);

            if (state.LastObservedAt is { } previous && (now < previous || now - previous > MaximumObservationGap))
                state.ResetStability();
            state.LastObservedAt = now;

            if (!observation.IsArmed || observation.IsStopped || observation.IsStarting)
            {
                state.ResetStability();
                return null;
            }

            if (observation.HasAcceptedSubmission && observation.HasVerifiedCompletion &&
                !observation.IsAwaitingInput && !observation.HasDefiniteFailure)
            {
                state.FailureSince = state.StallSince = null;
                state.CompletionSince ??= now;
                if (!state.Emitted.Contains(TaskNotificationKind.Completed) && IsStable(state.CompletionSince, now, CompletionStability))
                {
                    state.Emitted.Add(TaskNotificationKind.Completed);
                    return notificationsAllowed ? new(observation.ProjectKey, observation.AttemptId, TaskNotificationKind.Completed) : null;
                }
                return null;
            }
            state.CompletionSince = null;

            if (observation.IsAwaitingInput)
            {
                state.FailureSince = state.StallSince = null;
                return null;
            }

            if (observation.HasDefiniteFailure)
            {
                state.StallSince = null;
                state.FailureSince ??= now;
                if (notificationsAllowed && !state.Emitted.Contains(TaskNotificationKind.Failed) &&
                    IsStable(state.FailureSince, now, FailureStability))
                {
                    state.Emitted.Add(TaskNotificationKind.Failed);
                    return new(observation.ProjectKey, observation.AttemptId, TaskNotificationKind.Failed);
                }
                return null;
            }
            state.FailureSince = null;

            if (observation.HasAcceptedSubmission && observation.HasVerifiedStall)
            {
                state.StallSince ??= now;
                if (notificationsAllowed && !state.Emitted.Contains(TaskNotificationKind.Stalled) &&
                    IsStable(state.StallSince, now, StallStability))
                {
                    state.Emitted.Add(TaskNotificationKind.Stalled);
                    return new(observation.ProjectKey, observation.AttemptId, TaskNotificationKind.Stalled);
                }
                return null;
            }

            state.StallSince = null;
            return null;
        }
    }

    public void Forget(string projectKey)
    {
        if (string.IsNullOrWhiteSpace(projectKey)) return;
        lock (_gate) _attempts.Remove(projectKey);
    }

    private static bool IsStable(DateTimeOffset? since, DateTimeOffset now, TimeSpan required) =>
        since is { } started && now >= started && now - started >= required;

    private sealed class AttemptState(string attemptId)
    {
        public string AttemptId { get; } = attemptId;
        public DateTimeOffset? LastObservedAt { get; set; }
        public DateTimeOffset? CompletionSince { get; set; }
        public DateTimeOffset? FailureSince { get; set; }
        public DateTimeOffset? StallSince { get; set; }
        public HashSet<TaskNotificationKind> Emitted { get; } = [];
        public void ResetStability() => CompletionSince = FailureSince = StallSince = null;
    }
}

public sealed record TaskNotificationPreferences(bool Enabled = true, DateTimeOffset? SnoozedUntilUtc = null)
{
    public bool CanNotify(DateTimeOffset now) => Enabled && (SnoozedUntilUtc is not { } until || now >= until);

    public static bool TryGetSnoozeUntil(string minutes, DateTimeOffset now, out DateTimeOffset until)
    {
        until = default;
        if (!int.TryParse(minutes?.Trim(), NumberStyles.None, CultureInfo.InvariantCulture, out int value) || value <= 0)
            return false;
        try
        {
            until = now.AddMinutes(value);
            return true;
        }
        catch (ArgumentOutOfRangeException)
        {
            until = default;
            return false;
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALACTIVITYPALETTE_CS
#region Services/TerminalActivityPalette.cs
namespace TerminalNotes.Services
{

/// <summary>
/// Saturated state colors shared by terminal bodies, headings, and floating tiles.
/// Only work in progress is green and requests for user input are orange.
/// Every inactive state is gray; orange uses dark text for contrast.
/// </summary>
public static class TerminalActivityPalette
{
    public static string Background(TerminalActivity activity, bool hasCompletedWork = false) => activity switch
    {
        TerminalActivity.NeedsInput => "#FF8A00",
        _ when hasCompletedWork => "#252D3A",
        TerminalActivity.Active => "#00853F",
        _ => "#252D3A"
    };

    public static string Foreground(TerminalActivity activity, bool hasCompletedWork = false) =>
        activity == TerminalActivity.NeedsInput ? "#211000" : "#FFFFFF";

    /// <summary>Brighter accents for text shown outside the colored terminal surface.</summary>
    public static string Accent(TerminalActivity activity, bool hasCompletedWork = false) => activity switch
    {
        TerminalActivity.NeedsInput => "#FF8A00",
        _ when hasCompletedWork => "#B6C4D9",
        TerminalActivity.Active => "#00FF73",
        _ => "#B6C4D9"
    };
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALACTIVITYTRACKER_CS
#region Services/TerminalActivityTracker.cs
namespace TerminalNotes.Services
{
using global::System.Text;
using global::System.Text.RegularExpressions;


public enum TerminalActivity
{
    Starting,
    Active,
    NeedsInput,
    Quiet,
    Idle,
    RateLimited,
    Exited,
    Error
}

/// <summary>
/// Classifies terminal activity from observable I/O without treating a live
/// process or silence alone as proof that work is in progress or blocked.
/// </summary>
public sealed class TerminalActivityTracker
{
    private static readonly Regex AnsiSequence = new(
        "\\x1B\\][^\\x07]*(?:\\x07|\\x1B\\\\)|\\x1B\\[[0-?]*[ -/]*[@-~]",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex PowerShellPrompt = new(
        @"(?i)(?:^|\n)\s*PS\s+[^\r\n]*?>\s*\z",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex DeviceResponse = new(
        @"\A(?:\x1b\[[0-9;:?><=$]*[cRntxyIO])+\z",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex InterruptHint = new(
        @"(?i)\besc(?:ape)?\s+(?:to\s+)?(?:interrupt|cancel|stop)\b",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex OpenCodeComposer = new(
        @"(?i)┃\s*Ask\s+anything(?:…|\.\.\.)?",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex OpenCodeIdleFooter = new(
        @"(?i)(?:ctrl\+p\s+)?commands\b",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex OpenCodeComposerLine = new(
        @"(?i)(?:┃|│|\|)?\s*Ask\s+anything(?:…|\.\.\.)?",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex OpenCodeBorder = new(
        @"^[\s┃│|]+",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex OpenCodeBusyLine = new(
        @"(?i)\b(?:working|thinking|running|processing|building|progress)\b|[▓⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏]",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly Regex OpenCodeChromeLine = new(
        @"(?i)(?:^\s*(?:\+p\s+|ctrl\+p\s+)?commands\b|\besc(?:ape)?\s+(?:to\s+)?(?:interrupt|cancel|stop)\b|\bopencode\s+zen\b.*\b\d+\.\d+\.\d+\b)",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);
    private static readonly string[] ApprovalPrompts =
    [
        "Do you want to proceed?",
        "Would you like to proceed?",
        "Would you like to run",
        "Press Enter to continue",
        "Allow this command",
        "Approve this command",
        "(y/n)",
        "[y/N]",
        "계속하시겠습니까",
        "승인하시겠습니까",
        "명령을 허용"
    ];

    private readonly object _gate = new();
    private readonly TimeProvider _timeProvider;
    private readonly TimeSpan _activeWindow;
    private readonly TimeSpan _startupWindow;
    private DateTimeOffset _startedAt;
    private DateTimeOffset? _lastOutputAt;
    private bool _manualNeedsInput;
    private bool _inferredNeedsInput;
    private string? _lastScreen;
    private string? _lastLayout;
    private bool _screenBusy;
    private bool _idlePrompt;
    private bool _screenLimited;
    private bool _workSubmitted;
    private bool _screenBusyObserved;
    private bool _completionPending;
    private bool _completionScreenChanged;
    private bool _completionTuiResponseObserved;
    private bool _openCodeComposerReady;
    private bool _busyHintWasActiveAtSubmit;
    private string? _busyHintAtSubmit;
    private string? _completionBaselineContent;
    private string? _submittedPrompt;
    private readonly StringBuilder _inputDraft = new();
    private DateTimeOffset? _completionCandidateAt;
    private bool _hasCompletedWork;
    private TerminalActivity _activity;
    private string _activityLabel;

    public TerminalActivityTracker(
        TimeProvider? timeProvider = null,
        TimeSpan? activeWindow = null,
        TimeSpan? startupWindow = null)
    {
        _timeProvider = timeProvider ?? TimeProvider.System;
        _activeWindow = activeWindow ?? TimeSpan.FromSeconds(1.5);
        _startupWindow = startupWindow ?? TimeSpan.FromSeconds(5);
        _startedAt = _timeProvider.GetUtcNow();
        _activity = TerminalActivity.Starting;
        _activityLabel = LabelFor(_activity, manualNeedsInput: false);
    }

    public event Action? ActivityChanged;

    public TerminalActivity Activity
    {
        get
        {
            lock (_gate)
            {
                return _activity;
            }
        }
    }

    public string ActivityLabel
    {
        get
        {
            lock (_gate)
            {
                return _activityLabel;
            }
        }
    }

    public bool HasCompletedWork
    {
        get
        {
            lock (_gate)
            {
                return _hasCompletedWork;
            }
        }
    }

    public void MarkStarted(bool startupWork = false)
    {
        bool changed;
        lock (_gate)
        {
            _startedAt = _timeProvider.GetUtcNow();
            _lastOutputAt = null;
            _manualNeedsInput = false;
            _inferredNeedsInput = false;
            _lastScreen = null;
            _lastLayout = null;
            _screenBusy = false;
            _idlePrompt = false;
            _screenLimited = false;
            _workSubmitted = startupWork;
            _screenBusyObserved = false;
            _completionPending = startupWork;
            _completionScreenChanged = false;
            _completionTuiResponseObserved = false;
            _openCodeComposerReady = false;
            _busyHintWasActiveAtSubmit = false;
            _busyHintAtSubmit = null;
            _completionBaselineContent = null;
            _submittedPrompt = null;
            _inputDraft.Clear();
            _completionCandidateAt = null;
            changed = SetCompletedLocked(false);
            changed |= SetStateLocked(TerminalActivity.Starting, manualNeedsInput: false);
        }

        RaiseChanged(changed);
    }

    public void ObserveOutput(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (text.Length == 0)
        {
            return;
        }

        bool changed;
        lock (_gate)
        {
            if (IsTerminalState(_activity))
            {
                return;
            }

            _lastOutputAt = _timeProvider.GetUtcNow();
            _inferredNeedsInput = false;
            _idlePrompt = false;
            _screenBusy = false;
            _screenLimited = false;
            _openCodeComposerReady = false;
            _completionCandidateAt = null;
            changed = _manualNeedsInput
                ? SetStateLocked(TerminalActivity.NeedsInput, manualNeedsInput: true)
                : SetStateLocked(TerminalActivity.Active, manualNeedsInput: false);
        }

        RaiseChanged(changed);
    }

    public void ObserveRenderedTail(string renderedTail)
    {
        ArgumentNullException.ThrowIfNull(renderedTail);
        bool changed;
        lock (_gate)
        {
            if (IsTerminalState(_activity))
            {
                return;
            }

            _idlePrompt = LooksLikeIdlePrompt(renderedTail);
            _inferredNeedsInput = !PowerShellPrompt.IsMatch(renderedTail.Replace("\r", "")) && LooksLikeInputPrompt(renderedTail);
            changed = EvaluateLocked(_timeProvider.GetUtcNow());
        }

        RaiseChanged(changed);
    }

    // The renderer reports text after applying ANSI commands. Cursor queries,
    // colour changes and repainting identical content are not new output.
    public void ObserveRenderedScreen(string renderedTail, string screen, string layout, bool promptAtCursor = false)
    {
        bool changed;
        lock (_gate)
        {
            if (IsTerminalState(_activity)) return;
            bool resized = _lastLayout is not null && _lastLayout != layout;
            bool screenChanged = !resized && !string.IsNullOrWhiteSpace(screen) && screen != _lastScreen;
            if (screenChanged)
            {
                _lastOutputAt = _timeProvider.GetUtcNow();
                if (_completionPending)
                    _completionScreenChanged = true;
            }
            _lastScreen = screen;
            _lastLayout = layout;
            if (_completionPending && !resized && _completionBaselineContent is not null &&
                HasOpenCodeResponseDelta(_completionBaselineContent, screen, _submittedPrompt))
            {
                _completionTuiResponseObserved = true;
                _completionScreenChanged = true;
            }
            string footer = string.Join('\n', screen.Split('\n').Where(line => !string.IsNullOrWhiteSpace(line)).TakeLast(8));
            string recent = string.Join('\n', renderedTail.Split('\n').Where(line => !string.IsNullOrWhiteSpace(line)).TakeLast(4));
            _screenLimited = Regex.IsMatch(recent, @"(?i)(?:you['’]ve hit your (?:usage )?limit|(?:token|usage|rate) limit (?:exceeded|reached)|(?:exceeded|reached).{0,25}(?:token|usage|rate) limit|insufficient_quota|(?:토큰|사용량|요청).{0,12}(?:한도|제한).{0,12}(?:초과|도달|소진)|(?:credit|quota)s? (?:exhausted|exceeded)|out of (?:extra usage|credits))");
            string? busyHint = FindInterruptHint(footer);
            bool unchangedPreSubmitHint = _workSubmitted && !_busyHintWasActiveAtSubmit &&
                busyHint is not null && string.Equals(busyHint, _busyHintAtSubmit, StringComparison.Ordinal);
            _screenBusy = busyHint is not null && (_workSubmitted || OpenCodeBusyLine.IsMatch(busyHint)) &&
                !unchangedPreSubmitHint;
            if (_screenBusy)
            {
                _workSubmitted = true;
                _screenBusyObserved = true;
                _completionCandidateAt = null;
            }
            bool openCodeIdleComposer = !_screenBusy &&
                OpenCodeComposer.IsMatch(recent) && OpenCodeIdleFooter.IsMatch(footer);
            _openCodeComposerReady = openCodeIdleComposer;
            _idlePrompt = promptAtCursor || LooksLikeIdlePrompt(renderedTail) || openCodeIdleComposer;
            // A shell prompt means the command has returned. Agent input rows
            // can remain visible while busy or while asking for confirmation.
            bool shellIdle = PowerShellPrompt.IsMatch(renderedTail.Replace("\r", ""));
            bool approval = ApprovalPrompts.Any(prompt => recent.Contains(prompt, StringComparison.OrdinalIgnoreCase));
            string inputEvidence = openCodeIdleComposer ? BeforeOpenCodeComposer(renderedTail) : renderedTail;
            _inferredNeedsInput = !shellIdle && (approval ||
                (!_screenBusy && LooksLikeInputPrompt(inputEvidence)));
            bool completed = _completionPending && _completionScreenChanged && shellIdle &&
                !_screenBusy && !_inferredNeedsInput && !_screenLimited;
            changed = _screenBusy ? SetCompletedLocked(false) : false;
            if (completed)
            {
                _completionPending = false;
                _completionScreenChanged = false;
                _workSubmitted = false;
                _screenBusyObserved = false;
                _completionCandidateAt = null;
                changed |= SetCompletedLocked(true);
            }
            bool returnedToTuiComposer = _workSubmitted && _completionPending && _completionScreenChanged &&
                _idlePrompt && !_screenBusy && !_inferredNeedsInput && !_screenLimited &&
                (_screenBusyObserved || (openCodeIdleComposer && _completionTuiResponseObserved));
            if (returnedToTuiComposer)
            {
                // The composer can remain visible while an agent is working.
                // Require a busy hint to disappear, or an actual response plus
                // OpenCode's ready composer, then keep that screen stable.
                if (_completionCandidateAt is null || screenChanged)
                    _completionCandidateAt = _timeProvider.GetUtcNow();
            }
            else
            {
                _completionCandidateAt = null;
            }
            changed |= EvaluateLocked(_timeProvider.GetUtcNow());
        }
        RaiseChanged(changed);
    }

    public void ObserveUserInput(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        // xterm.onData also includes device/cursor replies, not just keyboard input.
        // Match the same keyboard-impossible CSI reports accepted by the input
        // capture. Arrow/history and other real key sequences must still reset
        // completion like any other user input.
        if (DeviceResponse.IsMatch(text)) return;
        bool changed;
        lock (_gate)
        {
            if (IsTerminalState(_activity))
            {
                return;
            }

            bool answeringPrompt = _manualNeedsInput || _inferredNeedsInput || _activity == TerminalActivity.NeedsInput;
            bool wasBusy = _screenBusy;
            string? currentBusyHint = FindInterruptHint(_lastScreen ?? string.Empty);
            _inferredNeedsInput = false;
            _screenBusy = false;
            _idlePrompt = false;
            _screenLimited = false;
            _lastOutputAt = null;
            _completionCandidateAt = null;
            changed = SetCompletedLocked(false);
            if (text.Length > 0 && answeringPrompt)
            {
                _manualNeedsInput = false;
                _workSubmitted = true;
            }
            if (text.Contains('\r') || text.Contains('\n'))
            {
                CaptureSubmittedInputLocked(text);
                _manualNeedsInput = false;
                _workSubmitted = true;
                _completionPending = true;
                _completionScreenChanged = false;
                _completionTuiResponseObserved = false;
                _screenBusyObserved = false;
                _completionBaselineContent = OpenCodeResponseContent(_lastScreen ?? string.Empty);
                _busyHintAtSubmit = currentBusyHint;
                _busyHintWasActiveAtSubmit = wasBusy;
                _openCodeComposerReady = false;
            }
            else
            {
                CaptureDraftInputLocked(text);
            }
            changed |= EvaluateLocked(_timeProvider.GetUtcNow());
        }

        RaiseChanged(changed);
    }

    public void MarkNeedsInput()
    {
        bool changed;
        lock (_gate)
        {
            if (IsTerminalState(_activity))
            {
                return;
            }

            _manualNeedsInput = true;
            _completionCandidateAt = null;
            changed = SetCompletedLocked(false);
            changed |= SetStateLocked(TerminalActivity.NeedsInput, manualNeedsInput: true);
        }

        RaiseChanged(changed);
    }

    public void ClearActivityOverride()
    {
        bool changed;
        lock (_gate)
        {
            if (_activity == TerminalActivity.Error)
            {
                return;
            }

            _manualNeedsInput = false;
            changed = EvaluateLocked(_timeProvider.GetUtcNow());
        }

        RaiseChanged(changed);
    }

    public void MarkExited()
    {
        bool changed;
        lock (_gate)
        {
            if (_activity == TerminalActivity.Error)
            {
                return;
            }

            _manualNeedsInput = false;
            _inferredNeedsInput = false;
            _completionPending = false;
            _completionScreenChanged = false;
            _completionTuiResponseObserved = false;
            _completionCandidateAt = null;
            _screenBusyObserved = false;
            _openCodeComposerReady = false;
            _completionBaselineContent = null;
            _submittedPrompt = null;
            _inputDraft.Clear();
            changed = SetCompletedLocked(false);
            changed |= SetStateLocked(TerminalActivity.Exited, manualNeedsInput: false);
        }

        RaiseChanged(changed);
    }

    public void MarkError()
    {
        bool changed;
        lock (_gate)
        {
            _manualNeedsInput = false;
            _inferredNeedsInput = false;
            _completionPending = false;
            _completionScreenChanged = false;
            _completionTuiResponseObserved = false;
            _completionCandidateAt = null;
            _screenBusyObserved = false;
            _openCodeComposerReady = false;
            _completionBaselineContent = null;
            _submittedPrompt = null;
            _inputDraft.Clear();
            changed = SetCompletedLocked(false);
            changed |= SetStateLocked(TerminalActivity.Error, manualNeedsInput: false);
        }

        RaiseChanged(changed);
    }

    public void MarkWorkCompleted()
    {
        bool changed;
        lock (_gate)
        {
            if (IsTerminalState(_activity))
            {
                return;
            }

            _workSubmitted = false;
            _screenBusyObserved = false;
            _completionPending = false;
            _completionScreenChanged = false;
            _completionTuiResponseObserved = false;
            _completionCandidateAt = null;
            _manualNeedsInput = false;
            _inferredNeedsInput = false;
            _screenBusy = false;
            _screenLimited = false;
            _openCodeComposerReady = false;
            _completionBaselineContent = null;
            _submittedPrompt = null;
            _inputDraft.Clear();
            changed = SetCompletedLocked(true);
            changed |= SetStateLocked(TerminalActivity.Idle, manualNeedsInput: false);
        }

        RaiseChanged(changed);
    }

    public void Tick()
    {
        bool changed;
        lock (_gate)
        {
            changed = EvaluateLocked(_timeProvider.GetUtcNow());
        }

        RaiseChanged(changed);
    }

    public static bool LooksLikeInputPrompt(string renderedTail)
    {
        if (string.IsNullOrWhiteSpace(renderedTail))
        {
            return false;
        }

        string plainText = AnsiSequence.Replace(renderedTail, string.Empty).Replace("\r", string.Empty, StringComparison.Ordinal);

        string[] recentLines = plainText
            .Split('\n')
            .Where(line => !string.IsNullOrWhiteSpace(line))
            .TakeLast(3)
            .ToArray();
        string recentText = string.Join('\n', recentLines);
        return ApprovalPrompts.Any(prompt =>
            recentText.Contains(prompt, StringComparison.OrdinalIgnoreCase)) ||
            recentLines.Any(line => Regex.IsMatch(line, @"[?？]\s*$"));
    }

    private static bool LooksLikeIdlePrompt(string text) => PowerShellPrompt.IsMatch(text.Replace("\r", "")) ||
        Regex.IsMatch(text, @"(?:^|\n)\s*[›❯]\s*\z");

    private static string BeforeOpenCodeComposer(string text)
    {
        string plainText = AnsiSequence.Replace(text, string.Empty).Replace("\r", string.Empty, StringComparison.Ordinal);
        Match composer = OpenCodeComposer.Match(plainText);
        return composer.Success ? plainText[..composer.Index] : plainText;
    }

    private void CaptureSubmittedInputLocked(string text)
    {
        int newline = text.IndexOfAny(['\r', '\n']);
        string beforeSubmit = newline >= 0 ? text[..newline] : text;
        CaptureDraftInputLocked(beforeSubmit);
        _submittedPrompt = _inputDraft.ToString().Trim();
        _inputDraft.Clear();
        if (newline >= 0 && newline + 1 < text.Length)
            CaptureDraftInputLocked(text[(newline + 1)..]);
    }

    private void CaptureDraftInputLocked(string text)
    {
        foreach (char value in text)
        {
            if (value is '\b' or '\x7f')
            {
                if (_inputDraft.Length > 0) _inputDraft.Length--;
            }
            else if (!char.IsControl(value))
            {
                _inputDraft.Append(value);
            }
            else if (value == '\x1b')
            {
                // Navigation/editing sequences make the local draft uncertain.
                _inputDraft.Clear();
            }
        }
    }

    private static string? FindInterruptHint(string screen) => screen
        .Split('\n')
        .Where(line => !string.IsNullOrWhiteSpace(line))
        .TakeLast(8)
        .LastOrDefault(InterruptHint.IsMatch)?.Trim();

    private static bool HasOpenCodeResponseDelta(string baseline, string screen, string? submittedPrompt)
    {
        string[] previous = baseline.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        string[] current = OpenCodeResponseContent(screen)
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (current.Length == 0) return false;

        var knownWords = TokenizeOpenCodeContent(string.Join(' ', previous)).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach (string promptWord in TokenizeOpenCodeContent(submittedPrompt ?? string.Empty))
            knownWords.Add(promptWord);
        return TokenizeOpenCodeContent(string.Join(' ', current)).Any(word => !knownWords.Contains(word));
    }

    private static IEnumerable<string> TokenizeOpenCodeContent(string text) =>
        Regex.Matches(text, @"[\p{L}\p{N}]+")
            .Cast<Match>()
            .Select(match => match.Value);

    private static string OpenCodeResponseContent(string screen) => string.Join('\n',
        AnsiSequence.Replace(screen, string.Empty)
            .Replace("\r", string.Empty, StringComparison.Ordinal)
            .Split('\n')
            .Select(line => OpenCodeBorder.Replace(line.Trim(), string.Empty).Trim())
            .Where(line => line.Length > 0 &&
                !OpenCodeComposerLine.IsMatch(line) &&
                !OpenCodeChromeLine.IsMatch(line)));

    private bool EvaluateLocked(DateTimeOffset now)
    {
        if (IsTerminalState(_activity))
        {
            return false;
        }

        if (_screenLimited) return SetStateLocked(TerminalActivity.RateLimited, manualNeedsInput: false);

        if (_manualNeedsInput)
        {
            return SetStateLocked(TerminalActivity.NeedsInput, manualNeedsInput: true);
        }

        if (_inferredNeedsInput)
        {
            return SetStateLocked(TerminalActivity.NeedsInput, manualNeedsInput: false);
        }
        if (_screenBusy)
            return SetStateLocked(TerminalActivity.Active, manualNeedsInput: false);

        if (_completionCandidateAt is { } returnedAt && now - returnedAt >= _activeWindow &&
            _workSubmitted && _completionPending && _idlePrompt && !_screenLimited &&
            (_screenBusyObserved || (_openCodeComposerReady && _completionTuiResponseObserved)))
        {
            // The interactive TUI has returned to its stable composer after a
            // busy transition or a visible response. This is idle evidence, not
            // proof that the task succeeded, so HasCompletedWork stays false.
            _workSubmitted = false;
            _completionPending = false;
            _completionScreenChanged = false;
            _completionTuiResponseObserved = false;
            _screenBusyObserved = false;
            _completionCandidateAt = null;
            _completionBaselineContent = null;
            _submittedPrompt = null;
        }

        // Once meaningful work starts, silence, repainting and a persistent
        // agent input row are not completion evidence. Keep the active state
        // until a recognized TUI composer returns, a question or terminal state
        // appears, or completion is authoritative.
        if (_workSubmitted)
            return SetStateLocked(TerminalActivity.Active, manualNeedsInput: false);

        if (_idlePrompt) return SetStateLocked(TerminalActivity.Idle, manualNeedsInput: false);

        // Startup banners, suggestions and typing are not submitted work.
        // Explicit busy, question and limit signals above still take precedence.
        if (!_workSubmitted && _lastScreen is not null)
            return SetStateLocked(TerminalActivity.Idle, manualNeedsInput: false);

        if (_lastOutputAt is { } lastOutput && now - lastOutput <= _activeWindow)
        {
            return SetStateLocked(TerminalActivity.Active, manualNeedsInput: false);
        }

        if (_lastOutputAt is null && now - _startedAt <= _startupWindow)
        {
            return SetStateLocked(TerminalActivity.Starting, manualNeedsInput: false);
        }

        return SetStateLocked(TerminalActivity.Quiet, manualNeedsInput: false);
    }

    private bool SetStateLocked(TerminalActivity activity, bool manualNeedsInput)
    {
        string label = LabelFor(activity, manualNeedsInput);
        if (_activity == activity && string.Equals(_activityLabel, label, StringComparison.Ordinal))
        {
            return false;
        }

        _activity = activity;
        _activityLabel = label;
        return true;
    }

    private bool SetCompletedLocked(bool completed)
    {
        if (_hasCompletedWork == completed)
        {
            return false;
        }

        _hasCompletedWork = completed;
        return true;
    }

    private static bool IsTerminalState(TerminalActivity activity) =>
        activity is TerminalActivity.Exited or TerminalActivity.Error;

    private static string LabelFor(TerminalActivity activity, bool manualNeedsInput) => activity switch
    {
        TerminalActivity.Starting => "시작 중",
        TerminalActivity.Active => "진행 중",
        TerminalActivity.NeedsInput when manualNeedsInput => "확인 필요 (수동)",
        TerminalActivity.NeedsInput => "확인 필요",
        TerminalActivity.Quiet => "대기 중 · 출력 없음",
        TerminalActivity.Idle => "대기 중",
        TerminalActivity.RateLimited => "토큰·사용량 한도",
        TerminalActivity.Exited => "종료됨",
        TerminalActivity.Error => "오류",
        _ => activity.ToString()
    };

    private void RaiseChanged(bool changed)
    {
        if (changed)
        {
            ActivityChanged?.Invoke();
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALEXECUTIONTIMING_CS
#region Services/TerminalExecutionTiming.cs
namespace TerminalNotes.Services
{

/// <summary>Bounded phase budgets for terminal startup and native execution evidence.</summary>
public static class TerminalExecutionTiming
{
    public static readonly TimeSpan StartupReadyTimeout = TimeSpan.FromMinutes(5);
    public static readonly TimeSpan NativeSubmissionConfirmationTimeout = TimeSpan.FromMinutes(2);
    public static readonly TimeSpan MetadataRequestTimeout = TimeSpan.FromSeconds(30);
    public static readonly TimeSpan NativeStatusHandshakeTimeout = TimeSpan.FromSeconds(30);
    public static readonly TimeSpan InstallationProbeTimeout = TimeSpan.FromSeconds(30);
    public static readonly TimeSpan SlowStartupNoticeAfter = TimeSpan.FromSeconds(20);

    internal static async Task<bool> WaitForNativeSubmissionConfirmationAsync(
        Task confirmation,
        Func<bool> isStillOwned,
        TimeProvider? timeProvider = null,
        TimeSpan? timeoutOverride = null,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(confirmation);
        ArgumentNullException.ThrowIfNull(isStillOwned);
        TimeProvider clock = timeProvider ?? TimeProvider.System;
        TimeSpan timeout = timeoutOverride ?? NativeSubmissionConfirmationTimeout;
        DateTimeOffset deadline = clock.GetUtcNow() + timeout;

        while (clock.GetUtcNow() < deadline)
        {
            if (cancellationToken.IsCancellationRequested || !isStillOwned()) return false;
            if (confirmation.IsCompleted) return !cancellationToken.IsCancellationRequested && isStillOwned();
            TimeSpan remaining = deadline - clock.GetUtcNow();
            if (remaining <= TimeSpan.Zero) break;
            TimeSpan interval = remaining < TimeSpan.FromMilliseconds(200) ? remaining : TimeSpan.FromMilliseconds(200);
            Task delay = Task.Delay(interval, clock, cancellationToken);
            await Task.WhenAny(confirmation, delay).ConfigureAwait(false);
        }

        return confirmation.IsCompleted && isStillOwned() && !cancellationToken.IsCancellationRequested;
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALINPUTBUFFER_CS
#region Services/TerminalInputBuffer.cs
namespace TerminalNotes.Services
{
using global::System.Threading.Channels;


/// <summary>
/// Lossless FIFO storage for input chunks accepted by a ConPTY session.
/// </summary>
internal sealed class TerminalInputBuffer
{
    private readonly object _gate = new();
    private readonly Channel<byte[]> _channel = Channel.CreateUnbounded<byte[]>(new UnboundedChannelOptions
    {
        SingleReader = true,
        SingleWriter = false,
        AllowSynchronousContinuations = false
    });
    private bool _completed;
    private Exception? _failure;

    public ChannelReader<byte[]> Reader => _channel.Reader;

    public Exception? Failure
    {
        get { lock (_gate) return _failure; }
    }

    public bool TryWrite(byte[] bytes)
    {
        lock (_gate)
            return !_completed && _channel.Writer.TryWrite(bytes);
    }

    public bool TryFail(Exception failure)
    {
        ArgumentNullException.ThrowIfNull(failure);
        lock (_gate)
        {
            if (_completed) return false;
            _failure = failure;
            _completed = true;
            _channel.Writer.TryComplete(failure);
            return true;
        }
    }

    public void Complete()
    {
        lock (_gate)
        {
            if (_completed) return;
            _completed = true;
            _channel.Writer.TryComplete();
        }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALINPUTCAPTURE_CS
#region Services/TerminalInputCapture.cs
namespace TerminalNotes.Services
{
using global::System.Globalization;
using global::System.Text;
using global::System.Text.RegularExpressions;


/// <summary>
/// Reconstructs ordinary line-editor submissions from terminal input. It is
/// deliberately conservative: history recall and unknown control sequences
/// make the current submission ambiguous, so it is not reported.
/// </summary>
public sealed class TerminalInputCapture
{
    private const string PasteStart = "\x1b[200~";
    private const string PasteEnd = "\x1b[201~";
    private readonly List<string> _text = [];
    private string _pending = "";
    private int _cursor;
    private bool _inBracketedPaste;
    private bool _ambiguous;
    private bool _ignoreLineFeed;

    /// <summary>
    /// True while the user has typed or is pasting text that was not sent. Esc, arrows, Tab, Page keys and Ctrl chords only move around
    /// OpenCode: they keep a submission from being reported (see Submit) but are not a draft, and nothing clears them until the next Enter
    /// (사용자: 입력창에 입력한것도 없구만).
    /// </summary>
    public bool HasPendingInput => _text.Count != 0 || _inBracketedPaste;

    public event Action<string>? Submitted;

    public void Clear()
    {
        Reset();
        _ignoreLineFeed = false;
    }

    /// <summary>Whole xterm device, pointer, focus and color reports cannot contain composer text.</summary>
    public static bool IsTerminalResponse(string input)
    {
        if (input.Length == 0) return false;
        int index = 0;
        while (index < input.Length)
        {
            if (input.AsSpan(index).StartsWith("\x1b]", StringComparison.Ordinal))
            {
                int bell = input.IndexOf('\x07', index + 2);
                int st = input.IndexOf("\x1b\\", index + 2, StringComparison.Ordinal);
                int terminator = bell < 0 ? st : st < 0 ? bell : Math.Min(bell, st);
                if (terminator < 0 || terminator - index > 128) return false;
                string report = input[(index + 2)..terminator];
                if (!Regex.IsMatch(report, @"\A(?:4;[0-9]+;|1[012];)rgb:[0-9a-fA-F]{1,4}/[0-9a-fA-F]{1,4}/[0-9a-fA-F]{1,4}\z",
                    RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(50))) return false;
                index = terminator + (terminator == bell ? 1 : 2);
                continue;
            }
            if (index + 2 >= input.Length || input[index] != '\x1b' || input[index + 1] != '[') return false;
            int end = index + 2;
            while (end < input.Length && input[end] is < '@' or > '~') end++;
            if (end >= input.Length || !IsDeviceResponse(input[index..(end + 1)])) return false;
            index = end + 1;
        }
        return true;
    }

    /// <summary>
    /// Clears stale terminal-response ambiguity before an application-driven
    /// submission, but never discards text or an in-progress user paste.
    /// </summary>
    public void PrepareForProgrammaticSubmission()
    {
        if (_text.Count != 0 || _inBracketedPaste) return;
        _ambiguous = false;
        _pending = "";
        _cursor = 0;
        _ignoreLineFeed = false;
    }

    public void Observe(string input)
    {
        ArgumentNullException.ThrowIfNull(input);
        if (input.Length == 0) return;

        string data = _pending + input;
        _pending = "";
        int index = 0;
        while (index < data.Length)
        {
            if (_inBracketedPaste)
            {
                int end = data.IndexOf(PasteEnd, index, StringComparison.Ordinal);
                if (end >= 0)
                {
                    Insert(data[index..end]);
                    _inBracketedPaste = false;
                    index = end + PasteEnd.Length;
                    continue;
                }

                int retained = LongestSuffixPrefix(data, index, PasteEnd);
                int insertEnd = data.Length - retained;
                Insert(data[index..insertEnd]);
                if (retained > 0) _pending = data[insertEnd..];
                return;
            }

            char current = data[index];
            if (current == '\x1b')
            {
                int consumed = ConsumeEscape(data, index);
                if (consumed == 0) _pending = data[index..];
                if (consumed <= 0) return;
                index += consumed;
                continue;
            }

            if (current is '\r' or '\n')
            {
                if (current == '\n' && _ignoreLineFeed)
                {
                    _ignoreLineFeed = false;
                    index++;
                    continue;
                }

                _ignoreLineFeed = current == '\r';
                Submit();
                index++;
                continue;
            }

            _ignoreLineFeed = false;
            switch (current)
            {
                case '\x03': // Ctrl+C
                    Reset();
                    index++;
                    break;
                case '\b':
                case '\x7f':
                    Backspace();
                    index++;
                    break;
                case '\x01': // Ctrl+A
                    _cursor = 0;
                    index++;
                    break;
                case '\x05': // Ctrl+E
                    _cursor = _text.Count;
                    index++;
                    break;
                case '\x02': // Ctrl+B
                    Move(-1);
                    index++;
                    break;
                case '\x06': // Ctrl+F
                    Move(1);
                    index++;
                    break;
                case '\x04': // Ctrl+D
                    Delete();
                    index++;
                    break;
                default:
                    if (char.IsControl(current))
                    {
                        // Shell editing modes and TUI controls cannot be reconstructed
                        // safely from bytes alone.
                        _ambiguous = true;
                        index++;
                    }
                    else
                    {
                        int next = index + 1;
                        while (next < data.Length && data[next] != '\x1b' && !char.IsControl(data[next])) next++;
                        Insert(data[index..next]);
                        index = next;
                    }
                    break;
            }
        }
    }

    private int ConsumeEscape(string data, int index)
    {
        if (IsPartialAtEnd(data, index, PasteStart)) return 0;
        if (data.AsSpan(index).StartsWith(PasteStart, StringComparison.Ordinal))
        {
            _inBracketedPaste = true;
            return PasteStart.Length;
        }

        if (index + 1 >= data.Length) return 0;
        if (data[index + 1] != '[')
        {
            // Alt chords and application escape protocols are not line-editor text.
            _ambiguous = true;
            return Math.Min(2, data.Length - index);
        }

        int end = index + 2;
        while (end < data.Length && data[end] is < '@' or > '~') end++;
        if (end >= data.Length) return 0;

        string sequence = data[index..(end + 1)];
        switch (sequence)
        {
            case "\x1b[D": Move(-1); break;
            case "\x1b[C": Move(1); break;
            case "\x1b[H":
            case "\x1b[1~":
            case "\x1b[7~": _cursor = 0; break;
            case "\x1b[F":
            case "\x1b[4~":
            case "\x1b[8~": _cursor = _text.Count; break;
            case "\x1b[3~": Delete(); break;
            case "\x1b[I":
            case "\x1b[O":
                // Focus reports are generated by the terminal, not typed text.
                break;
            case "\x1b[A":
            case "\x1b[B":
                // The recalled history text is never present in the input stream.
                _ambiguous = true;
                break;
            default:
                if (!IsDeviceResponse(sequence)) _ambiguous = true;
                break;
        }

        return end + 1 - index;
    }

    private void Insert(string value)
    {
        if (value.Length == 0) return;
        var elements = StringInfo.GetTextElementEnumerator(value);
        while (elements.MoveNext())
        {
            string element = elements.GetTextElement();
            _text.Insert(_cursor++, element);
        }
    }

    private void Move(int delta) => _cursor = Math.Clamp(_cursor + delta, 0, _text.Count);

    private void Backspace()
    {
        if (_cursor == 0) return;
        _text.RemoveAt(--_cursor);
    }

    private void Delete()
    {
        if (_cursor < _text.Count) _text.RemoveAt(_cursor);
    }

    private void Submit()
    {
        string value = string.Concat(_text);
        bool report = !_ambiguous && !string.IsNullOrWhiteSpace(value);
        Reset();
        if (report) Submitted?.Invoke(value);
    }

    private void Reset()
    {
        _text.Clear();
        _cursor = 0;
        _ambiguous = false;
        _inBracketedPaste = false;
        _pending = "";
    }

    private static bool IsPartialAtEnd(string value, int index, string expected)
    {
        ReadOnlySpan<char> remaining = value.AsSpan(index);
        return remaining.Length < expected.Length && expected.AsSpan().StartsWith(remaining, StringComparison.Ordinal);
    }

    private static bool IsDeviceResponse(string sequence)
    {
        // OpenCode enables SGR mouse reporting. Moving, clicking, or scrolling
        // over its view must not leave a permanent ambiguous composer draft.
        if (Regex.IsMatch(sequence, @"\A\x1b\[<[0-9]+;[0-9]+;[0-9]+[Mm]\z",
            RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(50))) return true;
        char final = sequence[^1];
        if (final is not ('c' or 'R' or 'n' or 't' or 'x' or 'y' or 'I' or 'O')) return false;
        // Device attributes, cursor/status/window reports, and mode reports use
        // only numeric parameters and CSI parameter/intermediate punctuation.
        return sequence.AsSpan(2, sequence.Length - 3).IndexOfAnyExcept("0123456789;:?><=$".AsSpan()) < 0;
    }

    private static int LongestSuffixPrefix(string value, int start, string expected)
    {
        int maximum = Math.Min(expected.Length - 1, value.Length - start);
        for (int length = maximum; length > 0; length--)
        {
            if (value.AsSpan(value.Length - length).SequenceEqual(expected.AsSpan(0, length))) return length;
        }
        return 0;
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_LOOPAUTORECOMMANDUSERS_CS
#region Services/LoopAutoRecommandUsers.cs
namespace TerminalNotes.Services
{

/// <summary>
/// Who may use Loop and Auto Recommand (user request 2026-10-21): only the Windows accounts listed in
/// <see cref="AllowedUsers"/>. Matched against the Windows identity's account name (DOMAIN\name → name),
/// never environment variables. Other accounts never see or run either feature. Separate from
/// AnnouncementEditors (who may edit announcements).
/// </summary>
internal static class LoopAutoRecommandUsers
{
    /// <summary>
    /// Windows account names allowed to use Loop and Auto Recommand: the master accounts, MASTER_USERS in .env (comma-separated),
    /// compiled into the assembly at build time (TerminalNotes.csproj). Without that line the default below applies (the same as
    /// AnnouncementEditors', which focused tests compile apart from this file).
    /// </summary>
    internal static readonly string[] AllowedUsers = BuildAccountList("TerminalNotes.MasterUsers") ?? ["test_01", "test_07", "test_08"];

    internal static string[]? BuildAccountList(string key) =>
        typeof(LoopAutoRecommandUsers).Assembly.GetCustomAttributes(typeof(global::System.Reflection.AssemblyMetadataAttribute), false)
            .OfType<global::System.Reflection.AssemblyMetadataAttribute>().FirstOrDefault(attribute => attribute.Key == key)?.Value is { } value
            ? value.Split([',', ';', ' '], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(user => user[(user.LastIndexOf('\\') + 1)..]).Where(user => user.Length > 0).ToArray()
            : null;
    // Test hosts (another entry assembly) keep both features so their scenarios run; a test can force an account instead.
    internal static Func<string>? AccountOverride = null;
    private static readonly Lazy<bool> CurrentAllowed = new(() =>
        !string.Equals(global::System.Reflection.Assembly.GetEntryAssembly()?.GetName().Name, "TerminalNotes", StringComparison.OrdinalIgnoreCase) ||
        IsAllowedUser(CurrentAccount()));
    internal static bool Allowed => AccountOverride is { } account ? IsAllowedUser(account()) : CurrentAllowed.Value;

    internal static bool IsAllowedUser(string account)
    {
        string name = account[(account.LastIndexOf('\\') + 1)..];
        return AllowedUsers.Any(user => string.Equals(name, user, StringComparison.OrdinalIgnoreCase));
    }

    private static string CurrentAccount()
    {
        using var identity = global::System.Security.Principal.WindowsIdentity.GetCurrent();
        return identity.Name;
    }
}

/// <summary>
/// Who edits the Terminal Notes instructions (전역 지침, 플랜메이커 지침) in 작업 설정: the master accounts (MASTER_USERS in .env, the
/// same list as Loop's). 2026-11-10 사용자: "사용자는 opencode 지침만 수정하게 … 마스터인 경우에만 opencode 지침, 터미널 노트 전역지침,
/// 플랜메이커 전역지침 이렇게 수정되게 해". Other accounts edit only OpenCode's own AGENTS.md (OpenCode 지침), so their Terminal Notes
/// instructions stay the shipped defaults and follow app updates. Test hosts (another entry assembly) keep the editors unless a
/// test forces an account.
/// </summary>
internal static class InstructionEditors
{
    internal static Func<string>? AccountOverride = null;
    private static readonly Lazy<bool> CurrentAllowed = new(() =>
        !string.Equals(global::System.Reflection.Assembly.GetEntryAssembly()?.GetName().Name, "TerminalNotes", StringComparison.OrdinalIgnoreCase) ||
        LoopAutoRecommandUsers.IsAllowedUser(CurrentAccount()));
    internal static bool Allowed => AccountOverride is { } account ? LoopAutoRecommandUsers.IsAllowedUser(account()) : CurrentAllowed.Value;

    private static string CurrentAccount()
    {
        using var identity = global::System.Security.Principal.WindowsIdentity.GetCurrent();
        return identity.Name;
    }
}

}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALLAUNCHMODES_CS
#region Services/TerminalLaunchModes.cs
namespace TerminalNotes.Services
{

public enum TerminalPermissionMode
{
    Standard,
    Auto,
    Yolo,
    Bypass
}

/// <summary>
/// Build-time features from .env (features.json next to the app). AGENT_SELECTION=yes lets each terminal
/// use OpenCode, Claude Code or Codex; anything else (the default) keeps every terminal on OpenCode.
/// </summary>
public static class AppFeatures
{
    public static bool AgentSelection { get; } = LoadAgentSelection();

    private static bool LoadAgentSelection()
    {
        try
        {
            string path = global::System.IO.Path.Combine(AppContext.BaseDirectory, "features.json");
            if (!global::System.IO.File.Exists(path)) return false;
            using var document = global::System.Text.Json.JsonDocument.Parse(global::System.IO.File.ReadAllText(path));
            return document.RootElement.TryGetProperty("AgentSelection", out var value) &&
                value.ValueKind == global::System.Text.Json.JsonValueKind.True;
        }
        catch (Exception exception) when (exception is global::System.IO.IOException or UnauthorizedAccessException or global::System.Text.Json.JsonException)
        {
            return false;
        }
    }
}

/// <summary>
/// The agent CLI chosen per terminal in 작업 설정 (OpenCode, Claude Code or Codex) and its Auto Mode launch.
/// Auto Mode runs OpenCode with --auto, Claude Code in bypass-permissions mode and Codex in YOLO mode.
/// Saved per-slot legacy profiles never reach this: they still go through TerminalLaunchModes.
/// </summary>
public static class AgentCli
{
    public static TerminalTool Parse(string? value) => value switch
    {
        nameof(TerminalTool.ClaudeCode) => TerminalTool.ClaudeCode,
        nameof(TerminalTool.Codex) => TerminalTool.Codex,
        _ => TerminalTool.OpenCode
    };

    public static string Command(TerminalTool agent, bool autoMode) => agent switch
    {
        TerminalTool.ClaudeCode => autoMode ? "claude --dangerously-skip-permissions" : "claude",
        TerminalTool.Codex => autoMode ? "codex --yolo" : "codex",
        _ => autoMode ? "opencode --auto" : "opencode"
    };

    public static string Executable(TerminalTool agent) => agent switch
    {
        TerminalTool.ClaudeCode => "claude",
        TerminalTool.Codex => "codex",
        _ => "opencode"
    };

    public static string DisplayName(TerminalTool agent) => agent switch
    {
        TerminalTool.ClaudeCode => "Claude Code",
        TerminalTool.Codex => "Codex",
        _ => "OpenCode"
    };

    /// <summary>Claude Code and Codex have no session API here: input is typed into their prompt.</summary>
    public static bool IsTyped(string? startupCommand) =>
        startupCommand is "claude" or "codex" ||
        startupCommand?.StartsWith("claude ", StringComparison.Ordinal) == true ||
        startupCommand?.StartsWith("codex ", StringComparison.Ordinal) == true;

    public static TerminalTool FromCommand(string? startupCommand) =>
        startupCommand?.StartsWith("claude", StringComparison.Ordinal) == true ? TerminalTool.ClaudeCode
        : startupCommand?.StartsWith("codex", StringComparison.Ordinal) == true ? TerminalTool.Codex
        : TerminalTool.OpenCode;

    /// <summary>True when the CLI resolves on PATH the way PowerShell would run it (exe, cmd, bat or ps1).</summary>
    public static bool IsInstalled(TerminalTool agent)
    {
        string name = Executable(agent);
        foreach (string directory in (Environment.GetEnvironmentVariable("PATH") ?? string.Empty).Split(global::System.IO.Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries))
        {
            foreach (string extension in new[] { ".exe", ".cmd", ".bat", ".ps1" })
            {
                try { if (global::System.IO.File.Exists(global::System.IO.Path.Combine(directory.Trim().Trim('"'), name + extension))) return true; }
                catch (ArgumentException) { }
            }
        }
        return false;
    }
}

/// <summary>
/// Maps OpenCode permission modes. Legacy tool values are retained for settings
/// compatibility, but do not enable a second launch path.
/// </summary>
public static class TerminalLaunchModes
{
    public static bool Supports(TerminalTool tool, TerminalPermissionMode mode)
    {
        if (!Enum.IsDefined(tool) || !Enum.IsDefined(mode))
        {
            return false;
        }

        TerminalTool normalizedTool = tool == TerminalTool.Default ? TerminalTool.OpenCode : tool;
        return normalizedTool == TerminalTool.OpenCode &&
            mode is TerminalPermissionMode.Standard or TerminalPermissionMode.Auto;
    }

    public static TerminalPermissionMode Normalize(TerminalTool tool, TerminalPermissionMode mode) =>
        Supports(tool, mode) ? mode : TerminalPermissionMode.Standard;

    public static string? Command(TerminalTool tool, TerminalPermissionMode mode)
    {
        TerminalTool normalizedTool = tool == TerminalTool.Default ? TerminalTool.OpenCode : tool;
        TerminalPermissionMode normalizedMode = Normalize(tool, mode);

        return (normalizedTool, normalizedMode) switch
        {
            (TerminalTool.OpenCode, TerminalPermissionMode.Standard) => "opencode",
            (TerminalTool.OpenCode, TerminalPermissionMode.Auto) => "opencode --auto",
            _ => null
        };
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALLAUNCHPROFILE_CS
#region Services/TerminalLaunchProfile.cs
namespace TerminalNotes.Services
{

public enum TerminalTool
{
    // Keep these numeric values stable so settings written by older releases
    // can still be deserialized before their profiles are normalized.
    Default = 0,
    Codex = 1,
    ClaudeCode = 2,
    PowerShell = 3,
    OpenCode = 4,
    Custom = 5
}

public sealed record TerminalLaunchProfile(
    int Slot,
    TerminalTool Tool = TerminalTool.Default,
    string? Title = null,
    string? Command = null,
    string? WorkingDirectory = null,
    TerminalPermissionMode Mode = TerminalPermissionMode.Standard);
}
