#if TN_WPF || TN_SOURCE_SERVICES_TERMINALSLOTLAYOUT_CS
#region Services/TerminalSlotLayout.cs
namespace TerminalNotes.Services
{

/// <summary>
/// The splits the user picks (1 to 6 and 8) and where each cell sits: a row of up to three, 2×2, three on top of two wider
/// ones for five (a six-column grid), 3×2 for six, 4×2 for eight.
/// </summary>
public static class TerminalSplitLayouts
{
    public const int MaxCells = 8;
    public static readonly int[] Counts = [1, 2, 3, 4, 5, 6, 8];

    /// <summary>A saved or requested split as one of <see cref="Counts"/>: anything between two counts takes the larger one.</summary>
    public static int Normalize(int capacity) => Fitting(capacity);

    /// <summary>The smallest split that shows <paramref name="cells"/> cells.</summary>
    public static int Fitting(int cells)
    {
        foreach (int count in Counts)
            if (count >= cells) return count;
        return MaxCells;
    }

    public static (int Columns, int Rows) Grid(int capacity) => capacity switch
    {
        2 => (2, 1), 3 => (3, 1), 4 => (2, 2), 5 => (6, 2), 6 => (3, 2), 8 => (4, 2), _ => (1, 1)
    };

    /// <summary>How many cells wide the split looks (the width it needs next to other columns).</summary>
    public static int Width(int capacity) => capacity switch { 2 or 4 => 2, 3 or 5 or 6 => 3, 8 => 4, _ => 1 };

    public static (int Row, int Column, int Span) Cell(int capacity, int slot)
    {
        if (capacity == 5) return slot < 3 ? (0, slot * 2, 2) : (1, (slot - 3) * 3, 3);
        int columns = Grid(capacity).Columns;
        return (slot / columns, slot % columns, 1);
    }
}

/// <summary>Eight fixed positions. Capacity changes visibility, never session ownership.</summary>
public sealed class TerminalSlotLayout
{
    private readonly string?[] _slots = new string?[TerminalSplitLayouts.MaxCells];
    public int Capacity { get; private set; } = 1;
    public IReadOnlyList<string?> Slots { get; }

    public TerminalSlotLayout() => Slots = Array.AsReadOnly(_slots);

    public void SetCapacity(int capacity)
    {
        if (capacity is < 1 or > TerminalSplitLayouts.MaxCells)
            throw new ArgumentOutOfRangeException(nameof(capacity));
        Capacity = capacity;
    }

    public int IndexOf(string project) =>
        Array.FindIndex(_slots, value => string.Equals(value, project, StringComparison.OrdinalIgnoreCase));

    public void Assign(string project, int targetSlot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(project);
        if (targetSlot < 0 || targetSlot >= Capacity) throw new ArgumentOutOfRangeException(nameof(targetSlot));
        int previous = IndexOf(project);
        if (previous == targetSlot) return;
        if (previous >= 0) _slots[previous] = _slots[targetSlot];
        _slots[targetSlot] = project;
    }

    public bool CanEnsureVisibleWithoutReplacing(string project)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(project);
        int existing = IndexOf(project);
        if (existing >= 0) return existing < Capacity;
        return Array.FindIndex(_slots, 0, Capacity, value => value is null) >= 0;
    }

    public int EnsureVisible(string project)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(project);
        int existing = IndexOf(project);
        if (existing >= 0 && existing < Capacity) return existing;
        int target = Array.FindIndex(_slots, 0, Capacity, value => value is null);
        if (target < 0) target = 0;
        Assign(project, target);
        return target;
    }

    public void Remove(string project)
    {
        int index = IndexOf(project);
        if (index >= 0) _slots[index] = null;
    }

    public int Compact()
    {
        int next = 0;
        for (int index = 0; index < _slots.Length; index++)
        {
            if (_slots[index] is not string project) continue;
            if (next != index)
            {
                _slots[next] = project;
                _slots[index] = null;
            }
            next++;
        }
        return next;
    }

    public void Rename(string source, string destination)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(destination);
        int index = IndexOf(source);
        if (index < 0) return;
        int occupied = IndexOf(destination);
        if (occupied >= 0 && occupied != index) throw new InvalidOperationException("이미 배치된 프로젝트입니다.");
        _slots[index] = destination;
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALSTARTUPADMISSION_CS
#region Services/TerminalStartupAdmission.cs
namespace TerminalNotes.Services
{
using global::System.Runtime.InteropServices;


internal sealed record StartupResourceWait(string Code, string Reason)
{
    // Bound to this pending ticket, never to a pane's future starts or global settings.
    internal Func<bool>? TryRunOnce { get; init; }
    // Memory or system commit nearly exhausted: starting more work could take the PC down.
    internal bool Critical { get; init; }
}

/// <summary>Serializes new process startups and automatic model work. Active work is never suspended.</summary>
internal sealed class TerminalStartupAdmission : IDisposable
{
    private const ulong GiB = 1024UL * 1024 * 1024;
    internal static TerminalStartupAdmission Shared { get; } = new(new WindowsStartupResourceSampler().SampleAsync)
        { ObservedPressure = () => TerminalResourcePressure.Current };
    // Isolated integration tests may hold admission without starting real processes.
    internal static Func<CancellationToken, Task<IDisposable>>? AcquireOverride = null;
    private readonly LinkedList<Ticket> _queue = new();
    private readonly SemaphoreSlim _signal = new(0);
    private readonly CancellationTokenSource _shutdown = new();
    private readonly object _enqueueSync = new();
    private readonly Func<CancellationToken, Task<StartupResourceMeasurement>> _measure;
    private readonly TimeSpan _pollInterval;
    private readonly TimeSpan _minimumSpacing;
    private readonly TimeProvider _clock;
    private int _pending;
    private bool _disposed;
    private bool _pressureBlocked;
    private long? _healthySince;
    internal TimeSpan RecoveryDuration { get; init; } = TimeSpan.FromSeconds(10);
    // 사용자: Loop가 멈추면 안 됨. An office PC often sits at 85–95% memory or high CPU for hours; that pressure (or a
    // missing measurement) delays a start or a Loop round at most this long. Only a critical shortage keeps it waiting.
    internal TimeSpan MaximumPressureWait { get; init; } = TimeSpan.FromMinutes(3);
    internal Func<TerminalResourcePressureNotice?>? ObservedPressure { get; init; }
    private long? _lastObservedPressureTimestamp;
    private DateTimeOffset? _lastAdmission;
    private TaskCompletionSource _wake = new(TaskCreationOptions.RunContinuationsAsynchronously);
    internal Task Completion { get; }
    internal int PendingCount => Volatile.Read(ref _pending);

    internal TerminalStartupAdmission(Func<CancellationToken, Task<StartupResourceMeasurement>> measure,
        TimeSpan? pollInterval = null, TimeSpan? minimumSpacing = null, TimeProvider? clock = null)
    {
        _measure = measure;
        _pollInterval = pollInterval ?? TimeSpan.FromSeconds(2);
        _minimumSpacing = minimumSpacing ?? TimeSpan.FromSeconds(2);
        _clock = clock ?? TimeProvider.System;
        Completion = Task.Run(PumpAsync);
    }

    internal static async Task<IDisposable> AcquireSharedAsync(Action<StartupResourceWait> waiting, CancellationToken token)
    {
        var acquire = AcquireOverride;
        if (acquire is null) return await Shared.AcquireAsync(waiting, token).ConfigureAwait(false);
        waiting(new("queue", "터미널 시작 순서를 기다리는 중"));
        return await acquire(token).WaitAsync(token).ConfigureAwait(false);
    }

    internal async Task<IDisposable> AcquireAsync(Action<StartupResourceWait> waiting, CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        var ticket = new Ticket(waiting, token);
        ticket.RunOnce = () => TryRunOnce(ticket);
        using var registration = token.Register(() => CancelTicket(ticket));
        Notify(ticket, new("queue", $"터미널 시작 대기 · 대기 순서 {Volatile.Read(ref _pending) + 1}"));
        lock (_enqueueSync)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            if (!ticket.Result.Task.IsCompleted)
            {
                if (_pending >= 256) throw new InvalidOperationException("터미널 시작 대기열이 가득 찼습니다.");
                ticket.Node = _queue.AddLast(ticket);
                _pending++;
                if (_signal.CurrentCount == 0) _signal.Release();
            }
        }
        return await ticket.Result.Task.ConfigureAwait(false);
    }

    private async Task PumpAsync()
    {
        try
        {
            while (true)
            {
                var ticket = await TakeNextAsync().ConfigureAwait(false);
                if (ticket.Result.Task.IsCompleted) continue;
                using var linked = CancellationTokenSource.CreateLinkedTokenSource(_shutdown.Token, ticket.Token);
                long? pressureSince = null;
                try
                {
                    while (!ticket.Result.Task.IsCompleted)
                    {
                        linked.Token.ThrowIfCancellationRequested();
                        Task wake;
                        bool yielded = false;
                        lock (_enqueueSync)
                        {
                            wake = _wake.Task;
                            // An explicitly authorized request must not wait behind a blocked head.
                            // Requeue the head intact; an active lease is never preempted.
                            if (!ticket.RunOnceRequested && _queue.Any(t => t.RunOnceRequested && !t.Result.Task.IsCompleted))
                            {
                                ticket.Node = _queue.AddFirst(ticket);
                                _pending++;
                                yielded = true;
                            }
                        }
                        if (yielded) break;
                        StartupResourceWait? wait;
                        if (_lastAdmission is { } last && _clock.GetUtcNow() - last < _minimumSpacing)
                            wait = new("spacing", "터미널 시작 간격을 기다리는 중 · 최소 2초 간격");
                        else
                        {
                            StartupResourceMeasurement sample;
                            try { sample = await _measure(linked.Token).ConfigureAwait(false); }
                            catch (OperationCanceledException) when (linked.IsCancellationRequested) { throw; }
                            catch { sample = new(null, null, null, null); }
                            wait = CheckResources(sample);
                            lock (_enqueueSync)
                                if (ticket.RunOnceRequested && wait?.Code is "memory" or "cpu" or "recovery")
                                    wait = null;
                            if (wait?.Code is "memory" or "cpu" or "recovery" or "measurement_unavailable")
                            {
                                pressureSince ??= _clock.GetTimestamp();
                                if (!wait.Critical && _clock.GetElapsedTime(pressureSince.Value) >= MaximumPressureWait) wait = null;
                            }
                            else pressureSince = null;
                        }
                        if (wait is null)
                        {
                            var lease = new Lease(ticket.Released);
                            bool granted;
                            lock (_enqueueSync)
                            {
                                linked.Token.ThrowIfCancellationRequested();
                                ticket.CurrentWaitCode = null;
                                ticket.RunOnceRequested = false;
                                granted = ticket.Result.TrySetResult(lease);
                            }
                            if (!granted) { lease.Dispose(); break; }
                            // A run-once lease can stop sampling while pressure is
                            // still latched. Its idle time is not healthy evidence.
                            if (_pressureBlocked) _healthySince = null;
                            _lastAdmission = _clock.GetUtcNow();
                            // A cancelled owner must finish startup cleanup before releasing its lease.
                            while (!ticket.Released.Task.IsCompleted)
                            {
                                NotifyQueued();
                                await Task.WhenAny(ticket.Released.Task,
                                    Task.Delay(_pollInterval, _clock, _shutdown.Token)).ConfigureAwait(false);
                                _shutdown.Token.ThrowIfCancellationRequested();
                            }
                            break;
                        }
                        Notify(ticket, wait);
                        NotifyQueued();
                        await Task.WhenAny(Task.Delay(_pollInterval, _clock, linked.Token), wake)
                            .WaitAsync(linked.Token).ConfigureAwait(false);
                    }
                }
                catch (OperationCanceledException) when (linked.IsCancellationRequested)
                {
                    _healthySince = null;
                    ticket.Result.TrySetCanceled(ticket.Token.IsCancellationRequested ? ticket.Token : _shutdown.Token);
                }
                finally
                {
                    // A waiting callback may cancel the ticket synchronously;
                    // WhenAny can then complete normally without entering catch.
                    if (linked.IsCancellationRequested) _healthySince = null;
                }
            }
        }
        catch (OperationCanceledException) when (_shutdown.IsCancellationRequested) { }
        finally
        {
            Ticket[] abandoned;
            lock (_enqueueSync)
            {
                abandoned = _queue.ToArray();
                foreach (var ticket in abandoned) ticket.Node = null;
                _queue.Clear();
                _pending = 0;
            }
            foreach (var ticket in abandoned) ticket.Result.TrySetCanceled(_shutdown.Token);
        }
    }

    private async Task<Ticket> TakeNextAsync()
    {
        while (true)
        {
            _shutdown.Token.ThrowIfCancellationRequested();
            lock (_enqueueSync)
            {
                var node = _queue.First;
                for (var candidate = _queue.First; candidate is not null; candidate = candidate.Next)
                    if (candidate.Value.RunOnceRequested && !candidate.Value.Result.Task.IsCompleted)
                    { node = candidate; break; }
                if (node is not null)
                {
                    _queue.Remove(node);
                    node.Value.Node = null;
                    _pending--;
                    return node.Value;
                }
            }
            await _signal.WaitAsync(_shutdown.Token).ConfigureAwait(false);
        }
    }

    private void CancelTicket(Ticket ticket)
    {
        lock (_enqueueSync)
        {
            if (ticket.Node is { } node)
            { _queue.Remove(node); ticket.Node = null; _pending--; }
            ticket.Result.TrySetCanceled(ticket.Token);
        }
    }

    private bool TryRunOnce(Ticket ticket)
    {
        lock (_enqueueSync)
        {
            if (_disposed || ticket.Token.IsCancellationRequested || ticket.Result.Task.IsCompleted ||
                ticket.RunOnceRequested || ticket.CurrentWaitCode is not ("queue" or "spacing" or "memory" or "cpu" or "recovery"))
                return false;
            ticket.RunOnceRequested = true;
            var wake = _wake;
            _wake = new(TaskCreationOptions.RunContinuationsAsynchronously);
            wake.TrySetResult();
            return true;
        }
    }

    private StartupResourceWait? CheckResources(StartupResourceMeasurement sample)
    {
        // A monitor observation made between requests must also retain recovery
        // hysteresis. Isolated/injected gates do not consume global observations.
        if (ObservedPressure?.Invoke() is { } observed && _lastObservedPressureTimestamp != observed.ObservedAtTimestamp)
        {
            _pressureBlocked = true;
            _healthySince = null;
            _lastObservedPressureTimestamp = observed.ObservedAtTimestamp;
        }
        if (!TerminalResourcePressure.HasMeasurements(sample, requireCpu: true))
        {
            _healthySince = null;
            return new("measurement_unavailable", "시스템 자원 측정 대기 · 메모리/시스템 커밋/CPU 값을 확인할 수 없어 2초 후 다시 확인합니다");
        }
        string metrics = TerminalResourcePressure.Metrics(sample);
        if (TerminalResourcePressure.Detect(sample) is { } pressure)
        {
            _pressureBlocked = true;
            _healthySince = null;
            return new(pressure.Code, pressure.Reason) { Critical = pressure.IsCriticalMemory };
        }
        if (_pressureBlocked)
        {
            long now = _clock.GetTimestamp();
            if (!TerminalResourcePressure.IsHealthy(sample, requireCpu: true)) _healthySince = null;
            else if (_healthySince is null || now < _healthySince) _healthySince = now;
            TimeSpan elapsed = _healthySince is { } since ? _clock.GetElapsedTime(since, now) : TimeSpan.Zero;
            if (_healthySince is null || elapsed < RecoveryDuration)
                return new("recovery", "자원 회복 확인 중 · " + metrics + $" · 안정 확인 {elapsed.TotalSeconds:0}/{RecoveryDuration.TotalSeconds:0}초");
            _pressureBlocked = false;
            _healthySince = null;
        }
        return null;
    }

    private void NotifyQueued()
    {
        int position = 2;
        Ticket[] queued;
        lock (_enqueueSync) queued = _queue.ToArray();
        foreach (var ticket in queued)
            if (!ticket.Result.Task.IsCompleted)
                Notify(ticket, new("queue", $"터미널 시작 대기 · 대기 순서 {position++}"));
    }
    private void Notify(Ticket ticket, StartupResourceWait wait)
    {
        lock (_enqueueSync)
        {
            if (_disposed || ticket.Token.IsCancellationRequested || ticket.Result.Task.IsCompleted) return;
            ticket.CurrentWaitCode = wait.Code;
            if (!ticket.RunOnceRequested && wait.Code is "queue" or "spacing" or "memory" or "cpu" or "recovery")
                wait = wait with { TryRunOnce = ticket.RunOnce };
        }
        try { ticket.Waiting(wait); } catch { /* UI reporting cannot break admission. */ }
    }
    public void Dispose()
    {
        lock (_enqueueSync) { if (_disposed) return; _disposed = true; }
        _shutdown.Cancel();
    }
    private sealed record Ticket(Action<StartupResourceWait> Waiting, CancellationToken Token)
    {
        internal LinkedListNode<Ticket>? Node { get; set; }
        internal Func<bool>? RunOnce { get; set; }
        internal bool RunOnceRequested { get; set; }
        internal string? CurrentWaitCode { get; set; }
        internal TaskCompletionSource<IDisposable> Result { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        internal TaskCompletionSource Released { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
    }
    private sealed class Lease(TaskCompletionSource released) : IDisposable
    { public void Dispose() => released.TrySetResult(); }
}

internal sealed class WindowsStartupResourceSampler
{
    private ulong? _idle, _kernel, _user;
    internal Task<StartupResourceMeasurement> SampleAsync(CancellationToken token)
    {
        token.ThrowIfCancellationRequested();
        var memory = new MemoryStatus { Length = (uint)Marshal.SizeOf<MemoryStatus>() };
        bool memoryOk = GlobalMemoryStatusEx(ref memory);
        double? cpu = null;
        if (GetSystemTimes(out var idle, out var kernel, out var user))
        {
            if (_idle is { } oldIdle && _kernel is { } oldKernel && _user is { } oldUser &&
                idle >= oldIdle && kernel >= oldKernel && user >= oldUser)
            {
                ulong total = kernel - oldKernel + user - oldUser, idleDelta = idle - oldIdle;
                if (total > 0 && idleDelta <= total) cpu = 100d * (total - idleDelta) / total;
            }
            _idle = idle; _kernel = kernel; _user = user;
        }
        var commit = WindowsSystemCommit.Read();
        return Task.FromResult(new StartupResourceMeasurement(memoryOk ? (int)memory.Load : null,
            memoryOk ? memory.TotalPhysical : null, memoryOk ? memory.AvailablePhysical : null, cpu)
            { CommitTotalBytes = commit.Total, CommitLimitBytes = commit.Limit });
    }
    [StructLayout(LayoutKind.Sequential)] private struct MemoryStatus
    {
        internal uint Length, Load;
        internal ulong TotalPhysical, AvailablePhysical, TotalPageFile, AvailablePageFile,
            TotalVirtual, AvailableVirtual, AvailableExtendedVirtual;
    }
    [DllImport("kernel32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GlobalMemoryStatusEx(ref MemoryStatus status);
    [DllImport("kernel32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GetSystemTimes(out ulong idle, out ulong kernel, out ulong user);
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALTABDOCUMENTSTORE_CS
#region Services/TerminalTabDocumentStore.cs
namespace TerminalNotes.Services
{
using global::System.Collections.Concurrent;
using global::System.IO;


public sealed record TabDocumentSnapshot(string Path, string Text, bool Exists)
{
    internal MarkdownDocument? Document { get; init; }
}

/// <summary>Project-level Plan documents, with legacy per-slot paths for other modes.</summary>
public sealed class TerminalTabDocumentStore
{
    public const string ProjectPlanRelativePath = "terminal-notes/plan.md";
    private static readonly ConcurrentDictionary<string, SemaphoreSlim> Gates = new(StringComparer.OrdinalIgnoreCase);
    private readonly string _directory;
    private readonly string _planDocumentPath;

    public static string GetProjectPlanPath(string projectDirectory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(projectDirectory);
        return System.IO.Path.GetFullPath(System.IO.Path.Combine(
            System.IO.Path.GetFullPath(projectDirectory), ProjectPlanRelativePath));
    }

    public TerminalTabDocumentStore(string projectDirectory, string? planDocumentPath = null)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(projectDirectory);
        string fullProjectDirectory = System.IO.Path.GetFullPath(projectDirectory);
        _directory = System.IO.Path.Combine(fullProjectDirectory, "terminal-notes", "tabs");
        // Keep the optional parameter for callers and saved terminal state from older versions.
        // The project Plan has one canonical path now; custom values are never a runtime binding.
        _ = planDocumentPath;
        _planDocumentPath = GetProjectPlanPath(fullProjectDirectory);
    }

    public string GetDocumentPath(int slot, TerminalInputMode mode)
    {
        if (slot < 1) throw new ArgumentOutOfRangeException(nameof(slot));
        if (mode == TerminalInputMode.Question || !Enum.IsDefined(mode))
            throw new ArgumentException("질문은 파일로 저장하지 않습니다.", nameof(mode));
        if (mode == TerminalInputMode.Plan && _planDocumentPath is not null)
            return _planDocumentPath;
        return System.IO.Path.Combine(_directory, $"terminal-{slot:00}", $"{mode.ToString().ToLowerInvariant()}.md");
    }

    public Task<TabDocumentSnapshot> LoadAsync(int slot, TerminalInputMode mode, CancellationToken cancellationToken = default)
    {
        string path = GetDocumentPath(slot, mode);
        return Task.Run(() => Read(path), cancellationToken);
    }

    public async Task<TabDocumentSnapshot> SaveAsync(int slot, TerminalInputMode mode, string text,
        TabDocumentSnapshot expected, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(text);
        string path = GetDocumentPath(slot, mode);
        if (!string.Equals(path, expected.Path, StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("다른 탭의 문서는 저장할 수 없습니다.", nameof(expected));
        var gate = Gates.GetOrAdd(path, _ => new SemaphoreSlim(1, 1));
        await gate.WaitAsync(cancellationToken);
        try
        {
            return await Task.Run(() =>
            {
                cancellationToken.ThrowIfCancellationRequested();
                var current = Read(path);
                if (current.Exists != expected.Exists || current.Text != expected.Text)
                    throw new IOException("MD 파일이 외부에서 변경되었습니다. 초안을 복사한 뒤 다시 불러와 병합하세요.");
                if (current.Exists && string.Equals(current.Text, text, StringComparison.Ordinal)) return current;
                var document = expected.Document ?? current.Document ?? MarkdownDocument.Create();
                document.Text = text;
                Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path)!);
                document.Save(path);
                return Read(path);
            }, cancellationToken);
        }
        finally { gate.Release(); }
    }

    public static string BuildExecutionPrompt(TabDocumentSnapshot snapshot, TerminalInputMode mode)
    {
        if (mode == TerminalInputMode.Question || !Enum.IsDefined(mode) ||
            !(mode == TerminalInputMode.Plan
                ? string.Equals(System.IO.Path.GetExtension(snapshot.Path), ".md", StringComparison.OrdinalIgnoreCase)
                : string.Equals(System.IO.Path.GetFileName(snapshot.Path), $"{mode.ToString().ToLowerInvariant()}.md", StringComparison.OrdinalIgnoreCase)))
            throw new ArgumentException("실행할 기능 탭과 MD 파일이 일치하지 않습니다.", nameof(mode));
        if (!snapshot.Exists || string.IsNullOrWhiteSpace(snapshot.Text))
            throw new InvalidOperationException("실행할 MD 내용을 먼저 저장하세요.");
        string action = mode switch
        {
            TerminalInputMode.Plan => "요구사항을 현재 코드·변경분·검증 근거와 항목별로 대조해 미충족된 요구사항을 사용자가 원하는 결과가 실제로 동작할 때까지 구현하고 관련 검증을 실행하세요. 이미 충족된 요구사항은 근거를 확인하고 반복하지 마세요.",
            TerminalInputMode.Build => "요구사항에 맞게 프로젝트 코드를 구현하고 검증하세요.",
            TerminalInputMode.Review => "프로젝트 코드와 요구사항을 비교하여 검토하고 문제와 검증 결과를 보고하세요.",
            TerminalInputMode.Command => "문서에 명시된 작업을 수행하고 결과를 확인하세요.",
            _ => throw new ArgumentException("질문에는 MD 실행 지침을 만들지 않습니다.", nameof(mode))
        };
        return $"다음 MD 파일을 지금 직접 읽고 최신 내용을 이 작업의 지침으로 사용하세요: \"{snapshot.Path}\"\n" +
            "현재 코드·변경분·기존 결과를 요구사항별로 대조하세요. pending todo나 MD에 남은 항목만으로 미완료를 판단하지 말고, 이미 충족된 항목은 확인 근거와 todo 상태만 정리하세요. 모두 충족되었으면 코드 변경 없이 멈추세요. 남은 요구사항과 확인된 결함은 변경 규모나 토큰 사용량 때문에 줄이지 말고 필요한 만큼 수정해 완성하고, 새 요구나 결함이 없으면 유효한 기존 검증을 재사용하세요. 처음부터 다시 시작하거나 정상 구현을 다시 만들지 마세요. 추가 입력은 최신 플랜 요청과 정정을 반영하세요.\n" +
            action + "\n각 작업 단계에 들어가기 전에 같은 파일을 다시 읽어 수정·삭제된 요구사항을 반영하세요. " +
            "파일이 없거나 비어 있거나 읽을 수 없으면 이전 내용으로 진행하지 말고 알려주세요. " +
            "다른 터미널이나 기능 탭의 MD를 이 작업의 지침으로 사용하지 마세요.";
    }

    private static TabDocumentSnapshot Read(string path)
    {
        try
        {
            var document = MarkdownDocument.Load(path);
            return new(path, document.Text, true) { Document = document };
        }
        catch (FileNotFoundException) { return new(path, "", false); }
        catch (DirectoryNotFoundException) { return new(path, "", false); }
    }
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TERMINALTOKENUSAGE_CS
#region Services/TerminalTokenUsage.cs
namespace TerminalNotes.Services
{
using global::System.Globalization;
using global::System.Text;
using global::System.Text.Json;
using global::System.Text.RegularExpressions;


/// <summary>Tracks only explicit token counters emitted by this terminal session.</summary>
public sealed partial class TerminalTokenUsage
{
    private readonly object _gate = new();
    private readonly StringBuilder _lineBuffer = new();
    private readonly HashSet<string> _completedEvents = new(StringComparer.Ordinal);
    private long _completedInput;
    private long _completedOutput;
    private long _completedTotal;
    private long? _inputTokens;
    private long? _outputTokens;
    private long? _totalTokens;
    private bool _hasCumulativeCounter;
    private string? _scopeId;

    public event Action? Changed;

    public long? InputTokens { get { lock (_gate) return _inputTokens; } }
    public long? OutputTokens { get { lock (_gate) return _outputTokens; } }
    public long? TotalTokens { get { lock (_gate) return _totalTokens; } }
    public string Label { get { lock (_gate) return FormatLabel(_totalTokens); } }

    public void Observe(string text)
    {
        ArgumentNullException.ThrowIfNull(text);
        if (text.Length == 0) return;

        bool changed = false;
        lock (_gate)
        {
            string plain = StripAnsiRegex().Replace(text, "");
            foreach (Match match in ExplicitTotalRegex().Matches(plain))
            {
                if (TryNumber(match.Groups[1].Value, out long total))
                    changed |= SetCounters(null, null, total, cumulative: true);
            }

            _lineBuffer.Append(plain);
            while (TryTakeLine(out string? line)) changed |= ObserveLine(line);

            // A machine event may arrive without a trailing newline. Parse it once it
            // is a complete JSON value, while retaining partial values for later data.
            string pending = _lineBuffer.ToString().Trim();
            if (pending.Length > 1 && pending[0] == '{' && pending[^1] == '}' && TryParseJson(pending, out JsonDocument? document))
            {
                using (document) changed |= ObserveJson(document!.RootElement, pending);
                _lineBuffer.Clear();
            }

            if (_lineBuffer.Length > 1_000_000) _lineBuffer.Remove(0, _lineBuffer.Length - 64_000);
        }

        if (changed) Changed?.Invoke();
    }

    private bool ObserveLine(string line)
    {
        string value = line.Trim();
        bool changed = false;
        foreach (Match match in ExplicitTotalRegex().Matches(value))
        {
            if (TryNumber(match.Groups[1].Value, out long total))
                changed |= SetCounters(null, null, total, cumulative: true);
        }
        if (value.Length < 2 || value[0] != '{' || value[^1] != '}' || !TryParseJson(value, out JsonDocument? document)) return changed;
        using (document) return ObserveJson(document!.RootElement, value) || changed;
    }

    private bool ObserveJson(JsonElement root, string fingerprint)
    {
        string? type = FindString(root, "type");
        if (string.Equals(type, "thread.started", StringComparison.OrdinalIgnoreCase))
        {
            string scope = FindStringRecursive(root, "thread_id", "threadId") ?? fingerprint;
            if (!string.Equals(scope, _scopeId, StringComparison.Ordinal))
            {
                _scopeId = scope;
                _completedEvents.Clear();
            }
            return false;
        }
        if (string.Equals(type, "turn.completed", StringComparison.OrdinalIgnoreCase))
        {
            if (!_completedEvents.Add(fingerprint)) return false;
            JsonElement usage = FindObject(root, "usage");
            long? input = FindNumber(usage, "input_tokens", "inputTokens");
            long? output = FindNumber(usage, "output_tokens", "outputTokens");
            long? total = FindNumber(usage, "total_tokens", "totalTokens");
            if (input is null && output is null && total is null) return false;

            _completedInput += input ?? 0;
            _completedOutput += output ?? (total is { } t ? Math.Max(0, t - (input ?? 0)) : 0);
            _completedTotal += total ?? (input ?? 0) + (output ?? 0);
            if (_hasCumulativeCounter) return false;
            return SetCounters(_completedInput, _completedOutput, _completedTotal, cumulative: false);
        }

        if (string.Equals(type, "step_finish", StringComparison.OrdinalIgnoreCase))
        {
            string? session = FindStringRecursive(root, "sessionID", "session_id");
            if (session is not null && !string.Equals(session, _scopeId, StringComparison.Ordinal))
            {
                _scopeId = session;
                _completedEvents.Clear();
            }
            JsonElement part = FindObject(root, "part");
            JsonElement usage = FindObject(part, "tokens");
            if (usage.ValueKind != JsonValueKind.Object) return false;
            string stepFingerprint = (session ?? "") + ":" + (FindStringRecursive(part, "id") ?? FingerprintFor(root));
            if (!_completedEvents.Add(stepFingerprint)) return false;

            long input = FindNumber(usage, "input") ?? 0;
            long output = FindNumber(usage, "output") ?? 0;
            long reasoning = FindNumber(usage, "reasoning") ?? 0;
            JsonElement cache = FindObject(usage, "cache");
            long cacheRead = FindNumber(cache, "read") ?? 0;
            long cacheWrite = FindNumber(cache, "write") ?? 0;
            long total = FindNumber(usage, "total") ?? input + output + reasoning + cacheRead + cacheWrite;
            _completedInput += input + cacheRead + cacheWrite;
            _completedOutput += output + reasoning;
            _completedTotal += total;
            if (_hasCumulativeCounter) return false;
            return SetCounters(_completedInput, _completedOutput, _completedTotal, cumulative: false);
        }

        if (type?.Contains("token_count", StringComparison.OrdinalIgnoreCase) == true ||
            type?.Contains("token.count", StringComparison.OrdinalIgnoreCase) == true)
        {
            long? total = FindNumber(root, "total_tokens", "totalTokens");
            long? input = FindNumber(root, "input_tokens", "inputTokens");
            long? output = FindNumber(root, "output_tokens", "outputTokens");
            if (total is null && (input is not null || output is not null)) total = (input ?? 0) + (output ?? 0);
            return total is not null && SetCounters(input, output, total, cumulative: true);
        }

        return false;
    }

    private bool SetCounters(long? input, long? output, long? total, bool cumulative)
    {
        if (total is null || total < 0) return false;
        bool changed = _inputTokens != input || _outputTokens != output || _totalTokens != total;
        _inputTokens = input;
        _outputTokens = output;
        _totalTokens = total;
        _hasCumulativeCounter |= cumulative;
        return changed;
    }

    private bool TryTakeLine(out string line)
    {
        for (int i = 0; i < _lineBuffer.Length; i++)
        {
            if (_lineBuffer[i] is not ('\r' or '\n')) continue;
            line = _lineBuffer.ToString(0, i);
            int remove = i + 1;
            if (_lineBuffer[i] == '\r' && remove < _lineBuffer.Length && _lineBuffer[remove] == '\n') remove++;
            _lineBuffer.Remove(0, remove);
            return true;
        }
        line = "";
        return false;
    }

    private static JsonElement FindObject(JsonElement element, string name)
    {
        if (element.ValueKind == JsonValueKind.Object)
        {
            foreach (JsonProperty property in element.EnumerateObject())
            {
                if (property.Name.Equals(name, StringComparison.OrdinalIgnoreCase) && property.Value.ValueKind == JsonValueKind.Object) return property.Value;
                JsonElement nested = FindObject(property.Value, name);
                if (nested.ValueKind != JsonValueKind.Undefined) return nested;
            }
        }
        else if (element.ValueKind == JsonValueKind.Array)
        {
            foreach (JsonElement item in element.EnumerateArray())
            {
                JsonElement nested = FindObject(item, name);
                if (nested.ValueKind != JsonValueKind.Undefined) return nested;
            }
        }
        return default;
    }

    private static long? FindNumber(JsonElement element, params string[] names)
    {
        if (element.ValueKind == JsonValueKind.Object)
        {
            foreach (JsonProperty property in element.EnumerateObject())
            {
                if (names.Any(name => property.Name.Equals(name, StringComparison.OrdinalIgnoreCase)) &&
                    property.Value.ValueKind == JsonValueKind.Number &&
                    property.Value.TryGetInt64(out long value)) return value;
                long? nested = FindNumber(property.Value, names);
                if (nested is not null) return nested;
            }
        }
        else if (element.ValueKind == JsonValueKind.Array)
        {
            foreach (JsonElement item in element.EnumerateArray())
            {
                long? nested = FindNumber(item, names);
                if (nested is not null) return nested;
            }
        }
        return null;
    }

    private static string? FindString(JsonElement element, string name)
    {
        if (element.ValueKind != JsonValueKind.Object) return null;
        foreach (JsonProperty property in element.EnumerateObject())
        {
            if (property.Name.Equals(name, StringComparison.OrdinalIgnoreCase) && property.Value.ValueKind == JsonValueKind.String) return property.Value.GetString();
        }
        return null;
    }

    private static string? FindStringRecursive(JsonElement element, params string[] names)
    {
        if (element.ValueKind == JsonValueKind.Object)
        {
            foreach (JsonProperty property in element.EnumerateObject())
            {
                if (names.Any(name => property.Name.Equals(name, StringComparison.OrdinalIgnoreCase)) &&
                    property.Value.ValueKind == JsonValueKind.String) return property.Value.GetString();
                string? nested = FindStringRecursive(property.Value, names);
                if (nested is not null) return nested;
            }
        }
        else if (element.ValueKind == JsonValueKind.Array)
        {
            foreach (JsonElement item in element.EnumerateArray())
            {
                string? nested = FindStringRecursive(item, names);
                if (nested is not null) return nested;
            }
        }
        return null;
    }

    private static bool TryParseJson(string value, out JsonDocument? document)
    {
        try { document = JsonDocument.Parse(value); return true; }
        catch (JsonException) { document = null; return false; }
    }

    private static string FingerprintFor(JsonElement element) => element.GetRawText();

    private static bool TryNumber(string text, out long value) =>
        long.TryParse(text.Replace(",", "", StringComparison.Ordinal), NumberStyles.None, CultureInfo.InvariantCulture, out value);

    public static string FormatCount(long total)
    {
        string[] units = ["", "K", "M", "B"];
        decimal value = total;
        int unit = 0;
        while (value >= 1000 && unit < units.Length - 1)
        {
            value /= 1000;
            unit++;
        }
        value = decimal.Round(value, 2, MidpointRounding.AwayFromZero);
        // Promote rounded boundaries as well, so 999,999 displays as 1M, not 1000K.
        if (value >= 1000 && unit < units.Length - 1)
        {
            value /= 1000;
            unit++;
        }
        return value.ToString("0.##", CultureInfo.InvariantCulture) + units[unit];
    }

    private static string FormatLabel(long? total) => total is { } value
        ? $"토큰 {FormatCount(value)}"
        : "토큰 정보 없음";

    [GeneratedRegex("(?:total\\s+tokens|tokens\\s+used|token\\s+usage|총\\s*토큰)\\s*[:=]\\s*([0-9][0-9,]*)", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex ExplicitTotalRegex();

    [GeneratedRegex("\\x1B\\][^\\x07]*(?:\\x07|\\x1B\\\\)|\\x1B\\[[0-?]*[ -/]*[@-~]", RegexOptions.CultureInvariant)]
    private static partial Regex StripAnsiRegex();
}
}
#endregion
#endif

#if TN_WPF || TN_SOURCE_SERVICES_TRAYICONSERVICE_CS
#region Services/TrayIconService.cs
namespace TerminalNotes.Services
{
using global::System.IO;
using global::System.Windows;
using global::System.Windows.Threading;


/// <summary>
/// Owns the notification-area icon and forwards its commands to the WPF UI thread.
/// </summary>
public sealed class TrayIconService : IDisposable
{
    private const string IconResourceUri = "pack://application:,,,/TerminalNotes;component/Assets/AppIcon.ico";

    private readonly Dispatcher _dispatcher;
    private readonly Action _restoreWindow;
    private readonly Action _closeAllTerminals;
    private readonly Action _exitApplication;
    private readonly System.Drawing.Icon _icon;
    private readonly System.Windows.Forms.NotifyIcon _notifyIcon;
    private readonly System.Windows.Forms.ContextMenuStrip _menu;
    private readonly System.Windows.Forms.ToolStripMenuItem _openItem;
    private readonly System.Windows.Forms.ToolStripMenuItem _closeAllItem;
    private readonly System.Windows.Forms.ToolStripMenuItem _exitItem;
    private readonly System.Windows.Forms.ToolStripMenuItem _taskNotificationsItem;
    private readonly System.Windows.Forms.ToolStripMenuItem _notificationsEnabledItem;
    private readonly System.Windows.Forms.ToolStripMenuItem _notificationsOffItem;
    private readonly Dictionary<int, System.Windows.Forms.ToolStripMenuItem> _snoozeItems = [];
    private readonly System.Windows.Forms.ToolStripMenuItem _customSnoozeItem;
    private readonly Queue<QueuedBalloon> _balloonQueue = new();
    private readonly DispatcherTimer _balloonFallbackTimer;

    private Func<TaskNotificationPreferences>? _getNotificationPreferences;
    private Action<bool>? _setNotificationsEnabled;
    private Action<int>? _snoozeNotifications;
    private Action? _customSnooze;
    private bool _balloonIsShowing;
    private bool _hiddenNoticeShown;
    private bool _disposed;

    public TrayIconService(
        Action restoreWindow,
        Action closeAllTerminals,
        Action exitApplication)
    {
        ArgumentNullException.ThrowIfNull(restoreWindow);
        ArgumentNullException.ThrowIfNull(closeAllTerminals);
        ArgumentNullException.ThrowIfNull(exitApplication);

        _dispatcher = Application.Current?.Dispatcher ?? Dispatcher.CurrentDispatcher;
        _restoreWindow = restoreWindow;
        _closeAllTerminals = closeAllTerminals;
        _exitApplication = exitApplication;

        _icon = LoadIcon();
        try
        {
            _openItem = new System.Windows.Forms.ToolStripMenuItem("열기");
            _closeAllItem = new System.Windows.Forms.ToolStripMenuItem("터미널 모두 닫기")
            {
                Enabled = false
            };
            _exitItem = new System.Windows.Forms.ToolStripMenuItem("프로그램 종료");

            _openItem.Click += OpenItem_Click;
            _closeAllItem.Click += CloseAllItem_Click;
            _exitItem.Click += ExitItem_Click;

            _taskNotificationsItem = new System.Windows.Forms.ToolStripMenuItem("\uC791\uC5C5 \uC54C\uB9BC");
            _notificationsEnabledItem = new System.Windows.Forms.ToolStripMenuItem("\uC54C\uB9BC \uC0AC\uC6A9") { CheckOnClick = true };
            _notificationsOffItem = new System.Windows.Forms.ToolStripMenuItem("\uC601\uAD6C \uB044\uAE30");
            _customSnoozeItem = new System.Windows.Forms.ToolStripMenuItem("\uC0AC\uC6A9\uC790 \uC9C0\uC815 \uC2DC\uAC04\u2026");
            _balloonFallbackTimer = new DispatcherTimer(DispatcherPriority.Background, _dispatcher);
            _balloonFallbackTimer.Tick += BalloonFallbackTimer_Tick;
            _notificationsEnabledItem.Click += NotificationsEnabledItem_Click;
            _notificationsOffItem.Click += NotificationsOffItem_Click;
            _customSnoozeItem.Click += CustomSnoozeItem_Click;
            _taskNotificationsItem.DropDownItems.Add(_notificationsEnabledItem);
            _taskNotificationsItem.DropDownItems.Add(_notificationsOffItem);
            _taskNotificationsItem.DropDownItems.Add(new System.Windows.Forms.ToolStripSeparator());
            foreach (int minutes in new[] { 5, 10, 30, 60 })
            {
                var item = new System.Windows.Forms.ToolStripMenuItem($"{minutes}\uBD84 \uB3D9\uC548 \uC54C\uB9BC \uBBF8\uB8E8\uAE30");
                item.Tag = minutes;
                item.Click += SnoozeItem_Click;
                _snoozeItems.Add(minutes, item);
                _taskNotificationsItem.DropDownItems.Add(item);
            }
            _taskNotificationsItem.DropDownItems.Add(_customSnoozeItem);
            _taskNotificationsItem.DropDownOpening += TaskNotificationsItem_DropDownOpening;

            _menu = new System.Windows.Forms.ContextMenuStrip();
            _menu.Items.AddRange(
            [
                _openItem,
                _closeAllItem,
                _taskNotificationsItem,
                new System.Windows.Forms.ToolStripSeparator(),
                _exitItem
            ]);
            _menu.Opening += Menu_Opening;

            _notifyIcon = new System.Windows.Forms.NotifyIcon
            {
                ContextMenuStrip = _menu,
                Icon = _icon,
                Text = "Terminal Notes · 열린 터미널 없음"
            };
            _notifyIcon.DoubleClick += NotifyIcon_DoubleClick;
            _notifyIcon.BalloonTipClicked += NotifyIcon_BalloonTipClicked;
            _notifyIcon.BalloonTipClosed += NotifyIcon_BalloonTipClosed;
            _notifyIcon.Visible = true;
        }
        catch
        {
            _openItem?.Dispose();
            _closeAllItem?.Dispose();
            _exitItem?.Dispose();
            _taskNotificationsItem?.Dispose();
            _notificationsEnabledItem?.Dispose();
            _notificationsOffItem?.Dispose();
            _customSnoozeItem?.Dispose();
            foreach (var item in _snoozeItems.Values) item.Dispose();
            _balloonFallbackTimer?.Stop();
            _menu?.Dispose();
            _notifyIcon?.Dispose();
            _icon.Dispose();
            throw;
        }
    }

    public void UpdateSessionCount(int count)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(count);
        RunOnDispatcher(() =>
        {
            _closeAllItem.Enabled = count > 0;
            _notifyIcon.Text = count == 0
                ? "Terminal Notes · 열린 터미널 없음"
                : $"Terminal Notes · 열린 터미널 {count}개";
        });
    }

    public void ShowHiddenNotice()
    {
        RunOnDispatcher(() =>
        {
            if (_hiddenNoticeShown)
            {
                return;
            }

            _hiddenNoticeShown = true;
            EnqueueBalloon("Terminal Notes", "\uCC3D\uC744 \uB2EB\uC544\uB3C4 \uD2B8\uB808\uC774\uC5D0\uC11C \uACC4\uC18D \uC2E4\uD589\uB429\uB2C8\uB2E4.", System.Windows.Forms.ToolTipIcon.Info, 4000, () => true);
        });
    }

    internal void ConfigureTaskNotifications(
        Func<TaskNotificationPreferences> getPreferences,
        Action<bool> setEnabled,
        Action<int> snooze,
        Action customMinutes)
    {
        ArgumentNullException.ThrowIfNull(getPreferences);
        ArgumentNullException.ThrowIfNull(setEnabled);
        ArgumentNullException.ThrowIfNull(snooze);
        ArgumentNullException.ThrowIfNull(customMinutes);
        RunOnDispatcher(() =>
        {
            _getNotificationPreferences = getPreferences;
            _setNotificationsEnabled = setEnabled;
            _snoozeNotifications = snooze;
            _customSnooze = customMinutes;
            RefreshTaskNotificationMenu();
        });
    }

    public void ShowTaskNotification(string title, string body, bool warning, Func<bool> stillRelevant)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(title);
        ArgumentException.ThrowIfNullOrWhiteSpace(body);
        ArgumentNullException.ThrowIfNull(stillRelevant);
        RunOnDispatcher(() => EnqueueBalloon(title, body,
            warning ? System.Windows.Forms.ToolTipIcon.Warning : System.Windows.Forms.ToolTipIcon.Info,
            5000, stillRelevant, isTaskNotification: true));
    }

    public void CancelTaskNotifications()
    {
        RunOnDispatcher(() =>
        {
            var retained = _balloonQueue.Where(item => !item.IsTaskNotification).ToArray();
            _balloonQueue.Clear();
            foreach (var item in retained) _balloonQueue.Enqueue(item);
        });
    }

    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        _notifyIcon.DoubleClick -= NotifyIcon_DoubleClick;
        _notifyIcon.BalloonTipClicked -= NotifyIcon_BalloonTipClicked;
        _notifyIcon.BalloonTipClosed -= NotifyIcon_BalloonTipClosed;
        _menu.Opening -= Menu_Opening;
        _taskNotificationsItem.DropDownOpening -= TaskNotificationsItem_DropDownOpening;
        _openItem.Click -= OpenItem_Click;
        _closeAllItem.Click -= CloseAllItem_Click;
        _exitItem.Click -= ExitItem_Click;
        _notificationsEnabledItem.Click -= NotificationsEnabledItem_Click;
        _notificationsOffItem.Click -= NotificationsOffItem_Click;
        _customSnoozeItem.Click -= CustomSnoozeItem_Click;
        foreach (var item in _snoozeItems.Values) item.Click -= SnoozeItem_Click;
        _balloonFallbackTimer.Stop();
        _balloonQueue.Clear();

        // Hiding first removes the shell icon immediately instead of waiting for finalization.
        _notifyIcon.Visible = false;
        _notifyIcon.ContextMenuStrip = null;
        _notifyIcon.Dispose();
        _menu.Dispose();
        _icon.Dispose();
        GC.SuppressFinalize(this);
    }

    private static System.Drawing.Icon LoadIcon()
    {
        var resource = Application.GetResourceStream(new Uri(IconResourceUri, UriKind.Absolute))
            ?? throw new InvalidOperationException($"Tray icon resource was not found: {IconResourceUri}");

        using Stream stream = resource.Stream;
        using var sourceIcon = new System.Drawing.Icon(stream);
        return (System.Drawing.Icon)sourceIcon.Clone();
    }

    private void NotifyIcon_DoubleClick(object? sender, EventArgs e) => Dispatch(_restoreWindow);

    private void NotifyIcon_BalloonTipClicked(object? sender, EventArgs e) => Dispatch(_restoreWindow);

    private void NotifyIcon_BalloonTipClosed(object? sender, EventArgs e) => RunOnDispatcher(CompleteCurrentBalloon);

    private void EnqueueBalloon(string title, string body, System.Windows.Forms.ToolTipIcon icon, int timeout,
        Func<bool> stillRelevant, bool isTaskNotification = false)
    {
        _balloonQueue.Enqueue(new(title, body, icon, timeout, stillRelevant, isTaskNotification));
        DrainBalloonQueue();
    }

    private void DrainBalloonQueue()
    {
        if (_disposed || _balloonIsShowing) return;
        while (_balloonQueue.TryDequeue(out var next))
        {
            bool relevant;
            try { relevant = next.StillRelevant(); }
            catch { relevant = false; }
            if (!relevant) continue;

            _balloonIsShowing = true;
            try
            {
                _notifyIcon.BalloonTipTitle = next.Title;
                _notifyIcon.BalloonTipText = next.Body;
                _notifyIcon.BalloonTipIcon = next.Icon;
                _notifyIcon.ShowBalloonTip(next.Timeout);
                // Windows controls shell balloon duration; this fallback prevents a missing
                // close callback from blocking queued notices for the rest of the app lifetime.
                _balloonFallbackTimer.Interval = TimeSpan.FromSeconds(35);
                _balloonFallbackTimer.Start();
            }
            catch
            {
                _balloonIsShowing = false;
                continue;
            }
            return;
        }
    }

    private void CompleteCurrentBalloon()
    {
        if (!_balloonIsShowing) return;
        _balloonFallbackTimer.Stop();
        _balloonIsShowing = false;
        DrainBalloonQueue();
    }

    private void BalloonFallbackTimer_Tick(object? sender, EventArgs e) => CompleteCurrentBalloon();

    private void Menu_Opening(object? sender, System.ComponentModel.CancelEventArgs e) => RefreshTaskNotificationMenu();

    private void TaskNotificationsItem_DropDownOpening(object? sender, EventArgs e) => RefreshTaskNotificationMenu();

    internal void RefreshTaskNotificationMenu()
    {
        TaskNotificationPreferences? preferences = null;
        try { preferences = _getNotificationPreferences?.Invoke(); }
        catch { }
        DateTimeOffset now = DateTimeOffset.UtcNow;
        _taskNotificationsItem.Text = NotificationMenuHeader(preferences, now);
        _notificationsEnabledItem.Checked = preferences?.Enabled ?? false;
        _notificationsOffItem.Checked = !(preferences?.Enabled ?? false);
        foreach (var item in _snoozeItems.Values)
        {
            item.Checked = false;
            item.Enabled = preferences?.Enabled ?? false;
        }
        _customSnoozeItem.Enabled = preferences?.Enabled ?? false;
    }

    private static string NotificationMenuHeader(TaskNotificationPreferences? preferences, DateTimeOffset now)
    {
        if (preferences is null) return "\uC791\uC5C5 \uC54C\uB9BC";
        if (!preferences.Enabled) return "\uC791\uC5C5 \uC54C\uB9BC \u00B7 \uAEBC\uC9D0";
        if (preferences.SnoozedUntilUtc is not { } until || until <= now) return "\uC791\uC5C5 \uC54C\uB9BC";
        int remainingMinutes = Math.Max(1, (int)Math.Ceiling((until - now).TotalMinutes));
        return $"\uC791\uC5C5 \uC54C\uB9BC \u00B7 {remainingMinutes}\uBD84 \uC911\uC9C0";
    }

    private void NotificationsEnabledItem_Click(object? sender, EventArgs e) =>
        Dispatch(() => _setNotificationsEnabled?.Invoke(true));

    private void NotificationsOffItem_Click(object? sender, EventArgs e) =>
        Dispatch(() => _setNotificationsEnabled?.Invoke(false));

    private void SnoozeItem_Click(object? sender, EventArgs e)
    {
        if (sender is System.Windows.Forms.ToolStripMenuItem { Tag: int minutes })
            Dispatch(() => _snoozeNotifications?.Invoke(minutes));
    }

    private void CustomSnoozeItem_Click(object? sender, EventArgs e) => Dispatch(() => _customSnooze?.Invoke());

    private void OpenItem_Click(object? sender, EventArgs e) => Dispatch(_restoreWindow);

    private void CloseAllItem_Click(object? sender, EventArgs e)
    {
        if (_closeAllItem.Enabled)
        {
            Dispatch(_closeAllTerminals);
        }
    }

    private void ExitItem_Click(object? sender, EventArgs e) => Dispatch(_exitApplication);

    private void Dispatch(Action callback)
    {
        RunOnDispatcher(() =>
        {
            if (!_disposed)
            {
                callback();
            }
        });
    }

    private void RunOnDispatcher(Action action)
    {
        if (_disposed || _dispatcher.HasShutdownStarted || _dispatcher.HasShutdownFinished)
        {
            return;
        }

        if (_dispatcher.CheckAccess())
        {
            action();
            return;
        }

        try
        {
            _ = _dispatcher.BeginInvoke(() =>
            {
                if (!_disposed)
                {
                    action();
                }
            });
        }
        catch (InvalidOperationException) when (
            _dispatcher.HasShutdownStarted || _dispatcher.HasShutdownFinished)
        {
            // The application began shutting down between the checks and BeginInvoke.
        }
     }

    private sealed record QueuedBalloon(string Title, string Body, System.Windows.Forms.ToolTipIcon Icon,
        int Timeout, Func<bool> StillRelevant, bool IsTaskNotification);
}
}
#endregion
#endif

